/* 托福单词 · 精讲数据文件 data-mnemo：由 index.html 按需加载，内容与原内嵌数据逐字一致 */
window.__TOEFL_DATA__=window.__TOEFL_DATA__||{};
window.__TOEFL_DATA__["data-mnemo"]=JSON.parse("{\n\"adjust\":\"画面：司机调了调后视镜的角度，坐姿也跟着挪正——adjust「调整；适应」。ad-（向着）+ just（正）：把东西调到『正好』的位置；到新环境把自己调正，就是适应。\",\n\"alternative\":\"画面：正门堵死了，他转身走向侧门——alternative「可替代的（选择）」。alter 是『另一个、改变』（alter 改变）：正选之外的另一个选项；alternative energy 新能源就是替代能源。\",\n\"amend\":\"画面：法案文本上红笔划掉一行、旁边添上新词——amend「修正；修订」。它和 mend（修补）同源：把文件像补衣服一样修好；宪法修正案就叫 amendment。\",\n\"analogous\":\"画面：鸟的翅膀和蝙蝠的翼摊在一起比，形状不同、功用却一样——analogous「相似的；类似的」。analogy 是『类比』：用比例相同来打比方的那种相似。\",\n\"anticipate\":\"画面：天气预报说夜里降温，他提前把厚被子抱出来——anticipate「预料；预期」。anti- 在这里是『先』（ante-）：先一步料到并做好准备，比 expect 多一层『提前动手』。\",\n\"apparent\":\"画面：雾散了，远山一下子清清楚楚显出来——apparent「明显的；显而易见的」。appar- 是『出现』（appear 出现）：都摆到眼前出现了，当然明显；apparently 是『显然；据说』。\",\n\"archive\":\"画面：档案室里一排排铁柜，卷宗按年份码得整齐——archive「档案；档案馆」。读 /ˈɑːkaɪv/，ch 发 /k/ 不发『吃』音；把旧文件送进档案馆，也叫 archive。\",\n\"assemble\":\"画面：零件摊满桌子，他一步步把书架拼起来——assemble「组装；集合」。a- + semble『一起』（similar 的亲戚）：把散件凑到一起；人群集合到广场也用它。\",\n\"assign\":\"画面：老师把任务单一张张发到每人手里——assign「分配；布置」。a- + sign（记号）：给每件事做上记号、分派到人；家庭作业 assignment 就是被分派下来的活。\",\n\"assist\":\"画面：他搬箱子吃力，路人上前抬住另一头——assist「协助；帮助」。as-（向着）+ sist（站）：站到你旁边来帮你；名词 assistance，篮球里的『助攻』也叫 assist。\",\n\"attain\":\"画面：登山者伸手够到崖顶的标记旗——attain「达到；获得」。at- + tain『抓握』（contain 的 tain）：伸手抓到够不着的目标；attain a goal 达成目标是它的招牌搭配。\",\n\"attitude\":\"画面：同一件事，他双手抱臂一脸不屑，她却凑近了认真听——attitude「态度」。它本是身体的『姿势』，引申为心里摆出的姿势；attitude toward… 对…的态度。\",\n\"attribute\":\"画面：记者把这句名言安到了鲁迅头上，编辑摇头：出处不对——attribute「归因；归属」。at- + tribute（贡物→给予）：把功劳或原因『给』到某人某事名下；作名词重音前移，是『特性』。\",\n\"automatic\":\"画面：感应门人一走近就自己打开——automatic「自动的」。auto- 是『自己』（automobile 汽车）：自己会动的；引申为不假思索的：an automatic reaction 本能反应。\",\n\"bulk\":\"画面：一袋米占了后备厢大半个地方——bulk「大量；体积」。它先指『大块头占的地方』，再指『大部分』：the bulk of the work 工作的主体部分；批发大宗购买是 buy in bulk。\",\n\"capable\":\"画面：她一个人把整场活动撑下来，还滴水不漏——capable「有能力的」。cap- 是『抓、容纳』（capacity 容量）：脑子能装下多少事，就有多大能力；capable of doing 能做某事。\",\n\"channel\":\"画面：河水被引入一条窄窄的水渠，哗哗流向田里——channel「渠道；频道；水道」。它源于拉丁 canalis『管道』：水走水渠，信息走渠道，电视有频道——都是让东西通过的通路。\",\n\"classic\":\"画面：一本百年前的书摆在玻璃柜里，至今人人还在读——classic「经典的；典型的」。class 是『等级』：被排进最高一级、经得起时间的，就是经典；a classic example 典型例子。\",\n\"clause\":\"画面：合同密密麻麻，律师指着其中一条：就这款要改——clause「条款；从句」。它源于拉丁『关闭』：一条自成一段、意思封闭完整的文字；语法里能独立成义的从句也叫 clause。\",\n\"coherent\":\"画面：一篇作文段落间环环相扣，读下来一气呵成——coherent「连贯的；一致的」。co-（一起）+ her『黏』（adhere 黏附）：句子彼此黏得住、不脱节；物理里激光的『相干』也是它。\",\n\"comment\":\"画面：新闻下面评论区盖起高楼，有人只发了三个字——comment「评论；发表意见」。com- + ment『想』（mental）：把心里想的说出来；作动词 comment on… 评论某事。\",\n\"commodity\":\"画面：国际市场上原油、铜、咖啡豆按吨报价交易——commodity「商品；日用品」。它特指能大宗买卖的基础商品，和普通 goods 的『零售货』不同；commodity prices 是大宗商品价格。\",\n\"communicate\":\"画面：两人隔着山头用旗语一来一往传消息——communicate「交流；沟通」。commun- 是『共有』（common 共同）：把信息变成两边共有的，就是沟通；名词 communication。\",\n\"compatible\":\"画面：新插头咔哒一声严丝合缝插进插座——compatible「兼容的；合得来的」。com- + pati『承受』：彼此能『容忍、共存』；软件兼容、人合得来，都用它，反义 incompatible。\",\n\"compile\":\"画面：编辑把散页稿一件件收齐，订成厚厚一册——compile「汇编；编辑」。com- + pil『堆』：把材料堆到一起成集；程序员把代码『编译』成机器语言，也叫 compile。\",\n\"complement\":\"画面：拼图最后一块落下，画面完整了——complement「补充；补足」。com- + ple『满』（complete 完整）：补上缺的那块使之圆满；注意和 compliment（赞美）只差一个字母，意思完全不同。\",\n\"comprehensive\":\"画面：一份报告从历史、现状到对策无一遗漏——comprehensive「全面的；综合的」。com- + prehend『抓住』：把方方面面一把全抓住；comprehensive exam 综合考试，comprehensive insurance 全险。\",\n\"comprise\":\"画面：评委会由五位专家组成，一个不多一个不少——comprise「包含；构成」。整台机器 comprise 五个部件；反过来说 five parts comprise the machine 也行——它自带『comprise = be made up of』的双向用法。\",\n\"compute\":\"画面：老式计算尺拉来拉去，他在纸上算出轨道数据——compute「计算；估算」。com- + put『 reckon 算』（reputation 的 put 是『认为』）：把数字拢到一起算；computer 计算机就是『会算的机器』。\",\n\"conceive\":\"画面：画家盯着空白画布，脑中慢慢浮出整幅构图——conceive「构想；设想」。con- + ceiv『抓取』（receive 接收）：在心里『怀住』一个念头，所以它还有『怀孕』一义；I can't conceive of… 我无法想象。\",\n\"confer\":\"画面：校长把学位证书双手递到毕业生手里——confer「授予；协商」。con- + fer『带来』（transfer 转移）：把荣誉『带给』某人；另一义是大家聚到一起商量，conference 会议由此而来。\",\n\"confine\":\"画面：篱笆只圈住这一小片地，羊出不去——confine「限制； confined 于」。con- + fin『边界』（finite 有限）：画个边界关在里面；be confined to bed 卧床不起，confine yourself to… 把范围限于。\",\n\"confirm\":\"画面：酒店发来短信：订单已确认，房间留好了——confirm「确认；证实」。con- + firm（坚定、牢固）：把本来不定的事钉牢；confirm a reservation 确认预订，实验证实假设也用 confirm。\",\n\"conform\":\"画面：新同学默默换上了和大家一样的校服——conform「遵守； conform 习俗」。con- + form（形状）：把自己的形状改成和大家一样；conform to the rules 遵守规则，反义 rebel。\",\n\"constitute\":\"画面：十二个人坐成一圈，委员会就此成立——constitute「构成；组成」。con- + stit『站立』（statue 站立的像）：各个部分站到一起，整体就立起来了；What constitutes… 什么才算…。\",\n\"constrain\":\"画面：预算像一根绳，把方案捆得动弹不得——constrain「强迫；限制」。con- + strain『拉紧』（string 绳）：被绳子紧紧缚住；名词 constraint 是搞科研写论文绕不开的『限制条件』。\",\n\"contradict\":\"画面：两名证人站在法庭上，一个说向东，一个说向西——contradict「反驳；相矛盾」。contra-（反对）+ dict（说）：你说什么，我偏说反的；证据与说法相抵触也叫 contradict。\",\n\"contribute\":\"画面：每人往募捐箱里投一点，箱子满了——contribute「贡献；捐助；投稿」。con- + tribute（贡物）：大家一起把贡物凑出来；contribute to 还有『促成、导致』：Smoking contributes to cancer。\",\n\"convene\":\"画面：通知发下，各地代表陆续走进会场——convene「召开；召集」。con-（一起）+ ven『来』（venue 会场）：把人叫到一起来；会议 convene，就是人到齐、会开起来。\",\n\"coordinate\":\"画面：乐队指挥双手起落，各声部严丝合缝——coordinate「协调；配合」。co- + ordin『次序』（order 顺序）：让各方按同一次序行动；作名词是『坐标』，衣服的『配套』也是它。\",\n\"correspond\":\"画面：他按地址写了十年信，两地之间书信不断——correspond「对应；通信」。cor- + respond（回应）：你来我往互相应答；数学里图形对应、数据吻合也用 correspond to。\",\n\"couple\":\"画面：舞池里一对舞伴随着音乐旋转——couple「一对；夫妇」。它源于拉丁『连结』：两个连在一起就是 a couple；a couple of 除了『一对』，口语里还泛指『几个』。\",\n\"crucial\":\"画面：十字路口立着抉择牌，往左往右结局完全不同——crucial「至关重要的」。cruc- 是『十字』（cross）：到了十字路口、生死攸关的节点；crucial moment 关键时刻，考试高频词。\",\n\"define\":\"画面：词典里一条黑线圈住词条，边界画得清楚——define「定义；界定」。de- + fin『边界』：给一个概念画出边界，里面是什么、外面就不是；名词 definition。\",\n\"definite\":\"画面：他斩钉截铁：『就定在周五，不改了。』——definite「明确的；确定的」。de- + fin『边界』：边界都画死了，当然明确；definite answer 确切答复，definitely 是口头禅『肯定地』。\",\n\"delay\":\"画面：站台广播响起：列车晚点两小时——delay「延迟；耽搁」。它由 de- + 拉丁『放松缰绳』演变：缰绳一松，马就慢下来；without delay 立刻，delay doing 推迟做某事。\",\n\"delete\":\"画面：手指点住文件拖进回收站，确认删除——delete「删除」。de- + 拉丁『涂抹』：古罗马人把字从蜡板上抹掉，就是 delete；键盘上的 Delete 键由此得名。\",\n\"denote\":\"画面：红灯亮着，它表示『停』——denote「表示；指示」。de- + not『记号』（note 笔记）：一个符号指向一个意思；数学写作里 X denotes… 表示『X 代表…』，学术高频。\",\n\"derive\":\"画面：顺着小溪往上走，找到山里的源头——derive「取得；源自」。de- + riv『河』（river 河流）：从源头把水引下来；derive from 源于，be derived from 由…派生——词源题最爱它。\",\n\"deviate\":\"画面：航线本来是直线，飞机突然偏出去绕开雷暴——deviate「偏离」。de-（离开）+ via（路）：离开正道；deviate from the plan 偏离计划，名词 deviation 偏差。\",\n\"differentiate\":\"画面：双胞胎并排站，他指着眉梢的痣：靠这个分——differentiate「区分；区别」。differ 是『不同』：把本来混在一起的分辨出不同；和 distinguish 近义，数学里还有『求导』义。\",\n\"displace\":\"画面：石头扔进满杯水，水溢出来——石头占了水的位置——displace「取代；置换」。dis- + place（位置）：把原来的挤出位置自己坐上去；难民 displaced persons 流离失所者由此而来。\",\n\"display\":\"画面：橱窗里新款手机排成一列，灯光打亮——display「陈列；展示」。dis- + play 在这里是『展开』（古义）：把折着的东西摊开展示；电脑的显示屏也叫 display。\",\n\"dispose\":\"画面：他把过期药品封好袋，投进有害垃圾箱——dispose「处理；处置」。dis- + pos『放』（position 位置）：把东西放到该去的地方；dispose of 处理掉，disposal 处置。\",\n\"distort\":\"画面：哈哈镜里的人被拉长压扁，不成样子——distort「扭曲；歪曲」。dis- + tort『扭』（torture 折磨）：硬拧变形；报道被 distort，就是事实被拧歪了。\",\n\"distribute\":\"画面：志愿者把物资一箱箱分到每个村子——distribute「分发；分配」。dis- + tribute（贡物）：把东西散着给出去；名词 distribution 分布，物种的地理分布也是它。\",\n\"domain\":\"画面：地图上他的领地用金线围起来——domain「领域；范围」。它源于拉丁 dominus『主人』：主人说了算的地盘；学术 domain 学科领域，数学 domain 定义域，网站域名也是它。\",\n\"draft\":\"画面：桌面上摊着写满涂改的第一稿，旁边是揉掉的纸团——draft「草稿；起草」。它本义是『拉、抽』（draw）：先粗粗拉出个轮廓；draft a plan 起草计划，应征入伍也叫 the draft。\",\n\"edit\":\"画面：编辑的红笔在稿纸上圈点删改——edit「编辑；剪辑」。e-（出）+ dit『给』（edition 版本）：把稿子『给出』之前先修好；editor 编辑，视频剪辑也用 edit。\",\n\"emerge\":\"画面：潜水员从水面探出头，阳光照在脸上——emerge「出现；浮现」。e-（向外）+ merg『浸』（merge 合并的反面）：从水里冒出来；新趋势 emerge，就是从背景里浮现出来。\",\n\"enable\":\"画面：一把钥匙插进锁孔，门开了——enable「使能够；使可能」。en- + able（能够）：给人『能够』的钥匙；enable sb to do 使某人能做某事，科技 enable a feature 开启功能。\",\n\"entity\":\"画面：组织结构图上每个方框都是一个独立单位——entity「实体；独立存在体」。它来自拉丁 esse『存在』：凡是能单独『在』的东西都算 entity；公司在法律上就是 legal entity。\",\n\"equip\":\"画面：出征前士兵领齐头盔、水壶、工具包——equip「装备；配备」。它源于『给船装货出海』：出发前把家伙什配齐；equipment 设备，be equipped with 配备有…。\",\n\"estate\":\"画面：庄园大门内草坪、主楼、马厩连成一片——estate「房地产；庄园」。它与 state 同源，本是『地位、财产』：一大片连地带房的产业；real estate 就是房地产行业。\",\n\"evident\":\"画面：脚印从门口一路到窗边，谁来过一清二楚——evident「明显的」。e- + vid『看』（video 视频）：看得见的，当然明显；evidence 证据就是『让人看见真相的东西』；evidently 显然。\",\n\"except\":\"画面：全班都交了作业，只有他的名字被圈在名单外——except「除外；把…除去」。ex-（向外）+ cept『拿』：从总数里拿出去的那一个；except for 除…之外（整体不错时的美中不足）。\",\n\"exist\":\"画面：老地图上画着独角兽，可谁也没真见过——exist「存在」。ex- + sist『站立』：立在世上就是存在；existence 存在，existing 现有的，别和 extinct（灭绝）混。\",\n\"explicit\":\"画面：说明书一步步写明，连螺丝拧几圈都标了——explicit「明确的；直白的」。ex- + plic『折叠』：把折起来的全部摊开说明白；和 implicit（含蓄的）正是一对反义词。\",\n\"finite\":\"画面：沙漏里的沙总会漏完——资源再多也有尽头——finite「有限的」。fin 是『边界、终点』（finish 完成）：有终点的就是有限；反义 infinite 无限，数学里的 finite set 有限集。\",\n\"fundamental\":\"画面：盖楼先打地基，地基之下再无别物——fundamental「根本的；基础的」。fund 是『底部』（foundations 地基）：最底层的、动了它全局都塌的；fundamental difference 根本区别。\",\n\"furthermore\":\"画面：他数完三条理由，又竖起第四根手指：『还有——』——furthermore「此外；而且」。further（更远）+ more（更多）：话说得更远、再加一层；作文里递进衔接的万金油，比 moreover 口气更正式。\",\n\"grade\":\"画面：楼梯一级一级往上，学生按年级分班——grade「等级；年级；评分」。grad 是『步、级』（gradual 逐步的）：一级一级排出来的就是等级；make the grade 达到标准。\",\n\"hence\":\"画面：他推出最后一行公式，写下：『由此可得——』——hence「因此；由此」。它是 hence = from here『从这里（推出）』：由前面的原因走到这个结果；学术写作里代替 therefore 的高频词。\",\n\"ideology\":\"画面：两群人举着完全不同的旗帜，各有各的口号——ideology「意识形态」。ideo-（思想，idea）+ -logy（学说）：一整套关于社会该怎么运转的思想体系；ideological 意识形态的。\",\n\"image\":\"画面：湖面如镜，山在水里有个一模一样的倒影——image「形象；影像；图像」。它源于拉丁 imago『摹本』：本体在别处的『副本』；公众形象 public image、脑海中的画面 mental image 都是它。\",\n\"immigrate\":\"画面：一家人拖着箱子通过新国家的海关，开始新生活——immigrate「移入；移民（入境）」。im-（进入）+ migr（迁移）：迁进来；迁出去是 emigrate——方向别反，immigrant 是移入者。\",\n\"implement\":\"画面：新规贴上墙，第二天大家就照着做起来——implement「实施；执行」。im- + ple『填满』：把计划『填』成现实；作名词是『工具』：farm implements 农具——都是让想法落地的东西。\",\n\"implicit\":\"画面：他没说出口，只挑了挑眉，意思大家都懂——implicit「含蓄的；暗含的」。im- + plic『折叠』：意思折在话里没摊开，和 explicit（明确的）正相对；implicit trust 绝对信任是另一常用义。\",\n\"incidence\":\"画面：流感季节，门诊量曲线陡然爬升——incidence「发生率」。in- + cid『落下』（accident 落下来的事）：事情『落』到人群头上的比率；incidence of disease 发病率，统计阅读高频。\",\n\"incline\":\"画面：山坡斜着，他扶着栏杆往上挪——incline「倾斜；倾向于」。in- + clin『斜靠』（recline 躺靠）：斜过去就是倾斜；be inclined to do 倾向于做某事，心也是一种『斜』。\",\n\"inconsistent\":\"画面：他昨天说去、今天说不去，话对不上——inconsistent「不一致的；反复无常的」。in-（不）+ consistent（一致的）：前后对不上的；数据 inconsistent，就是几组数互相打架。\",\n\"indifferent\":\"画面：台上讲得热火朝天，他低头刷手机，头也不抬——indifferent「漠不关心的」。in- + different 本是『没差别』：对他来说怎样都『没差别』，所以无所谓；be indifferent to 对…漠不关心。\",\n\"induce\":\"画面：医生打了一针，产妇的宫缩被引发出来——induce「引诱；引起；归纳（物理感应）」。in- + duc『引导』（conduct 引导）：把结果『引』出来；induce sb to do 劝诱某人，电磁感应 induced current 也是引出来的。\",\n\"inhibit\":\"画面：一只手按住要按下按钮的手指——再等等——inhibit「抑制；阻碍」。in- + hib『拿住』（exhibit 把东西拿出来展）：从里面拿住、按住；化学 inhibit a reaction 抑制反应，心理 inhibition 压抑。\",\n\"initiate\":\"画面：他剪断红绸，新项目正式启动——initiate「创始；发起；发起使开始」。in- + it『走』（exit 出去走）：迈出第一步、走进去；initiate a program 启动计划，新人入会 initiation 入会仪式。\",\n\"injure\":\"画面：比赛中他扭伤脚踝，队医抬他下场——injure「伤害；使受伤」。in- + jur『法律、权利』本义是『不法侵害』：让身体或权利受损；injury 伤，injured 伤员——新闻里天天见。\",\n\"intrinsic\":\"画面：金子埋进土里一百年，挖出来还是金子——intrinsic「本质的；内在的」。intrin- 是『在内部』：不依赖外境、本来就有的；intrinsic value 内在价值，和 instrumental（工具性的）相对。\",\n\"invoke\":\"画面：律师起身：『我援引宪法第 X 条。』——invoke「援引；援引（法律、规则）」。in- + voc『喊』（voice 声音）：把沉睡的条款『喊』出来为自己撑腰；invoke a law 援引法律，也可指唤起情感 invoke memories。\",\n\"perception\":\"画面：同一张斑点图，有人看见狗、有人看见脸——大脑加工出的版本各不同——perception「感知」。per- + cept『抓取』：感官抓进来的信息经大脑『加工成像』，所以感知不等于感觉本身；perceive 是动词。\",\n\"cognition\":\"画面：棋手盯着棋盘在脑中推演十步——cognition「认知」。cogn- 是『知道』（recognize 再认）：思考、记忆、推理这一整套『知道世界』的过程；cognitive 认知的，心理学第一高频词。\",\n\"sensation\":\"画面：指尖碰到冰块，凉意顺着手臂窜上来——sensation「感觉」。sens- 是『感觉』（sense 感官）：刺激刚抵达感官、还没加工的那一瞬；和 perception（感知，加工后）成对出现。\",\n\"stimulus\":\"画面：铃声一响，狗就开始分泌唾液——stimulus「刺激」。它源于拉丁『尖棒』：像被尖棒戳一下，机体立刻反应；复数 stimuli，心理学实验里的一切信号都是它。\",\n\"behavior\":\"画面：监控里记录下他一整天的举动：排队、让座、皱眉——behavior「行为」。behave（举止）+ -ior：看得见、测得着的外在表现；行为主义 behaviorism 只研究它，因为内心看不见。\",\n\"instinct\":\"画面：刚出生的小海龟不用教，自己爬向大海——instinct「本能」。in- + stinct『刺、驱使』：天生被『驱使』着做的事，不学而会；by instinct 凭本能，动物行为学核心词。\",\n\"reflex\":\"画面：医生敲了下膝盖，小腿自己弹起来——reflex「反射」。re- + flex『弯回』：刺激像光一样被『弹回来』，快过大脑；条件反射 conditioned reflex 是巴甫洛夫的招牌。\",\n\"habit\":\"画面：他进门就把钥匙挂在同一个钩子上，想都不用想——habit「习惯」。它和 habitat（栖息地）同根，本义是『常待的状态』：做多了住下来的行为，就是习惯；habitual 习惯性的。\",\n\"learning\":\"画面：小鼠第三次走迷宫，径直奔向奶酪——learning「学习」。心理学定义很硬核：因经验引起的行为相对持久的变化；老鼠走迷宫、白鼠按杠杆，都是 lecture 里的经典画面。\",\n\"recall\":\"画面：考场上他望着天花板，把背过的公式往外『捞』——recall「回忆」。re- + call（喊）：把存进记忆的东西重新『喊回来』；心理学测记忆常用 free recall 自由回忆，和 recognition（识别）相对。\",\n\"recognition\":\"画面：老同学迎面走来，他一眼认出：『是你！』——recognition「识别；认出」。re- + cogn『知道』：再次『知道』——见过的东西混在一堆里也能挑出来，所以选择题比问答题容易。\",\n\"forgetting\":\"画面：黑板上的字被一点点擦掉，只剩淡淡的印——forgetting「遗忘」。艾宾浩斯的遗忘曲线就画这个：刚学完忘得最快；forget 的现在分词作名词，lecture 里和 memory 成对出现。\",\n\"attention\":\"画面：聚光灯只打亮舞台中央一小圈，四周全黑——attention「注意力」。at- + tend『拉紧、伸向』：把心神『拉向』一处；心理学说注意力像聚光灯，照到哪、哪才被加工。\",\n\"concentration\":\"画面：放大镜把阳光聚成一个小亮点，纸被点燃——concentration「专注；浓度」。con- + centr『中心』：把力量收拢到一个中心点；化学里溶液浓度也是它——『聚』是它的魂。\",\n\"distraction\":\"画面：正写论文，手机在桌角一下下震——思绪被拽走——distraction「分心」。dis- + tract『拉』：注意力被往旁边『拉走』的东西；distract 使分心，distracted 心不在焉的。\",\n\"motivation\":\"画面：一只驴面前吊着胡萝卜，劲头十足往前走——motivation「动机」。motiv- 源于拉丁『移动』（move）：心里推动你『动起来』的那个引擎；motivate 激励，intrinsic motivation 内在动机是考点。\",\n\"emotion\":\"画面：过山车冲下陡坡，全车人尖叫——心跳、表情、喊声一起来——emotion「情绪」。e- + mot『动』：被『搅动』起来的身心状态；心理学拆它的三成分：生理唤醒、表情、主观体验。\",\n\"disgust\":\"画面：他打开放了半月的饭盒，立刻捂鼻后仰——disgust「厌恶」。dis- + gust『品尝』（gusto 滋味）：尝到坏味道的生理排斥，引申为道德上的反感；disgusted 感到厌恶的。\",\n\"sympathy\":\"画面：朋友哭着说分手了，她递上纸巾，眼圈也红了——sympathy「同情」。sym-（共同）+ path『感受』（pathos 情感）：和对方一起『难受』；注意和 empathy（共情，站进对方位置）区分。\",\n\"personality\":\"画面：五个维度像五根柱子撑起一个人：外向、尽责、宜人……——personality「人格」。persona 原是演员的『面具』：一个人长期戴着的、稳定的行为面具；大五人格 Big Five 是 TOEFL 讲座常客。\",\n\"temperament\":\"画面：两个婴儿，一个见生人就哭，一个呵呵笑——temperament「气质」。temper 原是『调和比例』：与生俱来的情绪『底噪』，比 personality 更先天、更偏情绪反应速度。\",\n\"trait\":\"画面：性格档案上列着一行行：诚实、好胜、拖延……——trait「特质」。它源于拉丁『拉出的线』：从一个人身上抽出来的一根根稳定的『线』；trait theory 特质理论，personality trait 人格特质。\",\n\"character\":\"画面：没人看见时，他把多找的钱退了回去——character「性格；品格」。它源于希腊『刻痕』：刻在骨子里的印记；和 personality 相比，character 更带道德评价色彩，还可指『角色、字符』。\",\n\"aptitude\":\"画面：入学测试里，他看一眼数列就报出下一项——aptitude「天赋；资质」。apt 是『合适、灵巧』（apt 恰当的）：天生适合干某事的禀赋；aptitude test 性向测验，招生语境高频。\",\n\"talent\":\"画面：十岁孩子即兴弹的曲子让老师沉默了——talent「才能；天赋」。它古代是『秤、重量单位』，后成圣经寓言里的银子：上天称给你的那份本钱；talented 有才华的。别和 skill（练出来的技能）混。\",\n\"creativity\":\"画面：满桌废纸团里，他忽然把两个不相干的点子焊在了一起——creativity「创造力」。creat- 是『生、造』（create 创造）：无中生有、旧元素新组合；心理学测它常用『发散思维』任务。\",\n\"imagination\":\"画面：孩子举着纸箱说：『这是我的宇宙飞船！』——imagination「想象力」。imagin- 源于 image（图像）：在脑内放映不存在的画面；imagine 想象，imaginary 虚构的——词形三兄弟别混。\",\n\"fantasy\":\"画面：他望着窗外发呆，脑内正加冕为王——fantasy「幻想；空想」。它和 imagination 像，但 fantasy 更偏白日梦、不切实际的虚构；文学体裁 fantasy 是奇幻小说，重音在第一个音节。\",\n\"unconscious\":\"画面：车祸后他躺在病床上，对呼喊毫无反应——unconscious「无意识的；昏迷的」。un- + conscious（有意识的）：医学上是昏迷，心理学上是弗洛伊德那片『意识不到的心理区域』，unconscious mind 潜意识源头。\",\n\"subconscious\":\"画面：冰山浮在水面的下一层，隐约可见的轮廓——subconscious「潜意识的」。sub- 是『在…之下』：意识水面之下的那一层，平时察觉不到，却影响梦和口误；和 unconscious 分工不同。\",\n\"awareness\":\"画面：正念课上老师问：『听，此刻窗外有几种声音？』——awareness「意识；觉察」。aware 是『察觉到的』+ -ness：对周围和内心状态『保持察觉』；raise awareness 提高公众意识是社会类文章高频短语。\",\n\"intuition\":\"画面：老医生扫一眼化验单就皱眉：『不对劲。』——说不出理由却八九不离十——intuition「直觉」。in- + tuit『看顾』：不经推理的『一眼看穿』；心理学说它是经验压缩后的快速判断。\",\n\"induction\":\"画面：看了十只天鹅全是白的，他写下：天鹅皆白——induction「归纳；感应」。in- + duc『引导』：从一个个例子把结论『引』出来；和 deduction（演绎，从一般到个别）是逻辑课的一对。\",\n\"decision\":\"画面：岔路口他站了很久，终于迈向左边那条——decision「决定」。de- + cis『切』（scissors 剪刀）：把犹豫一刀『切断』就是决定；make a decision 做决定，decision-making 决策。\",\n\"heuristic\":\"画面：出门带不带伞？看天色、闻风向，三秒拍板——heuristic「启发式的（捷径）」。它来自希腊『我发现了』（尤里卡同根）：不保精确但够快的经验法则；心理学讲它常和 bias（偏差）一起出现。\",\n\"stereotype\":\"画面：新同学刚开口，众人已在心里给他贴好标签——stereotype「刻板印象」。stereo-（立体）+ type 本是印刷的『铅版』：用一块固定版子印所有人；社会心理讲偏见必提它。\",\n\"prejudice\":\"画面：法官还没听证据，心里已经判了——prejudice「偏见」。pre-（预先）+ jud『判断』（judge 法官）：审理之前先下判断；它比 stereotype 多一层情感好恶，是歧视的前一步。\",\n\"belief\":\"画面：他把那句话写在墙上，每天起床先看一遍——belief「信念；相信的事」。believe 的名词：心里认定为真的命题；心理学里 belief 和 attitude（态度）、value（价值观）三件套一起出现。\",\n\"value\":\"画面：天平一端放金子，一端放自由，他毫不犹豫选了后者——value「价值观；（价值）」。心理语境里它常是复数 values：一个人心里『什么最值钱』的排序；作动词是『重视』。\",\n\"conformity\":\"画面：一排人齐刷刷举手，新来的那个犹豫一下也举了——conformity「从众」。conform（遵从）+ -ity：行为向群体看齐的现象；阿希线段实验是它的经典画面：明知错也跟多数派。\",\n\"obedience\":\"画面：实验里老师让加电压，被试一次次按下开关——obedience「服从」。obey（服从）的名词：对权威指令的执行；米尔格拉姆电击实验专讲它——普通人会对权威服从到什么程度。\",\n\"leadership\":\"画面：队伍迷路时，有人站上高处指方向，众人跟上——leadership「领导力」。leader（领路人）+ -ship（资格、状态）：带队的人具备的那套本事；leadership style 领导风格是管理学讲座常客。\",\n\"cooperation\":\"画面：四个人各抬桌子一角，步子齐了桌子稳稳移动——cooperation「合作」。co-（一起）+ oper『工作』（operate 操作）：一起干活；和 competition（竞争）相对，博弈论里反复出现。\",\n\"competition\":\"画面：跑道上八个人同时冲出起跑线——competition「竞争」。com- + pet『奔向、寻求』（appetite 食欲同根）：大家奔向同一个稀缺目标；compete 竞争，competitor 对手。\",\n\"altruism\":\"画面：洪水里他把唯一的救生圈推给了不认识的孩子——altruism「利他主义」。alter 是『他人』：心里装着『他人』的行为，不求回报地帮人；亲缘选择 kin selection 与它成对讲。\",\n\"reinforcement\":\"画面：鸽子啄对按钮就掉一粒食，啄得越来越准——reinforcement「强化」。re- + inforce『加强』：让行为更强的后果；给奖励是正强化 positive reinforcement，斯金纳箱的灵魂词。\",\n\"punishment\":\"画面：孩子摔了碗，妈妈罚他站墙角——punishment「惩罚」。punish 的名词：让行为减少的后果，和 reinforcement（让行为增加）相对；心理学强调它副作用一堆，不等于纪律本身。\",\n\"reward\":\"画面：终点线旁，冠军咬着金牌笑——reward「奖励；报酬」。它本义是『回望、答谢』：好行为换来的回报；心理学实验里食物、分数、金钱都是 reward，和 reinforcement 形影不离。\",\n\"extinction\":\"画面：按了十次按钮都不掉食，鸽子慢慢不再啄了——extinction「（行为）消退」。这里不是物种灭绝！条件反射语境里，刺激不再带来后果，反应逐渐消失；读心理学文章最容易栽在这个义项上。\",\n\"conditioning\":\"画面：每天喂食前摇铃，第十天光摇铃狗就流口水——conditioning「条件反射（形成）」。condition 在这里是动词『使形成条件』：经典条件反射 classical、操作性条件反射 operant 两大类，心理学必考。\",\n\"generalization\":\"画面：被大狗吓过的孩子，看见小狗也往后躲——generalization「泛化」。general（普遍的）+ -ization：把对一个刺激的反应推广到相似刺激上；和 discrimination（辨别）是条件反射的一对反义过程。\",\n\"discrimination\":\"画面：训练后鸽子只啄绿灯、红灯坚决不啄——学会了分——discrimination「辨别」。心理语境是这个中性义：区分相似刺激；社会语境才是『歧视』——一篇讲座里先看上下文再定。\",\n\"threshold\":\"画面：水声开到第 7 格，他才刚好听见——threshold「阈限；门槛」。thresh 本是『 threshing 打谷的门槛石』：跨过这条线才有感觉；absolute threshold 绝对阈限：50% 概率能察觉的最小刺激。\",\n\"sensory\":\"画面：五种感官的图标排成一排：眼、耳、鼻、舌、身——sensory「感觉的；感官的」。sens- 是『感觉』：sensory memory 感觉记忆（信息第一站，只停留一瞬）、sensory receptor 感受器，认知章节必备。\",\n\"olfactory\":\"画面：他闭眼闻了闻，立刻说出是妈妈炖的汤——olfactory「嗅觉的」。olfact- 源于拉丁『闻』：olfactory bulb 嗅球；五感形容词里它最生僻，托福偏爱拿它出听力细节题。\",\n\"gustatory\":\"画面：舌尖刚碰到柠檬，他整张脸皱起来——gustatory「味觉的」。gust 是『品尝』（disgust 厌恶的字面是『坏味道』）：gustatory system 味觉系统，和 olfactory（嗅觉）成对出现。\",\n\"tactile\":\"画面：盲人指尖划过盲文凸点，读出整行字——tactile「触觉的」。tact 是『触碰』（contact 接触）：靠摸来感知；tactile feedback 触觉反馈，科技类文章也常用。\",\n\"illusion\":\"画面：两条等长的线，加了箭头看起来一长一短——illusion「错觉」。il- + lud『玩耍、戏弄』（prelude 前奏）：感官被『戏弄』了；缪勒-莱耶错觉图是心理学课本封面常客。\",\n\"delusion\":\"画面：他坚信邻居在监视自己，拿出多少证据都不动摇——delusion「妄想」。de- + lud『戏弄』：被错误信念『耍』住且不可纠正，是精神症状；和 illusion（人人都会有的错觉）要分清程度。\",\n\"obsession\":\"画面：他出门前反复确认门锁，走到楼下又折返三次——obsession「强迫观念」。ob- + sess『坐』（session 坐下来开会）：一个念头赖在脑子里『坐着不走』；obsessive-compulsive 强迫症的前半。\",\n\"compulsion\":\"画面：明知道手已经洗破皮，还是停不下来地洗——compulsion「强迫行为」。com- + puls『推』（pulse 脉搏的推力）：像被一股力量推着、不得不做的动作；和 obsession（念头）配成强迫症全貌。\",\n\"counseling\":\"画面：一间安静的咨询室，来访者慢慢说起积压多年的事——counseling「（心理）咨询」。counsel 是『商议、忠告』：咨询师不直接给答案，而是陪你梳理；school counseling 校园咨询，校园讲座高频场景。\",\n\"psychoanalysis\":\"画面：来访者躺在长沙发上自由联想，分析师在身后记录——psychoanalysis「精神分析」。psycho-（心理）+ analysis（分析）：弗洛伊德的招牌疗法，靠梦和自由联想挖潜意识；校园心理学史必讲。\",\n\"relaxation\":\"画面：瑜伽垫上他跟着引导放慢呼吸，肩膀一点点松下来——relaxation「放松」。re- + lax『松』（laxative 泻药的 lax）：把绷紧的弦松开；relaxation training 放松训练是对付焦虑的常用技术。\",\n\"coping\":\"画面：考试砸了他没躺平，而是拆解错题逐个补——coping「应对」。cope 源于『交手、搏斗』：和压力『过招』的办法；problem-focused coping 直面问题型，emotion-focused 先处理情绪型，是健康心理考点。\",\n\"resilience\":\"画面：橡皮筋被拉到极限，松手又弹回原样——resilience「心理韧性」。re- + sil『跳回』（salient 跳出来的）：遭遇打击后『弹回来』的能力；儿童心理讲座里，逆境中长好的孩子就靠它。\",\n\"self-esteem\":\"画面：镜子前他挺直腰板：『这次我做得不错。』——self-esteem「自尊」。esteem 是『评价、尊重』（estimate 估计同根）：自己给自己开的『估价单』；高低自尊影响社交，是发展心理常客。\",\n\"identity\":\"画面：毕业那年他反复问自己：我要成为什么样的人？——identity「身份认同」。idem 是拉丁『相同』：回答『我和谁是一类、我是谁』；埃里克森说青春期就是 identity 的危机与确立期。\",\n\"adolescence\":\"画面：中学校园里，个子蹿高、心里却忽晴忽雨的一群少年——adolescence「青春期」。它源于拉丁『长大』：从儿童长向成人的过渡带；puberty（生理青春期）和它常被对比出题。\",\n\"development\":\"画面：从翻身、爬行到走路，宝宝每月解锁新技能——development「发展」。de- + velop 本是『展开卷轴』：像画卷一样徐徐展开；发展心理学 developmental psychology 整门课都在讲它。\",\n\"maturation\":\"画面：果子不用催，到季节自己红透——maturation「成熟（生理）」。matur 是『熟』（mature 成熟的）：靠遗传时钟、而非练习到来的成长；和 learning（靠经验）相对，是发展课的经典对照组。\",\n\"nurture\":\"画面：同样的种子，一盆精心照料长得郁郁葱葱——nurture「后天培养；养育」。它源于拉丁『喂养』：出生之后环境与教养的塑造力；nature vs. nurture 先天与后天之争，心理学万年考点。\",\n\"nature\":\"画面：双胞胎分开抚养，长大后口味、脾气惊人地像——nature「先天因素」。心理语境里它专指遗传带来的那一半：写在基因里、出生就带来的禀赋；和 nurture（后天）成对，别按『自然』去套。\",\n\"consumer\":\"画面：一个人推着购物车在货架前挑东西，买回家吃掉、用掉——他是 consumer「消费者」。词里藏着 consume（消耗）：买来消耗的人，就是 consumer。\",\n\"resident\":\"画面：一栋居民楼亮起一排灯，每户窗后都住着人——住在这里的人就是 resident「居民」。resi- 近 re-sid-『坐下、定居』：坐下来长住的人。\",\n\"advocate\":\"画面：一个人站在台前举着标语替大家发声——他是 advocate「提倡者」。ad-（向着）+ voc（呼喊）：站出来大声呼吁的人。\",\n\"immigrant\":\"画面：一个人拖着行李箱走下飞机，护照上盖着新国家的章——他是 immigrant「移民」。im-（进入）+ migr（迁移）：迁进别国定居的人；迁出去的是 emigrant，别混。\",\n\"delegate\":\"画面：会议桌旁一个人举着代表团的铭牌发言——他是 delegate「代表」。dele- 是『派出、托付』：被派来替一群人说话的人。\",\n\"expert\":\"画面：白板前一个人三言两语解开难题，旁人连连点头——他是 expert「专家」。记 ex- 之外的高手：这一行里经验最多的人（experience 同源）。\",\n\"donor\":\"画面：献血车里一个人伸出手臂，血袋上贴着爱心标签——他是 donor「捐献者」。don- 就是『给』（donate 捐赠）：给出东西的人。\",\n\"master\":\"画面：毕业典礼上一个人接过硕士学位证书——master 在这里是「硕士」。它还有『主人、大师』义，先记学位这层：学士 bachelor 之上的一级。\",\n\"instructor\":\"画面：健身房里一个人站在队伍前面喊口令示范动作——他是 instructor「讲师；教练」。instruct 是『指导』：站在前面指导你做的人。\",\n\"mentor\":\"画面：实验室里一位年长者俯身指着数据，轻声点拨旁边的年轻人——他是 mentor「导师」。不是上大课的老师，是手把手带你的那个人。\",\n\"principal\":\"画面：开学典礼上站在全校师生面前致辞的那个人——principal「校长」。它也是形容词『主要的』：学校里最主要的那个人，就是校长。\",\n\"alumni\":\"画面：校庆日一群人戴着校友徽章回到老教学楼前合影——他们是 alumni「校友」。注意这是复数：一群已毕业的人；单个校友是 alumnus。\",\n\"reference\":\"画面：申请表最后一栏，一个人提笔写下愿意替你说好话的名字——那个人是 reference「推荐人」。refer 是『提及、引荐』：能替你作保被提及的人。\",\n\"producer\":\"画面：片场里一个人拿着通告单统筹全场——producer「制片人；生产者」。produce 是『生产、制作』：把东西生产出来、把片子制出来的人。\",\n\"merchant\":\"画面：集市摊位后一个人掀开货布，称秤算账——他是 merchant「商人」。merch- 和 merchandise（商品）同根：跟商品打交道买卖的人。\",\n\"entrepreneur\":\"画面：一个人把积蓄押进一间小店，亲手挂上招牌——他是 entrepreneur「企业家」。法语词，核心画面是『自己动手开创事业的人』，重音在最后的 -neur。\",\n\"employee\":\"画面：早晨一群人刷工牌走进办公楼——他们是 employee「雇员」。结尾 -ee 表示『被…的人』：被雇（employ）来上班的人；雇人的一方是 employer。\",\n\"employer\":\"画面：面试桌对面坐着决定录不录用你的人——employer「雇主」。结尾 -er 是『做事的人』：雇（employ）别人的人，和 employee 正好相对。\",\n\"citizen\":\"画面：投票站里一个人把选票投进箱子——他是 citizen「公民」。citi- 和 city 同根：属于这个国家、享有权利的『城里人』。\",\n\"attorney\":\"画面：法庭上一个人站在当事人身边，拿着卷宗起身陈述——attorney「律师；代理人」。美式说法，等于 lawyer；记住法庭上替你说话的这个人。\",\n\"defendant\":\"画面：法庭被告席上坐着一个人，对面的指控一条条念出来——他是 defendant「被告」。defend 是『辩护』：需要为自己辩护的那一方。\",\n\"plaintiff\":\"画面：法庭上先站起来陈述『我受了损失』的人——plaintiff「原告」。plain- 近 complain（抱怨、控诉）：先开口告状、要求赔偿的一方，和 defendant 相对。\",\n\"witness\":\"画面：法庭证人席上一个人举手宣誓，复述自己亲眼看到的事——witness「证人」。wit- 是『知道、看见』：亲眼见过、能作证的人。\",\n\"candidate\":\"画面：竞选海报上一个人的照片下写着名字，等着选民打勾——candidate「候选人」。古罗马候选人穿白袍（candid 白）拉票：等着被选的那个人。\",\n\"minister\":\"画面：新闻发布台上一个人对着话筒宣布新政策——minister「部长」。它也有『牧师』义；托福里多是政府部门的一把手，如教育部的 minister。\",\n\"premier\":\"画面：电视新闻里一国政府首脑走下飞机舷梯——premier「总理；首相」。premi- 是『第一』（premier 第一的）：政府里排第一的人。\",\n\"official\":\"画面：窗口后一个人拿起公章，在文件上重重盖下——official「官员」。office（办公室、职位）+ -ial：在机关里任职办事的人。\",\n\"nomad\":\"画面：草原上一个牧人赶着羊群，帐篷拆了装上马背继续走——nomad「游牧者」。no- 不是『没有』：他的特点就是没有固定住所、逐水草而行。\",\n\"settler\":\"画面：一家人把木屋搭在新开垦的土地上，钉下第一块门牌——settler「定居者」。settle 是『安顿下来』：迁来并定居下来的人，和 nomad 正相反。\",\n\"slave\":\"画面：古罗马市场上一个人手脚带着锁链，低头等待买主——slave「奴隶」。记住这沉重的一幕：失去自由、被迫劳役的人；废奴是 abolish slavery。\",\n\"archer\":\"画面：靶场上一个人拉满长弓，眯眼瞄准靶心——archer「弓箭手」。arch 是『弓』（弓形）：用弓的人，-er 是『做…的人』。\",\n\"scribe\":\"画面：古埃及神庙里一个人跪坐着，在莎草纸上一行行抄字——scribe「抄写员」。scrib- 是『写』（describe 的 scrib）：印刷术之前专职抄写的人。\",\n\"pilgrim\":\"画面：山路上一个背着行囊的人拄杖走向远方的圣殿——pilgrim「朝圣者」。pil- 记『远行』画面：为了信仰长途跋涉的人。\",\n\"model\":\"画面：T 台上一个人迈着台步展示新装——model 在这里是「模特」。它还可指『模型、典范』：托福听力里若在时装语境，就是这个人。\",\n\"sculptor\":\"画面：工作室里一个人举着凿子，石像的轮廓一点点显出来——sculptor「雕塑家」。sculpt 是『雕刻』：拿凿子的人，结尾 -or 和 actor 一样是『做事的人』。\",\n\"protagonist\":\"画面：一部小说的第一章，镜头始终追着的那个人——protagonist「主角」。proto- 是『第一』：全故事排第一重要的人物。\",\n\"narrator\":\"画面：有声书里传来一个声音，缓缓讲着『那天傍晚……』——narrator「叙述者」。narrate 是『讲述』：讲故事的那个声音本人。\",\n\"poet\":\"画面：月夜窗前一个人在稿纸上写下一行行短句——poet「诗人」。poem 是『诗』这件作品，poet 是写诗的人，poetry 是诗的总称，三词别混。\",\n\"user\":\"画面：一个人滑动手机屏幕点开 App——他是 user「用户」。use（使用）+ -er：使用产品的人；产品说明书里最常出现的主角。\",\n\"acquaintance\":\"画面：聚会上一个人和你点头寒暄，你知道他的名字却叫不出共同话题——acquaintance「熟人」。acquaint 是『结识』：认识但不熟的人，和 friend 有程度差。\",\n\"alien\":\"画面：夜空飞碟旁站着一个大眼睛的绿色身影——alien「外星人」。它也可作形容词『陌生的、外来的』：来自别处、不属于这里的存在。\",\n\"amateur\":\"画面：周末球场上一个人球技生疏却打得开心——amateur「业余爱好者」。词源是『爱』（法语 aimer）：因为热爱而做、不靠它吃饭的人，和 professional 相对。\",\n\"analyst\":\"画面：屏幕前一个人盯着曲线图，在拐点处画下记号——analyst「分析师」。analyze（分析）+ -ist（做…的人）：靠拆解数据下判断的人。\",\n\"anthropologist\":\"画面：田野里一个人蹲在部落篝火旁记笔记，记录婚俗和语言——anthropologist「人类学家」。anthropo- 是『人类』+ -logist『研究…的人』：研究人类社会的人。\",\n\"applicant\":\"画面：窗口前一个人双手递上填好的表格，等着被审核——applicant「申请人」。apply 是『申请』：递了申请、等结果的人；那张表叫 application。\",\n\"archaeologist\":\"画面：探方里一个人蹲着用小刷子扫去陶片上的土——archaeologist「考古学家」。archaeo- 是『古代的』：从土里挖古代遗迹来研究的人。\",\n\"architect\":\"画面：绘图桌前一个人铺开蓝图，楼的轮廓跃然纸上——architect「建筑师」。archi- 是『 chief 首要』+ tect『建造者』：画图纸定方案的人，盖楼的另有其人。\",\n\"assistant\":\"画面：办公桌旁一个人抱着文件，替主管安排日程——assistant「助理」。assist 是『协助』：站在旁边帮忙打下手的人。\",\n\"astronomer\":\"画面：山顶天文台里一个人整夜守着望远镜记录星轨——astronomer「天文学家」。astro- 是『星』（astronaut 的 astro）：研究星星的人，在地面观测；上天的是 astronaut。\",\n\"attendant\":\"画面：飞机客舱里一个人推着餐车逐排询问——attendant「服务员；乘务员」。attend 有『照料、出席』义：在场照料你的人，如 flight attendant 空乘。\",\n\"author\":\"画面：书桌前一个人在键盘上敲下最后一章，封面印上他的名字——author「作者」。auth- 记『原创』：写出这本书的人；authority（权威）同源。\",\n\"waiter\":\"画面：餐厅里一个人托着托盘穿梭桌间——waiter「服务员」。wait 在这里不是『等』：老义是『侍奉』；托盘上桌的人，女服务员是 waitress。\",\n\"fisherman\":\"画面：清晨码头上一个人撒网，渔船满载而归——fisherman「渔民」。fisher（捕鱼）+ man（人）拼起来就是这个词，读音跟着拼法走。\",\n\"hunter\":\"画面：林间一个人端着弓，脚步放得极轻——hunter「猎人」。hunt 是『打猎』这个动作，+ -er 变成做这件事的人。\",\n\"clerk\":\"画面：柜台后一个人低头登记表格、整理单据——clerk「职员；店员」。记柜台画面：做文书、登记工作的人，如 bank clerk 银行职员。\",\n\"cashier\":\"画面：收银台后一个人扫码、找零，钱箱叮当响——cashier「收银员」。cash 是『现金』：坐在钱箱旁收钱的人。\",\n\"salesman\":\"画面：展厅里一个人陪着顾客试车、讲解配置——salesman「推销员」。sales（销售）+ man：靠把东西卖出去工作的人。\",\n\"tailor\":\"画面：裁缝铺里一个人拿软尺量顾客的肩宽，粉笔在布上画线——tailor「裁缝」。它也可作动词『量身定制』：围着人和布打转的职业。\",\n\"barber\":\"画面：理发椅旁一个人拿着推剪，围布上落下碎发——barber「理发师（男士）」。barb- 和 beard（胡子）同源：给男士理发修面的人；美发沙龙里是 hairdresser。\",\n\"hairdresser\":\"画面：美发沙龙里一个人举着吹风机，镜前顾客的头发渐渐成型——hairdresser「美发师」。hair（头发）+ dresser（打理者）：打理头发造型的人。\",\n\"mathematician\":\"画面：黑板前一个人写满公式，最后在等号后写下答案——mathematician「数学家」。mathematics（数学）+ -ian（从事…的人）：以数学为业的人。\",\n\"physicist\":\"画面：实验室里一个人盯着粒子轨迹照片做标记——physicist「物理学家」。physics（物理）变形 + -ist：研究物质与能量规律的人。\",\n\"chemist\":\"画面：实验台前一个人举着试管，液体正变色冒泡——chemist「化学家」。chemistry（化学）+ -ist：在瓶瓶罐罐间研究物质变化的人；英式也可指药剂师。\",\n\"biologist\":\"画面：显微镜前一个人调整焦距，盯着载玻片上的细胞——biologist「生物学家」。bio- 是『生命』：研究一切活物的人。\",\n\"historian\":\"画面：档案馆里一个人戴着手套翻开泛黄的卷宗——historian「历史学家」。history（历史）+ -ian：研究过去、写历史的人。\",\n\"economist\":\"画面：一个人指着大屏幕上的经济曲线向记者解释——economist「经济学家」。economy 是『经济』这盘棋，economist 是研究这盘棋的人。\",\n\"politician\":\"画面：议会厅里一个人起身发言，镜头齐刷刷转过去——politician「政治家；政客」。politics（政治）+ -ian：从政的人，略带贬义时指政客。\",\n\"journalist\":\"画面：发布会现场一个人举着录音笔追问——journalist「记者」。journal 原是『日报』：为报纸、新闻跑现场写报道的人。\",\n\"reporter\":\"画面：暴雨街头一个人对着镜头直播，身后是积水的主干道——reporter「记者（出镜）」。report 是『报道』：站在现场把消息报回来的人。\",\n\"editor\":\"画面：深夜办公室里一个人对着稿子划改，红笔圈满段落——editor「编辑」。edit 是『编辑、修改』：定稿前把关修改的人。\",\n\"novelist\":\"画面：咖啡馆角落一个人对着笔记本写长篇，人物关系图贴满墙——novelist「小说家」。novel 是『小说』：写长篇小说的人，比 author 更专一。\",\n\"dancer\":\"画面：舞台灯光下一个人踮起脚尖旋转——dancer「舞者」。dance（跳舞）+ -er：以跳舞为业或所长的人。\",\n\"designer\":\"画面：工作台前一个人拖动鼠标调整海报的版式——designer「设计师」。design 是『设计』这个动作和图纸，+ -er 是做设计的人。\",\n\"programmer\":\"画面：双屏前一个人敲着代码，运行结果一点点变绿——programmer「程序员」。program 在这里是『程序』：写程序的人，美式拼写 programmer 双 m。\",\n\"developer\":\"画面：一个人把新版本软件发布上线，用户量曲线往上走——developer「开发人员」。develop 是『开发、发展』：把产品从无到有做出来的人，也可指房地产开发商。\",\n\"technician\":\"画面：一个人打开机柜，用仪器逐项检测故障点——technician「技术员」。techni- 是『技术』：靠手上技术活吃饭、负责维修调试的人。\",\n\"operator\":\"画面：控制室里一个人守着仪表盘，随时转动旋钮——operator「操作员」。operate 是『操作、运转』：守着机器让它运转的人；电话里则是接线员。\",\n\"lifeguard\":\"画面：泳池边高椅上一个人吹着哨子，目光扫过水面——lifeguard「救生员」。life（生命）+ guard（守护）：守护生命的人，词本身就是画面。\",\n\"coach\":\"画面：球场边一个人掐着秒表喊『再快一点』——coach「教练」。它也是『长途客车』：托福里看语境，体育语境就是场边这位。\",\n\"leader\":\"画面：队伍最前面一个人举着旗，后面的人跟着他的方向走——leader「领袖；领导者」。lead 是『带领』：走在最前面带路的人。\",\n\"chief\":\"画面：部落空地上坐在中央的一位长者，众人等他发话——chief「首领；最高负责人」。它也可作形容词『主要的』：排在最前、最主要的那个人或事物。\",\n\"boss\":\"画面：办公室里一个人拍板『就这么定』，众人点头执行——boss「老板」。短词重音干脆：发号施令、说了算的人。\",\n\"senator\":\"画面：议会上院里一个人投下庄重的一票——senator「参议员」。senat- 和 senate（参议院）一起记：坐在参议院里的人。\",\n\"representative\":\"画面：大会会场里一个人举起写着地区名的牌子——representative「代表」。re-present『再次呈现』：替一群人出面呈现意见的人；也是形容词『有代表性的』。\",\n\"volunteer\":\"画面：社区活动里一个人戴着红袖标维持秩序，不领报酬——volunteer「志愿者」。volunt- 是『自愿』（voluntary）：自愿出力的人，也作动词『自愿做』。\",\n\"activist\":\"画面：广场上一个人举着牌子，和人群一起喊出诉求——activist「活动家；积极分子」。active（积极的）+ -ist：为某个主张积极奔走的人。\",\n\"inventor\":\"画面：车库工作台前一个人举起刚装好的小装置，灯亮了——inventor「发明家」。invent 是『发明』：第一个把新东西做出来的人，如爱迪生。\",\n\"founder\":\"画面：老照片里一个人站在公司第一间办公室门口——founder「创始人」。found 在这里是『创立』（不是 find 的过去式）：把机构从零创立的人。\",\n\"broker\":\"画面：交易大厅里一个人对着电话快速报价，替客户买卖股票——broker「经纪人」。记『中间人』画面：不拥有货物，只替买卖双方牵线抽佣的人。\",\n\"guest\":\"画面：一个人被迎进门，主人端上茶点——guest「客人」。注意拼写 gu- 开头：被邀请来作客的人；节目里则是嘉宾。\",\n\"host\":\"画面：晚宴上一个人起身举杯欢迎大家——host「主人；主持人」。既是请客的人，也是节目里串场的人；和 guest 正好一对。\",\n\"pedestrian\":\"画面：斑马线上一个人等绿灯亮起才迈步——pedestrian「行人」。ped- 是『脚』（pedal 踏板同根）：用脚走路过街的人；作形容词是『平淡的』。\",\n\"stranger\":\"画面：小镇车站里一张谁也不认识的面孔拖着箱子走过——stranger「陌生人」。strange 是『奇怪的、陌生的』：没见过、不认识的人。\",\n\"neighbor\":\"画面：隔壁院子的人隔着篱笆和你打招呼——neighbor「邻居」。neigh- 近 near（近）：住得近的人，美式拼写 neighbor，英式 neighbour。\",\n\"prisoner\":\"画面：铁栏后一个人望着高墙上的小窗——prisoner「囚犯」。prison 是『监狱』：被关在监狱里的人；war prisoner 是战俘。\",\n\"victim\":\"画面：事故现场一个人裹着毯子坐在救护车旁，惊魂未定——victim「受害者」。记这个无助的画面：在事件中遭受损害的一方。\",\n\"suspect\":\"画面：审讯室里一个人坐在强光下，侦探盯着他问话——suspect「嫌疑人」。作名词时重音在前 sus-：被怀疑做了坏事、但还没定罪的人；作动词重音在后。\",\n\"wizard\":\"画面：尖顶帽下一个人挥动魔杖，杖尖冒出火花——wizard「巫师；男巫」。奇幻语境的词；也可喻指某领域的高手，如电脑 wizard。\",\n\"lord\":\"画面：中世纪城堡大厅里一个人坐在高背椅上，仆人躬身听命——lord「勋爵；领主」。英国贵族称号；大写 Lord 也用于称上帝或法官。\",\n\"clown\":\"画面：马戏团里一个人戴着红鼻子故意摔跤，孩子们笑成一片——clown「小丑」。记住红鼻子：逗人发笑的表演者。\",\n\"escort\":\"画面：重要人物身旁一个人贴身随行，警惕地环顾四周——escort「护送者；护卫」。作动词是『护送』：陪在旁边保护着走的人。\",\n\"eyewitness\":\"画面：案发现场围观人群里一个人站出来说『我全看见了』——eyewitness「目击者」。eye（眼睛）+ witness（证人）：用自己的眼睛亲眼看见的人。\",\n\"area\":\"画面：一张地图上用红笔圈出一块地——圈住的那一片就是 area。先记具体的『地区、面积』，再记引申的『领域』：都是『一片范围』。\",\n\"authority\":\"画面：讲台上所有人都安静听一个人讲话，因为他是这个领域说了算的人——authority「权威」。author（作者、源头）+ -ity：话从源头出，所以有权威；也可指当局。\",\n\"available\":\"画面：货架上贴着『有货』，伸手就能拿到——available「可获得的」。avail 是『有用、可用』：摆在那里能被你用上的状态。\",\n\"benefit\":\"画面：一个人拆开福利信封，里面是补贴和假期——benefit「益处；福利」。bene- 是『好』（benevolent 仁慈的同根）：对你有好处的东西。\",\n\"consistent\":\"画面：十次称重，秤上的数字每次都是同一个——consistent「一致的」。con-（一起）+ sist（站立）：每次都站在同一个位置，不自相矛盾。\",\n\"context\":\"画面：一句话被单独剪下来贴在墙上看不懂，放回整段文字里立刻明白——context「背景；上下文」。con-（一起）+ text（文本）：和文字在一起的那些 surrounding 信息。\",\n\"contract\":\"画面：两个人隔桌签字，纸上条款一条条列明——contract「合同」。con-（一起）+ tract（拉）：把双方拉到一起绑定的约定；作动词重音后移，还有『感染；收缩』义。\",\n\"create\":\"画面：空画布前一个人落下第一笔，平地起了一幅画——create「创造」。从无到有地做出新东西，比 make 更强调『首创』。\",\n\"data\":\"画面：实验记录本上密密麻麻的数字等待分析——data「数据」。datum 的复数：一个个被测量、记录下来的事实，是结论的地基。\",\n\"definition\":\"画面：词典里一条释义被黄笔划出，边界清清楚楚——definition「定义」。de-（完全）+ fin（边界，如 finish）：把一个词的边界划清楚的话。\",\n\"derived\":\"画面：一条河从源头分出支流，支流水来自主流——derived「源自的」。derive 是『起源于』：从某个源头流出来的东西带着源头的印记。\",\n\"distribution\":\"画面：仓库里一箱箱货被分送到各家门店的货架上——distribution「分布；分配」。dis-（分开）+ tribute（给予）：把东西分散送出去，落点图就是分布图。\",\n\"environment\":\"画面：一条鱼周围的水、礁石、水草合起来就是它的 environment「环境」。environ- 是『环绕』：环绕着生物或人的一切外部条件总和。\",\n\"evidence\":\"画面：法庭上律师把物证袋举起来给陪审团看——evidence「证据」。e-（向外）+ vid（看，如 video）：摆出来能被看见、用来说话算数的东西。\",\n\"export\":\"画面：港口吊车把集装箱装上远洋货轮，驶向别国——export「出口」。ex-（向外）+ port（搬运）：把货运出国门；反方向是 import 进口。\",\n\"factor\":\"画面：一道结果大题被拆成几个相乘的小项，其中一项被圈出——factor「因素」。既是数学里的『因数』，也是现实里的『促成因素』：起作用的那一项。\",\n\"financial\":\"画面：银行大楼玻璃幕墙里，报表和货币符号在屏幕上滚动——financial「金融的」。fin- 和 finance（金融）一起记：和钱、银行、投资有关的。\",\n\"formula\":\"画面：黑板上写着 H₂O 这样的式子，人人照着就能算——formula「公式」。form 是『形式、格式』：被固定成标准形式的一串符号；婴儿奶粉也叫 formula（配方）。\",\n\"function\":\"画面：一台机器贴着说明：『本机负责加热』——function「功能」。也可作动词『运转』：它被造出来是干什么的，它正常干活就是 functioning。\",\n\"indicate\":\"画面：仪表盘上一根指针缓缓偏向红区，驾驶员立刻警觉——indicate「表明；指示」。in- + dic（说，如 dict）：像指针在『说』出状态，不用开口就表明了。\",\n\"individual\":\"画面：合唱团里镜头单独推近其中一张脸——individual「个体的；个人」。in-（不）+ divid（分割）：不可再分割的最小单位，就是单个的人。\",\n\"interpretation\":\"画面：同一幅抽象画，两个人站在前面说出完全不同的理解——interpretation「解释；阐释」。interpret 是『解读』：把原文/数据读出意思来的那个版本。\",\n\"major\":\"画面：乐队里最响亮的声部被标成粗体——major「主要的」。它也是大学生的『专业』：份量最重的那一部分；和 minor（次要的）相对。\",\n\"method\":\"画面：实验手册上编号 1、2、3 的步骤，谁照着做都能重复出结果——method「方法」。希腊 meta（沿着）+ hodos（路）：沿着一条有序的路做事的方式。\",\n\"occur\":\"画面：日历上某一天突然被红圈标出：那天发生了一件事——occur「发生」。也可指『被想起』（It occurred to me）：事情冒出来、念头冒出来，都是 occur。\",\n\"percent\":\"画面：一个圆饼被切成 100 份，取走的 25 份涂上颜色——percent「百分比」。per（每）+ cent（百，如 century）：每一百里占多少。\",\n\"policy\":\"画面：公司白板上贴出成文规定：『迟到三次扣奖金』——policy「政策」。政府、公司定下的成文方针；保险单也叫 policy，别在听力里愣住。\",\n\"principle\":\"画面：一个人面对诱惑摇头：『这违背我的原则』——principle「原则」。也可指科学『原理』：像地基一样不轻易动的基本准则；注意别和 principal（校长）混拼写。\",\n\"procedure\":\"画面：手术前核查清单一项项打勾，顺序一步都不能乱——procedure「程序；步骤」。proceed 是『按步进行』：照着规定一步步走的过程。\",\n\"process\":\"画面：流水线上原料从一端进去，经过冲压、组装，从另一端出来成了产品——process「过程」。也可作动词『加工、处理』：一步步向前（pro-）推进的变化链。\",\n\"response\":\"画面：老师提问，学生举手应答——response「回应」。re-（回）+ spons（承诺、回答）：对刺激、问题作出的回话或反应；respond 是动词形。\",\n\"role\":\"画面：剧本上每个名字后面写着他要演的人物——role「角色」。也可指抽象的『作用』：在整件事里，你站的是哪个位置、担什么任务。\",\n\"section\":\"画面：一本书被书签分成几大块，其中一块被荧光笔标出——section「部分」。sect- 是『切』（insect 昆虫身体分节）：被切出来的一段。\",\n\"sector\":\"画面：一张城市地图按颜色分成工业区、商业区、居住区——sector「部门；区域」。同样源于『切』：经济或城市被切出的一块专业领地。\",\n\"significant\":\"画面：曲线图上一个拐点被红笔重重圈出：这个变化不能忽略——significant「重要的；显著的」。sign（迹象）+ fic（使）：发出明确信号的，统计里还指『显著的』。\",\n\"source\":\"画面：河流的源头，一股泉水从石缝里涌出——source「来源」。新闻的『消息来源』、论文的『文献来源』都是它：东西最初冒出来的地方。\",\n\"specific\":\"画面：订单备注栏写清『要 3 号电池，不要 5 号』——specific「具体的」。speci- 和 species（物种）同根：明确到是哪一种、哪一个，不含糊。\",\n\"variable\":\"画面：天气 App 上温度数字一天三变——variable「变量；可变的」。vari- 是『变』（vary 变化）：会变的量；实验里被操纵的那个是 independent variable。\",\n\"administration\":\"画面：大楼里一层层办公室，文件在科室之间流转审批——administration「管理；行政」。administer 是『管理执行』：管人管事的整套机构与工作；也可指政府班子。\",\n\"affect\":\"画面：一场暴雨过后，河水暴涨淹了农田——天气 affect（影响）了收成。记住它是动词『去影响别人』；名词『效果』多是 effect，别写反。\",\n\"appropriate\":\"画面：面试者穿上正装走进写字楼——场合对了，着装就 appropriate「适当的」。它还可作动词『拨款；挪用』重音在末尾 -ate：托福阅读多取形容词义。\",\n\"aspect\":\"画面：一颗钻石转动，每一面折射不同的光——aspect「方面」。a- + spect（看）：从某个角度看過去的那一面；谈一件事要分几个 aspect 来看。\",\n\"assistance\":\"画面：老人上台阶时，一只手稳稳扶住他的胳膊——assistance「协助」。assist（帮助）+ -ance：伸手帮忙这件事本身，比 help 更正式。\",\n\"category\":\"画面：图书馆书架按标签分区：小说、历史、科学各就各位——category「类别」。每个 category 是一个筐，同类东西放进同一个筐。\",\n\"credit\":\"画面：信用卡在 POS 机上一刷，机器先替你付了钱——credit「信贷；信用」。cred- 是『相信』（credible 可信的）：因为信你，先把钱借你用；学分、荣誉也叫 credit。\",\n\"design\":\"画面：建筑师在图纸上画下还没盖的楼——design「设计」。de- + sign（标记）：先在纸上把标记画出来；作动词是『设计、构思』。\",\n\"distinction\":\"画面：老师把两个易混词写在黑板两边，中间画一条粗线——distinction「区别」。distinct 是『明显的、不同的』：能清楚分开的那条界线；也指『卓越』如 with distinction。\",\n\"document\":\"画面：一份盖了章的文件被装进档案袋——document「文件」。doc- 和 doctor、doctrine 同源于『教、示』：写下来能作凭据的正式纸面材料；动词是『记录』。\",\n\"domestic\":\"画面：机场大厅两块牌子：『国内航班』和『国际航班』——domestic「国内的」。dom- 是『家』（dome 家顶）：家里的、国境之内的；也有『家用的、驯养的』义。\",\n\"emphasis\":\"画面：演讲者说到关键词时突然加重语气、放慢速度——emphasis「强调」。em- + pha（显现）：把某一点用力显出来；动词 emphasize，复数 emphases。\",\n\"ensure\":\"画面：出门前一个人回头检查门锁，又推了推确认锁好——ensure「确保」。en- + sure（确定）：动手让结果『确定』发生，比保证结果的 insure（保险）适用面更广。\",\n\"equation\":\"画面：天平两端放着砝码，指针正好居中——equation「等式」。equa- 是『相等』（equal）：等号两边相等的那条式子；也可引申为『需要权衡的因素组合』。\",\n\"feature\":\"画面：新手机发布会上，大屏幕逐条打出亮点——feature「特征；卖点」。也可作动词『以…为特色』：让一件东西被认出来的那几个显著点。\",\n\"focus\":\"画面：相机镜头转动，画面从模糊变清晰，焦点锁在花蕊上——focus「焦点；聚焦」。拉丁语原是『炉火』：光和注意力汇聚的那一点。\",\n\"institute\":\"画面：一栋挂着『研究所』牌子的建筑，学者进进出出——institute「机构；研究所」。也可作动词『设立、制定』：被正式立起来的机构。\",\n\"item\":\"画面：购物小票上一行行列着买的东西，其中一行被圈出——item「物品；条目」。清单上的一项就是一个 item：新闻条目、拍卖品都用它。\",\n\"journal\":\"画面：学者把最新论文投给一本厚厚的学术刊物——journal「期刊」。原是『日报、日记』（jour 是『日』）：定期刊登研究的刊物，也可指个人日记。\",\n\"maintenance\":\"画面：工人定期给电梯换零件、加润滑油，让它不坏——maintenance「维护；保养」。maintain（保持）+ -ance：让机器、建筑保持能用的日常照料。\",\n\"normal\":\"画面：体检表上各项数值都落在参考区间里——normal「正常的」。norm 是『标准、准则』：落在标准范围内的，就是 normal。\",\n\"participation\":\"画面：一场讨论里每个人都举手发言，没人旁观——participation「参与」。part（部分）+ cip（取）：人人取一份、出一份力，就是参与。\",\n\"positive\":\"画面：化验单上盖着『阳性 +』的章——positive「积极的；阳性的」。posi- 是『放、立』：立场明确向上的；也可指确定的、肯定的。反义 negative。\",\n\"potential\":\"画面：一颗种子躺在手心，还没发芽却藏着长成大树的力——potential「潜在的；潜力」。potent 是『有力的』：力还没释放出来的状态。\",\n\"previous\":\"画面：翻相册时手指停在前一张照片上——previous「先前的」。pre-（在前）+ vi（路，如 via）：走在前面的那一个，时间上就是上一个。\",\n\"primary\":\"画面：小学门口孩子们背着书包进校——primary「首要的；初级的」。prim- 是『第一』（prime 首要的）：排第一位的，如 primary school 小学、primary cause 首要原因。\",\n\"range\":\"画面：温度计上从 -10 到 40 的一整段刻度——range「范围」。也可指『山脉、一系列』和动词『在…之间变化』：一整段连续的跨度。\",\n\"region\":\"画面：地图上一个省被涂成黄色，和邻省隔着一条河——region「地区」。reg- 是『统治、划界』：被划出来的一大片行政或地理区域，比 area 更正式、更大。\",\n\"regulation\":\"画面：工厂墙上贴着安全规章，条条编号——regulation「规章；管理」。regulate 是『调节、管理』：定下来让人遵守的成文规则；也可指『调节』。\",\n\"resource\":\"画面：地图上标着煤矿、水源、森林的图例——resource「资源」。能被拿来用的东西都是 resource：自然资源、人力资源、学习资源。\",\n\"restricted\":\"画面：门口挂着『限高 2 米』和『禁止入内』的牌子——restricted「受限的」。re- + strict（严格、拉紧）：被严格收紧、划了禁区的状态。\",\n\"select\":\"画面：自助餐台前一个人端着盘子，只夹走自己想要的几样——select「选择」。se-（分开）+ lect（挑、读，如 lecture 同源的挑选）：从一堆里挑出要的。\",\n\"site\":\"画面：工地上拉起围挡，牌子上写着『施工现场』——site「地点；现场」。网站 website 就是网上的『地点』；考古 site 是遗址现场。\",\n\"traditional\":\"画面：春节时一家人按老规矩贴春联、包饺子——traditional「传统的」。tradition 是『传统』：一代代传（trad- 交递）下来的做法。\",\n\"adapt\":\"画面：北极熊一身白毛站在雪地里，与环境融为一体——adapt「适应」。ad-（向）+ apt（合适）：把自己调整到『合』环境；改编小说也是 adapt。\",\n\"atmosphere\":\"画面：从太空看，地球裹着一层薄薄的蓝色光晕——atmosphere「大气（层）」。atmo-（蒸汽）+ sphere（球）：包着地球的气球壳；也可指场所的『气氛』。\",\n\"barrier\":\"画面：赛道上横着一道栏，跑者跃过去——barrier「障碍」。bar 是『横木、栏杆』：挡在路中间、必须跨越或拆除的那道阻隔，如语言 barrier 语言障碍。\",\n\"capacity\":\"画面： stadium 体育场座无虚席，广播说『满员』——capacity「容量；能力」。cap- 是『容纳、抓取』（capture）：一个容器、人或场所能装下、能承担的最大量。\",\n\"carbon\":\"画面：铅笔芯在纸上划出黑线，钻石在灯下闪光——它们都是 carbon「碳」。元素周期表 6 号：从石墨到钻石到 CO₂，处处有它；carbon dioxide 二氧化碳必记。\",\n\"component\":\"画面：一台电脑被拆开，主板、内存、硬盘并排摆开——component「成分；部件」。com-（一起）+ pon（放）：被放进整体里的一个组成部分。\",\n\"concentrate\":\"画面：一杯清水滴入颜料，所有颜色聚向中心一点——concentrate「集中；浓缩」。con-（一起）+ centr（中心）：把注意力或溶液都收向中心。\",\n\"conserve\":\"画面：一个人随手关掉哗哗流的水龙头——conserve「节约；保护」。con- + serv（保持，如 preserve）：把资源护住、省着用，和 consume（消耗）相对。\",\n\"consume\":\"画面：汽车加油表指针往下掉，油被一点点烧完——consume「消耗」。con- + sum（取）：把东西用光、吃光；consumer 就是消耗东西的人。\",\n\"creature\":\"画面：深海热泉旁蠕动着一只从没见过的白色小生物——creature「生物」。creat- 是『创造』（create）：被造出来的活物，从细菌到蓝鲸都算。\",\n\"density\":\"画面：同样大的盒子，一个塞满铁块重得搬不动——density「密度」。dense 是『稠密的』：单位体积里塞了多少质量或多少人（人口密度 population density）。\",\n\"dimension\":\"画面：工程师在图纸上标出长、宽、高三条线——dimension「维度；尺寸」。di- + mens（测量）：一个方向上的量；科幻里的『异次元』也是它。\",\n\"dissolve\":\"画面：一勺糖落进热水，搅拌几下不见了踪影——dissolve「溶解」。dis-（散开）+ solv（松开）：固体松开散进液体里；议会『解散』也用它。\",\n\"distinct\":\"画面：双胞胎站在一起，一个戴眼镜一个不戴，一眼能分清——distinct「明显的；截然不同的」。distinct 是『分得清』：边界清楚，不会认错。\",\n\"element\":\"画面：元素周期表墙上一个个小格子，氢、氧、碳各占一格——element「元素」。也可指『基本组成部分』：拆到不能再拆的基本单位。\",\n\"emit\":\"画面：烟囱口飘出白烟，向空中散开——emit「释放；排放」。e-（向外）+ mit（送，如 submit 交出送）：把光、气、声送到外面去。\",\n\"energy\":\"画面：闪电劈下，整座城市灯火通明——energy「能量」。物理里是做功的本领；人的『精力』也是它：能让人动起来的那股量。\",\n\"erosion\":\"画面：海浪年年拍打，海岸的岩石被啃出一道道凹痕——erosion「侵蚀」。e- + rod（啃咬，rodent 啮齿动物同根）：水和风像牙一样慢慢啃掉土地。\",\n\"evaporate\":\"画面：晾着的湿衣服到中午摸上去干了，水不见了——evaporate「蒸发」。e- + vapor（水汽）：液体变成水汽逸散；人群、希望『蒸发消失』也用它。\",\n\"evolve\":\"画面：一组连环画：鱼长出脚、爬上岸、变成猴子——evolve「演化」。e-（向外）+ volv（卷、转）：像卷轴展开一样，物种慢慢变出新样子。\",\n\"extinct\":\"画面：博物馆里只剩骨架的渡渡鸟，展牌写着『已灭绝』——extinct「灭绝的」。ex- + stinct（熄灭）：一个物种的火彻底熄了，地球上再无活体。\",\n\"fertile\":\"画面：黑土地里麦苗齐刷刷窜得老高——fertile「肥沃的」。fert- 是『生育、产出』：能长出庄稼、能孕育的土；反义 barren 贫瘠的。\",\n\"habitat\":\"画面：一只熊猫住进竹林，吃住都在这片林子——habitat「栖息地」。habit 在这里是『居住』：一个物种天然生活的那片地方，毁了它物种就无家可归。\",\n\"horizon\":\"画面：站在海边，天和海在最远处接成一条线——horizon「地平线」。目光能到的边界线；broaden your horizons 就是『开阔眼界』。\",\n\"inhabit\":\"画面：地图上一个小岛点着几户人家的灯火——inhabit「栖息；居住」。in- + habit（住）：住在某地（多指动物或人群），居民是 inhabitant。\",\n\"liquid\":\"画面：把杯子倾斜，水随杯形流动——liquid「液体的；液体」。liqu- 是『流』：会流动、没有固定形状的一类物质，和 solid、gas 并列。\",\n\"mechanism\":\"画面：打开钟表后盖，齿轮一环扣一环地转——mechanism「机制；机械结构」。machine（机器）的运作方式；引申为事情运转的那套咬合关系。\",\n\"moisture\":\"画面：清晨草叶上挂着一层细密的水珠——moisture「湿气；水分」。moist 是『潮湿的』：空气、土壤里含的那点水汽，量不大但关键。\",\n\"nutrient\":\"画面：一袋肥料标着氮、磷、钾的含量——nutrient「养分」。nutri- 是『滋养』（nutrition 营养）：生物长身体必须吸收的物质。\",\n\"orbit\":\"画面：地球沿着椭圆轨道绕太阳转，画出一圈闭合的线——orbit「轨道」。orb- 是『圆』：天体绕行画出的那条圈；也可作动词『绕轨道运行』。\",\n\"organism\":\"画面：显微镜下一只草履虫摆动纤毛游来游去——organism「有机体；生物」。organ（器官）组成的整体：从单细胞到人，都是能独立生存的活体。\",\n\"oxygen\":\"画面：潜水员背上的气瓶咕噜冒着泡——oxygen「氧气」。元素符号 O：燃烧和呼吸都离不开的气，约占空气五分之一。\",\n\"phenomenon\":\"画面：夜空出现极光，众人举手机拍摄这罕见一幕——phenomenon「现象」。pheno- 是『显现』（希腊 phainein 显示）：能被感官察觉、显现出来的事或现象；复数 phenomena。\",\n\"predict\":\"画面：气象台看着云图说『明天有雨』，第二天果然下了——predict「预言；预测」。pre-（在前）+ dict（说）：提前说出还没发生的事。\",\n\"preserve\":\"画面：一罐泡菜封好口放进冰箱，冬天打开还脆生生的——preserve「保存；保护」。pre- + serv（保持）：提前护好，让它久不变坏；自然保护区也是 preserve。\",\n\"species\":\"画面：动物园牌子上写着『孟加拉虎』这一物种的拉丁名——species「物种」。speci- 是『外形、种类』：生物分类的基本单位，同种能互相繁殖。\",\n\"stable\":\"画面：桌子四条腿稳稳立着，推也推不倒——stable「稳定的」。sta- 是『站立』（stand 同源）：站得稳、不晃动；作名词是『马厩』，记四条腿的画面正好两用。\",\n\"substance\":\"画面：实验室烧杯里盛着一种白色粉末，标签待填写——substance「物质」。sub-（在下）+ sta（站）：垫在性质下面的实体本身；也可指要旨。\",\n\"survive\":\"画面：沙漠里一株仙人掌在大旱后仍绿着——survive「幸存；存活」。sur-（超过）+ viv（活）：活得比灾难更久，活着穿过它；survivor 是幸存者。\",\n\"vapor\":\"画面：烧开的水壶嘴喷出白气——vapor「水汽；蒸气」。vap- 就是蒸汽本身：液体受热变的气，美式 vapor、英式 vapour。\",\n\"velocity\":\"画面：高铁窗外景物飞退，仪表显示 350 km/h——velocity「速度」。veloc- 是『快』：物理里带方向的速度，比 speed 多一个方向感。\",\n\"absorb\":\"画面：一块海绵丢进水盆，水肉眼可见地被吸干——absorb「吸收」。ab- + sorb（吸）：像海绵一样把液体、知识、成本吸进去；吸收知识是 absorb information。\",\n\"accurate\":\"画面：射箭正中靶心，分毫不差——accurate「准确的」。ac- + cur（关心、照料，如 cure）：用心到不差分毫；accuracy 是名词『准确性』。\",\n\"circumstance\":\"画面：一个人站在聚光灯圈外围，四周环境一圈圈标出——circumstance「情形；环境」。circum- 是『周围』（circle 同源）：围着一件事的那些周遭条件。\",\n\"cluster\":\"画面：一串葡萄一颗挨一颗挂在藤上——cluster「聚集；一簇」。也可作动词：人和星星『成群聚集』时就 cluster 在一起，星团是 star cluster。\",\n\"discharge\":\"画面：水库开闸，水轰地冲出来——discharge「释放；排放」。dis-（放开）+ charge（装载）：把装着的东西放出去；也有『出院、退役、卸货』义，都是一放了之。\",\n\"dynamic\":\"画面：齿轮飞转、曲线起伏，一刻不停——dynamic「动态的；充满活力的」。dynam- 是『力』（dynamite 炸药同根）：有力量在动的，和 static（静止的）相对。\",\n\"ecology\":\"画面：一张食物网图：草、兔、鹰用箭头连成一片——ecology「生态学」。eco-（家、栖息地）+ -logy（学问）：研究生物和它们『家』之间关系的学问。\",\n\"emission\":\"画面：汽车排气管吐出一团尾气——emission「排放（物）」。e-（向外）+ miss（送）：被送到空气里的东西，碳排放是 carbon emissions。\",\n\"enormous\":\"画面：一头大象站在小汽车旁，车显得像玩具——enormous「巨大的」。e- + norm（常规）：超出常规大小的，大得离谱。\",\n\"exceed\":\"画面：仪表指针冲过了红线刻度——exceed「超过」。ex- + ceed（走，如 proceed）：走得比界限更远；excess 是『过量』。\",\n\"expose\":\"画面：相机胶片被拉出盒外见了光——expose「暴露；揭露」。ex-（向外）+ pose（放）：把藏着的东西放到外面来；exposure 是名词。\",\n\"extract\":\"画面：牙医用钳子把坏牙拔出来——extract「提取；拔出」。ex-（向外）+ tract（拉）：把东西从里面拉出来；文章的『摘录』也是 extract。\",\n\"fluctuate\":\"画面：股票曲线上上下下，没有一刻水平——fluctuate「波动」。fluct- 是『浪』（fluid 流动同源）：像波浪一样起起伏伏。\",\n\"fluid\":\"画面：把水倒进方盒它是方的，倒进圆瓶它是圆的——fluid「流体」。flu- 是『流』（fluent 流利同根）：会流动、随容器变形的东西；也可作形容词。\",\n\"fragment\":\"画面：花瓶摔在地上，碎片散了一地——fragment「碎片」。frag- 是『破』（fragile 易碎的）：破开后剩下的小块；不完整的句子也叫 fragment。\",\n\"frequency\":\"画面：收音机旋钮转到 98.7，电台声清晰起来——frequency「频率」。frequ- 是『频繁』：单位时间里重复多少次；也可指『频繁』这件事本身。\",\n\"gradual\":\"画面：斜坡缓缓上升，走上去毫不费力——gradual「逐渐的」。grad- 是『步、级』（grade 等级）：一级一级慢慢变的，和 sudden（突然的）相对。\",\n\"inherent\":\"画面：磁铁天生能吸铁，掰开一半还是能吸——inherent「固有的」。in- + her（黏着，如 adhere）：黏在事物内部、生来就带的属性，如 inherent risk 固有风险。\",\n\"input\":\"画面：键盘敲下的字符被送进电脑——input「输入」。in + put（放进去）：放进去的数据、意见或投入；反义 output 输出。\",\n\"insert\":\"画面：把钥匙插进锁孔，咔哒一声到位——insert「插入」。in- + sert（连接、排入）：把东西塞进一个位置里，如 insert a coin 投币。\",\n\"intact\":\"画面：考古出土的花瓶历经千年竟完好无损——intact「完好无损的」。in-（不）+ tact（触碰，如 contact）：没被碰坏过的，原封不动。\",\n\"integrate\":\"画面：拼图最后一块嵌进去，整幅图完整了——integrate「整合；融入」。integr- 是『完整』（integrity 完整、正直）：把散件合成为一个整体。\",\n\"intense\":\"画面：正午阳光刺得人睁不开眼——intense「强烈的」。in- + tens（拉紧，如 tension）：被拉到极限的强度：强光、强情绪、强竞争都用它。\",\n\"interact\":\"画面：两人打乒乓，球在中间来回——interact「相互作用」。inter-（之间）+ act（行动）：双方互相施加影响，人和人、物和物都可以。\",\n\"internal\":\"画面：医生把听诊器贴在胸口听身体内部——internal「内部的」。inter- 在此是『里面』：关起门在里面的，如内科 internal medicine；反义 external。\",\n\"interpret\":\"画面：同声传译员戴着耳机，把外语实时说成中文——interpret「解释；口译」。把一种表达『翻』成另一种让人懂，既可译语言，也可解数据。\",\n\"interval\":\"画面：课间十分钟，时钟上两段课之间的空白——interval「间隔」。inter-（之间）+ val（墙、营垒）：两件事之间隔开的那段时间或距离。\",\n\"involve\":\"画面：一张大网把好几个人都罩在里面——involve「包含；牵涉」。in- + volv（卷）：被卷进一件事里，脱不开身；involved 是『参与其中的』。\",\n\"layer\":\"画面：切开千层蛋糕，一层奶油一层饼看得清清楚楚——layer「层」。lay（放）出来的薄片：地层、涂层、衣服层层叠都是 layer。\",\n\"allocate\":\"画面：班长把一箱水按人头分到每张桌上——allocate「分配」。al- + loc（地方，如 locate）：把资源按计划放到各个地方去。\",\n\"bias\":\"画面：天平一端被悄悄压了手指，秤歪向一边——bias「偏见；偏倚」。秤本该平，被压歪了就是 bias：认知被先入之见压偏；统计里的 systematic bias 同理。\",\n\"campaign\":\"画面：竞选团队举着牌子走过街道，传单发到每户——campaign「活动；战役」。原是军事『战役』：有组织、有目标的一整套行动，如广告 campaign。\",\n\"challenge\":\"画面：一堵高墙立在面前，选手活动手腕准备翻越——challenge「挑战」。既是要战胜的难关这个名词，也是『向人挑战、质疑』的动词。\",\n\"clarify\":\"画面：浑水静置后慢慢变清，杯底看得见了——clarify「澄清」。clar- 是『清』（clear 同源）：把话、把液体都弄清楚；问题 clarify 之后不再含糊。\",\n\"collaborate\":\"画面：两个人共用一张桌子拼一份报告，你写一半我写一半——collaborate「协作」。col-（一起）+ labor（劳动）：一起干活，尤指创作出成果；名词 collaboration。\",\n\"colleague\":\"画面：同一间办公室里并排工位的两个人互相递文件——colleague「同事」。col-（一起）+ league（联盟）：在同一单位一起工作的人，特指同行同僚。\",\n\"civil\":\"画面：法庭审理一起邻里赔偿纠纷，不涉及刑罚——civil「民事的」。civ- 是『公民』（citizen）：公民之间的事，如 civil law 民法；也可指『有礼貌的』。\",\n\"compensate\":\"画面：航班取消，航空公司给乘客发餐券和赔偿金——compensate「赔偿；补偿」。com- + pens（称量、支付）：用钱把损失称平；也可指心理上的『补偿』。\",\n\"consent\":\"画面：手术前家属在知情同意书上签下名字——consent「同意」。con- + sent（感觉，如 sense）：双方感觉一致、点头许可；名词和动词同形。\",\n\"considerable\":\"画面：一笔钱装满整个手提箱，分量不轻——considerable「可观的；相当大的」。consider（考虑）+ -able：大到值得认真考虑的程度，修饰数量、差距、影响。\",\n\"contemporary\":\"画面：两位画家同一年代办展，作品并排挂在墙上——contemporary「当代的；同时代的」。con-（一起）+ tempor（时间，如 temporary）：生活在同一个时代的。\",\n\"convention\":\"画面：每年大会上所有人按老规矩起立鼓掌——convention「惯例；大会」。con- + vent（来）：大家聚拢形成的老规矩；也可指大型会议和公约。\",\n\"convince\":\"画面：辩论结束，原本摇头的人慢慢点头——convince「使信服」。con- + vinc（征服，如 victory）：用理由『征服』对方的想法；be convinced 是『确信』。\",\n\"cooperate\":\"画面：两个人合力抬一张重桌子，一人抬一头——cooperate「合作」。co-（一起）+ operate（操作）：一起动手把事做成；名词 cooperation。\",\n\"core\":\"画面：切开苹果，正中间那截带籽的部分——core「核心」。核在最中心、最关键：core value 核心价值、core issue 核心问题都取这个画面。\",\n\"corporate\":\"画面：一栋总部大楼，各部门按公司章程运转——corporate「企业的；公司的」。corpor- 是『身体』（corpse 之外，corporation 是法人团体）：属于公司这个『法人身体』的。\",\n\"culture\":\"画面：一个村庄的节日、吃食、礼节被画成一幅长卷——culture「文化」。cult- 是『耕作、培养』（agriculture 同根）：在人群里慢慢『养』出来的生活方式；也可指细菌『培养』。\",\n\"dedicate\":\"画面：作家在扉页写下『献给我的母亲』——dedicate「奉献；献给」。de- + dic（说）：郑重说出把某物某时献给谁；dedicate oneself to 是『全身心投入』。\",\n\"demonstrate\":\"画面：实验课上老师当众点燃镁条，全班看清现象——demonstrate「演示；证明」。de- + monstr（展示）：摆出来给大家看，用事实说明；游行示威也是它。\",\n\"deny\":\"画面：被问到是否拿了东西，孩子连连摇头摆手——deny「否认」。de-（向下、否定）+ 否认的姿态：说『没有这回事』；也可指『拒绝给予』。\",\n\"despite\":\"画面：下着大雨，跑者还是冲出了家门——despite「尽管」。画面记住『顶着阻碍硬上』：despite the rain 尽管下雨；后面跟名词，不能直接跟句子。\",\n\"devote\":\"画面：她把退休后的全部时间都给了社区图书馆——devote「致力于；奉献」。de- + vot（誓言，如 vote 的亲戚）：像立誓一样把时间精力全交出去，devote oneself to doing。\",\n\"discipline\":\"画面：队伍在口令下齐步走，没人乱动——discipline「纪律；学科」。disciple 是『门徒』：守规矩的训练；大学科 discipline 是被系统训练出的一门学问。\",\n\"discriminate\":\"画面：海关人员把人群按是否申报分开对待，有人被多盘问——discriminate「歧视；区别对待」。dis- + crimin（分辨）：分辨本是中性，针对人区别对待就成了歧视；也有『辨别』义。\",\n\"dominate\":\"画面：棋盘上一方的棋子占了大半江山——dominate「支配；主导」。domin- 是『主人』（domain 领地）：像主人一样压住全场，居高临下地控制。\",\n\"encounter\":\"画面：转过街角，迎面撞上多年不见的老友——encounter「遭遇；偶遇」。en- + counter（相对）：面对面碰上，可以是人、困难或野生动物；作名词是这次相遇。\",\n\"enforce\":\"画面：交警吹哨拦下违规车辆，规定立刻执行——enforce「强制执行」。en- + force（力量）：给规则加上力量，让它必须被遵守，如 enforce the law。\",\n\"enhance\":\"画面：修图时拉高对比度，照片一下子鲜明起来——enhance「增强；提高」。把已有的东西再往上抬一档：质量、价值、能力被 enhance。\",\n\"ethic\":\"画面：医生面对病人的秘密，摇头不说——ethic「伦理（准则）」。ethos 是『品性』：做人做事该守的道德底线，常以复数 ethics 出现，如 professional ethics。\",\n\"exclude\":\"画面：俱乐部名单公布，有人的名字被划在门外——exclude「排除」。ex-（向外）+ clud（关，如 include 的反面）：把人或选项关在外面；反义 include 包括。\",\n\"exploit\":\"画面：矿山里工人采出的矿石被运走卖钱——exploit「开发；剥削」。ex- + ploit（展开）：把资源『展开来用』；用在人身上就是剥削，用在资源上多是中性开发利用。\",\n\"external\":\"画面：医生只检查身体表面，不开刀——external「外部的」。exter- 是『外』：在外面的，如 external factors 外部因素；反义 internal 内部的。\",\n\"facilitate\":\"画面：坡道修好后，推车的人轻松上了台阶——facilitate「使便利；促进」。facil- 是『容易』（facility 设施）：把难事变容易，让过程跑得顺。\",\n\"federal\":\"画面：一张美国地图由五十个州拼成，中央有一面国旗——federal「联邦的」。feder- 是『联盟』：各州结盟成的中央层级，如 federal government 联邦政府。\",\n\"flexible\":\"画面：一根竹条被弯成弧形，松手又弹回去——flexible「灵活的」。flex- 是『弯』：能弯不断，引申为时间、计划、人都能变通；反义 rigid。\",\n\"format\":\"画面：交论文前把字体、行距调成统一模板——format「格式」。form（形式）+ -at：内容摆成的固定样子；也可作动词『格式化』。\",\n\"foundation\":\"画面：盖楼前先浇下深厚的地基——foundation「基础；基金会」。found 是『奠基、创立』：托住整栋楼的那一层；引申为学问的基础、慈善基金会。\",\n\"gender\":\"画面：表格里『男 / 女』两个选项框——gender「性别」。gen- 是『出生、种类』（gene 同源）：出生带来的社会性别分类；语言里的『性』（阴阳性）也用它。\",\n\"generate\":\"画面：风车转动，灯泡亮起——电被 generate 出来。gen- 是『产生』（gene 起源）：无中生有地造出电、想法、收入；generator 是发电机。\",\n\"goal\":\"画面：球员起脚，球直奔球门上角——goal「目标」。先记球场上的球门：你瞄准要打进的那个点，就是人生和计划里的 goal。\",\n\"grant\":\"画面：基金会把一笔资助款打到实验室账户，附一封批准信——grant「拨款；授予」。也可作动词『同意给予』：正式批下来的钱或权利，如 research grant。\",\n\"guideline\":\"画面：手册里一条条粗体线框出的建议，照着做不会错——guideline「指导方针」。guide（引导）+ line（线）：给你画出走向的指导线，不是法律，是照着走的建议。\",\n\"hierarchy\":\"画面：一张组织图：总裁在顶，往下是经理、主管、员工——hierarchy「层级」。hier-（神圣、统治）+ arch（统治）：一级压一级的等级金字塔，动物社会也有。\",\n\"highlight\":\"画面：课本上一句重点被荧光笔涂亮——highlight「强调；突出」。high + light（光）：给重点打上高光，既可指荧光标记这个动作，也指『最精彩部分』。\",\n\"ignore\":\"画面：手机响个不停，他看都不看继续看书——ignore「忽视」。i-（不）+ gnore（知道，如 ignorant 无知）：知道了也当不知道，故意不理。\",\n\"illustrate\":\"画面：课本文字旁配了一幅图，看图就懂了——illustrate「阐明；给…加插图」。il- + lustr（照亮）：用例子和图把抽象的话照亮；illustration 是插图。\",\n\"imply\":\"画面：他说『房间有点冷』，眼睛却看着窗户——imply「暗示」。im- + ply（折叠，如 apply）：意思折叠在话里，没有明说；听者推断是 infer，别混。\",\n\"impose\":\"画面：新税法颁布，企业必须照章缴纳——impose「强加；征收」。im- + pose（放）：把负担、规则放到别人身上由不得拒绝，如 impose a tax 征税。\",\n\"incentive\":\"画面：终点线上挂着奖金牌，选手们跑得更卖力了——incentive「刺激；激励」。in- + cent（唱、煽动，源自歌）：让人愿意往前冲的那股诱因，多指钱和奖励。\",\n\"incident\":\"画面：街口两车轻微剐蹭，路人围拢——incident「事件（多指不好的）」。in- + cid（落下）：突然落下来发生的事，常是事故、外交风波这类插曲。\",\n\"index\":\"画面：书最后几页按字母列着词条和页码——index「索引；指数」。in- + dex（指向）：指向内容的清单；经济 index 是把一篮子数据合成的指标。\",\n\"industry\":\"画面：一排厂房烟囱林立，卡车进进出出——industry「工业；行业」。也可指某一整行当如旅游业 tourism industry；形容词 industrial 是工业的。\",\n\"inevitable\":\"画面：冬天再暖，北方终会下雪，谁也挡不住——inevitable「必然的」。in-（不）+ evit（避开，如 avoid 亲族）：躲不开、一定会发生的事，如 death and taxes。\",\n\"influence\":\"画面：一块磁铁靠近，铁屑悄悄转向它——influence「影响」。in-（向内）+ flu（流动）：像潮水流入一样，悄悄改变别人的想法和局面；作名词动词都常见。\",\n\"insight\":\"画面：一团乱的线条里他突然看出隐藏的图案——insight「见解；洞察」。in + sight（眼光）：目光看进事物内部得出的深刻理解，不是表面信息。\",\n\"insist\":\"画面：孩子拉着妈妈的衣角，一遍遍说『我就要这个』——insist「坚持」。in- + sist（站立）：站在原地不挪窝，反复坚持主张或坚持要做，insist on doing。\",\n\"integrity\":\"画面：一根梁木从头到尾没有裂缝——integrity「诚信；完整」。integr- 是『完整』：做人没有裂缝，言行如一；数据完整性也用它。\",\n\"intelligence\":\"画面：棋手盯着棋盘三秒，落子封死对手——intelligence「智力」。intel-（在中间挑选、理解）：理解和判断的脑力；也可指『情报』，如情报机构。\",\n\"intervene\":\"画面：两人争吵快要动手，第三人上前隔开——intervene「介入；干预」。inter-（之间）+ ven（来）：走到中间来插手，如政府干预市场 government intervention。\",\n\"invest\":\"画面：一个人把积蓄放进一家初创公司，等它长大——invest「投资」。in- + vest（穿衣、授予）：把钱『穿』到资产上期待回报；investigate（调查）是同根的另一词，别混。\",\n\"justify\":\"画面：法庭上律师一条条摆出理由为当事人辩护——justify「辩护；证明正当」。just 是『公正的』：拿出理由让一件事显得公正合理；justify your answer 是考试常用语。\",\n\"label\":\"画面：一排瓶子各贴一张小纸签，写着名称和日期——label「标签」。也可作动词『贴标签；把…称为』：贴上去用来识别的那张小签。\",\n\"levy\":\"画面：税务局发文：对进口货加征一笔税——levy「征收」。名词动词同形，多和 tax 连用 levy a tax：正式地把税『提』上来征收。\",\n\"license\":\"画面：驾校考试通过，工作人员递上一张驾驶证——license「许可证」。lic- 是『允许』：官方允许你做某事的凭证；美式拼写 license，英式名词 licence。\",\n\"likewise\":\"画面：他向老师问好，我同样鞠了一躬——likewise「同样地」。like（相似）+ wise（方式）：用同样的方式、同样地回应；句首常用，表『同样』的副词。\",\n\"locate\":\"画面：地图上一个图钉扎下去：『就是这里』——locate「定位；坐落于」。loc- 是『地方』（local 当地的）：找到位置，或被动『位于』be located in。\",\n\"logic\":\"画面：三段论写在黑板上：因为 A，所以 B——logic「逻辑」。log- 是『言语、道理』（-logy 学问同根）：推理时环环相扣的那套道理；logical 是形容词。\",\n\"maintain\":\"画面：园丁天天修剪，让花园始终整齐——maintain「维护；保持」。main- 是『手』（manual 手册）：用手一直扶持着不让坏、不让掉，如 maintain health。\",\n\"manual\":\"画面：新电器旁附着一本厚厚的小册子——manual「手册」。manu- 是『手』（manuscript 手稿）：拿在手里照着操作的书；也可作形容词『手工的』。\",\n\"margin\":\"画面：笔记本每页边缘留出一指宽的空白——margin「边缘；页边距」。marg- 是『边』：页边的空白；也可指利润 margin、差距（胜选 margin）。\",\n\"mature\":\"画面：葡萄由青转紫，咬一口甜了——mature「成熟的」。果子熟透、人心智成熟都用它；作动词是『长成、到期』，如债券 mature 到期。\",\n\"media\":\"画面：电视、报纸、手机新闻同时播报同一件事——media「传媒；媒体」。medi- 是『中间』（medium）：站在信息中间传递的渠道总称，medium 的复数。\",\n\"medium\":\"画面：三件 T 恤挂着 S、M、L，中间那件——medium「媒介；中等的」。同样是『中间』：不大不小的尺码、传递信息的媒介、培养细菌的培养基。\",\n\"mental\":\"画面：一个人揉着太阳穴，脑子连轴转累了——mental「精神的；脑力的」。ment- 是『心智』（mention 提及同根）：和头脑、心理有关的，如 mental health 心理健康。\",\n\"migrate\":\"画面：秋天大雁排成人字飞向南方过冬——migrate「移居；迁徙」。migr- 是『移动居住地』：人 migrate 求生活，鸟 migrate 随季节，都有方向和距离。\",\n\"military\":\"画面：一队士兵迈着整齐步伐走过广场——military「军事的；军队」。milit- 是『士兵』（militia 民兵）：和军队、战争有关的一切。\",\n\"minimal\":\"画面：房间里只有一张床和一张桌，再无多余——minimal「极小的」。minim- 是『最小』（minimum 最低限度）：小到不能再小的量或程度。\",\n\"minimize\":\"画面：把电脑窗口点一下缩小到任务栏——minimize「使最小化；淡化」。让风险、成本、损失缩到最小；也可指有意『轻描淡写』问题。\",\n\"minor\":\"画面：大调音阶旁标着小调，声音更柔和——minor「较小的；次要的」。和 major（主要的）相对：份量小的一方；也可指『未成年人』。\",\n\"mode\":\"画面：手机切换到夜间模式，屏幕暗了下来——mode「模式；方式」。做事的固定方式或设备的运行档位；统计里是『众数』，服装里是『时尚』。\",\n\"motive\":\"画面：侦探在白板上写下『他为什么杀人？』——motive「动机」。mot- 是『动』（motion 运动）：推动一个人去做某事的内在原因，破案先查 motive。\",\n\"network\":\"画面：一张蛛网，每个节点连着好几条线——network「网络」。net（网）+ work：节点互联成的网，可以是人脉网、计算机网、交通网。\",\n\"norm\":\"画面：班里大多数人的作息被画成一条基准线——norm「准则；常态」。norm 是大家默认的标准，如 social norms 社会规范；normal（正常的）由此而来。\",\n\"objective\":\"画面：裁判吹哨只看规则，不看选手是谁——objective「客观的」。object 是『对象、物体』：只对着事实本身、不带个人感情；也可作名词『目标』。\",\n\"obtain\":\"画面：排了长队终于领到那张限量证书——obtain「获得」。ob- + tain（握住，如 contain）：通过努力把东西握到手，比 get 更正式。\",\n\"obvious\":\"画面：答案就写在脸上，谁都看得出来——obvious「明显的」。ob- + vi（路）：摆在路当中、人人过得去都看见的，不用猜。\",\n\"occupy\":\"画面：一间空房被家具和箱子渐渐填满——occupy「占用；占据」。oc- + cup（抓取）：抓住并占住空间时间，如 occupy a seat 占座、occupy oneself 忙于。\",\n\"odd\":\"画面：一双袜子一只红一只蓝，怎么看都别扭——odd「奇怪的；奇数的」。既是『怪』：不一样的那只；也是数学里的奇数（odd number），和 even 相对。\",\n\"offset\":\"画面：天平一端多了重量，另一端加砝码补平——offset「弥补；抵消」。off + set：用一个量去抵另一个量，如种树 offset 碳排放；作名词是抵消量。\",\n\"option\":\"画面：菜单上三个套餐，你只能圈一个——option「选项」。opt- 是『选择』（optimist 之外的 opt 是挑选）：摆在你面前可供挑的几条路之一。\",\n\"overall\":\"画面：退后一步看整幅拼图，而不是一小块——overall「大体上的；总体的」。over + all：盖住全部的判断，如 overall impression 整体印象；也可作名词『工装服』。\",\n\"overlap\":\"画面：两个圆相交，中间那块月牙被涂了两次——overlap「部分重叠」。over + lap（搭叠）：时间、范围、职责有一段是共同重合的。\",\n\"abstract\":\"画面：画家只画了几条曲线和色块，没有具体的马或树——abstract「抽象的」。abs-（离开）+ tract（拉）：从具体实物里『拉走』形，只剩概念；论文的 abstract 是『摘要』。\",\n\"acknowledge\":\"画面：他在台上接过奖，第一句话是感谢导师——acknowledge「承认；致谢」。ac- + knowledge（知道的知识）：公开承认自己知道、接受事实；收到信件回执也是它。\",\n\"acquire\":\"画面：公司把一家小工作室买下，招牌换上自己的名字——acquire「获得；收购」。ac- + quir（寻求，如 require 需要）：通过努力求得、学得，如 acquire a language 习得语言。\",\n\"adjacent\":\"画面：两间教室门挨着门，只隔一道墙——adjacent「毗邻的」。ad-（向着）+ jac（躺、放，如 jacket 之外的 jac 是躺）：紧挨着躺在一起的，数学里是『邻角』。\",\n\"photosynthesis\":\"画面：阳光照在绿叶上，叶子吸进二氧化碳、放出氧气泡——photosynthesis「光合作用」。photo-（光）+ synthesis（合成）：植物用光把原料『合成』成养分的过程。\",\n\"neon\":\"画面：夜市招牌上一排发光的彩色玻璃管——neon「氖；霓虹灯」。惰性气体通电发橘红光，招牌里的气就是它；先记发光的管子，再记元素名。\",\n\"diffraction\":\"画面：一束光穿过窄缝后散开成彩色条纹——diffraction「衍射」。di- + fract（破开，如 fracture）：波遇到障碍『绕开、散开』的现象，和折射 refraction 分清。\",\n\"laser\":\"画面：一束细而直的红光射出，在墙上落成一个小点——laser「激光」。它本身是缩写词：受激辐射放大的光——细、直、能量集中是它的样子。\",\n\"beam\":\"画面：手电筒在黑暗里打出一道光柱——beam「光线；横梁」。作动词『发射光线』时就是这道光柱射出去的样子；建筑里的 beam 是横着的梁。\",\n\"blaze\":\"画面：干柴堆被点着，火舌蹿起一人高——blaze「熊熊燃烧」。也可作名词『火焰；光辉』：烧得最旺、最显眼的那一团火。\",\n\"ember\":\"画面：篝火熄后，灰烬里还有几点暗红一闪一闪——ember「余烬」。大火之后的残火：小、暗红、还带温度，常以复数 embers 出现。\",\n\"brittle\":\"画面：一块薄玻璃板轻轻一碰就裂成蛛网纹——brittle「易碎的」。记这个『一碰就裂』的瞬间：干而脆的东西（枯枝、薄饼、老塑料）都 brittle；它另有一种糖果名义，托福里多取形容词。\",\n\"probe\":\"画面：一艘无人探测器伸出机械臂，缓缓探向行星表面取样——probe「探测器；探查」。prob- 是『试、测』（prove 证明同源）：伸进去试探、查明真相的工具；作动词就是『探查、追问』。\",\n\"porcupine\":\"画面：一只豪猪受惊时竖起满背黑白尖刺，敌人无从下口——porcupine「豪猪」。porc- 是『猪』（pork 猪肉同根）+ pine 记『松针』：像猪一样大、背上插满松针的啮齿动物。\",\n\"kitchen\":\"画面：灶台上的锅冒着热气，冰箱门贴满购物清单——kitchen「厨房」。它和 cook（做饭）同源：飘着饭香、能做饭的房间，就是 kitchen。\",\n\"bedroom\":\"画面：一张床、一盏台灯、一摞睡前读物——bedroom「卧室」。bed（床）+ room（房间）：放床睡觉的房间，词本身就把主要家具写出来了。\",\n\"bathroom\":\"画面：浴缸放满热水，镜子蒙上一层水汽——bathroom「浴室」。bath（洗澡）+ room（房间）；美式英语里问 bathroom 在哪，往往就是问洗手间。\",\n\"toilet\":\"画面：按下冲水钮，马桶里哗啦一声冲得干干净净——toilet「厕所；抽水马桶」。它来自法语 toilette（梳妆），是借梳妆间之名说的委婉词，指器物时就是马桶本身。\",\n\"shower\":\"画面：站在花洒下，水珠像一阵雨哗哗落满全身——shower「淋浴」。shower 的本义就是『阵雨』：淋浴就是站在人造阵雨里洗澡，天气预报里的 showers 也是阵雨。\",\n\"towel\":\"画面：游完泳，把湿透的毛巾搭在栏杆上晾——towel「毛巾」。记它吸水的本事：一擦就干的布；浴室里挂着的、健身房人手一条的，都是 towel。\",\n\"soap\":\"画面：一块肥皂在手里搓出满手白泡沫——soap「肥皂」。soap opera（肥皂剧）就是当年插播肥皂广告的电视剧；先记住这块冒泡的 soap。\",\n\"shampoo\":\"画面：洗头时泡沫堆得像一座小山——shampoo「洗发水」。它来自印地语，本义是『按摩』：早年指洗头按摩，后来专指洗头发的那瓶液体，作动词就是『洗头』。\",\n\"toothbrush\":\"画面：牙刷挤上牙膏，在牙齿上上下刷动——toothbrush「牙刷」。tooth（牙齿）+ brush（刷子）：给牙齿用的刷子，构词一目了然。\",\n\"toothpaste\":\"画面：牙膏从管口挤出一条蓝白相间的膏体，落在牙刷上——toothpaste「牙膏」。tooth（牙齿）+ paste（膏）：抹在牙齿上的膏，每天早晚都要见它。\",\n\"mirror\":\"画面：出门前对着镜子整理衣领，镜中人同步抬手——mirror「镜子」。它和 miracle（奇迹）沾亲，都源于拉丁语『惊奇地看』；作动词时 mirror 是『映照出；反映』。\",\n\"comb\":\"画面：梳子齿划过头发，把打结处一点点梳通——comb「梳子」。末尾的 b 不发音（像 climb 的 b）：只梳不读；蜂巢 honeycomb 也是这个 comb，齿状排列。\",\n\"razor\":\"画面：剃须刀贴着下巴缓缓刮过，胡茬应声而落——razor「剃须刀」。它和 erase（擦除）同源，都是『刮擦』：把胡须从脸上刮掉的那把薄刃。\",\n\"scissors\":\"画面：两片刀刃交叉开合，咔嚓剪断一张纸——scissors「剪刀」。永远用复数：a pair of scissors（一把剪刀）；拼写里藏着两个 s、两个刃口，正好像它交叉的样子。\",\n\"needle\":\"画面：奶奶眯着眼把线头对准细小的针眼——needle「针」。缝衣针、注射针、指针都是 needle：一切细长带尖的东西；记它『细长尖头』的模样。\",\n\"thread\":\"画面：一根细线穿过针眼，缝合裂开的衣角——thread「线；线索」。穿针引线的那根线；网上帖子的『话题串』也叫 thread，思路之线，一以贯之。\",\n\"button\":\"画面：大衣最上面那颗纽扣总是最难扣——button「纽扣；按钮」。衣服上是纽扣，机器上是按钮：都是小小一个圆点，按下去、扣起来；源于法语『小芽苞』，圆鼓鼓的样子。\",\n\"zipper\":\"画面：拉链头一拉到底，外套从下到上严丝合缝——zipper「拉链」。zip 是拟声词『嗖』：拉链嗖地一声合上，就是 zipper，快得像它的名字。\",\n\"pocket\":\"画面：手插进口袋摸到钥匙和零钱——pocket「口袋」。pocket money 是零花钱（放在口袋里的钱）；pock- 原是『小袋子』，衣服上的小袋子就是它。\",\n\"wallet\":\"画面：打开钱包，卡片和钞票分层码得整整齐齐——wallet「钱包」。它和旅行装衣服的袋子同源；数字时代有 crypto wallet（加密钱包），装钱的容器概念没变。\",\n\"purse\":\"画面：她从手提包里翻出口红和钥匙——purse「手提包；钱包」。英式英语里 purse 多指女士小钱包，美式里就是随身手提包；和 wallet 的区别在大小和拿法。\",\n\"umbrella\":\"画面：暴雨突至，一把伞撑开，伞下两个人挤着躲雨——umbrella「雨伞」。它源于意大利语 ombra（影子）：最初是遮阳的『小影子』，后来才兼管下雨。\",\n\"glove\":\"画面：冬天出门前把五指逐个套进手套——glove「手套」。fit like a glove 是『严丝合缝、天衣无缝』；棒球场上接球的手套也叫 glove。\",\n\"scarf\":\"画面：寒风里把围巾绕了脖子两圈才敢出门——scarf「围巾」。它既指保暖的长围巾，也指装饰的丝巾；画面记住『绕在脖子上的一圈布』。\",\n\"hat\":\"画面：棒球帽、草帽、毛线帽挂满一面墙——hat「帽子」。hat 是帽子的总称，有帽檐、包住头顶；戴帽子的场合 hat trick（帽子戏法）还引申为连进三球。\",\n\"cap\":\"画面：他把鸭舌帽反戴，帽檐朝后——cap「鸭舌帽；盖子」。cap 的帽檐在前、只盖头顶，和 hat 的宽檐不同；瓶盖、封顶（cap the price）都用这个『盖住顶』的意思。\",\n\"coat\":\"画面：大衣挂在门边，冬天出门顺手披上——coat「外套；涂层」。衣服是最外层的外套；a coat of paint 是『一层漆』：凡是覆在表面的那一层，都可叫 coat。\",\n\"jacket\":\"画面：夹克拉链拉到胸口，袖口利落收紧——jacket「夹克」。它比 coat 短、比 shirt 厚，是春秋的主力外套；书的护封也叫 jacket，同是『外衣』。\",\n\"shirt\":\"画面：白衬衫熨得笔挺，挂在衣架上等主人——shirt「衬衫」。shirt 指有领有扣的上衣；T-shirt 的名字就来自它摊开时像字母 T 的形状。\",\n\"pants\":\"画面：一条长裤搭在椅背上，裤腿垂到地板——pants「裤子」。美式英语里 pants 是长裤，英式里却指内裤；永远复数形，两条裤腿就是它的复数理由。\",\n\"dress\":\"画面：一条连衣裙在橱窗里转着圈展示——dress「连衣裙；着装」。作名词是连衣裙，作动词是『穿衣、装扮』：dress up 就是盛装打扮，一词两头都管穿着。\",\n\"skirt\":\"画面：裙摆随步伐轻轻摆动——skirt「裙子」。skirt 本义是衣物的『下摆、边缘』：作动词 skirt around 是『绕开（问题）』，像沿着裙边走，不碰中间。\",\n\"suit\":\"画面：西装三件套挂在衣橱正中，领带配得一丝不苟——suit「西装；套装」。suit 是『一套』：西装是成套的衣服，lawsuit（诉讼）是成套走完的法律程序。\",\n\"tie\":\"画面：他对着镜子把领带结推到喉结正下方——tie「领带；平局」。领带是系（tie）在脖子上的带子；比赛打平也叫 tie，都是『系在一起、分不开』。\",\n\"jewelry\":\"画面：首饰盒打开，项链耳环在绒布上闪着光——jewelry「珠宝（总称）」。jewel 是单件宝石，jewelry 是不可数的总称：说『一件首饰』要 a piece of jewelry。\",\n\"ring\":\"画面：无名指上的戒指在灯光下转出一圈光晕——ring「戒指；铃声」。圆环状的首饰是 ring；电话铃响、按门铃也是 ring：圆圈和响声共用一个词。\",\n\"necklace\":\"画面：一条项链垂在锁骨上方，吊坠正落在中间——necklace「项链」。neck（脖子）+ lace（花边、带子）：绕在脖子上的饰带，构词直接画出它戴的位置。\",\n\"bracelet\":\"画面：手镯随手腕转动，碰出细碎的轻响——bracelet「手镯」。brace 本指手臂：戴在腕上的环就是 bracelet；手铐在口语里也被戏称为 bracelets。\",\n\"earring\":\"画面：耳环在耳垂下轻轻晃动， catch 住一道光——earring「耳环」。ear（耳朵）+ ring（环）：挂在耳朵上的小环，构词就是它的使用说明书。\",\n\"watch\":\"画面：抬腕看一眼手表，离会议开始还有五分钟——watch「手表；观看」。手腕上的 watch 是『守望时间』的工具；动词 watch 是专注地看，和守望同源。\",\n\"glasses\":\"画面：摘下眼镜擦去雾气，世界重新清晰——glasses「眼镜」。两片 glass（玻璃）镜片凑成复数 glasses；单说 glass 是玻璃或玻璃杯，别混。\",\n\"sunglasses\":\"画面：正午阳光刺眼，戴上太阳镜世界立刻柔和——sunglasses「太阳镜」。sun（太阳）+ glasses（眼镜）：挡太阳的眼镜，构词就是功能说明。\",\n\"key\":\"画面：一把钥匙插进锁孔，咔哒一声门开了——key「钥匙；关键」。开锁的钥匙是本义；key point（关键点）、答案（answer key）都是它：能打开问题症结的东西。\",\n\"lock\":\"画面：出门前拧两下门锁，确认反锁才放心——lock「锁；锁上」。名词是锁，动词是上锁；a lock of hair 是『一绺头发』，像锁一样绞在一起的一束。\",\n\"door\":\"画面：推开吱呀作响的木门，院子里的光涌进来——door「门」。next door 是隔壁，outdoor 是户外：door 是一切出入口的总代表，托福听力里的宿舍、教室都从门开始。\",\n\"window\":\"画面：雨点敲在窗玻璃上，屋里的人望着外面发呆——window「窗户」。它源于古北欧语『风的眼』：墙上透风透光的眼；电脑的 window（窗口）也是借这只眼。\",\n\"curtain\":\"画面：幕布缓缓拉开，舞台灯光亮起——curtain「窗帘；幕布」。窗上拉的是窗帘，台上拉的是幕布：都是能开合、能遮挡视线的一幅布。\",\n\"floor\":\"画面：光脚踩在木地板上，能感到纹理的凉意——floor「地板；楼层」。脚下踩的是地板；电梯里的 floor 是楼层，会议上 get the floor 是『获得发言权』。\",\n\"ceiling\":\"画面：躺在床上盯着天花板上的吊灯发呆——ceiling「天花板」。头顶那面就是 ceiling；价格的『上限』也叫 ceiling，封顶的天花板，涨不过它。\",\n\"wall\":\"画面：一面砖墙把两个院子隔开，墙上爬满藤蔓——wall「墙壁」。wall 是竖起来的隔断：城墙、院墙、房间的墙；hit the wall 是撞墙期，墙就是一切阻挡的代称。\",\n\"roof\":\"画面：雨点砸在屋顶上噼啪作响，屋里却滴水不漏——roof「屋顶」。roof 是房子的『帽子』；under one roof 是『在同一屋檐下』，口腔上颚也叫 the roof of the mouth。\",\n\"stair\":\"画面：一级级楼梯盘旋而上，脚步声在楼道里回响——stair「楼梯」。stairs 总是复数：一级叫 a stair，一整段楼梯是 a flight of stairs；stare（盯着看）是它的同音捣蛋鬼。\",\n\"elevator\":\"画面：电梯门叮一声打开，里面挤满赶早课的人——elevator「电梯」。elevate 是『升高』：把人往上升的机器；英式英语叫 lift，美式叫 elevator。\",\n\"balcony\":\"画面：阳台上摆着两把椅子，清晨在这里喝咖啡看街景——balcony「阳台」。探出外墙的小平台是阳台；剧院二层的包厢席也叫 balcony，都是『悬挑出去的一圈』。\",\n\"garden\":\"画面：花园里玫瑰开了满墙，蜂蝶在花间忙碌——garden「花园」。种花种菜的那块地；英式里 garden 还泛指自家院子，园艺 gardening 是托福常客话题。\",\n\"yard\":\"画面：后院草坪上孩子们追着球跑——yard「院子」。yard 是房子周围的空地；作单位时 1 yard = 3 英尺（约 0.91 米），yard sale 是美国人卖旧货的院子集市。\",\n\"fence\":\"画面：一排木栅栏沿着院子边界立着，把邻里分开——fence「栅栏」。木板或铁丝竖成的界线；sit on the fence 是『骑墙观望』，坐在栅栏上哪边都不下。\",\n\"gate\":\"画面：机场登机口的大门打开，人群开始排队——gate「大门；登机口」。院门、城门是 gate；机场的登机口也叫 gate，-gate 还成了丑闻后缀（Watergate 水门事件）。\",\n\"garage\":\"画面：车库门缓缓升起，车灯照亮里面的工具墙——garage「车库」。停放汽车的房子；英国人创业爱从 garage 起步，车库创业（garage startup）是硅谷神话的发源地。\",\n\"basement\":\"画面：顺着楼梯走进地下室，空气里带着凉意和旧纸箱的味道——basement「地下室」。base 是『底部、基础』：整栋楼最底下那一层，常年不见阳光，常放杂物和锅炉。\",\n\"furniture\":\"画面：搬家卡车卸下沙发、桌子和床垫，新家慢慢填满——furniture「家具」。家具的总称、不可数：a piece of furniture 是一件家具；它源于法语『配备』，给房子配齐的东西。\",\n\"table\":\"画面：一张木桌摆好四副餐具，等全家人落座——table「桌子；表格」。吃饭学习的平面家具是本义；数据排成行列也是 table，会议上 table a proposal 是『搁置提案』。\",\n\"chair\":\"画面：他拉开椅子坐下，会议正式开始——chair「椅子」。有靠背供一人坐的是 chair；会议的『主席』也叫 chair，坐在主位椅子上的人。\",\n\"desk\":\"画面：书桌上台灯、电脑和摊开的笔记各就各位——desk「书桌」。带抽屉、用来写字办公的是 desk；前台（front desk）、服务台都是这个词。\",\n\"sofa\":\"画面：整个人陷进沙发里，抱着靠垫看电视——sofa「沙发」。软包带靠背扶手的长沙发；美式口语也叫 couch，sofa 更正式一点，托福听力两个都出现。\",\n\"lamp\":\"画面：深夜只有台灯还亮着，圈出一小片暖光——lamp「台灯；灯」。lamp 是能搬动的灯：台灯、油灯、路灯（street lamp）；固定在天花板上的多叫 light。\",\n\"clock\":\"画面：墙上的时钟指针指向整点，铃声准时响起——clock「时钟」。挂在墙上、放在桌上的是 clock；手腕上的叫 watch，手机里的叫 alarm，clock 专管『坐着和挂着』的钟。\",\n\"picture\":\"画面：墙上挂着一幅全家福，是全家唯一一次到齐的合影——picture「图画；照片」。画的、拍的、脑海里的画面都是 picture；take a picture 是拍照，big picture 是大局。\",\n\"photo\":\"画面：手机相册里翻出一张十年前的照片——photo「照片」。photo 是 photograph 的缩写，photo- 是『光』：用光留下的影像；证件照、新闻照都用它。\",\n\"book\":\"画面：一本书摊开在膝上，书页被风轻轻翻动——book「书」。名词是书，动词 book 是『预订』：订票订房都用它，把名字写进预订册（book）里。\",\n\"newspaper\":\"画面：早餐桌上摊着一份报纸，头版是昨夜的大新闻——newspaper「报纸」。news（新闻）+ paper（纸）：印着新闻的纸；如今多在手机上读，名字还是这张纸。\",\n\"magazine\":\"画面：候机厅里随手翻一本杂志，封面是当红明星——magazine「杂志」。它源于阿拉伯语『仓库』：杂志就是装满文章的仓库；枪械的弹匣也叫 magazine，同是『装东西的仓』。\",\n\"letter\":\"画面：把写好的信折好塞进信封，贴上邮票——letter「信件；字母」。一封信是 letter，26 个字母也是 letter：写信和字母同源，都是『字』的事。\",\n\"envelope\":\"画面：信封封口涂上胶水，地址写得端端正正——envelope「信封」。envelop 是『包裹』：把信包起来的纸套就是 envelope，发薪水的信封里曾经装着现金。\",\n\"stamp\":\"画面：在信封右上角贴一枚邮票，信才能启程——stamp「邮票；印章」。贴的是邮票，盖的是印章，跺脚也是 stamp：都是『用力压下去』留下的印记。\",\n\"pen\":\"画面：钢笔在纸上沙沙写字，墨迹未干——pen「钢笔；笔」。pen 泛指笔，钢笔、圆珠笔都是它；动词 pen a letter 是『写信』，动笔（pen）成文。\",\n\"pencil\":\"画面：铅笔在草稿纸上写写擦擦，橡皮屑落了一桌——pencil「铅笔」。源于拉丁语『小尾巴』（笔尖拖出的细线像尾巴）；pencil in 是『暂定安排』，铅笔写的可以擦。\",\n\"eraser\":\"画面：橡皮擦过铅笔字，纸上只剩淡淡的印——eraser「橡皮」。erase 是『擦除』：擦掉铅笔字的小块就是 eraser；英式叫 rubber，美式 eraser 更常见。\",\n\"ruler\":\"画面：用尺子压住纸边，画出一条笔直的线——ruler「尺子；统治者」。量长度的是尺子，管国家的是统治者：都是『划出规矩、定下标准』的人和物。\",\n\"notebook\":\"画面：笔记本上记得密密麻麻，页边全是批注——notebook「笔记本」。记笔记的本子；notebook computer 就是笔记本电脑，像本子一样能合上的电脑。\",\n\"binder\":\"画面：活页夹咔嗒打开，抽出旧讲义换上新的——binder「活页夹」。bind 是『装订、捆绑』：能打开合上、增删页面的夹子，学生人手一个。\",\n\"folder\":\"画面：文件夹里夹着按日期排好的作业——folder「文件夹」。fold 是『折叠』：对折夹住纸的皮就是文件夹；电脑里的 folder 是同样的道理，装文件的夹子。\",\n\"box\":\"画面：纸箱打包封口，写上『易碎品』三个字——box「盒子；箱子」。方的、能装东西的容器总称；动词 box 是拳击，把对手『关进』出拳的范围里。\",\n\"bottle\":\"画面：一瓶水咕咚咕咚灌下，瓶身瘪了下去——bottle「瓶子」。细颈的容器专装液体；bottle up feelings 是『把情绪装瓶子里憋着』，瓶口一开就喷出来。\",\n\"cup\":\"画面：双手捧着一杯热茶，暖意传到掌心——cup「杯子」。带把手的小杯是 cup（茶杯、咖啡杯）；世界杯是 World Cup，奖杯也是这种杯形。\",\n\"glass\":\"画面：玻璃杯碰出清脆的叮当声——glass「玻璃杯；玻璃」。材质是玻璃，容器是玻璃杯（无把）；a glass of water 是一杯水，glasses 复数就成了眼镜。\",\n\"plate\":\"画面：一盘菜端上桌，盘沿擦得锃亮——plate「盘子」。平平的盛菜器皿；地壳的板块也叫 plate，平摊开的薄板都是这个形状。\",\n\"bowl\":\"画面：双手捧起一碗热汤，先吹一吹再喝——bowl「碗」。深口盛汤盛饭的碗；超级碗 Super Bowl 的名字就来自这只碗的形状。\",\n\"spoon\":\"画面：用勺子舀起一勺汤送到嘴边——spoon「勺子」。圆头带柄的小勺；a spoonful of sugar 是『一勺糖』，玛丽·鲍萍的歌都唱它。\",\n\"fork\":\"画面：叉子卷起意面，稳稳送进嘴里——fork「叉子」。餐桌上的四齿叉；路的分叉、河的分流也叫 fork，凡是『一分为二』的形状都归它管。\",\n\"knife\":\"画面：一把刀稳稳切开面包，刀刃闪着冷光——knife「刀」。切东西的刀；复数是 knives（f 变 v）；on a knife-edge 是『如履薄冰』，在刀刃上。\",\n\"chopstick\":\"画面：一双筷子稳稳夹起一颗花生米——chopstick「筷子」。chop 是『快』（洋泾浜英语 pidgin 里的『快快』）+ stick（棍）：快速夹菜的两根小棍，常以一双（a pair）出现。\",\n\"pot\":\"画面：一口大锅炖着汤，锅盖被蒸汽顶得直跳——pot「锅」。深口带盖的锅；a pot of tea 是一壶茶，花盆 flowerpot 也是这种深口容器。\",\n\"pan\":\"画面：平底锅里煎蛋滋滋作响，边缘微微焦黄——pan「平底锅」。浅口的煎锅；pan out 是『（事情）进展、结果』，像淘金盘（pan）里筛出结果。\",\n\"oven\":\"画面：烤箱门打开，面包的香气扑面而来——oven「烤箱」。封闭加热的箱体；微波炉是 microwave oven，oven 专指能烤出面包香的那种大火力箱。\",\n\"stove\":\"画面：炉灶上四口锅同时开工，火苗蓝蓝的——stove「炉灶」。烧火做饭的台子；老式取暖火炉也叫 stove，核心是『有火眼的加热台』。\",\n\"fridge\":\"画面：打开冰箱，冷气扑面，牛奶鸡蛋码得整齐——fridge「冰箱」。refrigerator 的口语缩写；英美人都说 fridge，深夜觊觎冰箱（midnight fridge raid）是共同爱好。\",\n\"freezer\":\"画面：冷冻柜打开，速冻饺子排排站——freezer「冷冻柜」。freeze 是『结冰、冻住』：零下十八度的格子，冰淇淋和饺子的长住地。\",\n\"microwave\":\"画面：微波炉嗡嗡转着，里面的爆米花噼啪炸开——microwave「微波炉」。micro（微小）+ wave（波）：用短波加热的炉子；名词动词同形，microwave the leftovers 就是热剩饭。\",\n\"sink\":\"画面：水槽里泡着待洗的碗，水声哗哗——sink「水槽；下沉」。厨房洗碗的池子是 sink；船沉了、太阳落了也是 sink，都是『往下沉』。\",\n\"tap\":\"画面：拧开水龙头，水哗哗流进杯子——tap「水龙头（英式）；轻拍」。英国人管水龙头叫 tap（美式 faucet）；tap 还有『轻敲』义：tap the screen 点屏幕。\",\n\"faucet\":\"画面：老式水龙头滴滴答答漏了一夜水——faucet「水龙头」。美式说法，指管口带开关的出水嘴；它来自法语『假塞子』，是塞住水管的那个阀门。\",\n\"dishwasher\":\"画面：洗碗机嗡嗡作响，出来时碗盘锃亮——dishwasher「洗碗机」。dish（盘子）+ washer（清洗机）：洗盘子的机器；在餐厅打工刷盘子的人也叫 dishwasher。\",\n\"kettle\":\"画面：水壶烧开，壶嘴喷出白汽呜呜作响——kettle「水壶」。烧水的壶，壶嘴壶把一应俱全；a different kettle of fish 是『完全是另一回事』，壶都换了。\",\n\"toaster\":\"画面：面包片弹起，烤得金黄酥脆——toaster「烤面包机」。toast 是『烤面包片』：把面包烤成金黄色的机器；碰杯祝酒也叫 toast，同源于烤面包配酒的旧俗。\",\n\"blender\":\"画面：搅拌机轰鸣，水果瞬间被打成smoothie——blender「搅拌机」。blend 是『混合』：把水果奶块搅成一团的机器；文化融合也用 blend，搅拌机是它的实体版。\",\n\"coffee\":\"画面：清晨第一杯咖啡，热气裹着香气升起——coffee「咖啡」。世界第二大贸易商品；coffee break 是茶歇，coffee table 是茶几，托福听力里教授的咖啡从不缺席。\",\n\"tea\":\"画面：茶壶倾斜，琥珀色的茶汤注入小杯——tea「茶」。not my cup of tea 是『不是我的菜』；下午茶（afternoon tea）是英式仪式，茶是这一切的中心。\",\n\"milk\":\"画面：一杯牛奶放在餐桌上，配着面包当早餐——milk「牛奶」。挤奶、哺乳都源于它；milk 作动词还有『榨取、捞好处』义，从挤奶的动作引申而来。\",\n\"juice\":\"画面：鲜榨橙汁倒进杯子，果肉在杯底沉浮——juice「果汁」。水果压出的汁；手机『没电』口语说 out of juice，汁水就是能量，形象得很。\",\n\"bread\":\"画面：刚出炉的面包掰开，热气和麦香一起冒出来——bread「面包」。主食的代名词：bread and butter 是『生计』，最好的东西叫 the best thing since sliced bread。\",\n\"butter\":\"画面：黄油在热吐司上慢慢融化，渗进每一个气孔——butter「黄油」。butter someone up 是『拍马屁』，像抹黄油一样把话说得又滑又顺。\",\n\"cheese\":\"画面：一块奶酪切开，拉出长长的丝——cheese「奶酪」。拍照喊 cheese 是因为发音要咧嘴笑；big cheese 是『大人物』，奶酪之王。\",\n\"egg\":\"画面：鸡蛋在碗边轻轻一磕，蛋液滑进碗里——egg「鸡蛋」。egg on 是『怂恿』（另一个词源），put all your eggs in one basket 是『孤注一掷』，鸡蛋易碎，风险自明。\",\n\"rice\":\"画面：一碗白米饭热气腾腾，粒粒分明——rice「大米；米饭」。亚洲主食之王；rice 是不可数名词，一粒米要说 a grain of rice。\",\n\"noodle\":\"画面：一筷子面条从碗里挑起，热气蒸腾——noodle「面条」。细长的面条；泡面是 instant noodles，动词 noodle around 是『瞎琢磨、即兴弹奏』，像面条一样绕来绕去。\",\n\"pasta\":\"画面：一盘意面卷在叉子上，裹满番茄酱——pasta「意大利面」。意大利语本义是『面团』：意面、通心粉、千层面的总称，是个集合名词。\",\n\"pizza\":\"画面：披萨拉出长长的芝士丝，饼边烤得焦脆——pizza「披萨」。意大利那不勒斯的国民食物；拼写里的双 z 读作 /ts/，一口咬下就是这个音。\",\n\"burger\":\"画面：汉堡里肉饼滋滋冒油，生菜番茄层层叠——burger「汉堡」。hamburger 的简称（源于德国汉堡市，与火腿无关）；burger 可以夹着一切，素食的叫 veggie burger。\",\n\"sandwich\":\"画面：两片面包夹住火腿和生菜，一刀切成三角形——sandwich「三明治」。以三明治伯爵命名（他打牌时让人把肉夹进面包好不离桌）；sandwiched between 是『被夹在中间』。\",\n\"salad\":\"画面：一盘沙拉拌好，油醋汁淋在翠绿的叶上——salad「沙拉」。源于拉丁语『盐』（sal）：古罗马人用盐拌生菜；salad days 是『青涩的少年时代』，莎翁造的词。\",\n\"soup\":\"画面：一碗热汤端上桌，先闻香再尝味——soup「汤」。从汤到坚果（from soup to nuts）是『从头到尾全套』；in the soup 是『陷入困境』，像掉进汤锅。\",\n\"cake\":\"画面：生日蛋糕上蜡烛点亮，全场唱起生日歌——cake「蛋糕」。a piece of cake 是『小菜一碟』；卖得火叫 sell like hot cakes，蛋糕就是甜点界的通用货币。\",\n\"cookie\":\"画面：一盘曲奇刚出炉，巧克力豆还半融着——cookie「饼干」。来自荷兰语『小蛋糕』；上网的 cookie（网站小饼干数据）借了这个名字，英式英语里饼干叫 biscuit。\",\n\"candy\":\"画面：糖果罐里五颜六色的糖纸沙沙作响——candy「糖果」。美式叫 candy，英式叫 sweets；eye candy 是『养眼的东西』，糖果就是甜蜜的代称。\",\n\"chocolate\":\"画面：一块巧克力在舌尖慢慢融化——chocolate「巧克力」。源于阿兹特克语『苦水』：可可原味是苦的；chocolate 既是食物也是深棕色，hot chocolate 是冬日标配。\",\n\"fruit\":\"画面：果篮里苹果、橙子、葡萄堆成小山——fruit「水果」。水果的总称（不可数）；劳动的成果也叫 fruits，植物结出的果实引申为一切收获。\",\n\"banana\":\"画面：剥开香蕉皮，果肉弯弯像一弯月牙——banana「香蕉」。go bananas 是『发疯、狂热』；香蕉皮滑倒人的桥段（banana peel）是喜剧的百年老梗。\",\n\"orange\":\"画面：剥开橙子，汁水溅到手上，满屋清香——orange「橙子；橙色」。水果先有名字，颜色借了它：orange 是先果后色的词，比较橙子和苹果（apples and oranges）就是『没法比』。\",\n\"grape\":\"画面：一串葡萄挂在藤上，颗颗挂着白霜——grape「葡萄」。酿酒的原料；sour grapes 是『酸葡萄心理』，伊索寓言里狐狸吃不到葡萄就说葡萄酸。\",\n\"strawberry\":\"画面：一颗草莓咬下去，籽粒分明，酸甜爆汁——strawberry「草莓」。straw（稻草）+ berry（浆果）：传说因铺稻草种植得名；它其实不是真正的 berry，却是浆果界的门面。\",\n\"peach\":\"画面：桃子熟透，绒毛下透出粉红，咬一口汁水横流——peach「桃子」。源于『波斯果』（经波斯传入欧洲）；a peach 还能夸人『可人儿』，桃子在中国是长寿，在英语里是讨喜。\",\n\"pear\":\"画面：一只梨握在手中，梨皮光滑，梨把儿朝天——pear「梨」。pear 和 pair（一双）同音，是听力里的经典陷阱；梨形身材叫 pear-shaped。\",\n\"melon\":\"画面：剖开一只瓜，瓤红籽黑，清甜扑鼻——melon「瓜」。甜瓜类总称：西瓜 watermelon、哈密瓜 cantaloupe 都是 melon 一家；源于希腊语『苹果形的葫芦』。\",\n\"lemon\":\"画面：切开柠檬挤汁，酸得人眯起眼——lemon「柠檬」。酸味担当；买到次品车也叫 a lemon（酸得让人皱眉）；人生给你柠檬就做柠檬水（make lemonade）。\",\n\"cherry\":\"画面：一对樱桃连着梗，像耳环一样垂下来——cherry「樱桃」。cherry on top 是『锦上添花』；樱桃红（cherry red）是颜色，樱桃小口是它在各文化里的共同形象。\",\n\"mango\":\"画面：芒果切开划十字，果肉翻出金黄的『芒果花』——mango「芒果」。经葡萄牙人从印度带来这个名字；热带果王，甜香浓烈，未熟的青芒是另一番酸脆。\",\n\"pineapple\":\"画面：一只菠萝顶着绿冠，表皮是菱格的铠甲——pineapple「菠萝」。pine（松树）+ apple（果）：外形像松果的大果子；它和松树、苹果都无关，全怪殖民者的想象力。\",\n\"vegetable\":\"画面：菜市场摊位上青菜、萝卜、瓜果码成小山——vegetable「蔬菜」。veget- 源于拉丁语『使有生气』（和 vigil 守夜同根）：吃菜长精神；日常口语简称 veg / veggies。\",\n\"cabbage\":\"画面：一颗卷心菜层层包紧，像一只绿色的球——cabbage「卷心菜」。它源于拉丁语 caput（头）：长得像颗头的菜；拼写里的双 b 就像它层层叠叠的叶。\",\n\"cauliflower\":\"画面：一朵花椰菜雪白蓬松，像一小片云落在盘子里——cauliflower「花椰菜」。cauli- 是卷心菜的花茎，flower 是花：开成花束的菜，名字就是长相。\",\n\"broccoli\":\"画面：一棵西兰花像迷你小树，绿冠深深——broccoli「西兰花」。意大利语本义是『小嫩芽』（brocco 是芽）；记住它『绿色小树』的造型，托福阅读里蔬菜常客。\",\n\"lettuce\":\"画面：生菜叶子脆嫩带水珠，包着烤肉一口咬下——lettuce「生菜」。它源于拉丁语 lactuca（含乳汁的植物，掰开有白色汁液）；沙拉里的绿叶主力，汉堡里也夹它。\",\n\"celery\":\"画面：一根根芹菜茎脆生生，蘸着酱当零食嚼——celery「芹菜」。长条带筋的绿茎就是标志；传言吃芹菜消耗的热量比它本身还多，是减肥餐的象征。\",\n\"cucumber\":\"画面：一根黄瓜切开，清香扑鼻，水分十足——cucumber「黄瓜」。cool as a cucumber 是『镇定自若』（黄瓜内部比室外凉几度）；切片敷眼睛是它的经典出场方式。\",\n\"pumpkin\":\"画面：万圣节的南瓜灯咧着嘴，秋天田里还躺着一地大南瓜——pumpkin「南瓜」。源于希腊语『大瓜』；南瓜派是感恩节餐桌的主角，pumpkin spice 是秋天的味道代号。\",\n\"zucchini\":\"画面：一条夏南瓜躺在砧板上，绿皮细长像黄瓜的亲戚——zucchini「夏南瓜」。意大利语 zucca（南瓜）的指小词：小号的瓜；美式叫 zucchini，英式叫 courgette。\",\n\"eggplant\":\"画面：一只紫茄子油亮发光，像挂着水珠的紫灯笼——eggplant「茄子」。egg（蛋）+ plant（植物）：早期品种结白色蛋形果而得名；美式叫 eggplant，英式叫 aubergine。\",\n\"chili\":\"画面：一串红辣椒挂在屋檐下，红得耀眼——chili「红辣椒」。chili con carne 是墨西哥辣肉酱；拼写里两个 l 别丢，辣味担当，托福饮食文化阅读常提它。\",\n\"onion\":\"画面：切洋葱切到一半，眼泪止不住地流——onion「洋葱」。层层剥开像它的结构；peel an onion 是『层层深入』，切洋葱流泪是厨房的共同记忆。\",\n\"garlic\":\"画面：一头大蒜掰成瓣，蒜香辛辣冲鼻——garlic「大蒜」。garlic breath 是吃蒜后的口气；吸血鬼怕大蒜是西方老传说，托福民俗类阅读会提到。\",\n\"ginger\":\"画面：一块生姜切开，辛香立刻窜进鼻子——ginger「生姜」。姜茶、姜饼人（gingerbread man）都靠它；ginger 还是红黄发色，gingerly 是『小心翼翼地』（像怕辣一样谨慎）。\",\n\"carrot\":\"画面：兔子抱着一根胡萝卜啃得咯嘣响——carrot「胡萝卜」。橙色长根是标志；carrot and stick 是『胡萝卜加大棒』（恩威并施），胡萝卜就是奖励的代称。\",\n\"potato\":\"画面：一筐土豆沾着泥，是欧洲人餐桌上的主食——potato「土豆」。couch potato 是『沙发土豆』（整天窝着看电视的人）；它源于美洲，经哥伦布带回欧洲改变了饮食史。\",\n\"tomato\":\"画面：一颗番茄红透，咬开酸甜多汁——tomato「番茄」。到底读『特马头』还是『特妹头』吵了一个世纪；它源于阿兹特克语，曾被欧洲人当毒果，意大利面酱的灵魂。\",\n\"corn\":\"画面：一根玉米棒掰开，金黄颗粒排得整整齐齐——corn「玉米」。美式 corn 专指玉米，英式旧义是谷物总称；popcorn 爆米花是看电影的标配，corn 是北美农业的头号作物。\",\n\"pea\":\"画面：剥开青豆荚，一排圆滚滚的青豆滚出来——pea「豌豆」。豌豆公主（The Princess and the Pea）隔着二十层床垫都能硌到一颗豌豆；like two peas in a pod 是『像一个豆荚里的豆』——非常相像。\",\n\"soybean\":\"画面：一把大豆晒在簸箕里，金黄圆润——soybean「大豆」。soy 是酱油（源于日语『しょうゆ』）：大豆是酱油、豆腐、豆奶的共同老家，东亚餐桌的蛋白质主力。\",\n\"peanut\":\"画面：剥开花生壳，两粒红衣花生米并排躺着——peanut「花生」。pea（豆）+ nut（坚果）：长得像豆的坚果；work for peanuts 是『挣仨瓜俩枣』，花生在英语里是『不值钱』的代称。\",\n\"cashew\":\"画面：一粒腰果弯弯的，像一弯小月牙挂在果子下面——cashew「腰果」。腰果长在 cashew apple 的底部，形状是它唯一的身份证；名字来自葡萄牙语转写的土著语。\",\n\"walnut\":\"画面：砸开核桃壳，里面的果仁像一颗小小的大脑——walnut「核桃」。形状像脑回路，常被说『以形补脑』；wal- 源于『外国的』（古英语里它是外来的坚果）。\",\n\"hazelnut\":\"画面：一颗榛子裹在绿萼里，壳硬仁香——hazelnut「榛子」。hazel 是榛树；能多益榛果酱（Nutella）的主料就是它，小而圆就是它的模样。\",\n\"chestnut\":\"画面：冬夜里糖炒栗子热气腾腾，壳裂开口——chestnut「栗子」。带刺的外壳（burr）是标志；an old chestnut 是『老生常谈的旧段子』，像年年都炒的栗子。\",\n\"coconut\":\"画面：一只椰子插上吸管，椰汁清甜解渴——coconut「椰子」。外面毛茸茸、里面白白的是它；摔开椰子先喝汁再吃肉，热带海岛的画面就全了。\",\n\"olive\":\"画面：一枝橄榄枝上挂着青黑色的果子——olive「橄榄」。橄榄枝（olive branch）是和平的象征；地中海饮食的灵魂是橄榄油，olive 还是橄榄绿这种颜色。\",\n\"avocado\":\"画面：切开牛油果，绿肉黄心，挖一勺抹在吐司上——avocado「牛油果」。源于阿兹特克语，经西班牙语变形而来；avocado toast 是网红早餐，中间那颗大核是它的标志。\",\n\"fig\":\"画面：掰开无花果，里面是密密麻麻的粉红小籽——fig「无花果」。它『无花』却结果（花藏在果内）；亚当夏娃用无花果叶遮身，fig leaf 就成了『遮羞布』的代称。\",\n\"date\":\"画面：一盘椰枣堆在斋月餐桌上，甜得发亮——date「枣」。date 既是日期也是椰枣：约会、日期、海枣同形；开斋先吃一颗 date 是中东的传统画面。\",\n\"plum\":\"画面：一颗李子紫红圆润，咬一口酸甜多汁——plum「李子」。plum job 是『美差』（李子味的甜头）；李子干是 prune，plum pudding 是英国圣诞布丁（里面其实没有李子）。\",\n\"papaya\":\"画面：切开木瓜，橙红的瓤里排着一圈黑籽——papaya「木瓜」。热带大个子水果，切开的颜色就是身份证；它含木瓜蛋白酶（papain），能嫩肉，厨房里当天然嫩肉粉。\",\n\"pomegranate\":\"画面：剖开石榴，成百上千颗红宝石般的籽挤在一起——pomegranate「石榴」。pome 是『苹果类果』，granate 是『多籽』：一肚子籽的大果子；希腊神话里珀耳塞福涅吃下石榴籽，从此每年回冥界。\",\n\"blueberry\":\"画面：一把蓝莓滚进碗里，颗颗蒙着白霜——blueberry「蓝莓」。blue（蓝）+ berry（浆果）：蓝紫色的小浆果，名字直白；蓝莓派、蓝莓松饼是北美早餐桌的常客。\",\n\"raspberry\":\"画面：一颗覆盆子像小灯笼，由无数小珠攒成——raspberry「覆盆子」。它由一粒粒小 drupelet 攒成、中空套在梗上；吹口哨式的『嘘声』（raspberry）是另一个俚语义，先记这颗红珠攒成的小果。\",\n\"blackberry\":\"画面：一串黑莓由小珠攒成，熟透了黑得发亮——blackberry「黑莓」。black（黑）+ berry（浆果）：黑亮的小珠果；曾经红极一时的黑莓手机就借了它成串的造型当名字。\",\n\"cranberry\":\"画面：一片蔓越莓田注满水，红果子漂满水面等着采收——cranberry「蔓越莓」。北美的采收奇观：果子中空能浮水；感恩节的 cranberry sauce 是火鸡的固定搭档，酸味担当。\",\n\"watermelon\":\"画面：剖开西瓜，红瓤黑籽，一口下去暑气全消——watermelon「西瓜」。water（水）+ melon（瓜）：水分最足的瓜，名字里写着 92% 的含水量，夏天的主角。\",\n\"cantaloupe\":\"画面：切开哈密瓜，橙色瓤香甜扑鼻，表皮带着网纹——cantaloupe「哈密瓜」。名字来自意大利小镇 Cantalupo（最早在欧洲种出它）；网纹 + 橙瓤就是它的身份证。\",\n\"honeydew\":\"画面：一只蜜瓜切开，青白的瓤清甜如蜜——honeydew「蜜瓜」。honey（蜜）+ dew（露）：甜得像蜜露的瓜；它和哈密瓜是亲戚，瓤是淡青色，皮光滑无网纹。\",\n\"tangerine\":\"画面：一只橘子剥开，瓣瓣分明，皮薄得一撕就开——tangerine「橘子」。名字来自摩洛哥港口丹吉尔（Tangier）；它比 orange 小、皮松、好剥，是柑橘家族里最好上手的一个。\",\n\"grapefruit\":\"画面：半个葡萄柚撒上糖，用勺子挖着吃——grapefruit「葡萄柚」。因成串挂在树上像葡萄（grape）得名，其实个头大得多；酸苦清爽，是减肥餐和早餐的常客。\",\n\"lime\":\"画面：半颗酸橙挤进汽水，气泡立刻翻涌——lime「酸橙」。青绿、比柠檬更酸的是 lime；它还是『石灰』，两个义都来自黏糊糊的鸟胶（古英语 lim），先记这颗青果子。\",\n\"herb\":\"画面：窗台上一排香草盆栽，罗勒薄荷绿油油——herb「草药；香草」。能入药、能调味的草本植物总称；herb 的 h 在美式里常不发音，是厨房和药房的交界词。\",\n\"basil\":\"画面：一把罗勒叶铺在披萨上，香气冲鼻——basil「罗勒」。源于希腊语『国王』（basilikos）：香草之王；意大利青酱（pesto）的灵魂，和番茄是天生一对。\",\n\"mint\":\"画面：一片薄荷叶揉一揉，清凉直冲鼻腔——mint「薄荷」。薄荷糖、牙膏、莫吉托都靠它；mint 还是『铸币厂』，in mint condition 是『崭新如刚出厂』。\",\n\"parsley\":\"画面：一盘菜端上桌，先撒一把切碎的欧芹点缀——parsley「欧芹」。西餐盘边的绿点缀担当，长得像香菜却是两味；它源于希腊语『石头芹菜』（长在石缝边）。\",\n\"cilantro\":\"画面：一把香菜撒在牛肉面上，爱的人狂喜恨的人皱眉——cilantro「香菜」。美式叫 cilantro，英式叫 coriander；爱恨分明是因为有人天生尝出肥皂味，托福听力都拿它开玩笑。\",\n\"dill\":\"画面：一簇羽毛状的莳萝叶搭在腌黄瓜罐子边——dill「莳萝」。羽毛一样的细叶是标志；dill pickle 是北美经典酸黄瓜，北欧人做三文鱼离不开它。\",\n\"rosemary\":\"画面：一枝迷迭香针叶细长，揉一揉满手松香——rosemary「迷迭香」。rose（玫瑰）+ mary（玛丽）：传说圣母的外袍染蓝了它的花；针叶 + 强香是它的身份证，烤肉必备。\",\n\"thyme\":\"画面：一小把百里香撒进炖锅，香气慢慢渗出——thyme「百里香」。它和 time 同音，是英语老师的经典玩笑；希腊语本义是『 fumigation 熏香』，古人拿它当香料和勇气象征。\",\n\"cinnamon\":\"画面：几根肉桂卷成棒，炖肉煮茶都放一根——cinnamon「肉桂」。树皮卷起来就是它；cinnamon roll 是肉桂卷，秋冬热红酒和苹果派的暖香担当。\",\n\"vanilla\":\"画面：一根香草荚剖开，黑籽密密麻麻香得浓烈——vanilla「香草」。兰花的果荚；plain vanilla 是『原味的、普通的』，因为香草冰淇淋是最基础的口味。\",\n\"cocoa\":\"画面：一杯热可可冒着热气，表面浮着可可粉——cocoa「可可」。cacao 的拼写变体；巧克力的原料，苦味是它的底色，托福讲美洲作物交换时必提它。\",\n\"wheat\":\"画面：一片麦田金浪翻滚，麦穗沉甸甸低头——wheat「小麦」。面包、面条、意面的共同源头；separate the wheat from the chaff 是『去芜存菁』，麦子就是精华的代称。\",\n\"barley\":\"画面：一把大麦粒圆润带芒，是啤酒的原料——barley「大麦」。比小麦耐寒，喂牲口、酿啤酒、煮麦茶；麦芒（芒刺）长是它和 wheat 的区别。\",\n\"oat\":\"画面：一碗燕麦粥撒上莓果，是健身人群的早餐——oat「燕麦」。oats 总是复数出场；sow wild oats 是『年轻时荒唐放纵』，燕麦在英语里和放纵有点关系。\",\n\"rye\":\"画面：一片黑麦做成的面包颜色深、味道酸香——rye「黑麦」。北欧黑面包（rye bread）的原料，麦穗细长；《麦田里的守望者》原名 The Catcher in the Rye，抓的就是这片麦田。\",\n\"millet\":\"画面：一把小米金黄细小，熬出的粥浮着一层米油——millet「小米」。世界上最古老的粮食之一，耐旱；鸟食里也常见它，小粒金黄就是标志。\",\n\"sorghum\":\"画面：一株高粱举着红穗，比人还高一头——sorghum「高粱」。茎秆像甘蔗、穗子结实粒；中国高粱酿白酒，美国南部有 sorghum syrup（高粱糖浆），耐旱是它的本事。\",\n\"quinoa\":\"画面：一碗藜麦饭松松散散，小粒带着卷曲的芽环——quinoa「藜麦」。安第斯山区的『粮食之母』，其实是种子不是谷物；读音是 KEEN-wah，拼写最容易被读错的健康食物。\",\n\"flour\":\"画面：一把面粉扬起，案板上白雾蒙蒙——flour「面粉」。它源于 flower（花的精华部分）：谷物磨成的粉；flour 和 flower 同音，是听力老陷阱。\",\n\"dough\":\"画面：一团面团在案板上揉得光滑，醒发后胖了一圈——dough「面团」。水和面粉的结合体；俚语里 dough 还是『钱』（做面包是生计，和 bread 同理）。\",\n\"yeast\":\"画面：面团里的小气泡越来越多，整团面慢慢鼓起来——yeast「酵母」。让面包发起来、啤酒冒泡的微生物；没有它 dough 只是死面团，发酵就是它的魔法。\",\n\"crumb\":\"画面：吃完面包，桌上落了一层细细的面包屑——crumb「面包屑；碎屑」。汉塞尔与格莱童的面包屑小路就是它；breadcrumb 在电脑里是『面包屑导航』，顺着碎屑找回路。\",\n\"slice\":\"画面：一刀切下薄薄一片面包，断面整齐——slice「切片；一片」。名词是切下的一片，动词是切；a slice of life 是『生活的一个横截面』，披萨按 slice 卖。\",\n\"chunk\":\"画面：一大块巧克力掰下来，厚实实在——chunk「大块」。粗粗厚厚的一块是 chunk：冰块、肉块、代码块（chunk of code）都行，和 slice 的薄片正好成对比。\",\n\"grain\":\"画面：指尖捻起一粒麦，阳光下看得见它的纹路——grain「谷粒；纹理」。一粒谷物是 grain；木头的纹理、照片的颗粒感也叫 grain，against the grain 是『逆着纹理』——别扭。\",\n\"kernel\":\"画面：剥开玉米棒，一颗颗金黄的粒整齐排列——kernel「果仁；粒」。玉米粒、坚果仁都是 kernel；操作系统的『内核』也叫 kernel，都是最核心的那颗仁。\",\n\"husk\":\"画面：掰开玉米，外层干皮被一层层剥下——husk「外壳」。谷物果实外面的干皮；剥壳的动作也叫 husk，它是 kernel 的反面——一个护着、一个被护着。\",\n\"stalk\":\"画面：一根麦秆直立田间，顶上托着麦穗——stalk「茎秆」。植物的主干是 stalk；作动词是『跟踪、悄悄接近』（猎人贴着秆子摸近猎物），两义都带着细长贴近的影子。\",\n\"sausage\":\"画面：一根香肠在锅里煎得滋滋响，肠衣微微卷边——sausage「香肠」。肉馅灌进肠衣的长条；英式早餐的标配，德式香肠（wurst）是它的大家族亲戚。\",\n\"bacon\":\"画面：两片培根在平底锅里煎出焦边，油香四溢——bacon「培根」。猪腹肉腌制烟熏而成；bring home the bacon 是『挣钱养家』，培根就是餐桌上的硬通货。\",\n\"ham\":\"画面：一只火腿挂在梁上，油光发亮——ham「火腿」。猪后腿腌制的整块肉；圣诞火腿（Christmas ham）是欧美节日主菜，ham 还是『拙劣的演员』（俚语），先记这条腿。\",\n\"steak\":\"画面：一块牛排在铁板上滋滋作响，表面煎出菱格纹——steak「牛排」。厚切的肉排，牛排为主；三分熟 medium rare 的点单对话是托福听力的高频场景。\",\n\"beef\":\"画面：菜市场案板上一块牛肉纹理分明——beef「牛肉」。牛是 cow，上桌叫 beef（法语词源，诺曼征服的历史痕迹）；俚语 beef 还是『抱怨、过节』，where's the beef 是经典广告词。\",\n\"pork\":\"画面：一块猪肉带着雪花纹的脂肪——pork「猪肉」。猪是 pig，上桌叫 pork，和 beef 同理是法语借词；pork barrel 是『政治分肥』，猪肉桶里捞好处。\",\n\"mutton\":\"画面：一盘羊肉端上桌，膻香扑鼻——mutton「羊肉」。成年羊的肉叫 mutton，羊羔肉叫 lamb；mutton dressed as lamb 是句刻薄话——『装嫩』，记年龄差就记住这对词。\",\n\"seafood\":\"画面：一盘海鲜拼盘，虾蟹贝类堆得满满——seafood「海鲜」。sea（海）+ food（食物）：来自海里的食物总称；过敏提示里 seafood 是常客词。\",\n\"dessert\":\"画面：正餐结束，一份甜点端上桌，全场眼睛发亮——dessert「甜点」。饭后甜食；和 desert（沙漠）只差一个 s，却是托福拼写第一陷阱：甜点有双 s，因为好吃想再来一份。\",\n\"pudding\":\"画面：一勺布丁颤巍巍，淋上焦糖酱——pudding「布丁」。英式里 pudding 泛指甜点，美式是奶冻状的软甜品；圣诞布丁（Christmas pudding）其实是硬实的果料蛋糕。\",\n\"custard\":\"画面：一碗蛋奶冻滑嫩嫩，勺子下去微微颤动——custard「蛋奶冻」。牛奶鸡蛋蒸成的嫩冻；卡仕达酱是西点馅料的常客，滑、嫩、蛋香是它的三字诀。\",\n\"jam\":\"画面：草莓酱抹在吐司上，红得透亮——jam「果酱；堵塞」。果肉熬成的酱；交通堵塞是 traffic jam，人被『酱』住动不了；jam session 是乐手的即兴合奏。\",\n\"jelly\":\"画面：一盘果冻晃一晃，弹性十足——jelly「果冻」。果汁凝成的透明冻；美式 jelly 是涂面包的果冻酱，英式 jelly 是餐桌甜品冻，先记它『颤巍巍』的样子。\",\n\"honey\":\"画面：一勺蜂蜜拉出长长的丝，淋在面包上——honey「蜂蜜」。蜜蜂的产物；honey 也是亲爱的（称呼），honeymoon 是蜜月——甜，就是这个词的全部联想。\",\n\"syrup\":\"画面：糖浆缓缓淋在松饼上，顺着边缘流下来——syrup「糖浆」。枫糖浆（maple syrup）是加拿大的招牌；止咳糖浆也叫 syrup，浓、稠、甜是它的标志。\",\n\"vinegar\":\"画面：一碟醋摆在饺子边，酸香冲鼻——vinegar「醋」。源于法语『酸酒』（vin aigre）：酒酸了变醋；吃醋的『醋意』在英语里没有这层，vinegar 只管调味和腌渍。\",\n\"mustard\":\"画面：热狗上挤出一道黄色的芥末酱——mustard「芥末」。黄芥末酱是热狗汉堡的搭档；芥末色（mustard yellow）是种土黄色，种子磨的酱就是它。\",\n\"ketchup\":\"画面：薯条蘸着番茄酱，一根接一根停不下来——ketchup「番茄酱」。词源众说纷纭，一说来自闽南语『茄汁』（kê-tsiap）；红色瓶身是餐桌的固定风景。\",\n\"mayonnaise\":\"画面：一勺蛋黄酱拌进土豆沙拉，立刻顺滑起来——mayonnaise「蛋黄酱」。油和蛋黄乳化的白酱；拼写是法语长相，常被简写成 mayo，沙拉和三明治都离不开它。\",\n\"rocking\":\"画面：一把摇椅在门廊上前后轻轻晃着——rocking「摇椅（rocking chair）」。rock 是『摇晃』：rocking chair 是能前后摇的椅子，rock and roll 的摇晃也源于它；此处指那把晃着的椅子。\",\n\"stool\":\"画面：一张三条腿的圆凳摆在吧台前——stool「凳子」。没有靠背、没有扶手的小座；吧台的高脚凳叫 bar stool，和 chair 的区别就是『没靠背』。\",\n\"bench\":\"画面：公园里一张长凳，两个人分坐两端看书——bench「长凳」。供多人坐的长条座；法官席也叫 the bench（长凳升格成法庭），替补席球员坐的也是它。\",\n\"couch\":\"画面：周末整个人摊在长沙发上看剧——couch「长沙发」。比 sofa 更口语的美式词；couch potato 是沙发土豆，couch surfing 是借宿沙发——都是这张能躺的沙发。\",\n\"loveseat\":\"画面：一张双人沙发刚好坐两个人，肩并肩——loveseat「双人沙发」。love（爱）+ seat（座位）：为两个人设计的座位，比 couch 小、比单人椅大，名字自带亲密感。\",\n\"ottoman\":\"画面：一只软脚凳摆在沙发前，脚搭上去正舒服——ottoman「脚凳」。源于奥斯曼帝国传来的无背软凳；搁脚、临时当座、当茶几都行，是客厅的多面手。\",\n\"bookshelf\":\"画面：一排书架塞满书，书脊颜色深浅不一——bookshelf「书架」。book（书）+ shelf（架子）：放书的层架；单层是 shelf，整架是 bookshelf / bookcase。\",\n\"bookcase\":\"画面：一只带玻璃门的书柜立在书房角——bookcase「书柜」。case 是『箱、柜』：比 bookshelf 更像家具柜子，带门带框，把书收进格子间。\",\n\"cupboard\":\"画面：打开碗柜，碗盘按大小叠放整齐——cupboard「碗柜；橱柜」。cup（杯子）+ board（板）：原是放杯盘的架子；厨房吊柜、地柜都归它管，老鼠嫁女的故事里躲的就是它。\",\n\"wardrobe\":\"画面：拉开衣柜门，一排衣服挂得满满当当——wardrobe「衣柜」。ward（看守）+ robe（袍子）：守着衣服的大柜子；引申为一个人全部的衣服（her winter wardrobe）。\",\n\"dresser\":\"画面：一台梳妆台上摆着镜子和首饰盒——dresser「梳妆台；衣柜」。dress（穿衣）+ -er：换衣服时用的家具，美式还指带抽屉的衣柜；镜面 + 抽屉是它的模样。\",\n\"nightstand\":\"画面：床头柜上放着台灯、水杯和一本书——nightstand「床头柜」。night（夜）+ stand（架台）：守夜的小柜子，手机眼镜的夜间停机坪。\",\n\"mattress\":\"画面：一张床垫弹簧回弹，躺上去整个人被托住——mattress「床垫」。源于阿拉伯语『垫子、躺卧处』；air mattress 是充气床垫，mattress 决定睡眠质量，是家具购买清单的大件。\",\n\"pillow\":\"画面：一个枕头拍松软，头陷进去正舒服——pillow「枕头」。枕头打架是 pillow fight；pillow talk 是枕边私语——枕头是夜里最亲近的家具。\",\n\"blanket\":\"画面：冬夜把毯子裹紧，只露出脸——blanket「毯子」。盖在身上的大块织物；blanket 还作形容词『全覆盖的』（blanket ban 全面禁令），像毯子一样盖住一切。\",\n\"quilt\":\"画面：一床棉被绗线成格，鼓鼓囊囊——quilt「被子」。填充棉絮、绗缝成格的厚被；美式拼布被（patchwork quilt）是手工传统，一格一格就是它的身份证。\",\n\"sheet\":\"画面：一张床单铺平掖好，平整无皱——sheet「床单；一张」。铺床的单层布是 sheet；一张纸也是 a sheet，同是『薄薄的一层』，冰层叫 ice sheet。\",\n\"rug\":\"画面：一块小地毯铺在沙发前，脚感立刻暖了——rug「小地毯」。能卷起来、铺局部的叫 rug；全屋铺满的叫 carpet，大小是它俩的界线，sweep under the rug 是『掩盖丑闻』。\",\n\"carpet\":\"画面：整间屋子铺满地毯，走路悄无声息——carpet「地毯」。墙到墙全覆盖的是 carpet；红毯是 red carpet，on the carpet 是『被叫去训话』，地毯见证一切场合。\",\n\"mat\":\"画面：一张瑜伽垫铺开，出门还有一块擦脚垫——mat「垫子」。薄薄的一片垫：门垫、餐垫、瑜伽垫都归它；mat 还是『无光泽的』（哑光），垫子般的平和闷。\",\n\"candle\":\"画面：一支蜡烛在停电的夜里摇曳着光——candle「蜡烛」。生日、烛光晚餐、停电夜都靠它；can't hold a candle to 是『远比不上』，替人举蜡烛的助手都算不上。\",\n\"lantern\":\"画面：元宵节一盏灯笼挂在檐下，暖光透纸——lantern「灯笼」。有罩护着火的提灯；南瓜灯是 jack-o'-lantern，中式灯笼是 paper lantern，能提着走的光。\",\n\"flashlight\":\"画面：手电筒的光束划破黑暗，照亮脚下的路——flashlight「手电筒」。flash（闪光）+ light（光）：手握的光源；英式叫 torch，美式 flashlight 更常见。\",\n\"bulb\":\"画面：一只灯泡亮起，钨丝发出暖黄的光——bulb「灯泡；球茎」。圆球状的发光体；植物的球茎（ tulip bulb）也叫 bulb，都是圆鼓鼓的『球』。\",\n\"plug\":\"画面：把插头插进插座，指示灯亮起——plug「插头；塞子」。插进电的叫 plug in；堵水池的塞子也是 plug，plug away 是『埋头苦干』——一直插着使劲。\",\n\"socket\":\"画面：墙上的插座两个孔，像一张小脸——socket「插座」。插头插入的孔座；眼窝是 eye socket，凡是『凹进去承接的座』都是 socket。\",\n\"switch\":\"画面：手指按下开关，灯应声而亮——switch「开关；切换」。名词是开关，动词是切换：switch jobs 换工作、switch sides 换边——开关一拨，状态就变。\",\n\"wire\":\"画面：一根电线把插座和台灯连起来——wire「电线」。金属细线总称；电报时代 wire 是电文，under the wire 是『压线完成』，线就是连接与传递。\",\n\"cord\":\"画面：一根电源线从桌后垂下来，绕成一团——cord「绳索；电线」。细绳、电线、线缆都叫 cord；声带是 vocal cords，脊髓是 spinal cord，都是身体里的『索』。\",\n\"rope\":\"画面：一根粗绳把船系在码头桩上——rope「绳子」。比 cord 粗壮的绳索；know the ropes 是『懂门道』（水手的绳索学问），跳绳是 jump rope。\",\n\"string\":\"画面：一根细绳系着气球，飘在半空——string「细绳」。比 rope 细的线绳；吉他弦也是 string，a string of 是『一串』——珠子、事件都能串在这根细线上。\",\n\"chain\":\"画面：一环扣一环的铁链锁住大门——chain「链条」。金属环相扣成链；连锁店是 chain store，食物链是 food chain，环环相扣就是它的全部形象。\",\n\"nail\":\"画面：一锤下去，钉子没入木板——nail「钉子；指甲」。钉进木头的是钉子，长在指尖的也是 nail；hit the nail on the head 是『一语中的』，正中钉子头。\",\n\"screw\":\"画面：螺丝刀旋转，螺丝一点点没入木板——screw「螺丝」。带螺纹、靠旋转固定的钉子；screw up 是『搞砸』，拧过头了——先记这颗转着进去的螺丝。\",\n\"bolt\":\"画面：一颗螺栓配着螺母，把钢梁锁得死死的——bolt「螺栓；闪电」。配螺母的大螺栓；闪电也是 bolt（一道劈下的力量），门闩同名——都是『猛地插上』。\",\n\"hammer\":\"画面：一把锤子抡起，钉子应声入木——hammer「锤子」。名词动词同形；拍卖锤、裁判锤都是它；hammer out 是『反复敲定』（协议），锤子是敲定的象征。\",\n\"saw\":\"画面：一把锯子来回拉动，木头应声而断——saw「锯子」。锯齿来回是标志；saw 也是 see 的过去式，同形不同命，靠语境分——托福听力的小陷阱。\",\n\"drill\":\"画面：电钻嗡嗡钻进墙面，粉尘簌簌落下——drill「钻；演练」。打孔的钻，操练的 drill（消防演练 fire drill）同名：都是『反复钻研、反复练』。\",\n\"wrench\":\"画面：一把扳手卡住螺母，用力一拧——wrench「扳手」。美式叫 wrench（英式 spanner）；throw a wrench in 是『捣乱、搅局』，扳手掉进机器里最耽误事。\",\n\"pliers\":\"画面：一把钳子夹住钉子，一使劲拔了出来——pliers「钳子」。永远复数（两片咬合）：拔钉、夹物、拧铁丝都靠它，和 scissors 一样是『双片工具』家族。\",\n\"shovel\":\"画面：一把铲子插进土里，翻起一锹土——shovel「铲子」。铲雪、铲土的大号工具；snow shovel 是雪铲，它和 spade 的区别在铲面更大更平。\",\n\"rake\":\"画面：一把耙子把落叶拢成一堆——rake「耙子」。长齿梳地：耙土、耙落叶；rake in money 是『大把捞钱』，像耙子一样往自己这边搂。\",\n\"hoe\":\"画面：一把锄头翻开田土，杂草连根带起——hoe「锄头」。农具里的翻土高手；a hard row to hoe 是『艰难的处境』，锄头就是农活的象征。\",\n\"axe\":\"画面：一把斧头劈下，木柴应声成两半——axe「斧头」。劈柴开山的利器；get the axe 是『被解雇、被砍掉』，斧头落下就是终结。\",\n\"bucket\":\"画面：一只水桶从井里提上来，水花四溅——bucket「水桶」。圆筒带提梁的容器；kick the bucket 是『翘辫子』（俚语），bucket list 是『遗愿清单』，都从这只桶来。\",\n\"broom\":\"画面：一把扫帚扫过院子，落叶聚成一堆——broom「扫帚」。长柄带刷头的清扫工具；女巫骑的就是它，new broom 是『新官上任三把火』的新扫帚。\",\n\"mop\":\"画面：拖把在水桶里涮一涮，拖过地板一片水光——mop「拖把」。拖地的布头杆子；mop up 是『收尾、善后』，像拖把吸干最后的水迹。\",\n\"dustpan\":\"画面：一只簸箕贴地，扫帚把灰尘扫进去——dustpan「簸箕」。dust（灰尘）+ pan（平盘）：承接灰尘的平盘，和 broom 是天生的搭档。\",\n\"trash\":\"画面：一袋垃圾扎好口，扔进楼下的桶里——trash「垃圾」。美式日常词（英式 rubbish）；trash talk 是『垃圾话』，trash 在口语里还能作动词『抨击、毁坏』。\",\n\"garbage\":\"画面：厨余垃圾散发着隔夜的味道——garbage「垃圾」。偏指厨余等有机垃圾，常和 trash 混用；garbage in, garbage out 是计算机名言——『废料进，废料出』，数据的质量守恒。\",\n\"recycling\":\"画面：空瓶子投进蓝色回收箱，开始新的轮回——recycling「回收」。re-（再）+ cycle（循环）：让材料转圈重生；recycle bin 是回收站，recycling 是环保话题的核心词。\",\n\"forehead\":\"画面：发烧时把手贴上额头，烫得吓人——forehead「前额」。fore-（前面）+ head（头）：头最前面的那块，发际线到眉毛之间，皱眉、冒汗都在这里发生。\",\n\"eyeball\":\"画面：显微镜下一颗眼球的模型缓缓转动——eyeball「眼球」。eye（眼）+ ball（球）：眼睛的那颗球体；动词 eyeball 是『盯着估量』，像用眼球当尺子。\",\n\"pupil\":\"画面：强光下瞳孔迅速缩成小点——pupil「瞳孔」。瞳孔里能照出人影，古罗马人叫它 pupilla『小娃娃』；pupil 还是『小学生』，两个义都来自『小』。\",\n\"iris\":\"画面：放大镜下虹膜的纹路像一片花瓣向外辐射——iris「虹膜」。iris 是希腊彩虹女神之名：虹膜的颜色千人千样（蓝、棕、绿），鸢尾花也叫 iris，同是彩虹色。\",\n\"cornea\":\"画面：隐形眼镜轻轻贴上眼球最前面的透明层——cornea「角膜」。corn- 是『角质』（和 horn 同根）：眼球前部透明坚韧的『窗』，光线进眼睛的第一站。\",\n\"retina\":\"画面：眼底镜下，视网膜像一张铺满血管的网——retina「视网膜」。ret- 源于拉丁语 rete（网）：眼球后部那层感光的网，倒像成在这里，再传给大脑翻正。\",\n\"nostril\":\"画面：感冒时一个鼻孔堵得死死的——nostril「鼻孔」。nost- 是鼻子（nose 的亲戚），-thril 是古英语『洞』：鼻子上的两个洞，呼吸和嗅觉的入口。\",\n\"cheek\":\"画面：孩子笑起来，脸颊鼓起两个酒窝——cheek「脸颊」。眼睛下方、嘴角两旁的软肉；cheek 对 cheek 是『脸贴脸』跳舞，cheeky 是英式『厚脸皮的、没大没小的』。\",\n\"chin\":\"画面：思考时手托着下巴，胡茬扎手——chin「下巴」。嘴以下的面部底座；keep your chin up 是『别灰心，抬起下巴』，double chin 是双下巴，chin 是脸的下巴底线。\",\n\"jaw\":\"画面：嚼口香糖时下颌一上一下地动——jaw「颌」。上下颌骨统称，尤指下颌；his jaw dropped 是『惊得下巴掉下来』，jaw 还是老虎钳的钳口——都是咬合的部件。\",\n\"lip\":\"画面：冬天嘴唇干裂，抹上润唇膏才敢张口——lip「嘴唇」。上下两片唇；bite your lip 是『强忍着不说』，lip service 是『口头支持』——只有嘴唇在动，没有行动。\",\n\"tongue\":\"画面：尝一口柠檬，舌头立刻缩回去——tongue「舌头」。尝味、说话都靠它；mother tongue 是母语，tongue-tied 是『张口结舌』——舌头就是语言的代称。\",\n\"tooth\":\"画面：一颗智齿在牙科灯下被拔出，白得晃眼——tooth「牙齿」。复数是 teeth（oo 变 ee 的老规矩）；武装到牙齿 armed to the teeth，甜食爱好者是 sweet tooth，都离不开这口牙。\",\n\"gum\":\"画面：刷牙太用力，牙龈渗出血丝——gum「牙龈」。包着牙根的粉色软肉；gum 还是口香糖（gum tree 的胶）和胶水，黏糊糊是它三个义的共同点。\",\n\"throat\":\"画面：嗓子发炎，咽口水都像吞刀片——throat「喉咙」。声音和食物的共同通道；a lump in the throat 是『哽咽』，clear your throat 清嗓子是发言前的经典动作。\",\n\"neck\":\"画面：长颈鹿伸长脖子去够高处的叶子——neck「脖子」。连接头和躯干的通道；neck and neck 是『并驾齐驱』（脖子齐着脖子），瓶颈 bottleneck 就藏在这个词里。\",\n\"shoulder\":\"画面：他耸耸肩表示无能为力——shoulder「肩膀」。shrug（耸肩）的发生地；shoulder the blame 是『扛起责任』，路肩也叫 shoulder——都是边缘承重的那条带。\",\n\"armpit\":\"画面：举起手臂，腋下夹着体温计——armpit「腋窝」。arm（手臂）+ pit（坑）：手臂根部的凹陷；体味、剃毛、夹温度计都在这里，是个有点尴尬但实用的词。\",\n\"elbow\":\"画面：胳膊肘撑在桌上，手托着腮——elbow「肘」。手臂的『铰链』；elbow room 是『活动空间』（肘能伸开的地方），elbow grease 是『费力气的苦工』，弯的那一节就是它。\",\n\"wrist\":\"画面：手表戴在手腕上，脉搏在表下轻轻跳——wrist「手腕」。手和胳臂之间的细关节；wristwatch 的家，扭伤最常见的部位，键盘族的职业病也在这里。\",\n\"palm\":\"画面：摊开手掌，掌纹清清楚楚——palm「手掌」。手心的一面是 palm；棕榈树也叫 palm tree，传说因叶片像手掌得名——摊开的手就是形状本身。\",\n\"finger\":\"画面：五根手指在钢琴键上翻飞——finger「手指」。拇指单独叫 thumb，其余四根是 finger；point the finger 是『指责』（手指指人），指纹是 fingerprint。\",\n\"thumb\":\"画面：竖起大拇指给他一个赞——thumb「拇指」。最短最粗的手指；rule of thumb 是『经验法则』，under someone's thumb 是『受人摆布』，点赞的手势全球通用。\",\n\"fist\":\"画面：握紧拳头砸在桌上，关节发白——fist「拳头」。五指收拢的团；raise a fist 是抗议的姿势，紧握（clench your fist）是愤怒的信号，拳头是力量的最小单位。\",\n\"chest\":\"画面：深吸一口气，胸膛高高鼓起——chest「胸部」。心肺的『保险箱』；get it off your chest 是『把心里话说出来』（从胸口卸下），藏宝箱也叫 chest，同是带盖的箱体。\",\n\"breast\":\"画面：知更鸟的胸脯一片鲜红，格外醒目——breast「乳房；胸脯」。鸟类的胸、人的乳房、鸡胸肉（chicken breast）都用它；解剖学词，在生物阅读里中性出现。\",\n\"belly\":\"画面：吃饱后肚子圆鼓鼓，裤腰都紧了——belly「腹部；肚子」。口语的肚子（正式说 abdomen）；belly laugh 是『捧腹大笑』，肚子先笑起来；火的中心叫 the belly of the fire。\",\n\"waist\":\"画面：量腰围时把软尺绕在腰最细处——waist「腰」。躯干最细的那一圈；waistline 是腰围，裤腰是 waistband——衣服和身体的交界线就是 waist。\",\n\"hip\":\"画面：她随着音乐摆动臀部跳起舞——hip「臀；髋」。骨盆两侧的突起；hip 还是俚语『时髦的』（hip-hop 的 hip），先记身体的这个转角：腰以下、腿以上的枢纽。\",\n\"thigh\":\"画面：深蹲时大腿前侧绷得发酸——thigh「大腿」。膝盖到髋的这一段，人体最粗的肌肉群所在地；鸡腿的整段也叫 thigh，健身房里练的就是它。\",\n\"knee\":\"画面：跪下求婚时单膝触地——knee「膝盖」。on your knees 是『跪地求饶』，bee's knees 是俚语『出类拔萃』；膝盖是腿的铰链，踢到膝盖反射是体检的经典一幕。\",\n\"shin\":\"画面：踢到桌腿，小腿前侧疼得倒吸凉气——shin「小腿前部」。膝盖到脚踝的正面、胫骨所在处；踢足球戴的护腿板就护 shin，这里皮薄骨硬，磕一下最疼。\",\n\"heel\":\"画面：踮起脚尖时脚后跟离地——heel「脚后跟」。阿喀琉斯之踵（Achilles' heel）是致命弱点，正是脚后跟；高跟鞋的『跟』也是 heel，脚的最末端。\",\n\"toe\":\"画面：脚趾抠住地面保持平衡——toe「脚趾」。脚上的『手指』；toe the line 是『循规蹈矩』（脚趾踩线），dip your toe in 是『试试水』，都从这排小趾开始。\",\n\"sole\":\"画面：光脚踩在沙滩上，脚底沾满细沙——sole「脚底」。脚掌着地的一面；鞋底同名；表『唯一』的 sole（sole survivor 唯一幸存者）来自拉丁 solus，是同形异源的另一个词，只是拼写相同。\",\n\"scalp\":\"画面：头皮屑落在深色衣服上格外明显——scalp「头皮」。覆盖头骨的皮肤层；黄牛票贩子也叫 scalper，是『高价倒卖牟利』的江湖义，与解剖义无关。\",\n\"pelvis\":\"画面：X 光片上骨盆像一只蝴蝶张开翅膀——pelvis「骨盆」。拉丁语本义是『盆』：托住内脏的骨盆，连接脊柱和双腿，是人体重心的底座。\",\n\"abdomen\":\"画面：做仰卧起坐时腹部收紧发力——abdomen「腹部」。医学正式词（口语是 belly/tummy）；昆虫身体三段的最后一段也叫 abdomen，体检报告上写的是它。\",\n\"intestine\":\"画面：示意图里肠道像盘起的水管，占满腹腔——intestine「肠」。盘曲的消化通道，小肠大肠总称；源于拉丁语『内部的』，它就是身体内部最长的那条管路。\",\n\"stomach\":\"画面：饿得胃咕咕叫，闻到饭香更受不了——stomach「胃」。装食物的袋子；have the stomach for 是『有胆量做某事』，on an empty stomach 是空腹——胃和勇气在英语里有点关系。\",\n\"bladder\":\"画面：喝水太多，膀胱胀得坐立难安——bladder「膀胱」。存尿的囊袋；原意就是『囊、泡』，鱼鳔、球胆（气囊）都叫 bladder，充气收纳的容器是其本相。\",\n\"gallbladder\":\"画面：超声图上胆囊像一颗小梨挂在肝下——gallbladder「胆囊」。gall 是古英语『胆汁』：储存胆汁的小囊，挂在肝脏下面，胆结石就长在这里。\",\n\"pancreas\":\"画面：解剖图上胰腺横卧在胃的后方，黄黄的一条——pancreas「胰腺」。希腊语『全是肉』（pan 全 + kreas 肉）；分泌胰岛素的器官，糖尿病阅读里必出现。\",\n\"spleen\":\"画面：体检单上脾脏大小一栏标着正常——spleen「脾」。左上腹的淋巴器官；古希腊医学认为它管忧郁，vent your spleen 是『发泄怒气』，脾在旧医学里是情绪器官。\",\n\"appendix\":\"画面：右下腹一阵剧痛，医生怀疑是阑尾炎——appendix「阑尾」。肠子尾巴上的小盲管；书末的附录也叫 appendix——都是『正文之外挂着的小尾巴』，同词两用。\",\n\"diaphragm\":\"画面：深呼吸时膈膜像降落伞一样上下起伏——diaphragm「膈膜」。希腊语『隔墙』：分开胸腔腹腔的肌肉穹顶；相机光圈也叫 diaphragm，同是开合的隔片。\",\n\"trachea\":\"画面：解剖课上气管的 C 形软骨环一节一节——trachea「气管」。通向肺的空气管道，前面有硬环支撑；医学词，日常说 windpipe，考试阅读用 trachea。\",\n\"esophagus\":\"画面：造影片上一口水顺着食道滑进胃里——esophagus「食道」。希腊语『把吃的东西送下去』：连接喉咙和胃的肌管，食物的专用滑梯，拼写里的 ph 读 /f/。\",\n\"bone\":\"画面：X 光片上骨头白得发亮，骨折线清清楚楚——bone「骨头」。骨骼的单块；bone dry 是『干透了』，have a bone to pick 是『有账要算』，狗啃的骨头是最原始的画面。\",\n\"marrow\":\"画面：敲开筒骨，里面的骨髓滑嫩鲜香——marrow「骨髓」。骨头芯里的软组织，造血的工厂；chilled to the marrow 是『冷到骨子里』，marrow 就是『最核心处』。\",\n\"pore\":\"画面：放大镜下皮肤上的毛孔像小小的火山口——pore「毛孔」。皮肤上的微孔，出汗透气；pore over a book 是『埋头钻研』（凑近了连毛孔都对着书），满脸汗时 pores 全开。\",\n\"sweat\":\"画面：跑完五公里，汗珠顺着额头往下滚——sweat「汗」。名词是汗水，动词是出汗；no sweat 是『小事一桩』，sweat the small stuff 是『为小事焦虑』，汗是努力的计量单位。\",\n\"tear\":\"画面：一滴眼泪顺着脸颊滑下——tear「眼泪」。眼睛流出的是 tear（读『梯尔』）；撕裂也是 tear（读『太尔』），同形不同音，托福听力分辨全靠语境。\",\n\"saliva\":\"画面：看到酸梅，唾液不自觉地分泌——saliva「唾液」。口腔里的消化液，望梅止渴靠它；医学正式词，日常说 spit，唾液腺是 salivary gland。\",\n\"mucus\":\"画面：感冒时鼻涕不断，纸巾用掉一整包——mucus「黏液」。呼吸道、消化道分泌的黏滑液体；名词是 mucus，形容词是 mucous（一字之差），感冒阅读里的常客。\",\n\"blood\":\"画面：一滴血在显微镜下，红细胞密密麻麻——blood「血液」。blood pressure 血压、blood test 验血；blood 还指血统（bloodline），in cold blood 是『冷血地』，血是生命的代称。\",\n\"downtown\":\"画面：市中心高楼林立，霓虹灯亮到深夜——downtown「市中心」。down（往下）+ town（城）：老地图上城在下方而得名，美式专指商业中心区，和郊区 suburb 正对。\",\n\"suburb\":\"画面：一排带草坪的独栋小楼，离市中心半小时车程——suburb「郊区」。sub-（次于、靠近）+ urb（城市）：城边的住宅区，美国梦的标配场景，托福听力里的家庭住址常在这里。\",\n\"outskirts\":\"画面：城市边缘最后一排楼房，再往外就是农田——outskirts「市郊」。out（外）+ skirt（裙边）：城市的『裙边地带』，永远用复数，城乡在这里交界。\",\n\"neighborhood\":\"画面：街区里小店、学校、公园一应俱全——neighborhood「社区；街区」。neighbor（邻居）+ -hood（范围）：邻里生活的圈子；in the neighborhood of 还表示『大约』（在某数附近）。\",\n\"district\":\"画面：地图上金融区被涂成一片金色——district「地区；区」。行政或功能划分的一区：学区、商业区、红灯区都是 district；哥伦比亚特区（D.C.）的 D 就是它。\",\n\"zone\":\"画面：地图上把一片区域涂成黄色，标着『施工区』——zone「地带」。按功能圈定的带状区域：时区 time zone、禁区 no-go zone；zone out 是『走神』，人飘出了自己的区域。\",\n\"province\":\"画面：中国地图上一个省被单独涂上颜色——province「省」。国家的一级行政区（加拿大、中国都用 province）；源于罗马帝国的『行省辖区』；the provinces 引申为『外省、地方』，带一点眼界之外的味道。\",\n\"county\":\"画面：美国地图上密密麻麻的小格子，每格是一个县——county「县」。美国的二级行政区（州下面是 county）；源于伯爵（count）的领地，英国的『郡』同名。\",\n\"township\":\"画面：一个乡镇有主街、小学和邮局，规模不大——township「乡镇」。美国的一种基层行政区，南非史上另有其义；比 town 小、比 village 大的聚居单位，慢生活是其画面。\",\n\"village\":\"画面：一个小村庄炊烟袅袅，鸡犬相闻——village「村庄」。global village 是『地球村』（麦克卢汉名言）；奥运村叫 Olympic Village，村子就是自给自足的小聚落。\",\n\"hamlet\":\"画面：一个只有几户人家的小村落，连商店都没有——hamlet「小村庄」。village 的缩小版；大名鼎鼎的 Hamlet 是莎翁的丹麦王子，同形不同人，拼写一字不差。\",\n\"town\":\"画面：一座小镇主街两侧是面包房和邮局——town「城镇」。介于 village 和 city 之间；go to town 是俚语『大干一场』，ghost town 是鬼城——镇是聚落的中间站。\",\n\"city\":\"画面：一座城市的天际线在黄昏里亮起万家灯火——city「城市」。city 是大聚落的总称；city hall 是市政厅，inner city 是市中心老区——城市越大，city 的搭配越多。\",\n\"metropolis\":\"画面：一座超级大都市，高楼和轨道交通织成巨网——metropolis「大都市」。希腊语『母城』（meter 母亲 + polis 城）：城市的母体版，纽约、东京这个量级才配叫 metropolis。\",\n\"port\":\"画面：港口里集装箱堆成山，吊车来回装卸——port「港口」。船只停靠装卸的口岸；port 还是左舷、端口（USB port）、加强葡萄酒。注意：港口的 port 源于拉丁 portus『门户、避风港』，和『搬运』的 port（portare）同出古老的『穿过』一源，却不是同一个词，别混拆。\",\n\"harbor\":\"画面：夜里港湾避风安静，渔船排排停靠——harbor「海港」。能避风浪的天然或人工水域；harbor 还作动词『窝藏、心怀』（harbor doubts 心怀疑虑），港湾藏船，心里藏事。\",\n\"dock\":\"画面：货轮靠上码头，工人开始系缆绳——dock「码头」。船停靠装卸的那段岸；笔记本扩展坞也叫 dock，船进坞、电脑接坞，都是『对接停靠』。\",\n\"pier\":\"画面：一条木栈桥伸进海里，尽头有人垂钓——pier「栈桥；码头墩」。从岸边探进水里的长条平台；桥墩也叫 pier（支撑的那根柱），海滨小城的风景线。\",\n\"lighthouse\":\"画面：灯塔的光束在夜海上旋转，警告暗礁——lighthouse「灯塔」。light（光）+ house（房）：装灯的塔，给夜航的船指方向；孤悬海角是它的标准像。\",\n\"bridge\":\"画面：一座大桥跨江而过，车流如织——bridge「桥梁」。连接两岸的结构；牌类桥牌、鼻梁、乐器的琴马都叫 bridge——一切『横跨连接之物』。\",\n\"tunnel\":\"画面：车钻进隧道，只剩车灯照着前方的洞口亮光——tunnel「隧道」。穿山、过江底的通道；tunnel vision 是『视野狭窄』（只看洞口那点光），掘地道也用这个词。\",\n\"highway\":\"画面：一条高速公路笔直伸向地平线——highway「高速公路」。美国州际公路的主称（英式 motorway）；highway robbery 是『明抢』（贵得离谱），公路是流动的大动脉。\",\n\"freeway\":\"画面：多车道快速路上车流飞驰，没有红绿灯——freeway「快速路」。free 是『免费/畅通』：无信号灯、可高速行驶的城市快速路，加州人把它叫 the freeway。\",\n\"expressway\":\"画面：高架快速道绕城而行，出口牌一闪而过——expressway「快速干道」。express（快速）+ way（路）：城市高架的主干道，和 freeway 近义，多见于亚洲英语和美东。\",\n\"boulevard\":\"画面：一条林荫大道两侧梧桐成排，咖啡馆临街——boulevard「林荫大道」。源于法语，原指城墙拆除后的宽阔大道；日落大道 Sunset Boulevard 是好莱坞的地标，宽、直、绿是它的气质。\",\n\"lane\":\"画面：一条乡间小路只容一车，两边是篱笆和野花——lane「小路；车道」。窄窄的一条道：乡间小路、泳道、车道都叫 lane；memory lane 是『回忆小巷』，慢行是其本色。\",\n\"path\":\"画面：一条林间小径蜿蜒，落叶铺满地面——path「小径」。人走出来的窄路；人生道路、文件路径（file path）都借它——选定方向留下痕迹的线，就是 path。\",\n\"trail\":\"画面：一条登山步道盘旋而上，路口立着木牌——trail「小道；足迹」。野外踩出的小径；足迹、尾迹也是 trail，trail off 是『声音渐弱』（像足迹消失在远方）。\",\n\"sidewalk\":\"画面：人行道上行人匆匆，旁边车道车流滚滚——sidewalk「人行道」。side（边）+ walk（走）：路边走人的那条道，美式词，英式叫 pavement，纽约的街景里全是它。\",\n\"crosswalk\":\"画面：斑马线上一队小学生举手过街——crosswalk「斑马线」。cross（横穿）+ walk（走）：行人横穿马路的白条区；美国司机遇它必停，交通安全课的头号词。\",\n\"intersection\":\"画面：十字路口四面车流，红绿灯轮流放行——intersection「十字路口；交点」。inter-（之间）+ sect（切）：道路互相切割的点；数学的交集也叫 intersection，十字路口的画面最直观。\",\n\"corner\":\"画面：街角的便利店亮着灯，转角就是地铁口——corner「街角；角落」。两条街、两面墙相交的角；cornered 是『被逼入死角』，球场角球同名——角落感是它的灵魂。\",\n\"plaza\":\"画面：一座广场上鸽子成群，喷泉在中央起舞——plaza「广场」。源于西班牙语的露天公共空间；购物广场也叫 plaza，人和活动聚集的开阔地是它。\",\n\"playground\":\"画面：操场上滑梯秋千，孩子们的笑声满场——playground「游乐场；操场」。play（玩）+ ground（场地）：给孩子玩的地盘；引申为富人的『游乐场』（度假胜地）也成立。\",\n\"zoo\":\"画面：动物园里大熊猫抱着竹子，游客隔栏围观——zoo「动物园」。zoological garden 的缩写，zoo- 是『动物』词根（zoology 动物学）；乱成一团的场面俚语也叫 a zoo。\",\n\"library\":\"画面：一排排书架望不到头，读者在长桌前安静阅读——library「图书馆」。拉丁语 liber 是『书』：收藏书的地方；程序员的代码库也叫 library，藏的都是可复用的宝贝。\",\n\"bookstore\":\"画面：一家书店飘着纸和咖啡的香气——bookstore「书店」。book（书）+ store（店）：卖书的店（英式 bookshop）；和 library 的分工是：一个卖，一个借。\",\n\"school\":\"画面：一所学校清晨升旗，学生鱼贯进教室——school「学校」。源于希腊语『闲暇』（古人闲暇时学习）；一群鱼也是 a school of fish，同形同拼，语境定身份。\",\n\"nursery\":\"画面：托儿所里小床排排，老师带着孩子唱歌——nursery「托儿所；苗圃」。nurse（照料）延伸：照料幼儿的叫托儿所，照料幼苗的叫苗圃；nursery rhyme 是童谣，陪孩子长大的歌。\",\n\"store\":\"画面：一家大商店橱窗明亮，货架满满——store「商店；储存」。美式大商店（英式 shop 偏小店）；store 还是动词『存储』，仓库和商店本是一家。\",\n\"shop\":\"画面：一家小店挂着手写招牌，老板在柜台后——shop「小店；购物」。英式的小型店铺；go shopping 是逛街买东西，workshop 是车间/研讨班——shop 的家族很大。\",\n\"mall\":\"画面：一座购物中心里几十家店围着中庭——mall「购物中心」。美式大型室内购物综合体；华盛顿的 National Mall 是林荫大道绿地，同名不同物，看上下文。\",\n\"supermarket\":\"画面：超市里推着购物车穿行在货架迷宫间——supermarket「超市」。super（超级）+ market（市场）：超大号自选市场；购物车和条形码是它的出场标配。\",\n\"bakery\":\"画面：面包店飘出刚出炉的香气，橱窗码着可颂——bakery「面包店」。bake（烘烤）+ -ery（场所）：烤面包的地方；清晨排队买面包是欧美街区的日常画面。\",\n\"butcher\":\"画面：肉店案板上挂着一排肉，老板手起刀落——butcher「肉店；屠夫」。卖肉的人和店同名；butcher 还作动词『屠杀、把事情搞砸』，刀口上的词，气质硬朗。\",\n\"grocery\":\"画面：拎着一袋杂货走出小店，面包牛奶探出袋口——grocery「杂货店；食品杂货」。卖食品日杂的小店（美式 grocery store）；groceries 是采购的一袋袋食材，家庭采购清单的统称。\",\n\"restaurant\":\"画面：一家餐馆里服务员端着菜穿梭，客人满座——restaurant「餐馆」。源于法语『使恢复』（最初卖滋补汤）：出外吃饭的地方，菜单和买单是它的固定剧本。\",\n\"cafe\":\"画面：一家咖啡馆靠窗座，咖啡拉花正美——cafe「咖啡馆」。法语 café 直借：卖咖啡简餐的小馆子；留学生泡图书馆之外的第二自习室，多半就是它。\",\n\"hotel\":\"画面：一家酒店大堂灯火通明，前台办理入住——hotel「酒店」。提供住宿的大型场所；hotel 和 hostel 一字之差：一个住得舒服，一个住得便宜，别订错。\",\n\"motel\":\"画面：公路边一排平房旅馆，车就停在房门口——motel「汽车旅馆」。motor（汽车）+ hotel（旅馆）：为开车人设计的旅馆，停车即到房门，美国公路片的标配。\",\n\"inn\":\"画面：一家山间小客栈挂着木招牌，炉火正旺——inn「客栈」。古老的小型旅店（尤指乡村、带酒馆）；圣经里『客栈没有空房』的 inn 就是它，温馨古朴是其气质。\",\n\"hostel\":\"画面：一间青年旅馆的上下铺宿舍，背包客们交换旅行故事——hostel「青年旅馆」。youth hostel 的简称：便宜、多人间、社交强，背包客的宇宙中心，和 hotel 只差一个字母。\",\n\"resort\":\"画面：一座海岛度假村，泳池椰林连着沙滩——resort「度假村」。专为休闲而建的综合体；last resort 是『最后的手段』（无处可去才去的地方），先记海岛这一面。\",\n\"theater\":\"画面：一座剧院幕布拉开，全场屏住呼吸——theater「剧院」。希腊语『观看之地』：演戏放电影的场所（美式 theater，英式 theatre）；手术室在英式里也叫 operating theatre。\",\n\"stadium\":\"画面：一座体育场座无虚席，世界杯决赛正酣——stadium「体育场」。源于希腊长度单位 stadion（约 192 米，一圈跑道）；环形看台 + 中央赛场是它的标准像。\",\n\"gym\":\"画面：一间健身房里器械排排，镜墙映着挥汗的人——gym「体育馆；健身房」。gymnasium（希腊语『裸身锻炼处』）的缩写；学校体育馆和商业健身房都叫 gym，汗味是其气味。\",\n\"pool\":\"画面：一座泳池水光粼粼，泳道线笔直——pool「游泳池」。swimming pool 的简称；水洼、资源池（car pool 拼车）都叫 pool——汇聚成一洼的都是 pool。\",\n\"office\":\"画面：一间办公室格子间成排，键盘声此起彼伏——office「办公室」。办公的场所；office 还指公职（in office 在任），box office 是票房——都是『办理事务』的地方。\",\n\"factory\":\"画面：一座工厂流水线运转，产品鱼贯而出——factory「工厂」。fact- 是『制造』：把原料做成产品的地方；工业革命的象征，托福工业史阅读的常客场景。\",\n\"farm\":\"画面：一座农场里红谷仓和绿田相映——farm「农场」。种庄稼养牲口的地；farm 还作动词『务农』，服务器农场（server farm）是借它的『成片经营』之意。\",\n\"ranch\":\"画面：一座牧场上栅栏望不到边，牛仔骑马赶牛——ranch「牧场」。美式大牧场（尤指养牛）；ranch 也是单层平房的风格名，西部牛仔的家就是这幅画。\",\n\"barn\":\"画面：一座红谷仓里堆着干草，燕子在梁上筑巢——barn「谷仓」。存粮草、关牲口的大棚屋；美国农场的标志性建筑（多漆成红色），谷仓猫头鹰 barn owl 是它的住户。\",\n\"greenhouse\":\"画面：一座玻璃温室里热带植物郁郁葱葱——greenhouse「温室」。green（绿）+ house（房）：种满绿植的玻璃房；温室效应是 greenhouse effect，地球被罩住的画面同一个来源。\",\n\"orchard\":\"画面：一片果园里苹果树成行，果子压弯枝头——orchard「果园」。专门种果树的园子；樱桃园、柑橘园都叫 orchard，和 vineyard（葡萄）、grove（小片）分工明确。\",\n\"vineyard\":\"画面：一片葡萄园顺山坡排开，葡萄藤成行成列——vineyard「葡萄园」。vine（葡萄藤）+ yard（园地）：酿酒葡萄的产地；托斯卡纳和纳帕谷的风景照就是它的模样。\",\n\"field\":\"画面：一片田野望不到边，麦子在风里起伏——field「田野；领域」。开阔的农田草地；学术领域（field of study）、运动场、电场磁场都叫 field——一块有边界的开阔面。\",\n\"pasture\":\"画面：一片牧场草地上奶牛低头吃草——pasture「牧场草地」。专门放牧的草地；put out to pasture 是『让退休』（把老马放回草场），草地就是牛羊的食堂。\",\n\"woods\":\"画面：一片树林幽深，阳光从叶缝漏下来——woods「树林」。比 forest 小、比 grove 大的成片树木地带；out of the woods 是『脱离困境』，走出林子就安全了。\",\n\"grove\":\"画面：一小片橘树林整齐成阵，果香四溢——grove「小树林」。小片的、常是人工的树林（一类树为主）：柑橘园 olive grove 都用它，是 forest 的小清新版。\",\n\"jungle\":\"画面：一片热带丛林藤蔓交错，雾气弥漫——jungle「丛林」。密不透光的热带密林；the law of the jungle 是『丛林法则』（弱肉强食），城市丛林（concrete jungle）是它的比喻版。\",\n\"rainforest\":\"画面：一片雨林终年湿润，层层树冠遮天蔽日——rainforest「雨林」。rain（雨）+ forest（森林）：地球之肺（亚马孙），年雨量 2 米起步，生物多样性之王，托福生态阅读的头号场景。\",\n\"well\":\"画面：一口井边辘轳转动，水桶缓缓提上来——well「井」。取水的深洞；well 还是副词『好』和感叹词，井的画面最具体：打水、井喷（oil well 油井）都从这个洞出发。\",\n\"mammal\":\"画面：一只小狗出生后趴在妈妈肚子上吃奶，身上披着毛——mammal「哺乳动物」。判据就两条：有毛发、用母乳喂幼崽；人、鲸、蝙蝠都是它，再大也是吃奶长大的。\",\n\"reptile\":\"画面：一条蛇贴着晒热的石头缓缓爬行，鳞片闪光——reptile「爬行动物」。冷血、披鳞、贴地爬：蛇、蜥蜴、龟、鳄鱼都是它；体温随环境变，天冷就发僵。\",\n\"amphibian\":\"画面：一只青蛙小时候是水里甩尾巴的蝌蚪，长大蹦上岸用肺呼吸——amphibian「两栖动物」。amphi- 是『两边』：水陆两边都住，皮肤湿滑不能离水太远。\",\n\"insect\":\"画面：一只蚂蚁停下来数自己的腿：整整六条，身体分头、胸、腹三段——insect「昆虫」。六条腿加三段身体是昆虫身份证；蜘蛛八条腿，就不是昆虫。\",\n\"beetle\":\"画面：一只甲虫掀开硬邦邦的鞘翅，里面折着薄薄的飞行翅——beetle「甲虫」。前翅硬化成『铠甲』是它独有的构造，瓢虫、金龟子都是甲虫家族的。\",\n\"mosquito\":\"画面：深夜耳边嗡嗡响，一只蚊子正把细针似的口器扎进皮肤吸血——mosquito「蚊子」。吸血的是雌蚊（产卵要营养）；它传播疟疾，是托福卫生话题的常客。\",\n\"fly\":\"画面：一只苍蝇搓着前脚停在餐桌边，只有一对翅膀嗡嗡振动——fly「苍蝇」。它和 mosquito 同为双翅目；fly 也是动词『飞』，这只虫就是因善飞得名。\",\n\"cockroach\":\"画面：深夜厨房灯一亮，一只蟑螂贴着墙角飞快逃窜——cockroach「蟑螂」。夜行、扁身、跑得快，生命力极强；roach 是它的简称，美式口语常单说 roach。\",\n\"cricket\":\"画面：夏夜草丛里，雄蟋蟀摩擦翅膀发出清脆的唧唧声求偶——cricket「蟋蟀」。它靠翅膀摩擦发声、后腿善跳；注意 cricket 还指板球运动，看语境分辨。\",\n\"grasshopper\":\"画面：一只蚱蜢屈起粗壮的后腿，猛地一蹬跳出老远——grasshopper「蚱蜢」。grass（草）+ hopper（跳者）：草丛里的跳跃高手；成群爆发就是蝗灾的主角。\",\n\"dragonfly\":\"画面：一只蜻蜓悬停在池塘上方，两对透明大翅膀微微颤动，复眼占了大半个头——dragonfly「蜻蜓」。幼虫在水里生活，成虫是空中捕蚊高手，飞行可急停倒退。\",\n\"ladybug\":\"画面：一只红底黑点的瓢虫爬在叶片上，正津津有味地吃蚜虫——ladybug「瓢虫」。它是农民欢迎的益虫，一只一生能吃上千只蚜虫；英式英语叫 ladybird。\",\n\"firefly\":\"画面：夏夜的河边，一只萤火虫提着忽明忽暗的小灯一闪一闪飞过——firefly「萤火虫」。fire（火）+ fly：尾部发光是求偶信号，光是冷光，几乎不产生热。\",\n\"moth\":\"画面：一只飞蛾绕着路灯不停打转，身体毛茸茸、触角像小羽毛——moth「飞蛾」。多在夜间活动、爱扑光；和蝴蝶的区别：停下时翅膀平摊，触角呈羽状。\",\n\"wasp\":\"画面：一只黄蜂细腰一扭，尾针蜇人后还能拔出再蜇——wasp「黄蜂」。腰细、毒刺可反复使用（不像蜜蜂蜇完就死）；纸做的蜂巢挂在屋檐下要当心。\",\n\"hornet\":\"画面：一只个头硕大的大黄蜂嗡嗡盘旋，巢像灰纸灯笼挂在树杈上——hornet「大黄蜂」。它是黄蜂里体型最大的一类，毒性更强；惹怒一只可能招来整群。\",\n\"termite\":\"画面：一截木梁被白蚁蛀空，里面白花花的软体小虫密密麻麻——termite「白蚁」。长得像蚂蚁却不是蚂蚁，专吃木头纤维，是房屋的大害；名字里有 white ant 的旧叫法。\",\n\"flea\":\"画面：一只跳蚤在狗毛里一蹦老高，跳的高度是身长的上百倍——flea「跳蚤」。无翅、善跳、吸血；注意和 flee（逃跑）只差一个字母，读音却完全相同。\",\n\"louse\":\"画面：一只虱子扁扁地趴在头皮上吸血，卵黏在发根白白一点——louse「虱子」。寄生在毛发里、靠吸血过活；复数是 lice（和 mouse→mice 一样不规则）。\",\n\"tick\":\"画面：一只蜱虫把头埋进皮肤里吸血，肚子胀得圆鼓鼓——tick「蜱虫」。它属于蛛形纲（和蜘蛛是亲戚），会传播莱姆病；tick 还有『滴答声；勾选』义。\",\n\"mite\":\"画面：显微镜下，一只螨虫在尘埃里爬动，肉眼几乎看不见——mite「螨虫」。小到以微米计，藏在灰尘、被褥和皮肤毛囊里；和 tick 一样是八条腿的蛛形亲戚。\",\n\"centipede\":\"画面：一条蜈蚣贴着墙根飞快爬过，每一节身体都伸出一对脚——centipede「蜈蚣」。centi- 是『百』：脚多到号称百足，第一对脚是毒钩，能捕食小虫。\",\n\"millipede\":\"画面：一条千足虫慢慢卷成一团，圆柱形的身体每节有两对小脚——millipede「千足虫」。milli- 是『千』：脚比蜈蚣还多，性子却温和，只吃腐叶、没有毒钩。\",\n\"scorpion\":\"画面：一只蝎子高举钳子，尾巴弯过头顶，末端毒刺蓄势待发——scorpion「蝎子」。八条腿的蛛形动物，住在干热地带；记住对比：蜈蚣脚多身长，蝎子有钳有尾刺。\",\n\"crab\":\"画面：一只螃蟹举着大钳子横着走，眼睛长在短柄上四处张望——crab「螃蟹」。十足目、横着走是它的招牌；crab 还是动词『抱怨』，螃蟹的钳子别惹、牢骚别听。\",\n\"lobster\":\"画面：一只龙虾挥舞着一大一小两只巨钳，煮熟后通体变红——lobster「龙虾」。深海底栖，靠那对不对称的钳子 crush 猎物；活的其实是青褐色，下锅才红。\",\n\"shrimp\":\"画面：一只小虾弓着背在水里一弹一弹地游，须子长长的——shrimp「虾」。体型小、弯腰如弓；口语里 shrimp 还讽刺『矮小的人』，和 prawn 对虾比个头更小。\",\n\"prawn\":\"画面：盘子里一只对虾个头快有手掌长，两对钳子清晰可见——prawn「对虾」。和 shrimp 是近亲，个头明显更大，常成对出售所以叫『对虾』；菜单上 prawn 更显档次。\",\n\"squid\":\"画面：一只鱿鱼喷出一团墨汁，十条腕足推着梭子似的身体箭一样窜走——squid「鱿鱼」。十腕、速度快、会喷墨；和章鱼数脚区分：鱿鱼十条，章鱼八条。\",\n\"octopus\":\"画面：一只章鱼八只腕足吸盘密布，正拧开瓶盖取食——octopus「章鱼」。octo- 是『八』（October 原是第八月）：八腕、三心、极聪明，是无脊椎动物里的智商担当。\",\n\"jellyfish\":\"画面：一只水母像透明的伞在海里一张一合地漂，触手拖在下面暗藏毒刺——jellyfish「水母」。jelly（果冻）+ fish：身体 95% 是水，没有脑和心，却蜇人很疼。\",\n\"starfish\":\"画面：一只海星五腕张开趴在礁石上，正慢慢撬开一只贝——starfish「海星」。star（星星）形身体，切断一腕还能再生；它其实不是鱼，学名 sea star 更准。\",\n\"seahorse\":\"画面：一只海马竖着身子在海草间漂，马形的头、卷曲的尾，还由爸爸负责怀孕——seahorse「海马」。雄性有育儿袋是它独一无二的招牌；游动时直立，像水里的骑士。\",\n\"oyster\":\"画面：一只牡蛎粗糙的壳半张着，吸附在礁石上滤食海水——oyster「牡蛎」。壳面凹凸不平、固着生活；极少数能孕育珍珠，生食配柠檬是经典吃法。\",\n\"clam\":\"画面：一只蛤蜊把斧足伸出壳挖沙，两片壳一合严丝合缝——clam「蛤蜊」。藏身沙泥、壳闭如钳；高兴得像蛤蜊 as happy as a clam 是英语习语。\",\n\"mussel\":\"画面：一簇贻贝用足丝把自己拴在礁石上，黑壳密密麻麻——mussel「贻贝」。壳乌黑、成群固着在潮间带；和 muscle（肌肉）读音完全相同，靠语境和拼写区分。\",\n\"scallop\":\"画面：一只扇贝张开扇子形的壳喷水，竟靠开合壳『游』了起来——scallop「扇贝」。壳如折扇、边缘有亮蓝小眼；我们吃的『带子』就是它的大闭壳肌。\",\n\"eel\":\"画面：一条鳗鱼滑溜溜像蛇一样在水底蜿蜒，无鳞的皮肤抓都抓不住——eel「鳗鱼」。细长蛇形、洄游传奇：欧洲鳗要游回马尾藻海产卵；电鳗的电就是它的防御。\",\n\"salmon\":\"画面：一条鲑鱼逆流跃过瀑布，拼死游回它出生的那条溪流产卵——salmon「鲑鱼」。洄游认祖是它的史诗；肉呈橙红因吃了虾青素，l 不发音，读 /ˈsæmən/。\",\n\"trout\":\"画面：一条鳟鱼顶着清冽的山溪水流，身上的斑点在阳光下闪动——trout「鳟鱼」。鲑鱼的近亲，偏爱冷而清的淡水；彩虹鳟的体侧有一道彩虹带，最易认。\",\n\"tuna\":\"画面：一条金枪鱼像纺锤一样高速巡游，体温比海水还高——tuna「金枪鱼」。游泳健将、部分热血，是寿司与罐头的明星；过度捕捞让蓝鳍金枪鱼成了保护话题。\",\n\"cod\":\"画面：一条鳕鱼拖着颌下一根小须，在北大西洋冷水里成群游动——cod「鳕鱼」。下巴的须是它的标志；鳕鱼曾养活欧洲航海史，鱼肝油就是从它身上来的。\",\n\"bass\":\"画面：一条鲈鱼张着大口伏在水草边，等小鱼游近猛地吞下——bass「鲈鱼」。淡水海水都有，肉食性、是垂钓热门目标；注意 bass 作乐器是『低音』，读音不同。\",\n\"carp\":\"画面：一条鲤鱼跃过龙门造型的浪花，胡须在嘴边飘动——carp「鲤鱼」。适应力极强、能忍浑浊水质；在中国文化里是吉祥符号，跃龙门说的就是它。\",\n\"catfish\":\"画面：一条鲶鱼嘴巴宽宽，几对长须像猫须一样探着泥底找食——catfish「鲶鱼」。cat（猫）+ fish：须子就是名字来源；多栖息底层、夜行，肉嫩少刺。\",\n\"piranha\":\"画面：一群食人鱼围住落水的猎物，三角利齿几分钟就把肉剔净——piranha「食人鱼」。南美食肉鱼，牙尖群猛名声大；其实多数种类吃植物，真袭人事件极少。\",\n\"seagull\":\"画面：一只海鸥盘旋在码头上空，盯着游客手里的薯条俯冲抢食——seagull「海鸥」。sea（海）+ gull：白羽长翼、叫声响亮，是海港最熟悉的身影。\",\n\"pelican\":\"画面：一只鹈鹕张开大嘴，喉囊像网兜一样兜起一兜水和鱼——pelican「鹈鹕」。巨大的喉囊是它的渔网，一次能兜十几升水；成群排队驱鱼是它的合作战术。\",\n\"flamingo\":\"画面：一只火烈鸟单腿站在浅滩，粉红羽毛配弯成钩的喙——flamingo「火烈鸟」。粉色来自食物里的虾青素，停食就褪成白色；单腿站立能站一整天。\",\n\"ostrich\":\"画面：一只鸵鸟迈开长腿在草原狂奔，翅膀张着保持平衡却飞不起来——ostrich「鸵鸟」。世界最大的鸟、跑速冠军；『鸵鸟政策』埋头躲事的说法来自它的传说习性。\",\n\"peacock\":\"画面：一只雄孔雀展开尾屏，五彩眼斑像上百只眼睛同时睁开——peacock「孔雀」。开屏的是雄鸟（pea-cock 公），雌鸟灰褐朴素；proud as a peacock 就是『骄傲如孔雀』。\",\n\"swan\":\"画面：一只天鹅弓起长长的脖子成 S 形，雪白羽毛滑过平静湖面——swan「天鹅」。体态优雅、配偶终身制；丑小鸭变天鹅的故事让它成了蜕变的象征。\",\n\"goose\":\"画面：一只鹅伸长脖子嘎嘎叫着追赶靠近领地的陌生人——goose「鹅」。比鸭大、脖子长、护家凶；复数是 geese（和 tooth→teeth 同类元音变化）。\",\n\"duck\":\"画面：一只鸭子扁嘴嘎嘎叫，蹼足在水面划出涟漪——duck「鸭子」。扁喙、蹼足、水陆两栖；duck 作动词是『猛低头躲闪』，想它被水花吓得一缩脖子就是。\",\n\"chicken\":\"画面：一只鸡在院里刨土找虫，下的蛋是早餐桌常客——chicken「鸡」。被驯养最广的家禽；口语 chicken 还指『胆小鬼』，chicken out 就是临阵退缩。\",\n\"rooster\":\"画面：一只公鸡昂首站在柴堆上，红冠鲜亮，天没亮就扯着嗓子报晓——rooster「公鸡」。雄鸡专名（美式），英式叫 cock；尾巴羽毛和鸡冠是它和母鸡最大的区别。\",\n\"hen\":\"画面：一只母鸡蹲在窝里孵蛋，翅膀护着一窝毛茸茸的小鸡——hen「母鸡」。雌鸡专名，和 rooster 相对；hen party 是『女性派对』，全是『她』的场合。\",\n\"turkey\":\"画面：一只火鸡展开扇形尾羽咕噜咕噜叫，感恩节餐桌上它是主角——turkey「火鸡」。北美原产的大型家禽；注意小写 turkey 是火鸡，大写 Turkey 才是土耳其。\",\n\"parrot\":\"画面：一只鹦鹉歪头学舌，把主人那句『你好』学得惟妙惟肖——parrot「鹦鹉」。钩喙、艳羽、能模仿人语；parrot 作动词就是『鹦鹉学舌般复述』。\",\n\"canary\":\"画面：一只金丝雀在笼里婉转鸣唱，一身鲜亮的金黄色羽毛——canary「金丝雀」。以煤矿里的『预警鸟』闻名：对毒气比人敏感，矿工靠它保命；canary in a coal mine 成了预警的代名词。\",\n\"robin\":\"画面：一只知更鸟挺着橙红色的胸脯停在雪地枝头，像报春的使者——robin「知更鸟」。红胸脯是识别标记；英国国鸟，圣诞卡上常有它的身影。\",\n\"finch\":\"画面：一只小雀用粗短有力的喙一下磕开瓜子壳——finch「雀科鸟」。喙短而壮、专为嗑种子而生；达尔文在加拉帕戈斯看雀喙大小悟出进化论，说的就是它。\",\n\"raven\":\"画面：一只渡鸦通体漆黑，楔形尾、粗喙，站在枯枝上发出低沉的呱呱声——raven「渡鸦」。乌鸦家族里体型最大的，智商极高会用工具；比 crow 大一圈、叫声更沉。\",\n\"magpie\":\"画面：一只喜鹊黑白分明，长尾闪着蓝绿光泽，叼着亮闪闪的小物件回巢——magpie「喜鹊」。爱收集亮物是它的名声；在中国是报喜的吉祥鸟，七夕鹊桥就是它搭的。\",\n\"cuckoo\":\"画面：一只布谷鸟藏在林间只闻其声，发出『布谷、布谷』两声就换棵树——cuckoo「布谷鸟」。名字就是拟声；它把蛋下在别家巢里让别人养，是著名的『巢寄生』者。\",\n\"woodpecker\":\"画面：一只啄木鸟抱着树干，硬喙像凿子一样哒哒哒敲进树皮捉虫——woodpecker「啄木鸟」。wood（木）+ pecker（啄者）：一天敲上万次，脑内有天然减震结构。\",\n\"hummingbird\":\"画面：一只蜂鸟悬停在花前，翅膀快到只剩残影，长喙探入花心吸蜜——hummingbird「蜂鸟」。humming 是翅膀振动的嗡嗡声；世界最小的鸟，能倒飞、心跳每分钟上千次。\",\n\"bat\":\"画面：一只蝙蝠倒挂在洞顶，黄昏时靠回声定位在夜空捕虫——bat「蝙蝠」。唯一会飞的哺乳动物，靠超声波『看』路；bat 也是『球棒』，同形异义靠语境分。\",\n\"squirrel\":\"画面：一只松鼠抱着松果坐在枝头，大尾巴蓬松地翘在身后——squirrel「松鼠」。藏坚果的高手，埋下的种子常被忘掉，客观上帮森林播了种；拼写里的 squirr 最难记。\",\n\"chipmunk\":\"画面：一只花栗鼠脸颊鼓鼓囊囊塞满种子，背上有五条深色条纹——chipmunk「花栗鼠」。比松鼠小、脸上有颊囊、背纹是身份证；动画里的花栗鼠三兄弟就是它。\",\n\"beaver\":\"画面：一只海狸啃倒大树拖回溪里，硬生生筑起一座水坝——beaver「海狸」。门牙终生生长、天生水利工程师；它的坝能改变整片湿地，busy as a beaver 是『忙碌』的代称。\",\n\"otter\":\"画面：一只水獭仰躺在水面，肚皮上放块石头正敲开贝壳吃——otter「水獭」。蹼足、防水厚毛、爱玩水滑梯；海獭会用工具，是哺乳动物里的聪明玩家。\",\n\"skunk\":\"画面：一只臭鼬黑白条纹醒目，受惊时撅起尾巴喷出奇臭的液体——skunk「臭鼬」。黑白是警告色：别惹我；臭液能喷三米远，沾上几天洗不掉。\",\n\"raccoon\":\"画面：一只浣熊戴着『黑眼罩』，正用灵巧的前爪把食物放进水里搓洗——raccoon「浣熊」。眼部黑纹像蒙面侠，洗食是标志动作；夜里翻垃圾桶是城市常客。\",\n\"opossum\":\"画面：一只负鼠妈妈背上驮着一排幼崽，遇险时干脆躺倒装死——opossum「负鼠」。美洲有袋动物，装死（playing possum）是保命绝技；长尾能缠树枝。\",\n\"kangaroo\":\"画面：一只袋鼠妈妈育儿袋里探出小脑袋，后腿一蹬跳出十几米——kangaroo「袋鼠」。有袋、善跳、尾巴当第五条腿；澳大利亚的象征，boxing 般的前爪只是防御姿势。\",\n\"koala\":\"画面：一只考拉抱着桉树干呼呼大睡，大耳朵毛茸茸，一天睡 20 小时——koala「考拉」。只吃桉树叶、能量低所以嗜睡；它不是熊（koala bear 是误称），是有袋动物。\",\n\"panda\":\"画面：一只熊猫黑白分明，抱着竹子大口啃食，眼圈像戴了墨镜——panda「熊猫」。99% 的食谱是竹子，拇指状的腕骨专为握竹进化；中国国宝，租借外交的明星。\",\n\"grizzly\":\"画面：一只灰熊肩背隆起一块驼峰，爪子长如小刀，在溪里捞鲑鱼——grizzly「灰熊」。肩部的驼峰是挖掘的肌肉标志，毛尖灰白（grizzled）；北美最具威慑的陆地食肉动物。\",\n\"wolf\":\"画面：一只狼仰头对月长嗥，狼群靠声音集结分工围猎——wolf「狼」。群居、等级分明，是家犬的祖先；复数 wolves（f 变 v 加 es，和 leaf 一家）。\",\n\"coyote\":\"画面：一只郊狼瘦小机警，在西部荒原上独自或成对捕猎兔鼠——coyote「郊狼」。比 wolf 小一号的北美犬科，适应力极强，已扩散到城市郊区；动画里追赶跑者的就是它。\",\n\"fox\":\"画面：一只狐狸尖耳尖嘴，大尾巴蓬松，正竖耳细听雪下老鼠的动静——fox「狐狸」。听觉敏锐、会纵身扎进雪堆捕鼠；sly as a fox『狡如狐』是它的固定标签。\",\n\"jackal\":\"画面：一只豺在狮群外围徘徊，等猎食者吃完才上前捡食腐肉——jackal「豺」。比狼小的犬科，常跟在猛兽后面捡漏；古埃及的阿努比斯神就是豺首形象。\",\n\"hyena\":\"画面：一只鬣狗前高后低地踱步，发出像狂笑一样的叫声——hyena「鬣狗」。咬合力惊人、能嚼碎骨头；laughing hyena 的『笑声』其实是它的社交叫声。\",\n\"lion\":\"画面：一只雄狮鬃毛蓬松如王冠，吼声传遍草原，母狮群负责围猎——lion「狮子」。唯一群居的猫科，雄狮的鬃毛是地位象征；king of beasts 的称号来自它。\",\n\"tiger\":\"画面：一只老虎橙底黑纹潜伏在草丛，纹路把身形切得支离破碎——tiger「老虎」。最大的猫科，条纹每只都独一无二，连皮肤上都有；独行猎手，善游泳。\",\n\"leopard\":\"画面：一只豹子把猎物拖上树杈慢慢享用，满身玫瑰状斑点——leopard「豹」。斑点是 rosette 玫瑰斑，爬树高手；和 jaguar 比：豹在旧大陆，斑纹空心。\",\n\"cheetah\":\"画面：一只猎豹眼下两道黑色泪痕，起跑三秒就飙到汽车的速度——cheetah「猎豹」。陆地最快（时速过百），泪痕能防眩光；代价是耐力差，冲刺后必须喘很久。\",\n\"jaguar\":\"画面：一只美洲豹在亚马孙雨林里泅水捕猎，斑点中央还带小点——jaguar「美洲豹」。美洲最大的猫科，咬力惊人能咬穿龟壳；名字源于土著语『能一口杀猎物的兽』。\",\n\"cougar\":\"画面：一只美洲狮通体黄褐色没有斑纹，悄无声息地伏在岩上盯着鹿群——cougar「美洲狮」。又叫 puma、mountain lion：名字最多的大猫，却和狮子无关，是大型的『猫』。\",\n\"lynx\":\"画面：一只猞猁耳朵尖上竖着一簇黑毛，大脚掌像雪鞋一样踏雪无痕——lynx「猞猁」。耳簇毛和短尾是身份证；视力极佳，lynx-eyed 就是形容眼神锐利。\",\n\"elephant\":\"画面：一头大象用长鼻子卷起草料送进嘴里，蒲扇大的耳朵缓缓扇动——elephant「大象」。陆地最大的动物，鼻子有四万块肌肉；象群由年长母象带队，记忆力惊人。\",\n\"rhino\":\"画面：一头犀牛低着头，鼻梁上的独角对着可能的威胁——rhino「犀牛」。角由角蛋白（和指甲同成分）构成；全称 rhinoceros 太长，口语都简称 rhino。\",\n\"hippo\":\"画面：一只河马泡在河里只露出眼睛和鼻孔，天一黑就上岸吃草——hippo「河马」。hippopotamus 的简称，希腊语意为『河里的马』；看着笨拙，在陆地上跑得比人快。\",\n\"giraffe\":\"画面：一只长颈鹿叉开前腿低头喝水，脖子长到能吃最高处的树叶——giraffe「长颈鹿」。世界最高的动物，心脏重达 11 公斤才能把血泵上大脑；花纹每只独一无二。\",\n\"zebra\":\"画面：一匹斑马黑白条纹在马群里晃眼，条纹一直延伸到鬃毛——zebra「斑马」。条纹能迷惑采采蝇、帮同伴互相辨认；每只的纹路都不同，就像指纹。\",\n\"horse\":\"画面：一匹马扬蹄奔驰，鬃毛飞扬，马蹄声哒哒作响——horse「马」。被人类驯化数千年的伙伴；horsepower 马力这个单位，就是拿它跟蒸汽机比力气定的。\",\n\"donkey\":\"画面：一头驴长耳朵垂着眼，驮着货物走山路，脾气上来四蹄钉地不动——donkey「驴」。耐力强、记路准，『倔』其实是它谨慎的天性；叫声响亮刺耳很有辨识度。\",\n\"mule\":\"画面：一头骡子长着驴的大长耳朵和马的身板，驮货走险路稳稳当当——mule「骡子」。马和驴的后代（公驴+母马），力气大、寿命长，但自身不能繁殖后代。\",\n\"camel\":\"画面：一只骆驼驼峰高耸，踩着滚烫的沙漠几天不喝水照样前行——camel「骆驼」。驼峰存的是脂肪不是水；睫毛防沙、能忍体温波动，是当之无愧的『沙漠之舟』。\",\n\"llama\":\"画面：一只美洲驼在安第斯高原驮着货物，脾气不对还会朝人吐口水——llama「美洲驼」。骆驼的南美亲戚，没有驼峰；毛和驮运都宝贵，吐口水是它的抗议方式。\",\n\"alpaca\":\"画面：一只羊驼顶着蓬松的卷毛像团棉花糖，正呆萌地嚼着草——alpaca「羊驼」。为产毛驯化，毛比羊毛更保暖轻盈；和 llama 比个头更小、脸更圆。\",\n\"deer\":\"画面：一只鹿头顶分叉大角，警觉地抬头听着林间的动静——deer「鹿」。雄鹿的角每年脱落再生；单复数同形（one deer, two deer），和 sheep 一样是老英语的遗留。\",\n\"elk\":\"画面：一只麋鹿展开扇子般的巨掌形角，在北方针叶林里发出洪亮的鸣叫——elk「麋鹿」。鹿科里的大个子，角呈掌状；注意 elk 在欧洲指驼鹿，美洲指马鹿，翻译常混。\",\n\"moose\":\"画面：一只驼鹿垂着喉下的肉垂，掌形大角宽过一米，站在沼泽里啃水草——moose「驼鹿」。鹿科体型之最，鼻子大而下垂；moose 的复数还是 moose，不加 s。\",\n\"reindeer\":\"画面：一只驯鹿雌雄都长角，拉着雪橇踏过北极苔原——reindeer「驯鹿」。rein 是缰绳：唯一被人类半驯化的鹿，圣诞老人雪橇队的成员就是它。\",\n\"caribou\":\"画面：一只北美驯鹿成群迁徙，蹄声踏碎冻土，长途跋涉数千公里——caribou「北美驯鹿」。和 reindeer 是同一物种：野生的叫 caribou，驯养的叫 reindeer。\",\n\"bison\":\"画面：一头美洲野牛前半身披着厚重长毛，肩部高高隆起，正刨雪找草——bison「美洲野牛」。头部巨大、肩峰突出；曾被猎到濒临灭绝，是北美保护运动的起点。\",\n\"buffalo\":\"画面：一头水牛泡在泥塘里只露出头，弯月形的大角向两侧展开——buffalo「水牛」。亚洲农田的耕作主力，爱泡水降温；和 bison 常被混叫，但产地习性都不同。\",\n\"ox\":\"画面：一头公牛套着轭具拉犁，步子沉稳，鼻环牵引着方向——ox「公牛（役用）」。特指被训练干农活的阉牛；复数 oxen 是英语里少见的古复数形式。\",\n\"bull\":\"画面：一头公牛鼻孔喷气、前蹄刨地，低头随时准备冲锋——bull「公牛」。未阉的雄牛，脾气和力量都拉满；股市里的 bull 是看涨（牛角向上顶），bear 是看跌。\",\n\"cow\":\"画面：一头奶牛在牧场慢悠悠反刍，挤出的牛奶装满一桶——cow「奶牛」。专指母牛（bull 是公，合称 cattle）；holy cow 是英语里的惊叹语『天哪』。\",\n\"calf\":\"画面：一头小牛犊摇摇晃晃站起来，第一次尝试迈步走向妈妈——calf「小牛」。出生几小时就能站立；calf 还指『小腿肚』（形状像小牛？其实源于古词的另一支）。\",\n\"goat\":\"画面：一只山羊留着小胡子，踩着陡峭岩壁如履平地，还什么都想啃一口——goat「山羊」。胡须和直角是它和绵羊的区别；现在网络流行语 GOAT 是 Greatest Of All Time 的缩写。\",\n\"sheep\":\"画面：一只绵羊裹着厚厚卷毛，温顺地跟着羊群吃草——sheep「绵羊」。单复数同形；black sheep 指『害群之马』；它的毛（wool）是人类最古老的纺织原料。\",\n\"lamb\":\"画面：一只小羊羔蹦蹦跳跳跟在母羊身后，叫声又嫩又软——lamb「羔羊」。特指一岁内的小羊，肉质最嫩；lamb 末尾的 b 不发音，和 climb 一样是哑音。\",\n\"pig\":\"画面：一只猪在泥坑里打滚降温，鼻子拱来拱去找吃的——pig「猪」。其实爱干净，打滚是为防晒防虫；嗅觉比狗灵敏，智商在动物里排前列。\",\n\"boar\":\"画面：一头野猪獠牙外翻，在林地里横冲直撞，鬃毛竖立——boar「野猪」。家猪的野生祖先，凶猛难惹；和 sow（母猪）相对，boar 专指公野猪/公猪。\",\n\"sow\":\"画面：一头母猪侧躺着，一排小猪仔挤着吃奶——sow「母猪」。读 /saʊ/；注意 sow 还有个同形动词『播种』读 /soʊ/，一字两音两义，靠语境分辨。\",\n\"rabbit\":\"画面：一只兔子长耳朵竖起听动静，三瓣嘴飞快地嚼着胡萝卜——rabbit「兔子」。家养为主、耳朵长尾巴短；和 hare 野兔比：兔宝宝出生时没毛没睁眼，靠洞生活。\",\n\"hare\":\"画面：一只野兔后腿极长，在开阔草地上全速狂奔变向逃开猎狗——hare「野兔」。比 rabbit 大、腿更长、不住洞；龟兔赛跑里的主角其实是 hare，不是 rabbit。\",\n\"rat\":\"画面：一只大老鼠拖着长长的无毛尾巴，沿墙根溜进粮仓——rat「大老鼠」。比 mouse 大得多，适应力极强随人遍布全球；rat 还作动词『告密』，出卖同伴的人。\",\n\"hamster\":\"画面：一只仓鼠把瓜子塞满两个颊囊，脸蛋鼓成两个小包——hamster「仓鼠」。颊囊是它的随身粮仓；夜行、爱跑转轮，是最受欢迎的小宠之一。\",\n\"gerbil\":\"画面：一只沙鼠在沙地里直立张望，后腿修长随时准备蹦跳逃走——gerbil「沙鼠」。原产蒙古沙漠，耐旱、几乎不排尿味；常被当宠物，群居且极爱挖洞。\",\n\"mole\":\"画面：一只鼹鼠眼睛退化得几乎看不见，铲子似的前爪在土里飞快掘进——mole「鼹鼠」。一生住在地下，靠嗅觉和触觉找蚯蚓；mole 还是『痣；间谍』，潜伏地下是共同点。\",\n\"hedgehog\":\"画面：一只刺猬受惊蜷成一颗刺球，敌人无从下口——hedgehog「刺猬」。hedge（树篱）+ hog（猪）：住在篱边的『带刺小猪』；它的刺是特化的毛发。\",\n\"monkey\":\"画面：一只猴子长尾巴勾住树枝荡来荡去，正给同伴抓虱子社交——monkey「猴子」。有尾巴、群居、手指灵活；monkey business 是『胡闹、捣鬼』，别当正经事。\",\n\"chimpanzee\":\"画面：一只黑猩猩折根树枝伸进蚁穴钓白蚁吃，聪明得像个小人——chimpanzee「黑猩猩」。和人类基因最接近，会用工具、照镜子能认出自己；无尾，是 ape 不是 monkey。\",\n\"gorilla\":\"画面：一只大猩猩银背挺立，捶胸发出沉闷的轰响宣示力量——gorilla「大猩猩」。最大的灵长类，银背雄性是族群首领；看着凶猛，实则主要吃素、性情温和。\",\n\"orangutan\":\"画面：一只红猩猩披着锈红长毛，长臂在婆罗洲雨林树冠间悠荡——orangutan「红猩猩」。名字是马来语『森林之人』；手臂展开近两米，独居、动作慢条斯理。\",\n\"baboon\":\"画面：一只狒狒露出狗一样的长吻和尖犬齿，群体在岩石上理毛警戒——baboon「狒狒」。地面生活的大型猴类，臀部有鲜艳胼胝；古埃及人把它当智慧神的化身。\",\n\"lemur\":\"画面：一只狐猴瞪着圆溜溜的大眼睛，蓬松长尾高高翘起，在马达加斯加的林间跳跃——lemur「狐猴」。只产于马达加斯加，大眼为夜行而生；环尾狐猴的黑白环尾最出名。\",\n\"soccer\":\"画面：绿茵场上 22 人追着一只黑白足球，临门一脚直挂死角——soccer「足球」。美式叫法（源于 association football 的缩写），英式直接叫 football；美国人说 football 指的是橄榄球，别混。\",\n\"basketball\":\"画面：球员跃起把球扣进高高的篮筐，篮板震得嗡嗡响——basketball「篮球」。basket（篮子）+ ball：1891 年最初真把桃篮钉在墙上当筐，进球还得爬梯子掏出来。\",\n\"baseball\":\"画面：击球员一棒把球轰出全垒打墙，绕过一二三垒跑回本垒——baseball「棒球」。九人制、投打对决；美国的 national pastime，说的正是它。\",\n\"softball\":\"画面：一颗比棒球大得多的球被下手抛投，击球员在小一号的场地上挥棒——softball「垒球」。球更大更『软』、投球必须下手抛，场地比 baseball 小，节奏更快更安全。\",\n\"volleyball\":\"画面：二传手把球托到网口，扣球队员腾空重扣，球砸在对方界内——volleyball「排球」。volley 是『截击、凌空打』：球不许落地，隔网对打，每方最多触球三次。\",\n\"tennis\":\"画面：两人在网球场底线对拉，发球时速快得像子弹出膛——tennis「网球」。计分 15、30、40 的怪规矩来历有争议（一说是源于古代钟面刻度，但并无实证）；名字来自法语 tenez『拿着，接住』。\",\n\"badminton\":\"画面：一只羽毛球被高高吊起，又被一拍杀向边线，球速快得带风——badminton「羽毛球」。用的是羽毛+软木的 shuttlecock（毽球）；名字来自英国 Badminton 庄园。\",\n\"golf\":\"画面：球手在果岭上轻轻一推，小白球沿着草皮弧线滚进洞杯——golf「高尔夫」。18 洞、杆数越少越好；词源未定论，相传与苏格兰牧羊人赶石子的游戏有关。\",\n\"hockey\":\"画面：冰面上球员踩着冰刀高速滑行，球杆一拨，冰球贴冰疾射球门——hockey「冰球」。cn 指冰上版（ice hockey）；另有 field hockey 是草地曲棍球，加拿大国球指的是冰球。\",\n\"rugby\":\"画面：球员抱着橄榄形的球横冲直撞，被扑倒前把球向后传给队友——rugby「橄榄球」。只能向后传球、向前只能靠跑和踢；名字来自英国 Rugby 学校，源头就是从足球里抱球跑的那一刻。\",\n\"boxing\":\"画面：拳台上两人戴着厚拳套对峙，刺拳试探后一记重拳击中下巴——boxing「拳击」。靠拳头得分与击倒的运动；别被 box 的『盒子』义带偏，这个 boxing 来自动词 box『打拳』。\",\n\"wrestling\":\"画面：两名摔跤手抱缠在一起，一人被过肩摔重重砸在垫子上——wrestling「摔跤」。徒手把对手摔倒压制的古老运动；美式 WWE 是表演秀，奥运摔跤才是竞技本体。\",\n\"judo\":\"画面：柔道选手借力打力，一记背负投把高大的对手摔得四脚朝天——judo「柔道」。ju 是『柔』：不硬碰硬，用对方的力量摔对方；日本武道，讲究礼节与借力。\",\n\"karate\":\"画面：空手道选手手刀劈断木板，出拳瞬间一声短喝——karate「空手道」。kara（空）+ te（手）：徒手之术，源于冲绳；招式以直线拳脚为主，讲究一击必杀。\",\n\"taekwondo\":\"画面：跆拳道选手腾空回旋，一脚踢碎高举的木板——taekwondo「跆拳道」。tae（脚踢）+ kwon（拳）+ do（道）：韩国武道，腿法占比七成，腾空踢是招牌。\",\n\"fencing\":\"画面：两名剑手在剑道上进退如电，花剑剑尖点中对方胸前的有效部位——fencing「击剑」。花剑、重剑、佩剑三种；fence 本是『栅栏』，引申为用剑防护的技艺。\",\n\"shooting\":\"画面：射手屏住呼吸，准星、缺口、靶心三点一线，砰的一声十环——shooting「射击」。奥运项目拼的是稳与准；shooting 也是『拍摄』，拿枪拿相机都是 shoot。\",\n\"hunting\":\"画面：猎人带着猎犬在林间循迹，屏息等待猎物进入射程——hunting「打猎」。人类最古老的谋生方式之一，今多受严格许可管制；hunt 也有『搜寻』义，如 job hunting 找工作。\",\n\"fishing\":\"画面：垂钓者把鱼线远远甩进湖心，浮漂微微一动就提竿——fishing「钓鱼」。一竿一线等鱼上钩的耐心运动；go fishing 是休闲说法，商业捕捞则用 fishery 渔业。\",\n\"camping\":\"画面：星空下扎起一顶帐篷，篝火噼啪响，睡袋摊在防潮垫上——camping「露营」。camp 是『营地』：把家临时搬进野外；露营地叫 campsite，房车露营是另一派玩法。\",\n\"hiking\":\"画面：背着登山包沿山间小径一走大半天，登顶后群山尽在脚下——hiking「徒步」。专指野外长距离步行（区别于散步）；hike 还有『大幅涨价』义，a price hike。\",\n\"climbing\":\"画面：攀岩者手指抠住岩壁细缝，脚尖踩稳，贴着绝壁一寸寸上移——climbing「攀岩」。靠四肢与岩点博弈，绳索只保命不借力；室内抱石是它的入门版。\",\n\"skiing\":\"画面：滑雪者踩着双板从雪坡 S 形回转而下，身后扬起一片雪雾——skiing「滑雪」。双板、雪杖、高山速降；和单板的 snowboarding 区分：ski 是两只板分开穿。\",\n\"skating\":\"画面：滑冰者在冰面单脚滑行，起跳旋转后稳稳落冰——skating「滑冰」。冰刀在冰上近乎无摩擦地滑；也可指旱冰（roller skating），看搭配分辨场地。\",\n\"snowboarding\":\"画面：单板滑雪者双脚固定在一块宽板上，侧身从粉雪坡上冲浪般滑下——snowboarding「单板滑雪」。像冲浪搬上雪山，1998 年入冬奥；和双板 skiing 的站姿完全不同。\",\n\"surfing\":\"画面：冲浪者踩板站在浪壁上，随浪涌疾驰又钻出浪筒——surfing「冲浪」。surf 是『碎浪』：人板合一借浪前行；surf the internet 冲浪上网就是借了这个意象。\",\n\"diving\":\"画面：跳水运动员从十米台跃起，空中翻腾几周，入水只激起一圈小水花——diving「跳水」。评分看难度与入水水花；diving 也指潜水（scuba diving），托福语境多看搭配。\",\n\"swimming\":\"画面：游泳者在泳道里划臂打水，身体像鱼一样贴着水面前进——swimming「游泳」。最基础的生存技能与奥运大项；swim 的过去式 swam、过去分词 swum 别写错。\",\n\"rowing\":\"画面：四名桨手动作整齐划一，双桨同时入水出水，赛艇箭一般窜出——rowing「划船（竞技赛艇）」。双桨、向后划、面朝船尾；牛津剑桥赛艇对抗赛就是 rowing 的名片。\",\n\"sailing\":\"画面：一艘帆船借风斜行，白帆鼓满，船身压着浪花破水而行——sailing「帆船运动」。靠风力与帆的空气动力学前进；sail 既是『帆』也是『航行』这个动作本身。\",\n\"kayaking\":\"画面：划手坐在封闭舱里左右交替划双头桨，小艇贴着水面灵活穿梭——kayaking「皮划艇运动」。源于因纽特人的兽皮船 kayak：人坐舱内、双叶桨，是它和独木舟的分界。\",\n\"canoeing\":\"画面：划手跪坐在敞口独木舟里，单叶桨左右换边划水前行——canoeing「独木舟运动」。敞口、单叶桨、跪姿或坐姿；和 kayak 比：舱敞开、桨只有一头有叶。\",\n\"rafting\":\"画面：一船人坐在充气筏上冲下激流，浪头扑面，全员齐声划桨——rafting「漂流」。raft 是『木筏、皮筏』：白水漂流拼的是团队配合与胆量，等级按水流凶险分。\",\n\"cycling\":\"画面：骑行者踩着脚踏在公路上巡航，车队排成一线破风前进——cycling「骑行」。既是日常通勤也是环法级竞技；cycle 本义『循环』，车轮一圈圈转正是循环。\",\n\"running\":\"画面：跑者摆臂蹬地，步频稳定地在跑道上把距离一段段吃掉——running「跑步」。双脚有腾空期的步态（区别于 walking）；run 还有经营、流淌等几十种义，运动义最基础。\",\n\"jogging\":\"画面：慢跑者以能边跑边聊天的配速绕着公园小跑，呼吸平稳——jogging「慢跑」。jog 是『轻推、慢跑』：比 running 慢、重在有氧健身，风靡全球的晨跑就是它。\",\n\"sprint\":\"画面：短跑选手蹲踞式起跑，枪响瞬间如离弦之箭，百米十秒内冲线——sprint「短跑」。全速冲刺的短距离赛跑；引申义『冲刺赶工』：产品上线前的 sprint 就是这个画面。\",\n\"relay\":\"画面：接力赛第三棒选手回头接棒，金属接力棒在交接区精准易手——relay「接力赛」。relay 本义『中继、转递』：棒子一棒棒传下去，快在交接、输也在交接。\",\n\"hurdle\":\"画面：跨栏选手攻栏时前腿伸直压低，身体几乎贴着栏架掠过——hurdle「跨栏」。hurdle 本是『栏架』本身，引申为『障碍、难关』：overcome hurdles 克服重重障碍。\",\n\"javelin\":\"画面：标枪选手助跑到投掷线前，全身拧转把长枪掷向天际——javelin「标枪」。枪如长矛、投得最远者胜；源于古代打猎与战争的投矛，是田赛最有原始感的项目。\",\n\"discus\":\"画面：铁饼选手在投掷圈里旋转一周半，借离心力把圆盘甩向空中——discus「铁饼」。disc 是『圆盘』：古希腊雕塑《掷铁饼者》就是它；投的是盘形饼，不是铁球。\",\n\"gymnastics\":\"画面：体操运动员在平衡木上空翻稳稳落地，又到吊环上倒立如松——gymnastics「体操」。拼力量、柔韧与控制的综合项目；词源是希腊语『裸身训练』，古希腊人就是这么练的。\",\n\"aerobics\":\"画面：一群人跟着音乐节奏开合跳、踏步，额头冒汗呼吸加深——aerobics「有氧运动」。aero- 是『空气、氧』：持续供氧的运动才能燃脂；对应 anaerobic 无氧运动。\",\n\"yoga\":\"画面：练习者垫上做下犬式，呼吸拉长，身体在伸展中慢慢安静下来——yoga「瑜伽」。源于印度的身心修习，体式+呼吸+冥想三位一体；yoga 梵语本义是『结合』。\",\n\"pilates\":\"画面：练习者在垫上做卷腹与脊柱逐节滚动，动作慢而核心绷得死紧——pilates「普拉提」。20 世纪由 Joseph Pilates 创立，专练深层核心与体态；和 yoga 比：少冥想、多器械与控制。\",\n\"dancing\":\"画面：舞者踩着节拍旋转、伸展，裙摆和手臂划出一道道弧线——dancing「舞蹈」。dance 的动名词形：既是表演艺术也是社交娱乐；托福里常出现在艺术与民俗话题。\",\n\"singing\":\"画面：歌手握着话筒放声而歌，高音处全场屏息——singing「唱歌」。用嗓子把旋律唱出来；sing 的过去式 sang 别和 sink（下沉）混，那是托福听力爱挖的坑。\",\n\"concert\":\"画面：音乐厅里乐团齐奏，指挥棒落下瞬间全场寂静又沸腾——concert「音乐会」。现场音乐演出；in concert with 是『与…协同』的固定搭配，托福阅读常见。\",\n\"festival\":\"画面：街道张灯结彩，人群涌向广场看表演、吃小吃、庆祝一整天——festival「节日」。庆典活动的总称，从春节庙会到音乐节都算；festive 是形容词『喜庆的』。\",\n\"carnival\":\"画面：狂欢节巡游里花车缓行，舞者羽毛盛装，整条街都在跳桑巴——carnival「嘉年华」。源于天主教斋戒前的狂欢，里约狂欢节最盛大；美式也指巡回游乐场。\",\n\"parade\":\"画面：仪仗队迈着整齐步伐列队行进，军乐齐鸣，人群夹道挥旗——parade「游行」。有组织的列队行进展示，从阅兵到感恩节气球巡游都是 parade。\",\n\"fireworks\":\"画面：礼花弹升空炸开，金红的花火在夜空层层绽放又缓缓坠落——fireworks「烟花」。fire（火）+ works（作品）：火药做的空中作品；常用复数形，单放一支也多说 a firework。\",\n\"picnic\":\"画面：草坪上铺开格子餐布，三明治、水果和饮料摆满，一家人边吃边晒太阳——picnic「野餐」。把饭搬到户外吃；have a picnic 是固定搭配，蚂蚁是野餐的常客嘉宾。\",\n\"barbecue\":\"画面：炭火烤架上肉排滋滋冒油，刷上酱料，烟香飘满后院——barbecue「烧烤」。既指烤架/烤肉活动，也指烤好的肉；缩写 BBQ，人人都懂。\",\n\"wedding\":\"画面：新人在花拱下交换戒指，宾客鼓掌，捧花飞向人群——wedding「婚礼」。wed 源于古英语 wedd『誓约、抵押』——婚礼先是一纸立约；wedding ring 婚戒、wedding dress 婚纱都是高频搭配。\",\n\"birthday\":\"画面：蛋糕上插满蜡烛，寿星闭眼许愿一口气吹灭，全场唱起生日歌——birthday「生日」。birth（出生）+ day：出生那一天的周年；Happy birthday 是全世界通用的祝福。\",\n\"holiday\":\"画面：假期一到，全家关掉闹钟睡到自然醒，海滩和行李箱都在招手——holiday「假日」。英式 holiday 兼指『假期』（美式 vacation）；法定假日是 public holiday。\",\n\"vacation\":\"画面：他订好机票关掉工作邮箱，两周里只管看海发呆——vacation「假期」。美式专指较长的休假旅行；和 holiday 区分：美国人放假说 vacation，英国人说 holiday。\",\n\"trip\":\"画面：背起包出门，三天两夜看山看水再带着照片回来——trip「旅行」。泛指有去有回的出行，长短皆可；business trip 出差、a trip to… 去…的旅行最常用。\",\n\"tour\":\"画面：导游举着小旗带队，一站接一站把整座古城走透看遍——tour「旅游」。强调『巡回式游览』：多个站点串成线；tourist 游客、tourism 旅游业都是它的家人。\",\n\"cruise\":\"画面：一艘巨型邮轮缓缓驶离港口，甲板上的人挥手告别，海上漂一周——cruise「巡游」。乘船巡航度假；cruise 也是『巡航速度』，飞机巡航就用它。\",\n\"chess\":\"画面：棋盘上 32 枚棋子对峙，将军一步定胜负，落子无声却步步杀机——chess「国际象棋」。名字经波斯语『王』演变；将死 checkmate 源于波斯语『王死了』。\",\n\"poker\":\"画面：牌桌上几人面不改色地下注，靠一手牌型和心理博弈赢走筹码——poker「扑克（牌戏）」。既指纸牌本身（playing cards），也指德州扑克这类博弈游戏；poker face 扑克脸就是不动声色。\",\n\"dice\":\"画面：两颗骰子在桌上翻滚停下，一面六点一面三点，点数定输赢——dice「骰子」。单数是 die（和『死』同形），掷骰 roll the dice；引申义『冒险一搏』也常用。\",\n\"domino\":\"画面：一排多米诺骨牌被推倒第一块，哗啦啦连环倒下到最后一块——domino「多米诺骨牌」。先指那块黑白小牌，后因连环倒的景象有了 domino effect『骨牌效应』。\",\n\"puzzle\":\"画面：一千块拼图碎片摊满桌，边角先归位，画面一角角拼出全貌——puzzle「拼图；谜」。既是 jigsaw puzzle 拼图玩具，也是『让人费解的问题』：a puzzle 就是烧脑的事。\",\n\"riddle\":\"画面：他抛出一个谜面：什么东西早上四条腿、中午两条腿、晚上三条腿——riddle「谜语」。斯芬克斯之谜，答案是『人』；riddle 讲究文字双关，猜中靠悟性。\",\n\"joke\":\"画面：他讲了个笑话，全桌人笑得拍桌子——joke「笑话」。为逗乐而编的小段子；play a joke on someone 是『跟某人开玩笑、捉弄』，别和 funny story 混。\",\n\"movie\":\"画面：影院灯光暗下，银幕亮起，一场两小时的梦正式开场——movie「电影」。美式说法（moving picture 的缩略），英式更常说 film；go to the movies 是去看电影。\",\n\"cartoon\":\"画面：纸上勾出的夸张人物被拍成逐格动画，在屏幕上活蹦乱跳——cartoon「卡通」。既指报纸漫画，也指动画片；迪士尼、皮克斯做的都算 cartoon/animation 家族。\",\n\"animation\":\"画面：画师一张张画下动作，连续播放时纸上人物真的跑了起来——animation「动画」。anima 是『生命、灵魂』：让静图获得生命的技术；animator 是动画师。\",\n\"documentary\":\"画面：镜头潜入深海实拍鲸群迁徙，解说词把真实世界讲成故事——documentary「纪录片」。以真实素材为据的非虚构影片；和 movie 的虚构叙事相对，document 是『证据、档案』。\",\n\"game\":\"画面：棋盘、球场或屏幕上规则一立，所有人立刻认真争起输赢——game「游戏；比赛」。有规则、有胜负的活动总称；game 还指『猎物』，猎人眼里的 game 是野兽。\",\n\"toy\":\"画面：一只毛绒熊被孩子拖着满屋跑，玩具箱里还堆着积木和汽车——toy「玩具」。给孩子玩耍的物件；toy 作形容词是『玩具版的』，如 toy dog 玩具犬（真狗的小型种）。\",\n\"doll\":\"画面：一个玩偶穿着小裙子坐在玩具屋里，被孩子梳头喂饭——doll「玩偶」。人形玩具的统称，从布娃娃到 Barbie；doll up 是俚语『精心打扮』。\",\n\"kite\":\"画面：一只风筝乘着春风越飞越高，线轴在手里嗡嗡放线——kite「风筝」。纸/布蒙在轻架上靠风升空；kite 也是『鸢』（一种猛禽），金融里还有空头支票的俚语义。\",\n\"balloon\":\"画面：一只气球被吹得圆鼓鼓，松手就飘向天花板——balloon「气球」。薄橡胶充气玩具；热气球 hot-air balloon 同理；balloon 作动词是『急剧膨胀』，如 ballooning costs。\",\n\"swing\":\"画面：孩子坐在秋千上越荡越高，脚尖几乎够到树梢——swing「秋千」。swing 本是动词『摆动』：秋千就是来回摆的座椅；公园、后院都有它的身影。\",\n\"slide\":\"画面：孩子爬上梯子，从光滑的滑梯斜面一滑而下笑出声——slide「滑梯」。slide 本义『滑动』：滑梯就是专供下滑的斜面玩具；幻灯片也是 slide，别认错场合。\",\n\"seesaw\":\"画面：一块长板架在支点上，两个孩子一头一起一落此起彼伏——seesaw「跷跷板」。杠杆原理的玩具：重的一头沉、轻的一头升；seesaw 也作动词形容局势『反复拉锯』。\",\n\"merry-go-round\":\"画面：旋转木马载着一圈木马上下起伏，音乐响起灯光闪烁转个不停——merry-go-round「旋转木马」。游乐场的经典旋转设施；merry 是『欢乐』，go-round 是『转圈』，名字就是画面。\",\n\"ferris\":\"画面：摩天轮缓缓转动，座舱升到最高点时整座城市灯火尽收眼底——ferris「摩天轮」。全称 Ferris wheel，得名于 1893 年芝加哥世博会的工程师 Ferris；记忆点：大写 F 的人名变普通词。\",\n\"circus\":\"画面：大帐篷里空中飞人荡过天际，小丑滚出圆场，马戏团一晚演遍惊险与滑稽——circus「马戏团」。圆形表演场（circus 本义『圆圈』）里的杂技驯兽秀总称。\",\n\"magic\":\"画面：魔术师从空帽子里拎出一只兔子，观众席一片惊呼——magic「魔术」。障眼法制造的『不可能』；magic 也是形容词『神奇的』，magic word 是咒语、也是礼貌语的代称。\",\n\"trick\":\"画面：他手腕一翻，硬币凭空消失又从耳后变出来——trick「戏法；诡计」。小把戏、手法欺骗；trick or treat 万圣节讨糖话；考试里的 trick question 是陷阱题。\",\n\"juggle\":\"画面：杂耍艺人把五颗球抛成一道连绵的抛物线，一颗都不落——juggle「杂耍（抛接）」。多物轮流抛接不落地；引申义 juggle work and family 是『兼顾多头、忙得团团转』。\",\n\"acrobat\":\"画面：杂技演员在高空钢丝上翻跟头，落地稳如钉子——acrobat「杂技演员」。acro- 是『高』（acropolis 高城）：在高处翻腾的人；acrobatics 才是『杂技』这门技艺本身。\",\n\"puppet\":\"画面：一只布袋木偶套在手上，手指一动它的头和手就活了过来——puppet「木偶（手偶）」。手伸进偶身操纵的一类；提线的是 marionette，手套式的是 puppet，先分清操纵方式。\",\n\"marionette\":\"画面：提线木偶悬在细线下，操纵者手指轻提，它便抬臂转身像真人——marionette「提线木偶」。靠上方丝线操纵关节；和 puppet 比：线从上面来，是它名字的记忆点。\",\n\"instrument\":\"画面：乐团里小提琴、长笛、鼓一字排开，每件乐器各有各的声线——instrument「乐器」。musical instrument 的全称；instrument 泛指『仪器、工具』，乐器只是其中一类，看搭配定。\",\n\"guitar\":\"画面：吉他手抱着六弦琴，左手按和弦右手扫弦，旋律一下铺开——guitar「吉他」。六弦拨弦乐器，民谣摇滚的主力；电吉他 electric guitar 插上音箱音色全变。\",\n\"violin\":\"画面：小提琴手把琴夹在颌下，弓子在四根弦上拉出婉转高音——violin「小提琴」。弦乐家族音最高、体积最小；第一小提琴在乐团里坐首席（concertmaster）。\",\n\"cello\":\"画面：大提琴竖立膝间，琴手拉弓奏出低沉醇厚如人声的旋律——cello「大提琴」。全称 violoncello：比小提琴大得多、音低得多，必须立在地上拉；音色最接近人声。\",\n\"flute\":\"画面：长笛横握唇边，气流掠过吹孔，手指翻飞跑出一串清亮音符——flute「长笛」。横吹无簧片，靠气流发声；中国竹笛是它的同类，银长笛是管弦乐团的标准件。\",\n\"clarinet\":\"画面：单簧管竖吹，哨片震动发出圆润温暖的中音，音域宽得惊人——clarinet「单簧管」。单簧片木管，黑管就是它；音色能柔能亮，爵士古典都吃得开。\",\n\"oboe\":\"画面：双簧管吹奏者含着两片薄簧，奏出带点鼻音、穿透力极强的旋律——oboe「双簧管」。双簧片是它和 clarinet（单簧）的分界；乐团调音时全场都跟它的 A 音对齐。\",\n\"trumpet\":\"画面：小号手鼓起腮吹响号筒，金亮的声浪穿透整个乐队——trumpet「小号」。铜管家族音最高最亮，三个活塞按键变音；军号、爵士、庆典都少不了它。\",\n\"trombone\":\"画面：长号手把滑管一推一拉，音高也跟着滑上滑下——trombone「长号」。唯一靠伸缩滑管变音的铜管，glissando 滑音是绝活；名字在意大利语里是『大号小号』。\",\n\"saxophone\":\"画面：萨克斯手抱着弯管金 sax，爵士酒吧里流淌出慵懒的旋律——saxophone「萨克斯」。单簧片+金属身的混血木管（材质是铜，分类属木管）；发明者姓 Sax。\",\n\"drum\":\"画面：鼓手一棒敲下，鼓面震得发麻，节奏瞬间立住整个乐队——drum「鼓」。打击乐之王，膜鸣发声；drum 也是『圆桶』（油桶），形状都来自那个圆筒。\",\n\"piano\":\"画面：钢琴家十指在 88 个黑白键上奔跑，琴锤敲弦弹出强弱分明的乐章——piano「钢琴」。全称 pianoforte 意为『能弱能强』，是它取代羽管键琴的杀手锏；乐器之王。\",\n\"harp\":\"画面：竖琴手双手在 47 根弦上流水般拨动，三角琴身泛着金光——harp「竖琴」。最古老的拨弦乐器之一，弦直接绷在三角框架上无指板；天使画像里抱的就是它。\",\n\"banjo\":\"画面：班卓琴手快速轮指拨动五根弦，圆圆的琴身弹出明快的乡村调——banjo「班卓琴」。圆形共鸣箱+长颈，五弦（有一根短弦），美国蓝草音乐的灵魂。\",\n\"mandolin\":\"画面：曼陀林小巧的梨形琴身抱在怀里，拨片快速颤奏出细密音流——mandolin「曼陀林」。八弦（四组双弦）、颤音奏法（tremolo）是标志；和吉他比，个头小一大圈。\",\n\"accordion\":\"画面：手风琴手双臂拉开风箱，左手贝斯右手键盘，音浪一波波涌出——accordion「手风琴」。靠风箱供气、簧片发声的『背着的风琴』；街头艺人和民歌伴奏的宠儿。\",\n\"harmonica\":\"画面：他把口琴贴在唇边左右移动，十个小孔吹吸之间奏出布鲁斯味——harmonica「口琴」。最小最便携的簧乐器，吹吸发声不同音；装进口袋就能走天下的乐器。\",\n\"xylophone\":\"画面：琴手双槌敲击排排木条，清脆的叮咚声像水滴落在玉盘上——xylophone「木琴」。xylo- 是『木』（希腊语 xylon）：木条按音高排列，下方共鸣管放大声音。\",\n\"adaptation\":\"画面：沙漠里的仙人掌把叶子退化成刺、茎身储满水，硬是在干旱里活下来——adaptation「适应」。生物为环境改自己的过程与结果；adapt 是动词，考试里 evolve 的近义场景常换成它。\",\n\"predator\":\"画面：一头狮子压低身子潜近斑马群，目光锁死最慢的那只——predator「捕食者」。靠捕杀其他动物为食的一方；它的猎物叫 prey，一捕一被捕是固定对子。\",\n\"prey\":\"画面：一只野兔竖起耳朵僵在原地，鹰的影子正从头顶掠过——prey「猎物」。被捕食者吃掉的一方；prey on 是『捕食；折磨』，pray（祈祷）与它同音不同字。\",\n\"camouflage\":\"画面：一只变色龙趴在绿叶上，体色变得和叶子一模一样，鸟飞过毫无察觉——camouflage「伪装；保护色」。动物借体色花纹融进环境，既躲天敌也方便偷袭。\",\n\"hibernate\":\"画面：一只熊蜷在洞里心跳慢到几乎听不见，一睡就是整个冬天——hibernate「冬眠」。靠降代谢熬过寒冬，等春天再醒；夏眠是 aestivate，冷血动物冬眠叫 brumation。\",\n\"nocturnal\":\"画面：猫头鹰在午夜睁开大眼无声滑翔，专挑夜里出来捕鼠——nocturnal「夜行的」。noct- 是『夜』（nocturne 夜曲）：昼伏夜出是它的作息；反义 diurnal 是昼行的。\",\n\"herbivore\":\"画面：一匹马低头啃着青草，臼齿把草料磨得细细的——herbivore「食草动物」。herb 是『草』，-vore 是『吃』：只吃植物的一类，牛羊鹿都是；牙齿平、肠道长是标配。\",\n\"carnivore\":\"画面：一只老虎撕开猎物大口吃肉，犬齿尖得像刀——carnivore「食肉动物」。carni- 是『肉』（chili con carne 的 carne）：专吃肉的一类；植物界的捕蝇草也被戏称 carnivore。\",\n\"omnivore\":\"画面：一只熊刚捞完鱼又去掏浆果，荤素来者不拒——omnivore「杂食动物」。omni- 是『全部』（omnipotent 无所不能）：什么都吃，人和猪都是典型杂食者。\",\n\"parasite\":\"画面：一条绦虫盘在宿主肠子里，自己不开饭馆只等现成的营养送上门——parasite「寄生虫；寄生生物」。住在别家身上蹭吃蹭喝还伤主人；比喻义是『靠别人养活的人』。\",\n\"symbiosis\":\"画面：小丑鱼住在海葵毒触手间避敌，又替海葵引来食物，两家互利——symbiosis「共生」。sym-（共同）+ bio（生命）：两种生物绑在一起过日子，互利只是其中一种。\",\n\"mutation\":\"画面：一段 DNA 复制时抄错了一个字母，长出的果蝇眼睛变成了白色——mutation「突变」。基因序列的意外改动，多数无声无息，少数改变性状；mutate 是动词，mutant 是突变体。\",\n\"chromosome\":\"画面：细胞核里一条条 X 形的染色体排成队列，上面串着成千上万个基因——chromosome「染色体」。DNA 缠在蛋白上打包成的棒状物，人有 46 条；它因易被染色得名（chromo- 颜色）。\",\n\"gene\":\"画面：DNA 长链上标出的一小段，正指挥细胞造出血红蛋白——gene「基因」。决定一个性状的遗传片段，是 chromosome 上的一小截；genetics 遗传学、genome 基因组同族。\",\n\"protein\":\"画面：餐桌上一盘鸡蛋和瘦肉，健身者正按克数算今天的摄入——protein「蛋白质」。细胞的结构与功能主力：酶、抗体、肌肉都是它；由氨基酸按基因图纸折叠而成。\",\n\"enzyme\":\"画面：一颗酶像一把专用钥匙卡进底物，咔嗒一下把大分子剪成小段——enzyme「酶」。生物催化剂：只加速特定化学反应、自己不被消耗，温度过高就会『变性』罢工。\",\n\"cell\":\"画面：显微镜下一个细胞被薄膜裹着，核在中央，像一座微型工厂——cell「细胞」。生命的最小单位；cell 也是『小房间、手机』，修道士的小间和蜂窝都源于这个小格子意象。\",\n\"membrane\":\"画面：细胞表面那层薄膜像海关，只放小分子进出、大个子一律拦下——membrane「薄膜；细胞膜」。薄而有选择性的屏障；生物膜的『选择透过性』是托福生物的必考句。\",\n\"tissue\":\"画面：一层层心肌细胞排成整齐的组织，共同收缩泵出血液——tissue「（生物）组织」。同类细胞抱团干同一件活叫组织；别和纸巾 tissue 混，那是生活义，语境在实验室就是生物义。\",\n\"organ\":\"画面：心脏作为一个器官独立搏动，和肺、肝各就各位组成系统——organ「器官」。多种组织组装成的功能单位（心、肺、胃）；organ 也是『管风琴』，同词两义靠语境。\",\n\"stem\":\"画面：一株向日葵的茎直立托着花盘，里面水管养分上下跑——stem「茎；干」。植物的支撑与运输主干；stem 也是动词『起源；阻止』，STEM 学科则是科学技术工程数学的缩写。\",\n\"root\":\"画面：一棵大树的根在地下张开如伞，牢牢抓住土壤吸水——root「根」。植物的地下部分；引申义『根源』：the root of the problem 问题的根源，词根 root 本身也是这个画面。\",\n\"leaf\":\"画面：一片叶子摊开迎着阳光，叶绿体正忙着把光变成糖——leaf「叶子」。光合作用的主场；复数 leaves（f 变 v），一片两片要分清；leaf through 是『翻阅』，像翻叶子。\",\n\"seed\":\"画面：一颗种子埋进湿土，胚根先破壳扎下，子叶顶土而出——seed「种子」。植物的下一代包裹：胚+粮仓+种皮；seed 也是比赛『种子选手』，播下的都是希望。\",\n\"pollination\":\"画面：一只蜜蜂钻进花心蹭满花粉，飞到下一朵时把花粉蹭上柱头——pollination「授粉」。花粉从花药到柱头的旅程，没有它就没有果实；pollinator 授粉者是生态链关键岗。\",\n\"respiration\":\"画面：细胞里的线粒体把葡萄糖『烧』掉，释放能量同时呼出二氧化碳——respiration「呼吸作用」。生物版的缓慢燃烧，和 breathing（喘气）不同：respiration 发生在每个细胞里。\",\n\"metabolism\":\"画面：身体像一座不停工的化工厂，吃进去的拆、需要的合成，能量账天天结算——metabolism「新陈代谢」。分解与合成两条线合称代谢；代谢率 metabolic rate 决定易胖易瘦。\",\n\"mineral\":\"画面：山岩里挖出一块石英晶体，断面闪着玻璃光泽——mineral「矿物；矿物质」。天然无机物：岩石里的矿物、饮食里的矿物质（钙铁锌）同是一个词，靠语境分。\",\n\"vitamin\":\"画面：一颗橙子切开，维 C 正在帮身体防坏血病——vitamin「维生素」。量小却不可或缺的有机物，缺了就生病；vita 是『生命』：维持生命的 amine（胺），名字由此而来。\",\n\"calcium\":\"画面：一杯牛奶下肚，钙正沉积进骨骼让它更硬实——calcium「钙」。骨骼牙齿的主料，也是信号分子；calci- 源于拉丁『石灰』， chalk 粉笔就是它的亲戚。\",\n\"offspring\":\"画面：母鸟衔虫回巢，三只雏鸟张着黄嘴等喂——offspring「后代；幼崽」。父母的下一代统称，单复数同形；人、动物都可用，科学语境里比 children 更常见。\",\n\"breed\":\"画面：牧场主挑出跑得最快的两匹马配对，指望下一代更强——breed「繁殖；培育（品种）」。既指动物繁衍，也指人为选育：a breed 就是一个品种（狗的品种都叫 breed）。\",\n\"spawn\":\"画面：鲑鱼在碎石滩上掘巢产卵，成千上万颗橙色卵沉进水底——spawn「产卵；卵」。鱼蛙等水生动物产卵的专词；spawn 也作动词引申『大量产生』（ spawn ideas）。\",\n\"larva\":\"画面：一条毛毛虫的前身——刚孵出的幼虫只管吃，模样和成虫判若两物——larva「幼虫」。昆虫等变态发育的未成年期；复数 larvae；larva 之后是 pupa 蛹，再才是成虫。\",\n\"caterpillar\":\"画面：一条绿毛毛虫挂在叶边大口啃食，身上细毛根根分明——caterpillar「毛毛虫」。蝴蝶和蛾的 larva，吃饱就结蛹蜕变；同名还有履带拖拉机品牌 Caterpillar，履带像虫身。\",\n\"butterfly\":\"画面：一只蝴蝶停在花上，四片彩翅慢悠悠开合晒太阳——butterfly「蝴蝶」。白天活动、停落时翅膀竖起，和 moth 飞蛾对照记；butterfly 泳姿蝶泳也是借它的扇翅。\",\n\"bee\":\"画面：一只蜜蜂在花丛与蜂巢间往返，腿上沾着两团金色花粉——bee「蜜蜂」。社会性昆虫，靠舞蹈报信蜜源位置；busy as a bee 是忙碌的代称，蜇人后自己也会死。\",\n\"ant\":\"画面：一队蚂蚁排成线搬运比身体大几倍的叶屑，分工细致——ant「蚂蚁」。群居、分工（蚁后/工蚁/兵蚁）是社会性昆虫的模板；ant 也是天线 antenna 的词头来源误读，别混。\",\n\"spider\":\"画面：一只蜘蛛坐在网中央，八条腿分别搭在信号丝上等猎物触网——spider「蜘蛛」。八腿、无翅、能吐丝结网；不是昆虫（昆虫六腿），分类上是蛛形纲，和 tick 是亲戚。\",\n\"worm\":\"画面：雨后一条蚯蚓钻出泥土蠕动，松过的土透气又肥沃——worm「蠕虫；蚯蚓」。细长软体无腿动物的统称；bookworm 是书虫（比喻），电脑 worm 是蠕虫病毒，都借它的钻劲。\",\n\"snail\":\"画面：一只蜗牛背着螺旋壳慢吞吞爬过，留下一道闪亮黏液——snail「蜗牛」。慢的代名词（at a snail's pace）；壳是它的随身房，受惊就整只缩进去。\",\n\"frog\":\"画面：一只青蛙蹲在荷叶上，后腿一蹬跃入水中，喉下鸣囊一鼓一鼓地叫——frog「青蛙」。两栖代表：蝌蚪变青蛙是变态发育的教科书案例；皮肤湿滑、善跳善游。\",\n\"toad\":\"画面：一只蟾蜍皮肤粗糙布满疙瘩，蹲在墙角等夜里捕虫——toad「蟾蜍」。青蛙的粗皮亲戚，更耐旱、离水更远；耳后毒腺能分泌毒液，别被『癞蛤蟆』的长相欺骗，它是益兽。\",\n\"snake\":\"画面：一条蛇无腿贴地蜿蜒，靠腹鳞摩擦推进，舌头一吐一收闻气味——snake「蛇」。冷血、无腿、蜕皮生长；snake 作动词就是『蜿蜒前行』，河流蛇行也用它。\",\n\"lizard\":\"画面：一只蜥蜴趴在热石上晒太阳，断尾求生后又慢慢长出新尾——lizard「蜥蜴」。四腿披鳞的爬行类，多数能断尾再生；变色龙、鬣蜥、壁虎都是它的家族成员。\",\n\"turtle\":\"画面：一只海龟划着鳍状肢洄游千里，回到出生的沙滩产卵——turtle「海龟；龟」。硬壳护体、水陆两栖；美式 turtle 泛指龟鳖，tortoise 专指陆龟，托福阅读常区分。\",\n\"whale\":\"画面：一头鲸从海面跃起又重重落水，喷水柱在头顶开花——whale「鲸」。最大的哺乳动物（不是鱼！）：用肺呼吸、胎生哺乳；蓝鲸是地球史上最大的动物。\",\n\"shark\":\"画面：一条鲨鱼背鳍划破水面，几排牙齿掉了立刻有新牙顶上——shark「鲨鱼」。软骨鱼、嗅觉极灵敏（能嗅到几公里外的血）；shark 也指放高利贷的骗子，贪婪是共同点。\",\n\"dolphin\":\"画面：一只海豚跃出水面画弧线，用喀哒声回声定位锁定鱼群——dolphin「海豚」。高智商哺乳动物，靠声呐交流捕猎；它和 porpoise 鼠海豚比：嘴更长、身更秀气。\",\n\"seal\":\"画面：一只海豹趴在浮冰上晒太阳，前肢短小、后肢抱团扭动上岸——seal「海豹」。鳍足类哺乳动物，陆上笨拙水中灵活；seal 也是『印章、密封』，动物义在海洋话题里认准浮冰画面。\",\n\"penguin\":\"画面：一只企鹅挺着白肚皮在冰面摇摆行走，入水却快如鱼雷——penguin「企鹅」。不会飞的海鸟，翅膀变鳍；南极是主场，北极没有企鹅（和北极熊永不相遇）。\",\n\"eagle\":\"画面：一只鹰展开两米翼展盘旋高空，锐眼锁定地面的一只田鼠俯冲而下——eagle「鹰」。猛禽之王，视力是人的八倍；美国国鸟白头海雕就是 eagle，eagle-eyed 是『眼光敏锐』。\",\n\"owl\":\"画面：一只猫头鹰头转了大半圈盯住猎物，无声翅羽让它夜袭毫无声息——owl「猫头鹰」。大眼夜视、飞行无声、头能转 270 度；智慧象征（雅典娜的伴鸟）与夜行习性绑定记。\",\n\"hawk\":\"画面：一只隼收翼如箭俯冲，时速三百公里扑向鸽群——hawk「隼；鹰」。昼行猛禽，俯冲极速冠军是游隼；hawk 也指政治上的『鹰派』（主战派），和 dove 鸽派相对。\",\n\"crow\":\"画面：一只乌鸦通体漆黑，叼着核桃飞到高空摔下砸壳吃仁——crow「乌鸦」。聪明到会用工具、记仇记脸；as the crow flies 是『直线距离』（乌鸦飞行走直线）。\",\n\"sparrow\":\"画面：一只麻雀在电线上一字排开叽叽喳喳，小个子蹦蹦跳跳啄食谷粒——sparrow「麻雀」。最常见的灰褐小鸟，吃种子也吃虫；麻雀虽小五脏俱全，说的正是它。\",\n\"pigeon\":\"画面：一只鸽子挺着胸在广场踱步，脖子羽毛泛着虹彩，咕噜咕噜叫——pigeon「鸽子」。归巢本能极强，曾当信使（homing pigeon 信鸽）；和平鸽 dove 是它的白色近亲。\",\n\"feather\":\"画面：一片羽毛轻得飘起又缓缓落下，中空的羽轴两侧排着细羽枝——feather「羽毛」。鸟类独有，保温、飞行、求偶三合一；light as a feather 是『轻如鸿毛』。\",\n\"wing\":\"画面：一只鸟展开翅膀扇动空气，升力把它托离枝头——wing「翅膀」。鸟与昆虫的飞行器官；建筑侧翼、政党派系也叫 wing（像主屋伸出的翅膀）。\",\n\"claw\":\"画面：一只老鹰的利爪深深扣进猎物，弯钩般的角质爪放不开——claw「爪子」。猛禽猛兽的弯钩武器；猫狗的爪可伸缩，crab 的钳子则叫 pincer/claw 都见。\",\n\"beak\":\"画面：一只巨嘴鸟的大喙又轻又硬，正灵巧地剥开果皮——beak「鸟喙」。鸟的『嘴』专名，无齿靠喙取食；形状随食性变：鹰钩、鸭扁、蜂鸟细管都是 beak 的变奏。\",\n\"horn\":\"画面：一头公牛头顶两只弯角低头冲撞，角尖闪着寒光——horn「（动物）角」。角蛋白或骨质的头部武器；犀牛角是毛发角质，鹿角（antler）年年脱落，先分清这两类。\",\n\"tail\":\"画面：一条狗尾巴摇得飞快表欢迎，猫尾巴炸毛竖起是警告——tail「尾巴」。脊椎末端的延伸，管平衡、表达情绪；tail 也是『尾随』：尾巴总跟在最后。\",\n\"fur\":\"画面：一只水獭的毛皮密得水珠滚落不沾，保暖全靠这层绒——fur「毛皮」。哺乳动物的浓密毛层（区别于人的 hair）；皮草大衣的 fur 指带毛的兽皮。\",\n\"shell\":\"画面：一只乌龟把头脚缩进硬壳，掠食者咬不动这间随身堡垒——shell「贝壳；外壳」。软体与龟类的护甲；蛋壳、坚果壳也叫 shell，核心画面是『硬外层保护壳』。\",\n\"scale\":\"画面：放大看一条鱼的鳞片如瓦片层层叠覆，滑溜又坚韧——scale「鳞片」。鱼类爬行类的护甲小片；scale 的其他义『秤、规模、音阶』都源于梯级意象，在生物语境先认鳞片。\",\n\"fin\":\"画面：一条鱼胸鳍轻轻摆动保持平衡，尾鳍一甩便窜出老远——fin「鱼鳍」。鱼的划水桨与平衡舵；潜水员的脚蹼也叫 fin，冲浪板尾鳍同名，都为水中推进而生。\",\n\"gill\":\"画面：一条鱼鳃盖一张一合，水流过鳃丝时氧气被抽进血液——gill「鱼鳃」。鱼的水下肺：从水里提取氧气；蘑菇下面的菌褶也叫 gills，形似而得名。\",\n\"trunk\":\"画面：一头大象的长鼻卷起一捆草，鼻尖像手指一样捏起花生——trunk「象鼻；树干」。象鼻是鼻唇合体的万能手；trunk 的主干义（树干、躯干、后备箱）都源于『主体长干』。\",\n\"herd\":\"画面：一群野牛成群迁徙，幼崽被护在队伍中央——herd「兽群」。大型食草动物的群体专名；herd 也是动词『放牧；驱赶』，herd immunity 群体免疫借的就是这个群。\",\n\"flock\":\"画面：一群椋鸟在空中如黑云翻卷变换队形，整齐得像一个整体——flock「鸟群；羊群」。鸟群与羊群的专名（牧人 Jesus 语境里 flock 指羊群信众）；鱼群是 school，先分清。\",\n\"swarm\":\"画面：一团蜜蜂黑压压涌出蜂巢迁徙，嗡嗡声震得空气发麻——swarm「蜂群；大群昆虫」。昆虫（尤指蜜蜂）的大群专名；a swarm of reporters 记者蜂拥而至是它的比喻用法。\",\n\"colony\":\"画面：一座蚁丘下成千上万只蚂蚁各司其职，整座巢就是一个超级个体——colony「（生物）群体；殖民地」。生物学指同种生物的集群（蚁群、蜂群、菌落）；历史义殖民地同源于『成群定居』。\",\n\"nest\":\"画面：燕子衔泥把巢筑在屋檐下，雏鸟在草垫里张嘴待哺——nest「巢穴；鸟巢」。鸟类产卵育雏的家；nest egg 是『储备金』（像巢里的蛋留着孵未来）。\",\n\"burrow\":\"画面：一只兔子后腿飞快刨土，地道挖成迷宫躲开狐狸——burrow「（动物）洞穴；地洞」。动物亲手挖的地下窝，兼作动词『掘洞』；和 cave 天然洞窟分：burrow 是挖出来的。\",\n\"den\":\"画面：一头母狼把幼崽藏在岩缝兽穴深处，外人靠近就低吼警告——den「兽穴」。食肉动物的巢穴专名（狮穴 lion's den）；人的书房戏称 den，也是躲清静的『窝』。\",\n\"cave\":\"画面：探险者打着手电钻进溶洞，钟乳石从洞顶垂下如帘——cave「洞穴」。天然地下空间，史前人类曾居于此（cave painting 洞穴壁画）；cave in 是『塌陷；屈服』。\",\n\"forest\":\"画面：一片温带森林层层叠叠望不到边，林下光线幽暗苔藓遍地——forest「森林」。大面积成片的树林生态系统；rainforest 雨林是它的湿热版本，forest 托福生态话题的头号舞台。\",\n\"meadow\":\"画面：一片草甸野花遍地，蜜蜂在花间忙碌，远处雪山作背景——meadow「草甸」。长满野草野花的开阔草地，多在水边山间；比 prairie 湿润小片，比 lawn 多几分野趣。\",\n\"prairie\":\"画面：北美大草原一望无际，草浪随风起伏不见一棵树——prairie「大草原」。温带内陆的辽阔草原（如北美、欧亚草原带）；曾养育野牛群与印第安部落。\",\n\"savanna\":\"画面：非洲热带草原上稀疏的伞状金合欢树点缀草浪，长颈鹿在其间踱步——savanna「热带草原（稀树草原）」。草多树少的热带草原，旱雨季分明；和 prairie 比：更热、有零星大树。\",\n\"tundra\":\"画面：北极苔原一望无际只有苔藓地衣，冻土层下永不解冻——tundra「苔原」。极地无树平原，永久冻土、生长季极短；驯鹿与北极狐的家，气候变暖让它最先报警。\",\n\"desert\":\"画面：一片沙漠黄沙连天，仙人掌孤零零站着，几个月滴雨未下——desert「沙漠」。年降水极少的干旱地；重音在前（DE-sert），动词『遗弃』重音在后（de-SERT），别读错。\",\n\"oasis\":\"画面：黄沙中央突现一汪泉水和一圈椰枣树，驼队立刻有了精神——oasis「绿洲」。沙漠中有水草的地方，旅人的救命站；比喻义『乐土、慰藉之地』也常用。\",\n\"wetland\":\"画面：一片湿地水草交错，白鹭涉水觅食，泥土常年浸透——wetland「湿地」。水陆过渡带的总称（沼泽、滩涂都算），净化水质、候鸟驿站；wetland 比 marsh/swamp 范围更大。\",\n\"marsh\":\"画面：一片沼泽芦苇丛生、水浅草密，青蛙在浮萍间鸣叫——marsh「沼泽（草本）」。以草本植物为主的低洼湿地；记对比：marsh 多草、swamp 多树，先抓植物再分名。\",\n\"swamp\":\"画面：一片沼泽地里水杉泡在黑水里，藤蔓垂落，鳄鱼只露双眼——swamp「沼泽地（多树）」。有树木泡水的湿地；swamp 作动词是『淹没、压垮』（swamped with work 忙翻）。\",\n\"pond\":\"画面：一方池塘睡莲点点，鸭子划水，岸边垂柳倒映——pond「池塘」。比 lake 小得多的人造或天然小水体；across the pond 是俚语『大西洋彼岸（英国/美国）』。\",\n\"stream\":\"画面：一条溪流从山石间淌下，清澈见底，绕过鹅卵石哗哗作响——stream「溪流；小河」。比 river 小的流动水体；stream 也是数据的『流』（streaming 直播流），水流意象一以贯之。\",\n\"coral\":\"画面：一片珊瑚枝杈如鹿角伸展，热带鱼在缝隙间穿梭——coral「珊瑚」。珊瑚虫分泌的石灰质骨架堆成的海底森林；大堡礁 Great Barrier Reef 就是珊瑚的巨作。\",\n\"reef\":\"画面：一道暗礁横在航道下，船底擦过只差几米，浪花在礁顶翻白——reef「暗礁；礁」。水下岩石/珊瑚堆成的脊，特指 coral reef 珊瑚礁；对船是险，对海洋生物是家。\",\n\"algae\":\"画面：池塘水面漂满绿油油的藻类，显微镜下有单细胞也有成丝成片——algae「藻类」。无根茎叶分化的水生光合生物，从单细胞到巨藻；单数 alga 很少见，考试多用复数 algae。\",\n\"plankton\":\"画面：一滴海水在显微镜下满是漂浮的微小生物，随波逐流毫无游泳力——plankton「浮游生物」。plankt- 是希腊语『漂流』：被水冲着走的微小植物（phyto-）与动物（zoo-）总称，鲸靠它吃饭。\",\n\"fungus\":\"画面：一朵蘑菇从朽木上撑开伞盖，菌丝在木头里织成白网——fungus「真菌」。无叶绿素、靠分解有机物吃饭的王国：蘑菇、霉菌、酵母都是它；复数 fungi。\",\n\"moss\":\"画面：一层苔藓如绿毯裹住湿石，没有根只有假根，靠全身体表吸水——moss「苔藓」。最原始的陆生植物之一，无花无种靠孢子；a rolling stone gathers no moss 是它的谚语。\",\n\"fern\":\"画面：一片蕨的羽状叶卷着嫩芽展开，林下阴湿处长成绿毯——fern「蕨类」。不开花不结种、靠孢子繁殖的古老植物，恐龙时代就是森林主角；嫩叶卷如提琴头是标志。\",\n\"pine\":\"画面：一棵松树四季常青，针叶成束，松塔挂在枝头——pine「松树」。裸子植物代表，针叶耐旱耐寒；pine 也是动词『渴望、消瘦』，和树义无关，靠语境切开。\",\n\"oak\":\"画面：一棵橡树粗干虬枝，橡子戴着小帽子落满地——oak「橡树」。坚硬长寿的阔叶树，果实 acorn 橡子是松鼠的粮仓；mighty oaks from little acorns grow 是励志谚语。\",\n\"maple\":\"画面：一棵枫树秋来满树红叶，翅果像小螺旋桨旋转着飘落——maple「枫树」。掌状叶与翅果是标志，树液熬成 maple syrup 枫糖浆；加拿大国旗正中就是一片枫叶。\",\n\"bamboo\":\"画面：一片竹林节节高升，中空而有节，一场春雨后竹笋齐冒头——bamboo「竹子」。长得最快的植物（一天近一米），其实是草不是树；熊猫的主食、亚洲建材都是它。\",\n\"vine\":\"画面：一条藤蔓缠着大树向上攀爬，卷须牢牢勾住树干借力登高——vine「藤蔓」。茎柔弱必须攀附的植物（葡萄藤、常春藤）；短视频应用 Vine 也借了藤蔓蔓延的意象。\",\n\"shrub\":\"画面：一丛灌木从基部就分出许多枝条，高度只到人腰——shrub「灌木」。低矮多干的木本植物，比 tree 矮小、比草木质化；花园篱笆多用灌木修剪成型。\",\n\"branch\":\"画面：大树主干上分出一条粗枝，枝上再分细枝托着鸟巢——branch「树枝；分支」。树的分叉部分；分行、分店、学科分支都叫 branch，都是从主干分出去的意象。\",\n\"bark\":\"画面：一棵老树树皮粗糙开裂，剥下一块露出里面鲜活的形成层——bark「树皮」。树干的保护外衣；bark 也是『狗吠』，同形异义：树下狗叫 bark at the bark 别笑场。\",\n\"petal\":\"画面：一片玫瑰花瓣柔软带香，几片围成花冠引诱蜜蜂——petal「花瓣」。花最艳丽的部分，职责是广告招牌吸引 pollinators；花瓣凋落后才轮到果实登场。\",\n\"pollen\":\"画面：一阵风吹过松林，黄色花粉如烟飘散，落在水面成膜——pollen「花粉」。花的雄性配子，细如粉尘；花粉症 hay fever 的元凶，也是授粉环节的主角货物。\",\n\"nectar\":\"画面：一只蜂鸟把长喙探进花心，吸食甜甜的花蜜——nectar「花蜜」。花分泌的糖水，花请 pollinators 吃饭的报酬；神话里 nectar 是众神的不死饮料，甜是共同点。\",\n\"bud\":\"画面：早春枝头一个花芽裹着鳞片，气温一到就胀大绽开——bud「芽；花蕾」。未展开的叶或花，是植物的『预备队』；nip in the bud 是『防患于未然』（掐灭在芽里）。\",\n\"bloom\":\"画面：樱花满树绽放如粉云，一周内开到鼎盛又飘雪般落下——bloom「开花；花期」。花盛开的动作与状态；algal bloom 藻华（水华）是它在生态题里的高频用法。\",\n\"wither\":\"画面：缺水的花低垂下头，花瓣边缘卷曲发黄，慢慢干枯——wither「枯萎；凋谢」。植物失水或衰老导致的干瘪；也可形容人的容颜、希望『凋零』，如 withered hopes。\",\n\"decay\":\"画面：一根倒木被真菌分解得酥软，养分缓缓回归土壤——decay「腐烂；衰变」。有机物被微生物拆解的过程；牙齿蛀蚀、放射性衰变也叫 decay，核心是『由整变散的瓦解』。\",\n\"rotten\":\"画面：一个苹果从芯里烂出褐斑，散出酸腐气味不能再吃——rotten「腐烂的；糟糕的」。decay 的结果形容词；口语 a rotten day 是倒霉的一天，烂到家的感觉一脉相承。\",\n\"barren\":\"画面：一片贫瘠的土地裂着口子，撒下种子也不发芽——barren「贫瘠的；不育的」。土地不产、生物不育的共性是『没有产出』；barren desert 里 barren 就是寸草不生。\",\n\"drought\":\"画面：一场大旱持续数月，水库见底，田地龟裂成块——drought「干旱」。长期缺雨的气候灾害（拼写 gh 不发音最难记）；和 flood 洪水是一对极端天气反义词。\",\n\"flood\":\"画面：暴雨后河水漫过堤岸涌进街道，低洼处成泽国——flood「洪水；泛滥」。水多到溢出边界；信息洪流 a flood of emails 也是它；注意 flood 是自然灾害里的水，和 drought 对记。\",\n\"soil\":\"画面：一把黑土攥在手里松软带潮，蚯蚓在里面钻来钻去——soil「土壤」。岩石风化+有机质的混合层，植物的立足之本；soil erosion 水土流失是地理高频词组。\",\n\"clay\":\"画面：一团黏土湿时能捏成碗，干后硬如陶片——clay「黏土」。颗粒极细的土壤，湿塑干硬；烧成陶器的原料，网球 clay court 红土场用的也是它。\",\n\"silt\":\"画面：河水退去后岸边沉下一层细滑的淤泥，手指一捻没有沙感——silt「淤泥；粉砂」。粒径介于沙与黏土之间的沉积物，黄河的 silt 造就了冲积平原；silt up 是淤塞。\",\n\"gravel\":\"画面：一把砾石摊在掌心，全是豆粒大的小石子，铺路哗哗作响——gravel「砾石」。比沙大、比卵石小的碎石粒；花园小径和混凝土骨料都靠它，踩上去的声音很有辨识度。\",\n\"blink\":\"画面：强光一闪，他不由自主地眨了下眼——blink「眨眼」。双眼一起、快而不受控的本能动作；一生人眨眼上万次，in the blink of an eye 是『转瞬间』，拼写里的 link 是眨眼之间就连上的快。\",\n\"wink\":\"画面：台上的人朝同伴挤了下左眼——『暗号收到』——wink「眨眼示意」。和 blink 的区别就一条：wink 是单只眼、故意的，传递的是默契或玩笑；blink at 是惊讶，wink at 是会意。\",\n\"stare\":\"画面：他盯着黑板上的公式纹丝不动，眼都不眨——stare「凝视」。长时间、专注地直视，常带惊讶或无礼感；stare at 是固定搭配，和 glance（一瞥）正好是时间长短的两极。\",\n\"glance\":\"画面：进门时他往墙上的钟瞄了一眼，脚步没停——glance「瞥见；一瞥」。看得快、看得浅，一眼带过；at a glance 一眼就能看出，glance through 是快速浏览文章，阅读题高频。\",\n\"glare\":\"画面：被抢了车位的司机摇下车窗，狠狠瞪着对方——glare「怒视」。glare 的眼神带火气，是愤怒的瞪；它还有『刺眼强光』义：the glare of the sun，两种意思共享『扎眼』的感觉。\",\n\"peek\":\"画面：孩子踮起脚，从门缝里偷看屋里的生日蛋糕——peek「偷看」。peek 是短暂、悄悄的一眼，常接 through/at；游戏 peek-a-boo 用的就是它，强调趁人不备。\",\n\"peep\":\"画面：他从窗帘缝里窥见院子里有人影晃动——peep「窥视」。peep 比 peek 更鬼祟、时间略长，常带不该看的意味；peep 还可指小鸡的唧唧声、黎明微光，核心都是『刚冒头一点点』。\",\n\"swallow\":\"画面：她端起水杯，喉咙一滚把药片咽了下去——swallow「吞咽」。食物或液体经喉入胃的动作；紧张时 swallow hard 是咽口水；它还是名词『燕子』，两种义靠语境分。\",\n\"chew\":\"画面：他把口香糖嚼了又嚼，腮帮子一鼓一鼓——chew「咀嚼」。牙齿反复磨碎食物的动作；chew on/over 引申为『反复琢磨』一个问题，和 swallow 的一口吞下正相反。\",\n\"lick\":\"画面：小狗伸出舌头，一下下舔着主人手心里的盐——lick「舔」。舌头贴着表面滑过的动作；冰淇淋要 lick 着吃，lick one's lips 是馋得舔嘴唇，想吃和期待都在这一下里。\",\n\"suck\":\"画面：婴儿含着奶嘴，腮帮子一凹一凹地吮——suck「吸吮」。靠嘴造成负压把液体吸进来；吸管 straw 就是为 suck 而生；口语 It sucks 是『真糟糕』，记前者即可。\",\n\"scratch\":\"画面：蚊子包痒得不行，他伸手一挠挠出几道红印——scratch「抓挠」。指甲在皮肤上反复划过止痒；猫 scratch 家具、唱片被 scratch 出划痕，都是同一组『指甲/尖物划过』的动作。\",\n\"rub\":\"画面：她把护手霜在手背上揉开，来回搓了十几下——rub「摩擦；揉搓」。手掌贴着表面来回移动，有摩擦力；rub out 是擦掉，阿拉丁神灯也是 rub 出来的——摩擦生『变』。\",\n\"pat\":\"画面：他轻轻拍了拍哭泣孩子的后背：『没事了。』——pat「轻拍」。手掌平贴、轻轻落下，带安抚或鼓励；pat on the back 字面拍背、引申表扬，和 slap 的响亮耳光力度天差地别。\",\n\"slap\":\"画面：一记耳光甩在脸上，清脆又火辣——slap「拍打；掌掴」。手掌大力拍击、带声响，常含惩罚或羞辱；slap on 是随手贴上（标签、罚款），动作的随意感一脉相承。\",\n\"pinch\":\"画面：他捏起一小撮盐撒进汤里——pinch「捏」。拇指和食指夹住一点点东西；a pinch of salt 一撮盐是烹饪高频量词；太紧的鞋 pinch 脚，也是这种『两边夹紧』的痛感。\",\n\"squeeze\":\"画面：她双手拧毛巾，把水挤得哗哗往下滴——squeeze「挤压」。从两侧施压逼出内容物或变形；squeeze in 是挤时间见一面，squeeze out 利润被挤干——『压出剩余空间』是共同画面。\",\n\"hug\":\"画面：分别多年的人在机场张开双臂紧紧抱住——hug「拥抱」。双臂环住对方身体的亲密动作；bear hug 是熊抱；环保语境 tree hugger（抱树者）由此得名，指激进环保者。\",\n\"kiss\":\"画面：母亲俯身在婴儿额头上轻轻一吻——kiss「亲吻」。嘴唇轻触表示爱意或礼节；kiss of death 是『死亡之吻』，指看似好意实则致命的事；法式接吻之外的 kiss 多是点到为止。\",\n\"nod\":\"画面：听完汇报，老板微微低头又抬起——『通过』——nod「点头」。头上下动一次表示同意、招呼或困倦；nod off 是打瞌睡时头一点一点，和表示同意的点头动作一模一样。\",\n\"bow\":\"画面：演员谢幕时深深弯下腰向观众致意——bow「鞠躬」。上身前倾的礼节动作（读音 /baʊ/）；它还指弓和蝴蝶结（读音 /boʊ/），鞠躬时身体弯成弓形，两个义其实是一幅画。\",\n\"kneel\":\"画面：他在求婚时单膝跪地，举起戒指盒——kneel「跪下」。膝盖着地、身体直立或前倾；过去式 knelt；教堂祈祷、擦地板都是 kneel，拼写里的 k 不发音，和 knee 同源。\",\n\"squat\":\"画面：他蹲在路边系鞋带，脚跟稳稳踩实地面——squat「蹲下」。双膝弯曲、臀部落低的姿势；健身深蹲也是它；squat 还指非法占住空房，引申自『蹲守』的画面。\",\n\"crawl\":\"画面：宝宝手膝并用地在地毯上往前爬——crawl「爬行」。身体贴近地面、手脚交替推进；交通 crawl 是车流蠕动，网页爬虫 crawler 同源——慢而贴地是共同点。\",\n\"limp\":\"画面：他崴了脚，一瘸一拐地走向替补席——limp「跛行」。因腿脚受伤走路一高一低；limp 作形容词是『软塌塌的』：a limp handshake 无力的握手，走路和物体的『没劲』共享一个画面。\",\n\"stroll\":\"画面：晚饭后老两口沿着河边慢慢溜达——stroll「漫步」。速度比 walk 还慢、毫无目的、纯享受；take a stroll 是固定说法；和 march 的正步、wander 的迷茫相比，stroll 只有悠闲。\",\n\"wander\":\"画面：他在老城的小巷里漫无目的地转了一下午——wander「徘徊；漫游」。没有路线、随兴所至地走；思绪 wander 是走神，问题 wander off topic 是跑题——脚步和心思都能『游荡』。\",\n\"march\":\"画面：士兵们踏着鼓点齐步穿过广场——march「行进；游行」。有节奏、有队列感的步行；抗议游行也叫 march，三月 March 同源于战神 Mars——行军的季节就是三月。\",\n\"chase\":\"画面：警犬撒开腿追赶翻墙而逃的身影——chase「追逐」。为了抓住目标而紧追不舍；chase after fame 是追名逐利，chase 的目标永远在前方跑，它永远差一步。\",\n\"flee\":\"画面：山火逼近，村民们弃家向山下逃去——flee「逃跑」。为躲避危险而仓皇逃离（过去式 fled）；flee the country 是逃亡出国；和 chase 是一对：一个逃、一个追，常同篇出现。\",\n\"hide\":\"画面：捉迷藏的孩子蜷在窗帘后面屏住呼吸——hide「躲藏；隐藏」。把自己或东西藏到看不见的地方（hide–hid–hidden）；hide 还作名词『兽皮』，躲藏时披兽皮伪装，是它的老来源。\",\n\"seek\":\"画面：救援队在废墟里一处处搜寻幸存者——seek「寻找」。正式而执着地找抽象或具体目标（seek–sought–sought）；seek advice 是求教，seek shelter 是找避难所，比 find 多了过程感。\",\n\"grab\":\"画面：公交猛刹车，他一把抓住头顶的扶手——grab「抓取」。突然、快速、用力地抓，常带抢夺或救急感；grab a bite 是匆匆吃一口，grab attention 是抓住注意力，都有『猛地拿下』的劲。\",\n\"grasp\":\"画面：登山者手指扣进岩缝，牢牢抓住不放——grasp「抓牢；领会」。物理上抓得稳、抓得住；抽象义 grasp an idea 是『一下领会』——手抓牢和脑子抓牢，英文用同一个词。\",\n\"grip\":\"画面：他双手紧握方向盘，指节发白——grip「紧握」。长时间、持续用力地握住不放；grip 还作名词『把手、控制力』：get a grip 是稳住；和 grab 的猛抓相比，grip 贵在持久。\",\n\"clutch\":\"画面：过山车俯冲时，她死死攥住胸前的安全带——clutch「紧抓」。紧张或恐惧中下意识地攥紧，指节用力；汽车的 clutch（离合器）靠的也是这种『咬合抓紧』的机械动作。\",\n\"pull\":\"画面：他攥住绳子身体后仰，把水井里的桶拽上来——pull「拉」。力量朝向自己或跟随自己的方向；pull out 是拔出/退出，pull through 是渡过难关——都从『往这边带』延展开。\",\n\"push\":\"画面：车陷进泥里，几个人在车尾一起使劲往前推——push「推」。力量朝远离自己的方向施加；push 与 pull 是永恒的一对反义词；push for 是力推某事，推的劲头延伸到了抽象层面。\",\n\"drag\":\"画面：他拖着沉重的行李箱，轮子在地上磕磕绊绊——drag「拖」。东西贴着地面被拉着走，摩擦感强、不情愿；时间 drags 是日子拖沓难熬，被拖着走的无奈一脉相承。\",\n\"lift\":\"画面：他双腿一沉，把杠铃稳稳举过头顶——lift「举起」。把重物从低处抬到高处；lift 还指电梯（英式）和『顺风车』；心情被 lift 是被抬高，云雾 lift 是散去——都是『向上离开原地』。\",\n\"lower\":\"画面：国旗在暮色中沿旗杆缓缓降下——lower「降低；放下」。low 的动词形：让高度、音量、价格往低处去；lower your voice 压低声音，lower 还可表示放下武器——都是『往下走』。\",\n\"drop\":\"画面：他手一滑，杯子脱手坠地摔得粉碎——drop「落下；掉落」。物体因失去支撑垂直掉下；drop 还指一滴水和『下降』本身：a drop in price 降价——从掉下到数字下跌，一条直线。\",\n\"throw\":\"画面：投手抡圆手臂，把球朝本垒狠狠掷出——throw「扔」（throw–threw–thrown）。手臂发力让物体飞出去；throw a party 是办派对（像扔出一场热闹），throw up 是呕吐，画面都是『向外抛出』。\",\n\"toss\":\"画面：他随手把钥匙抛给门口的朋友，接得稳稳的——toss「抛」。比 throw 更轻、更随意，常是小弧线短距离；toss a coin 抛硬币，toss and turn 是辗转反侧——身体像被抛来抛去。\",\n\"kick\":\"画面：前锋一脚抽射，球直挂球门死角——kick「踢」。用脚发力击打；kick off 是开球/开场，kick the habit 是踢掉坏习惯——把习惯像球一样一脚踢开，干脆利落。\",\n\"hit\":\"画面：棒球手挥棒正中来球，球飞向看台——hit「击打」（hit–hit–hit，三态同形）。物体与物体猛烈接触的瞬间；hit 还指『爆红的作品』，像一记重击打中所有人；hit the road 是上路出发。\",\n\"punch\":\"画面：拳击手一记直拳打在沙袋上，沙袋深深凹陷——punch「拳击；猛击」。握紧拳头打出去；punch 还指打孔器和宾治酒，但做题先记『拳头出击』；punch line 是段子的包袱，也像最后一拳。\",\n\"stab\":\"画面：他攥紧匕首向前猛地一刺——stab「刺」。尖锐物用力扎入的动作；a stab of pain 是针扎般的刺痛，背后捅刀 stab in the back 是背叛——利器伤人的画面贯通字面与比喻。\",\n\"chop\":\"画面：厨师手起刀落，把一根胡萝卜剁成均匀小丁——chop「砍；剁」。刀刃垂直落下、反复切断；chop down 是砍倒树，chop 还指排骨（被剁下的一块）；和 slice 的横切、stab 的扎入分工不同。\",\n\"dig\":\"画面：考古队员跪在探方里，一铲一铲掘出陶片——dig「挖掘」（dig–dug–dug）。工具向土里深入，开出洞或沟；dig up 是挖出真相，dig in heels 是掘地般地固执——都从『往下扎』生发。\",\n\"bury\":\"画面：他亲手把老狗埋在院角的樱桃树下——bury「埋葬」。把东西放进土里盖严；bury the hatchet 是埋掉斧头=言归于好；埋头工作 bury oneself in work，也是被『埋』进去的画面。\",\n\"mend\":\"画面：奶奶戴上老花镜，一针一线把破袜子补好——mend「修补」。修好破损的衣物或关系；on the mend 是身体在好转，mend fences 是修复关系——破了再补好，是它的全部故事。\",\n\"sew\":\"画面：她穿针引线，把纽扣牢牢缝回衬衫上——sew「缝纫」（sew–sewed–sewn）。针带着线穿过布料来回固定；sewing machine 缝纫机；和 knit（织毛线）、weave（织布面）相比，sew 是『连接两片』。\",\n\"knit\":\"画面：她两根棒针翻飞，毛线一点点变成围巾——knit「编织（毛线）」。棒针把一根线套成环环相扣的织物；眉头 knit 是皱眉（眉毛『织』到一起）；骨头 knit 是断骨愈合，都是『连成一体』。\",\n\"weave\":\"画面：织工在织布机上让经纬线交错穿梭，布面渐渐成形——weave「编织（布）；穿行」（weave–wove–woven）。线线交错成面；车流中 weave 是蛇形穿行，weave a story 是编故事——都是一根线穿来穿去。\",\n\"untie\":\"画面：他蹲下解开缠成死结的鞋带，越急越乱——untie「解开」。un- 是『反着来』：把 tie（系、绑）的结松开；untie 还可指解开船缆、松开束缚，核心都是『让绑着的恢复自由』。\",\n\"wrap\":\"画面：她把礼物用彩纸包好，再系上缎带——wrap「包裹」。用纸或布把东西整个裹住；wrap up 是包完，也引申『收尾结束』（wrap up the meeting）；被裹住的东西看不见里面，和 unwrap 相对。\",\n\"pack\":\"画面：出发前夜，他把衣服一件件叠进行李箱压实——pack「打包」。把东西有条理地装进容器；pack 还指一群（狼群 a pack of wolves）和挤满（packed 满座），都源于『密密麻麻装在一起』。\",\n\"unpack\":\"画面：搬进新家第一件事，她拆开纸箱取出锅碗——unpack「拆包；取出」。pack 的反动作：把装好的东西拿出来；unpack an idea 是层层剖析一个观点，像拆箱一样把里面的东西一件件摆开看。\",\n\"fold\":\"画面：他把地图沿虚线对折两次，塞进口袋——fold「折叠」。让平面的一部分翻过来贴住另一部分；fold your arms 是抱臂（手臂『折』到胸前）；fold 还指企业倒闭——像被折起来收走。\",\n\"unfold\":\"画面：他展开地图铺满桌面，路线一目了然——unfold「展开」。fold 的反面：把折起的摊平打开；故事 unfold 是情节徐徐展开，像地图一样一点点露出全貌，和字面同源同画。\",\n\"hang\":\"画面：她把湿毛巾搭在阳台栏杆上晾着——hang「悬挂」（hang–hung–hung）。东西上端固定、下端垂着；hang out 是挂出来，引申『闲逛消磨』；表『绞死』时过去式是 hanged，别和 hung 混。\",\n\"lean\":\"画面：他把梯子斜靠在墙上，又累得倚着门框喘气——lean「倾斜；倚靠」。身体或物体偏离垂直、靠向支撑物；lean 是瘦（肉少得像倾斜的一根），lean toward 是倾向于某观点——都是『向一侧偏』。\",\n\"slip\":\"画面：他踩到香蕉皮，脚下一滑摔了个四脚朝天——slip「滑倒；滑动」。接触面太滑导致失控移动；slip 还指小纸条和『小失误』：a slip of the tongue 口误——话像脚一样打了个滑。\",\n\"crash\":\"画面：失控的卡车撞上护栏，玻璃碎了一地——crash「碰撞；坠毁」。高速撞击伴随巨响和损毁；股市 crash 是暴跌，电脑 crash 是死机——都是『轰然倒下』的同一种冲击感。\",\n\"collide\":\"画面：两颗台球在桌心正面对撞，各自弹开——collide「碰撞」。两个运动物体迎面相撞（比 crash 更中性、更物理）；利益 collide 是冲突，日程 collide 是撞期——凡是两条轨迹交汇相抗都是它。\",\n\"bounce\":\"画面：皮球落地又弹起，越弹越低——bounce「弹跳」。物体撞击表面后反弹回来；bounce back 是迅速恢复（球再弹起），支票 bounce 是跳票（像球一样被弹回）——弹性是它的魂。\",\n\"spin\":\"画面：陀螺在桌上飞速打转，转成一团虚影——spin「旋转」。绕着自己的轴快速转动（spin–spun–spun）；蜘蛛 spin a web 是抽丝织网，媒体 spin 是给新闻『加旋』带风向——转是共同点。\",\n\"roll\":\"画面：一只木桶沿着斜坡骨碌碌滚到坡底——roll「滚动」。物体贴着地面边转边走；roll 还指卷（卷起袖子 roll up）和名册；rock and roll 的 roll 就是这团滚动的劲。\",\n\"twist\":\"画面：她双手反向用力，把毛巾拧成一股绳——twist「扭曲；拧」。沿着轴向拧转使变形；twist the truth 是歪曲事实，plot twist 是剧情拧了个弯——『被拧过』的东西形状和意思都变了。\",\n\"calculate\":\"画面：会计对着一列数字按计算器，逐笔核对——calculate「计算」。calcul- 源于拉丁『小石子』，古人用石子计数；calculate 还可指『盘算』：a calculated risk 是算计过的冒险，不只是算数。\",\n\"calibrate\":\"画面：工程师拿标准砝码校准天平，指针归零——calibrate「校准」。让仪器对照标准调到准确；calibrate expectations 是校准预期（别太高也别太低），共同点是『对到标准刻度』。\",\n\"cancel\":\"画面：暴雪封路，航班信息牌上亮起红色的『取消』——cancel「取消」。源于拉丁『画格子叉掉』：在预订上打叉作废；数学里 cancel out 是约掉，债务 cancel 是勾销——叉掉即消失。\",\n\"cater\":\"画面：婚宴公司按客人口味定制菜单，连素食桌都单独备好——cater「迎合；承办宴席」。本义是供应酒菜（catering 餐饮外包）；cater to 迎合需求，就是『按客人的胃口上菜』的引申。\",\n\"capitalize\":\"画面：对手失误的瞬间，他抓住机会反超比分——capitalize「利用」。capital（资本）+ -ize：把某物当资本去经营获利；capitalize on 是利用良机；大写字母也叫 capitalize——『使成资本/大写』一词两面。\",\n\"capsize\":\"画面：巨浪掀来，小帆船船底朝天翻扣在水里——capsize「翻船」。船体倾覆、底面翻上来；和 sink（沉没）不同，capsize 的船还浮着，只是翻了个个儿，画面感极强。\",\n\"captivate\":\"画面：魔术师一抖手帕变出白鸽，全场孩子目不转睛——captivate「迷住」。capt- 是『抓』（capture 同根）：美得把人心『抓住』不放；captivating 是迷人的，比 interesting 强得多。\",\n\"capture\":\"画面：陷阱门砰地落下，狐狸被困在笼中——capture「捕获」。capt-『抓』：抓住人、动物或稍纵即逝的东西；capture the moment 是抓拍瞬间，capture market 是攻占市场——都是『抓住不放』。\",\n\"carve\":\"画面：匠人在木头上运刀，一只鹰渐渐从木料里显形——carve「雕刻」。用刀在硬材料上削刻出形；carve out a career 是『刻』出自己的事业版图；火鸡也是 carve 着切——刀工一脉相承。\",\n\"cascade\":\"画面：山泉从石阶上一级级跳下来，溅起层层水花——cascade「倾泻；小瀑布」。水或物像瀑布一样连绵落下；信息 cascade 是层层转发，她的长发 cascade down 也是这道『阶梯式倾泻』。\",\n\"cast\":\"画面：渔夫撒开渔网，网在空中张成一个圆盖向水面——cast「投射；撒网」。本义是用力抛出（cast–cast–cast 不变形）；cast a shadow 是投下阴影，cast 演员表是『被选派』，都从『抛出/分配』来。\",\n\"catalog\":\"画面：图书管理员给新书逐本编号、贴签、登记入册——catalog「编目；目录」。把物品按系统列成清单；种子目录、课程目录都是 catalog——『让一切有序可查』是它的职责。\",\n\"catalyze\":\"画面：加入一滴催化剂后，平静的溶液猛烈冒泡反应——catalyze「催化」。化学里加速反应而自己不变；引申 catalyze change 是催化变革：像催化剂一样，自己不大动，却让事情骤然加速。\",\n\"categorize\":\"画面：她把一堆照片按年份和地点分进五个相册——categorize「分类」。category（类别）+ -ize：按特征把东西放进各自的格子；categorize A as B 是『把 A 归为 B 类』的常用句型。\",\n\"censor\":\"画面：审片员的手悬在剪刀上，把敏感镜头一帧帧剪掉——censor「审查」。官方检查并删改出版物、影片内容；censor 也是审查官本人；自我审查 self-censor，是把那把剪刀装进了心里。\",\n\"certify\":\"画面：公证员在文件上盖下钢印：『兹证明属实』——certify「证明；颁发证书」。cert- 是『确定』（certain 同根）：以官方身份确认真实；certified 是持证的，certificate 是那张『被确认』的纸。\",\n\"chant\":\"画面：球迷看台上上千人齐声高喊同一句口号——chant「唱诵；反复高喊」。用单调有节奏的调子反复唱念；寺庙的诵经、抗议的口号都是 chant；核心是『一句词，千遍重复』。\",\n\"characterize\":\"画面：评论家写道：这座城市以潮湿和慵懒著称——characterize「描绘特征」。character（特征）+ -ize：说出某人某物最典型的样子；be characterized by 是 TOEFL 写作高频结构，等于『其标志是』。\",\n\"charm\":\"画面：他三言两语逗得全桌人哈哈大笑——charm「迷人；使着迷」。charm 是名词『魅力/小饰物』动词化：像护身符一样让人心甘情愿被吸引；charming 是迷人的，比 beautiful 更强调灵动劲儿。\",\n\"chastise\":\"画面：父亲板着脸训斥把邻居玻璃打碎的孩子——chastise「惩戒；严厉批评」。比 scold 更正式、更重，带惩罚意味；媒体 chastise 政府是公开敲打——都是『为过错付出代价式的批评』。\",\n\"cheapen\":\"画面：满街仿冒品涌入，正品的价格和口碑一起被拖低——cheapen「贬低；使廉价」。cheap + -en：让东西在价格或价值上变低；cheapen oneself 是自降身价，钱与格调在英文里都用 cheap 量。\",\n\"cheer\":\"画面：绝杀进球的瞬间，整片看台跳起来挥手欢呼——cheer「欢呼；喝彩」。为支持而发出的喊声和鼓掌；cheer up 是（让）振作起来，cheer on 是加油助威——声音里装着鼓劲。\",\n\"chime\":\"画面：午夜钟楼敲响十二下，钟声漫过小镇——chime「鸣钟；报时」。钟或铃发出清越的乐音；chime in 是插话附和（像钟一样应声而响），chime with 是与…一致（声音合拍）。\",\n\"chirp\":\"画面：清晨枝头，麻雀叽叽喳喳叫个不停——chirp「啁啾」。小鸟短促尖细的鸣叫声；蟋蟀的鸣叫也叫 chirp；人说话 chirp 是欢快地叽喳，声音的『小而碎而亮』是共同特征。\",\n\"choke\":\"画面：他吃鱼被鱼刺卡住喉咙，咳得满脸通红——choke「窒息；哽住」。喉咙被堵、呼吸不畅；紧张到 choke 是关键时刻掉链子（像被掐住）；浓烟 choke 人，植物被杂草 choke，都是『堵死通道』。\",\n\"choreograph\":\"画面：编舞老师对着镜子逐拍拆解动作，舞者跟着定格——choreograph「编舞」。choreo- 是『舞蹈』：为舞者设计一整套动作序列；引申 choreograph an event 是精心策划每个环节，如同排舞。\",\n\"chuckle\":\"画面：他看到短信忍不住低头轻笑，肩膀微微发抖——chuckle「轻笑；暗笑」。压着声音、带着得意或会心的笑；比 laugh 轻、比 giggle 稳；多是想到了什么好玩的事，笑不外露。\",\n\"churn\":\"画面：农妇上下捣动搅乳器，牛奶渐渐析出黄油块——churn「搅动」。剧烈翻搅使混合或分离；胃里 churn 是翻江倒海，客户 churn 是流失（被搅走的人）——都是『翻搅中发生变化』。\",\n\"circulate\":\"画面：血液沿着血管在全身不停地转圈输送——circulate「循环；流传」。circ- 是『圆』：沿环形路径流动；消息 circulate 是传开（在人群里转圈），图书馆的书 circulating 也是在读者间轮转。\",\n\"cite\":\"画面：论文结尾他逐条标注：这句话出自哪本书哪一页——cite「引用」。指名道姓地援引出处以支撑论点；cite 还可指传唤、表彰，但学术写作里先记『注明出处地引』，TOEFL 写作必备词。\",\n\"civilize\":\"画面：边远小镇通了学校、医院和法庭，生活渐渐有了规矩——civilize「使文明」。civ- 是『城市、公民』：让社会按城市文明的规则运转；civilized 是文明的、有教养的，词根里就写着『进城』。\",\n\"clamp\":\"画面：木匠用 G 型夹把两块木板死死夹住上胶——clamp「夹紧」。用夹具施加持续的压力固定；clamp down on 是严厉取缔（像夹子一样钳制住），clamp 的钳制感贯穿字面与比喻。\",\n\"clap\":\"画面：演出结束，观众席响起整齐热烈的掌声——clap「拍手」。双掌相击发声表示赞赏；a clap of thunder 是一声炸雷（天也在『拍手』）；clap 与 slap 区别在双掌对击 vs 单掌打物。\",\n\"clash\":\"画面：两支游行队伍在路口迎面相遇，口号声撞在一起——clash「冲突；相撞」。本义是金属相撞的哐当声；意见 clash、颜色 clash（不搭）、日程 clash——凡是硬碰硬对上都是它。\",\n\"clasp\":\"画面：老友重逢，两只手紧紧相握久久不放——clasp「紧握；扣住」。双手或手指扣合式地抓牢；clasp 还指搭扣（把两边扣住的零件）；和 grasp 的抓相比，clasp 多了『扣合』的形状感。\",\n\"classify\":\"画面：生物学家把新发现的甲虫归入库中对应的科属——classify「分类」。class（类）+ -ify：按标准把事物编入类别体系；classified 是机密的——被『分进保密那一格』的东西，来源很直白。\",\n\"clatter\":\"画面：一摞盘子从架子上滑落，在地上哗啦啦响成一片——clatter「哗啦作响」。硬物连续碰撞发出的清脆杂沓声；马蹄 clatter、键盘 clatter，都是『一连串硬碰硬的动静』。\",\n\"cleanse\":\"画面：她用温水和香皂把脸上的妆和尘土洗得干干净净——cleanse「净化；清洁」。比 clean 更彻底、更仪式化：洗掉污垢乃至『不洁』；ethnic cleansing 是种族清洗（贬义），词的净化感被扭曲利用。\",\n\"cleave\":\"画面：樵夫举斧对准木桩，一斧下去木头裂成两半——cleave「劈开」。沿纹理一劈为二的干脆动作；奇妙的是 cleave to 又是『黏着、忠于』——一个词装着劈开与黏合两个反义，靠语境区分。\",\n\"clench\":\"画面：听到判决，他咬紧牙关，拳头攥得指节发白——clench「紧握；咬紧」。愤怒或紧张时把拳头、牙齿死死收紧；clench 与 clutch 相近，但 clench 咬合的意味更重，多和 fist、teeth 搭配。\",\n\"click\":\"画面：鼠标轻轻一按，页面唰地跳转——click「点击」。短促清脆的『咔哒』声，引申为按鼠标；It clicks 是『一下想通了』（像机关咔哒合上），click with 是与人一见如故（咔哒对上了）。\",\n\"cling\":\"画面：考拉宝宝四肢抱紧桉树干，怎么晃都不松——cling「粘附；紧抱」（cling–clung–clung）。贴紧不放、难以分离；cling to hope 是抓住希望不放，静电让裙子 cling 在腿上——黏着力是核心。\",\n\"clip\":\"画面：剪辑师在时间轴上咔嚓剪掉多余的三秒——clip「剪辑；修剪」。用剪刀或工具利落地剪下一小段；clip 还指回形针（夹住纸的）和短视频片段——『截取一小段』是共同模样。\",\n\"cloak\":\"画面：他披上深色斗篷，身影没入夜色不见——cloak「掩盖；斗篷」。名词是遮身的斗篷，动词就是用它盖住：cloak in secrecy 是秘而不宣；间谍小说 cloak-and-dagger（斗篷与匕首）即源于此。\",\n\"clog\":\"画面：落叶堵满下水口，雨水漫上路面——clog「堵塞」。管道或通道被杂物塞住、流通不畅；动脉 clog 是血管被胆固醇堵住，交通 clog 是路被堵死——凡是『流不动』都是它。\",\n\"clone\":\"画面：实验室里，多利羊站在镜头前——它和供体羊长得一模一样——clone「克隆」。由单个细胞复制出基因完全相同的个体；clone 还指功能外观都照抄的仿制品，核心是『复制出一个同款』。\",\n\"clothe\":\"画面：母亲给婴儿穿上连体衣，扣好每一颗小扣子——clothe「穿衣；给…穿衣」。cloth（布）的动词形，正式词；be clothed in 是『身披…』，clothed in fog 是山被雾『穿』上外衣——给万物穿衣的画面。\",\n\"clout\":\"画面：他在行业里一句话就能让项目立项——clout「影响（力）」。本义是重击一拳，引申为说话办事的分量：political clout 政治影响力；有 clout 的人不动手，一句话就有『一击』的重量。\",\n\"cloy\":\"画面：连吃三块奶油蛋糕后，甜得发腻，再看一眼都反胃——cloy「腻烦」。甜或腻过头引起的厌倦，常和 sweet 连用；cloying 是腻人的（言情、香味、殷勤都可腻）——好东西过了量就成负担。\",\n\"clump\":\"画面：湿地里芦苇一簇簇成丛地长，根都缠在一起——clump「成丛；丛」。一群东西密集聚成一团；脚步声 clump 是沉重地咚咚走（像一团重量在移动）；a clump of trees 是一簇树，量词感很强。\",\n\"coagulate\":\"画面：伤口上的血慢慢变稠，凝成暗红色的痂——coagulate「凝结」。液体（尤指血液、蛋白质）变成半固体；coagul- 源于『凝聚剂』：分散的颗粒抱团变稠，和 dissolve（溶解分散）正相反。\",\n\"coalesce\":\"画面：天上的小水滴越聚越大，终于合并成一颗滚落——coalesce「合并；联合」。co-（共同）+ alesc（生长）：多个小体合长成一个大体；派别 coalesce 是结成联盟，水滴和政党用的是同一个『合』。\",\n\"codify\":\"画面：法学家把散见于判例的规矩逐条整理成法典——codify「编成法典」。code（法典）+ -ify：把零散规则系统地写成条文；引申为把惯例『明文化』——凡成文成体系，都是 codify。\",\n\"coerce\":\"画面：他被按着手在不情愿的文件上签了字——coerce「胁迫」。用威胁或压力迫使人做不想做的事；coercion 是胁迫行为；和 persuade（说服）相比，coerce 的对方全程不情愿，词本身带贬义。\",\n\"coexist\":\"画面：一片草原上斑马和角马同饮一池水，相安无事——coexist「共存」。co-（共同）+ exist（存在）：不同事物在同一时空和平并存；生物题里物种共存、和平共处五项原则都是 coexistence。\",\n\"coin\":\"画面：造币厂里金属圆片被模具砰地压出头像和面值——coin「铸币；创造新词」。名词是硬币，动词是造硬币；莎士比亚 coin 新词就像铸新币：把没人用过的说法『铸』进语言里流通。\",\n\"coil\":\"画面：消防员把水管一圈圈盘成整齐的圆摞——coil「盘绕」。绳、线、蛇身绕成一圈圈的螺旋；蛇 coil 是盘成一团蓄势，电线 coil 是收纳——『一圈圈收拢』是它的形状记忆。\",\n\"collate\":\"画面：印好的讲义一页页核对页码，再按顺序装订——collate「核对；整理排序」。把散页或数据对照比较、排成正确顺序；collate data 是汇总核对数据，collate 的细致在『对过才算数』。\",\n\"collude\":\"画面：两家公司老板深夜密会，商量好一起抬高标价——collude「共谋；勾结」。co- + lud（玩，ludicrous 同根）：暗地里『合伙演戏』坑第三方；collusion 是串通，招标和定价语境高频，天然贬义。\",\n\"colonize\":\"画面：大航海时代，一面旗帜插上新大陆的海岸——colonize「殖民」。colony（殖民地）的动词形；生物学里细菌 colonize 肠道、植物 colonize 裸岩，用的是同一套『占地扎根繁衍』的画面。\",\n\"combat\":\"画面：两军在山谷短兵相接，尘土飞扬——combat「战斗」。名词动词同形，正面交手地打；combat 还引申『与…斗争』：combat climate change 与气候变化作斗争，和 fight 相比更正式军事化。\",\n\"combust\":\"画面：干柴堆遇到火星，噼啪一声腾起火焰——combust「燃烧」。com- + ust（烧，源于拉丁 urere）：化学式地『烧起来』；combustion 是燃烧反应，combustible 是易燃的——物理化学题的正式词。\",\n\"commemorate\":\"画面：校庆日，老校友在纪念碑前献花，碑上刻着年份——commemorate「纪念」。com- + memor（记忆，memory 同根）：用仪式或纪念物让大家『共同记得』；commemorate 的日子都是被刻意留住的日子。\",\n\"commend\":\"画面：市长在仪式上为救人的消防员颁奖，全场起立——commend「赞扬；表彰」。公开而正式地夸奖并推荐；commendable 是值得称赞的，和 recommend（推荐）同根：都是『把好东西推到人前』。\",\n\"compact\":\"画面：垃圾压缩机把一堆废料压成方方正正的一块——compact「压紧」。把松散的东西压实变小；compact 作形容词是『小巧紧凑』（compact car），名词是粉盒/协议——核心都是『压到一起』。\",\n\"compel\":\"画面：证据确凿，法官迫使证人出庭作证——compel「迫使」。com- + pel（驱赶，pulse 同根）：用力量或义务把人『赶』去做某事；compelling 是令人信服到不得不然的（文章、理由），同样是被推着走。\",\n\"conceptualize\":\"画面：建筑师在白板上画出第一张草图：整个项目的概念定了型——conceptualize「概念化」。concept（概念）+ -ize：在脑子里把模糊想法收拢成清晰概念；学术写作里 conceptualize X as Y 是下定义的句型。\",\n\"concoct\":\"画面：他往锅里乱加香料，东拼西凑煮出一锅怪味汤——concoct「编造；调制」。con- + coct（煮，cook 同根）：本义是乱炖一锅，引申 concoct an excuse 是临时『炖』出一个借口——都是东拼西凑做出来的。\",\n\"condemn\":\"画面：法官宣判后，舆论也齐声谴责这桩暴行——condemn「谴责」。con- + damn（诅咒）：正式而强烈地宣判有罪或有错；建筑 be condemned 是被判定危房待拆——都是『被官方判了死刑』。\",\n\"condense\":\"画面：浴室镜面蒙上白雾，指尖一抹全是水珠——condense「浓缩；凝结」。dens（密）+ -ize 使变密：气体凝成液体、文章 condense 成摘要、牛奶 condensed 是炼乳——都是『挤掉水分只剩精华』。\",\n\"condone\":\"画面：老师明知学生抄袭却睁一只眼闭一只眼——condone「宽恕；纵容」。明知有错却不追究，带贬义；condone 与 forgive 区别：forgive 是真心原谅，condone 是不该放过却放过了，常用于暴力与腐败。\",\n\"conduct\":\"画面：指挥家抬起双臂，乐团随他的手势起落——conduct「实施；指挥」。con- + duct（引导，duct 管道同根）：把人或事『引着走』：conduct research 做研究，conduct 电流是引导电，conduct oneself 是举止（引导自己）。\",\n\"confess\":\"画面：他坐在神父的告解室里，低声说出藏了十年的秘密——confess「坦白；供认」。con- + fess（说）：把藏着的罪或秘密说出来；confess to 是承认做了，confession 是那份说出口的自白。\",\n\"confiscate\":\"画面：海关人员当场收走箱子里夹带的违禁品，贴上封条——confiscate「没收」。官方依法收缴私人财物；老师 confiscate 手机是课堂版没收；和 steal 区别：confiscate 有权力依据，是公权力的『收』。\",\n\"confound\":\"画面：魔术的最后一幕，全场观众面面相觑：『到底怎么做到的？』——confound「混淆；使惊讶」。con- + found（倒、熔）：把东西『倒成一团』分不清；confound expectations 是完全出乎意料，confounding variable 是混杂变量。\",\n\"confront\":\"画面：他鼓起勇气走到上司面前，直视对方说清问题——confront「面对；正视」。con- + front（前面）：站到对方面前不躲闪；confront a problem 是直面难题，confrontation 是对峙——躲不开的选择才叫 confront。\",\n\"congratulate\":\"画面：获奖名单公布，同学们围上来一一握手道贺——congratulate「祝贺」。con- + grat（高兴，grateful 同根）：为别人的好事一同高兴并说出来；congratulate sb on sth 是固定搭配，介词别用错。\",\n\"conjure\":\"画面：魔术师空手一挥，掌心凭空多出一枚硬币——conjure「变魔术；使浮现」。台上是手法变戏法；conjure up 是唤起画面（文字 conjure up images），言下之意都是『无中生有地召唤出来』。\",\n\"conquer\":\"画面：登山队在暴风雪后终于站上从未有人登顶的峰顶——conquer「征服」。con- + quer（寻求，quest 同根）：以力量夺取并控制；conquer fear 是征服恐惧，divide and conquer 是分而治之——夺取与压服是核心。\",\n\"consolidate\":\"画面：他把五张信用卡的欠款合并成一笔低息贷款——consolidate「巩固；合并」。con- + solid（结实）：把零散的并成结实的一整块；consolidate power 是巩固权力，consolidate gains 是巩固成果——都从『变结实』来。\",\n\"conspire\":\"画面：几个人关在小屋里压低声音，谋划着不可告人的计划——conspire「密谋」。con- + spir（呼吸）：头碰头『共呼吸』地商量坏事；conspiracy 是阴谋（论）；events conspire 是诸事凑巧作对，也是『串通好了』的味道。\",\n\"construe\":\"画面：他把这句含糊的判词理解成对自己有利的意思——construe「解释；理解」。正式词，尤指对文字、行为的解读；be construed as 被理解为；construe 与 interpret 同义，但 construe 更强调『按某种方式去理解』。\",\n\"consummate\":\"画面：筹备三年的项目在签约笔落下的一刻圆满完成——consummate「完成；使圆满」。con- + summ（最高，summit 同根）：做到顶点式的完成；consummate 作形容词读重音不同，指『技艺精湛的』（consummate artist）——顶级的圆满。\",\n\"contemplate\":\"画面：他独自坐在湖边，望着水面久久沉思去留——contemplate「沉思；考虑」。长时间安静地想一件大事；contemplate 是带画面的『凝视着想』，contemplate resigning 是认真考虑辞职，比 think 深、比 decide 早。\",\n\"contend\":\"画面：八名选手在决赛道上为一个冠军位置拼尽全力——contend「竞争；主张」。比赛里是争夺（contend for），辩论里是主张（contend that）；contend with 是不得不应对难题——争的对象可以是奖杯、观点或困境。\",\n\"contest\":\"画面：两位棋手在决赛桌前对坐，观众屏息——contest「竞赛；争夺」。名词是比赛，动词是质疑争夺（contest the result 对结果提出异议）；拼写与 contend 相近，但 contest 的场子感更强：有对手、有裁判。\",\n\"contrive\":\"画面：他用两根回形针和一截胶带，硬是鼓捣出一个开锁工具——contrive「谋划；设法做到」。费尽心机想出办法，常带贬义（contrive a plot 密谋）；contrive to do 是『居然设法做到』，心机与巧劲各占一半。\",\n\"converge\":\"画面：四条山溪在谷底汇成一条大河——converge「汇聚」。con- + verg（倾斜）：从不同方向斜向同一点；观点 converge 是趋同，人群 converge on 是涌向一处——多条线终成一点是它的几何魂。\",\n\"converse\":\"画面：两位老友在咖啡馆里一聊就是一下午——converse「交谈」。正式词，就是 talk 的书面版；converse 还作名词『相反的事物』、形容词『相反的』（读音重音不同），数学里的逆命题就是 the converse。\",\n\"convey\":\"画面：传送带把行李一件件送进分拣区——convey「传达；运送」。con- + vey（路，via 同根）：沿着路把东西送到：convey goods 是运货，convey feelings 是传情——信息和货物在英文里共用一辆『车』。\",\n\"convict\":\"画面：法槌落下，陪审团裁定被告罪名成立——convict「定罪」。con- + vict（征服，victory 同根）：在法庭上以证据『战胜』被告；名词 convict 是囚犯（重音前移）；conviction 还指坚定的信念。\",\n\"cordon\":\"画面：事故现场拉起黄色警戒线，警察守住每个路口——cordon「封锁；警戒线」。cordon off 是围出禁区；cordon 本义是装饰带（cord 绳同根）：一圈绳/一队人组成的封锁带，人和物都不得进出。\",\n\"cork\":\"画面：他抽出软木塞，砰的一声，红酒开瓶了——cork「塞住；软木塞」。cork 是栓皮栎树皮做的瓶塞，轻而富弹性；动词就是用它封口；和 plug 相比，cork 专指酒瓶那一声『砰』的仪式感。\",\n\"correlate\":\"画面：散点图上，冰淇淋销量和溺水人数竟同步升降——correlate「相关」。co- + relate（关联）：两个变量同涨同落；名言 correlation is not causation：相关不是因果，TOEFL 阅读和统计题的灵魂考点。\",\n\"counsel\":\"画面：心理咨询师坐在对面，轻声帮来访者理清思路——counsel「劝告；咨询」。既是名词『建议/法律顾问』也是动词；counsel 与 council（议会）同音易混：counsel 带 sel 是『给说法』，council 是开会的一群人。\",\n\"counter\":\"画面：拳击手挨了一拳后立刻一记勾拳还回去——counter「反击」。在柜台（counter）对面你来我往，引申为对着干：counter an argument 是反驳，counterattack 是反攻；counter- 前缀就是『反着来』（counterclockwise 逆时针）。\",\n\"covet\":\"画面：他盯着邻居家的新车，眼睛都看直了——covet「垂涎；贪求」。对别人的东西生出占有的渴望，宗教十诫里 covet 是被明文禁止的那种眼红；coveted 是人人想要的（coveted prize 人人垂涎的大奖）。\",\n\"crack\":\"画面：冰面在他脚下咔嚓裂开一道缝——crack「破裂」。硬脆物体裂开纹路或直接断开的声音与动作；crack a code 是破译（裂开密码的外壳），crack a joke 是讲笑话（把气氛『笑裂』）——裂开之后里面的东西露出来。\",\n\"cradle\":\"画面：母亲把婴儿放进木摇篮，轻轻推着晃——cradle「摇篮」。小床四脚带弧能摇动；cradle 还引申『发源地』：the cradle of civilization 文明摇篮；动词是像抱摇篮一样轻托——文明和婴儿都从摇晃里长大。\",\n\"cram\":\"画面：考前夜他把一学期的笔记硬往脑子里塞——cram「塞满」。在有限空间里硬挤硬塞：cram for an exam 是临时抱佛脚，车厢 crammed 是挤满了人——cramp 是抽筋、cram 是塞，拼写差一个字母，感觉都『挤』。\",\n\"cramp\":\"画面：游到泳池中央小腿突然抽筋，他疼得直扑腾——cramp「抽筋」。肌肉突然痉挛收缩的剧痛；cramped 是空间狭窄得让人『抽筋』（cramped room）；绊住手脚 cramp one's style 也是这种被卡住的感觉。\",\n\"crane\":\"画面：建筑工地的塔吊长臂缓缓转动，吊起一捆钢筋——crane「起重（机）；伸长（脖子）」。crane 本是鹤：长腿长脖子；起重机像鹤一样伸长脖子吊东西，人 crane one's neck 探头张望也是鹤的姿态——一种鸟撑起三个意思。\",\n\"crave\":\"画面：戒烟第三天，他满脑子都是香烟的味道，坐立难安——crave「渴望」。身体层面压不住的想要（crave sugar 馋甜食），比 want 强十倍；craving 是那股瘾劲；渴望到生理反应，是 crave 的标志。\",\n\"creak\":\"画面：老木楼梯踩上去嘎吱嘎吱响——creak「嘎吱作响」。木头、旧门轴受压发出的干涩声响；creak 与 creek（小溪）同音别混：一个是拟声的『吱呀』，一个是水流；creaky 是老得发响的。\",\n\"crease\":\"画面：他把揉皱的衬衫摊开，上面全是深深的折痕——crease「折痕」。布料、纸张被折压后留下的线状印记；crease 还指皮肤的皱纹线和球场线；creased 是起皱的——『被折过』的证据就是 crease。\",\n\"creep\":\"画面：藤蔓沿着墙面悄悄往上爬，一夏天爬满了整面墙——creep「爬行；蔓延」（creep–crept–crept）。贴着地、慢而无声地移动；物价 creep up 是悄悄上涨，creepy 是让人起鸡皮疙瘩的——慢慢逼近最吓人。\",\n\"crest\":\"画面：登山者踏上波浪般山脊的最高点，脚下云海翻腾——crest「顶峰；波峰」。山、浪、鸟冠的最高棱线；crestfallen 是垂头丧气（公鸡冠子耷拉下来）；crest 的位置永远在『浪尖』上。\",\n\"crib\":\"画面：考试时他偷偷瞄了一眼藏在袖口的小抄——crib「抄袭；小抄」。名词是婴儿床，动词是照抄别人的答案；crib sheet 就是小抄纸；crib 与 plagiarism 同义但更口语：抄得心虚、抄得临时。\",\n\"cringe\":\"画面：看到自己十年前的中二发言，他尴尬得脚趾抠地——cringe「畏缩；尴尬到缩起来」。身体因恐惧、厌恶或尴尬而本能蜷缩；网络语 cringe 专指『替人尴尬』到想缩成一团，身体反应即词义。\",\n\"cripple\":\"画面：老马腿受了伤，从此走不了远路——cripple「使跛；严重削弱」。本义是致人腿残；引申 cripple the economy 是重创经济：像被打断腿一样寸步难行；说人时带冒犯性，现代多用于抽象事物。\",\n\"crop\":\"画面：秋天一到，麦田金黄，农户忙着抢收这一季的庄稼——crop「收成；作物」。一茬种下、一茬收割的农作物总量；crop up 是突然冒出来（像庄稼出土）；crop 照片是裁掉边角——都是『从地里/图里取出一截』。\",\n\"crouch\":\"画面：猫压低身子伏在草丛里，眼睛死盯着前方的鸟——crouch「蹲伏」。身体蜷低、重心下沉，既为隐藏也为蓄势扑出；和 squat（日常蹲）相比，crouch 多了伏击与躲藏的紧张感。\",\n\"crystallize\":\"画面：糖水慢慢冷却，杯壁析出一颗颗透明的糖晶——crystallize「结晶」。液体里的分子排成规则晶格凝固；想法 crystallize 是思路『结晶』成形：混沌变有序，和字面同构，写作里极美。\",\n\"cub\":\"画面：熊妈妈身后跟着一只圆滚滚的小熊，跌跌撞撞学走路——cub「幼崽」。专指熊、狮、虎、狼等猛兽的幼崽；童子军 Cub Scout（幼童军）由此得名；家养宠物的幼崽用 puppy/kitten，野兽的才叫 cub。\",\n\"canvass\":\"画面：竞选志愿者挨家挨户敲门，说明政策拉选票——canvass「游说；拉票」。挨户走访征集选票或意见；canvass 还可指详细讨论、审查选票；和 campaign（整体竞选活动）比，canvass 是逐户敲门的那一段苦活。\",\n\"clue\":\"画面：侦探蹲下捡起一根不属于死者的头发丝——clue「线索」。源于希腊神话里引人走出迷宫的线团（clew）：顺着它能走出谜团；have no clue 是一点头绪都没有，clue in 是给人透个底。\"\n,\n\"continent\":\"画面：世界地图上七大块彩色陆地被海洋隔开——continent「大陆」。它是一整块最大的陆地单元；continental 大陆性的，the Continent 在英国人口中专指欧洲大陆本土。\",\n\"peninsula\":\"画面：一块陆地像舌头伸进海里，三面环水一面连着大陆——peninsula「半岛」。pen-（几乎）+insula（岛）：差一点就是岛；山东半岛、朝鲜半岛都是它。\",\n\"island\":\"画面：四面是海，中间一小块绿地立着椰子树——island「岛屿」。四面环水、比大陆小；读 /ˈaɪlənd/，s 不发音。isle 是它的诗意小兄弟。\",\n\"coast\":\"画面：站在悬崖边，海浪一排排拍上岸滩——coast「海岸」。海与陆交界的那条线；coastline 海岸线，West Coast 西海岸，coastal 沿海的。\",\n\"shore\":\"画面：船轻轻靠岸，他跳上湿漉漉的滩涂——shore「海岸；岸」。比 coast 更贴近水边那一带地；on shore 在岸上，offshore 离岸的。\",\n\"beach\":\"画面：金色沙滩斜斜没入海水，脚印一路到水边——beach「海滩」。专指沙质的缓坡岸；beach holiday 海滩度假，和 peach（桃子）只差首字母。\",\n\"bay\":\"画面：海岸线向内凹出一道弧，海水安静地躺在弧里——bay「海湾」。凹进去、比 gulf 小的海湾；海湾也因此 shelter 船只，bay window 凸窗是借了它的弧形。\",\n\"gulf\":\"画面：墨西哥湾在地图上张开一个大口，把海水揽进怀里——gulf「海湾」。比 bay 大得多的海湾；gulf 还引申为巨大隔阂：a gulf between rich and poor。\",\n\"strait\":\"画面：两片大陆之间只剩一条窄窄的水道，船排队通过——strait「海峡」。strait 本义『狭窄』：窄到挤的水道；台湾海峡 the Taiwan Strait，困境也叫 straits。\",\n\"ocean\":\"画面：飞机飞了五小时，窗外还是一望无际的深蓝——ocean「海洋」。地球上最大的水体，五大洋 the five oceans；比 sea 大一个量级。\",\n\"sea\":\"画面：内海被陆地半包着，渔船在平静的水面作业——sea「海」。比 ocean 小、常半被陆地围住；the Red Sea 红海，at sea 在海上（也比喻茫然）。\",\n\"lake\":\"画面：山间一汪清水四面被陆地围住，倒映着雪山——lake「湖」。陆地围着的淡水水体；the Great Lakes 五大湖，lake district 湖区。\",\n\"river\":\"画面：一条大水带从山里奔出，穿过平原汇入大海——river「河流」。自然形成的大水流；river bank 河岸，downstream 顺流而下。\",\n\"waterfall\":\"画面：河水走到悬崖边，整条坠下去砸出白雾——waterfall「瀑布」。water + fall：水在『落』；尼亚加拉瀑布 Niagara Falls 是它的招牌画面。\",\n\"glacier\":\"画面：一条冰的大河卡在山谷里，每年只挪几厘米——glacier「冰川」。会缓慢流动的巨型冰体；glacial 冰川的，也比喻极慢：at a glacial pace。\",\n\"iceberg\":\"画面：海面上只露出一座小冰山，水下还藏着九成体积——iceberg「冰山」。漂浮的大冰块；the tip of the iceberg 冰山一角，就是只露一小部分的意思。\",\n\"polar\":\"画面：地球仪的两端顶着白色冰盖，磁针在极点打转——polar「极地的」。pole（地极）派生：两极的；polar bear 北极熊，polar opposite 截然相反。\",\n\"equator\":\"画面：地球仪腰间画着一条红线，把球切成上下两半——equator「赤道」。equa-『等分』：把地球等分的线；equatorial 赤道的，赤道附近终年炎热。\",\n\"hemisphere\":\"画面：一个球被从中间切开，拿起一半扣在桌上——hemisphere「半球」。hemi-（半）+sphere（球）：半个球；南北半球、东西半球，也指大脑半球。\",\n\"latitude\":\"画面：地图上横着的一圈圈线，越往两极数字越大——latitude「纬度」。与赤道平行的横线角度；low latitudes 低纬（热），high latitudes 高纬（冷）。\",\n\"longitude\":\"画面：地图上竖着的线全部在两极收拢，像橘子瓣的棱——longitude「经度」。穿过格林尼治的本初子午线为 0°；和 latitude 一横一竖定位置。\",\n\"altitude\":\"画面：飞机爬升，仪表上的高度数字一路往上跳——altitude「海拔；高度」。alt-『高』（altar 高坛）：高出海平面的垂直距离；high altitude 高海拔。\",\n\"elevation\":\"画面：地图上这块高地被涂成深褐色，标着 3000 m——elevation「高程；海拔」。地势被『抬起』的高度；elevator 电梯也是把人抬起来的东西。\",\n\"peak\":\"画面：雪山最尖的那一点，登山者的旗子插在上面——peak「山峰」。一座山的最顶尖；peak season 旺季、peak hours 高峰时段都借了『到顶』的意思。\",\n\"ridge\":\"画面：连绵山顶连成一条起伏的脊线，像屋脊一样——ridge「山脊」。山顶那条长长的棱线；走山脊 ridge walk 是登山讲座里的常客画面。\",\n\"cliff\":\"画面：岩壁像被刀切一样直上直下，底下是海浪——cliff「悬崖」。陡峭的岩壁面；cliffhanger 悬念结尾，就是把人悬在崖边的意思。\",\n\"canyon\":\"画面：科罗拉多河在红岩里切出深深的沟，两壁陡立——canyon「峡谷」。河流在干旱区下切出的深谷；the Grand Canyon 大峡谷是它的代名词。\",\n\"valley\":\"画面：两山之间低下去的长带，河流在谷底拐弯，村庄沿河排开——valley「山谷」。低地长槽；Silicon Valley 硅谷就是借了谷地的名字。\",\n\"plateau\":\"画面：爬上高地后眼前忽然是一大片平地，边缘是陡坡——plateau「高原」。高而平；plateau 还作动词指增长后『进入平台期』，曲线走平了。\",\n\"plain\":\"画面：一眼望不到边的平地，草原和麦田铺到天边——plain「平原」。大片平坦开阔地；plain 还有『朴素的、清楚的』一义，都源于『平而一览无余』。\",\n\"basin\":\"画面：四周高、中间低，像一只大碗扣在地形上，河流往碗底汇——basin「盆地」。盆状低地；river basin 流域，洗脸盆也是 basin——形状说话。\",\n\"dune\":\"画面：风把沙子堆成一道弯弯的脊，背风面沙粒簌簌往下滑——dune「沙丘」。风成的沙丘；沙漠和海边都有，形状随风慢慢迁移。\",\n\"volcano\":\"画面：山口冒着烟，岩浆顺着坡面往下淌——volcano「火山」。会喷发的山；volcanic 火山的，active/dormant/extinct volcano 活/休眠/死火山是讲座三分类。\",\n\"eruption\":\"画面：火山口猛地炸开，火山灰柱冲上云层——eruption「喷发」。e- + rupt『断裂冲出』：憋不住地爆出来；volcanic eruption 火山喷发，皮疹爆发也用它。\",\n\"lava\":\"画面：红得发亮的熔流缓缓爬过地面，所到之处冒烟——lava「熔岩（地表）」。岩浆喷出地表后改名叫 lava；在地下时叫 magma，一出一名。\",\n\"magma\":\"画面：剖开地球，地壳之下橙红的黏稠岩浆在缓缓翻动——magma「岩浆（地下）」。地下的熔融岩石；它冷却成岩、喷出成 lava，是火山讲座的主角。\",\n\"crater\":\"画面：火山顶凹下去一个大碗，碗底还冒着气——crater「火山口」。crater 本是希腊人的『酒碗』：碗状凹口；月球上的环形山、陨石坑也叫 crater。\",\n\"earthquake\":\"画面：吊灯摇晃，桌上的杯子跳着移动，墙面裂开缝——earthquake「地震」。earth + quake（震动）：大地在抖；magnitude 震级，epicenter 震中是它的搭档词。\",\n\"seismic\":\"画面：地震仪的针尖剧烈摆动，纸带上画出锯齿波——seismic「地震的」。seism- 源于希腊『震动』：与地震有关的；seismic waves 地震波，seismic survey 地震勘探。\",\n\"fault\":\"画面：地层像被错开的书页，断面两侧上下错位——fault「断层」。岩层断裂错动的面，地震常沿它发生；fault 的日常义『过错』也是『裂了、错位了』的引申。\",\n\"crust\":\"画面：把地球比作苹果，地壳薄得像苹果皮——crust「地壳」。最外层薄壳；面包皮也叫 crust——都是『外面那层硬壳』。\",\n\"mantle\":\"画面：剖面图上地壳之下厚厚一层暗红色，包裹着地核——mantle「地幔」。mantle 本是『斗篷』：裹住地核的那一层；地壳—地幔—地核三层结构是考点。\",\n\"ore\":\"画面：矿工凿下一块闪着金属光泽的石头，里面嵌着铁——ore「矿石」。含金属、值得开采的天然矿物；iron ore 铁矿石，ore deposit 矿床。\",\n\"deposit\":\"画面：河水流速变慢，泥沙和金粒沉到河床上一层层积起来——deposit「矿床；沉积物」。de- + pos『放下』：被放下积起来的东西；银行存款也是『放下』的钱。\",\n\"sediment\":\"画面：浑浊河水静置一夜，杯底沉出一层泥沙——sediment「沉积物」。sed-『坐下』：沉下去坐底的固体颗粒；sedimentary rock 沉积岩由此层层压成。\",\n\"weathering\":\"画面：石碑上的字被风雨磨得越来越浅，岩面剥落——weathering「风化」。weather 作用在岩石上：风、雨、温差把岩石慢慢磨坏；和 erosion（侵蚀搬运）要分清。\",\n\"fossil\":\"画面：岩层里一条鱼的骨架印得清清楚楚，是亿万年前的它——fossil「化石」。foss-『挖』：从地里挖出的古代生物遗迹；fossil fuels 化石燃料（煤、石油）同源。\",\n\"amber\":\"画面：一块金黄透明的树脂里封着一只小昆虫，栩栩如生——amber「琥珀」。古代树脂化石；颜色 amber 是琥珀色，交通灯的黄灯也叫 amber。\",\n\"granite\":\"画面：厨房台面石纹里闪着黑白颗粒，硬得刀砍不动——granite「花岗岩」。gran-『颗粒』：颗粒结晶看得见的火成岩；坚硬耐久，常作建筑石材。\",\n\"marble\":\"画面：雕塑家在大理石上凿出衣褶，石面光滑发亮——marble「大理石」。变质岩、能抛光；米开朗基罗的大卫就是它；小时候玩的弹珠也叫 marble。\",\n\"limestone\":\"画面：白垩色的岩层里嵌着贝壳印，滴上盐酸冒气泡——limestone「石灰石」。主要由海洋生物遗骸沉积而成，含碳酸钙；烧制水泥、石灰的原料。\",\n\"sandstone\":\"画面：放大看，整块石头是沙粒被胶水似的物质黏在一起——sandstone「砂岩」。sand + stone：沙子压成的沉积岩；许多古建筑和峡谷岩壁都是它。\",\n\"slate\":\"画面：石匠一敲，岩块裂成一片片薄板，叠起来像瓦——slate「板岩」。能劈成薄片的变质岩；屋顶瓦、老式写字石板都是它，a clean slate 是『全新开始』。\",\n\"planet\":\"画面：八颗球沿着各自轨道绕着太阳转——planet「行星」。希腊语原义『漫游者』：在星空里会走动的天体；行星靠反射太阳光发亮，本身不发光。\",\n\"star\":\"画面：夜空中一颗亮点自己发着光，亿万年不熄——star「恒星」。能自行发光的天体，太阳就是最近的恒星；和 planet（行星）的区别就在发不发光。\",\n\"comet\":\"画面：一颗带长尾巴的亮点划过夜空，尾巴总背着太阳——comet「彗星」。希腊语『长发』：拖着尾巴的脏雪球天体；哈雷彗星 Halley’s Comet 76 年一回。\",\n\"asteroid\":\"画面：火星与木星之间漂着无数大小石块，缓缓绕日——asteroid「小行星」。aster（星）+ -oid（像…的）：像星的小岩石天体；asteroid belt 小行星带。\",\n\"meteor\":\"画面：一道亮线唰地划过夜空，一秒就灭——meteor「流星」。小天体冲进大气层摩擦燃烧的光迹；落地没烧完的叫陨石 meteorite，别混。\",\n\"eclipse\":\"画面：月亮慢慢挪到太阳前面，白天忽然暗下来——eclipse「日食；月食」。一个天体挡住另一个；solar eclipse 日食，lunar eclipse 月食，引申义是『使黯然失色』。\",\n\"lunar\":\"画面：带环形山的月面占满望远镜的视野——lunar「月亮的」。lun-『月』（luna 月亮女神）：与月有关的；lunar calendar 农历，lunar eclipse 月食。\",\n\"solar\":\"画面：屋顶的太阳能板正对正午的太阳发着电——solar「太阳的」。sol-『太阳』：与太阳有关的；solar system 太阳系，solar energy 太阳能，与 lunar 成对。\",\n\"telescope\":\"画面：他转动长筒，土星的光环一下子清晰起来——telescope「望远镜」。tele-（远）+ scope（看）：把远处拉近看的仪器；radio telescope 射电望远镜。\",\n\"astronaut\":\"画面：穿白色宇航服的人漂在空间站舱外，地球在脚下转——astronaut「宇航员」。astr（星）+ naut（航行者）：向星辰航行的人；中国航天员也称 taikonaut。\",\n\"gravity\":\"画面：苹果离开枝头直直往下掉，月亮却被地球拽着绕圈——gravity「引力」。grav-『重』：质量之间互相拉扯的力；地球引力把万物往地心拉，它还有『严肃』一义。\",\n\"axis\":\"画面：地球仪斜着穿过一根铁杆，球绕着它转——axis「轴；地轴」。旋转的中心线；地球的 axis 倾斜着，才有了四季。\",\n\"rotation\":\"画面：地球绕着自己的地轴转一圈，正好是一天——rotation「自转」。rot-『转』：绕自身轴转；地球自转 rotation 24 小时，公转 revolution 一年。\",\n\"revolution\":\"画面：地球拖着轨道绕太阳整整走一圈，四季轮换一遍——revolution「公转」。绕着别的中心转一整圈；它还有『革命』一义——都是『转了个大圈、局面全变』。\",\n\"phase\":\"画面：一个月里月亮从细钩变圆盘再变细钩——phase「月相；阶段」。月亮被照亮部分的形状变化；phase 更广义是任何循环的一个阶段。\",\n\"tide\":\"画面：海水白天涨上沙滩淹没礁石，夜里又退得老远——tide「潮汐」。月球引力拉起的海水周期涨落；high tide 涨潮，low tide 退潮，一天两次。\",\n\"current\":\"画面：地图上一条暖色箭头沿着海岸往北淌，是暖流的路线——current「洋流」。海水成带地定向流动；current 的电学义『电流』也是『流动』——水流、电流同源。\",\n\"wave\":\"画面：一排浪脊 rolling 向岸边，前一排碎成白沫，后一排又起——wave「波浪」。水面起伏推进的脊；光波、声波也叫 wave——都是起伏着传播。\",\n\"tsunami\":\"画面：海底地震后，海水整体涌起一道巨墙扑向海岸——tsunami「海啸」。日语『港湾波』：由海底地震或火山引发的破坏性巨浪，和普通风浪完全不是一回事。\",\n\"hurricane\":\"画面：卫星图上巨大的螺旋云团旋转着压向海岸——hurricane「飓风」。大西洋的强热带气旋；同样的东西在西太平洋叫 typhoon（台风），名字按海域分。\",\n\"typhoon\":\"画面：台风眼在卫星图上是个圆洞，周围云墙狂转——typhoon「台风」。西北太平洋的热带气旋；和 hurricane 是同一种天气，只是出生地不同。\",\n\"tornado\":\"画面：乌云底下垂下一个旋转的漏斗，触地处尘土横飞——tornado「龙卷风」。陆地上的猛烈旋风，范围小、破坏集中；俗称 twister，龙卷风走廊 Tornado Alley。\",\n\"monsoon\":\"画面：季节一到，风向整个翻转，暴雨连下三个月——monsoon「季风」。随季节反转的风系带来雨季；monsoon rains 季风雨，亚洲农业靠它吃饭。\",\n\"precipitation\":\"画面：气象图上雨、雪、冰雹被统统算作从天而降的水——precipitation「降水」。precip-『头朝下掉』：一切形式落下的水；年降水量 annual precipitation。\",\n\"rainfall\":\"画面：雨量筒里一年的水柱刻度，就是这个地方的雨量——rainfall「降雨量」。落雨的量；heavy rainfall 强降雨，和 precipitation 比，它专指雨这一种。\",\n\"snowfall\":\"画面：一夜过后，篱笆上积起一掌厚的雪——snowfall「降雪量」。飘雪的量；气象播报里的 snowfall amounts 就是各地的积雪数字。\",\n\"frost\":\"画面：清晨草叶和窗玻璃上结了一层白花花的冰晶——frost「霜」。水汽在 0℃ 以下表面直接凝华的冰晶；frostbite 冻伤，frosty 结霜的。\",\n\"fog\":\"画面：大雾里十米外的楼只剩影子，车灯晕成一团——fog「雾」。悬浮在近地面的小水滴，比 mist 浓得多；foggy 多雾的，伦敦的雾都名声来自它。\",\n\"mist\":\"画面：山间飘着一层薄纱似的水汽，远山若隐若现——mist「薄雾」。比 fog 稀薄的轻雾；清晨湖面的 mist 最典型，能见度比雾天好得多。\",\n\"dew\":\"画面：天亮时草尖挂满小水珠，鞋尖走过去全湿了——dew「露水」。夜里水汽在凉表面凝结的水珠；morning dew 朝露，它不是从天上落的，是就地凝出来的。\",\n\"hail\":\"画面：冰粒噼里啪啦砸在车顶上，有的弹起老高——hail「冰雹」。强对流里冻成的冰球降水；hail 还可作动词『招呼、欢呼』，靠语境分。\",\n\"thunder\":\"画面：闪电过后几秒，低沉的轰隆声滚过天空——thunder「雷；雷声」。放电引起的轰鸣；先见闪电后闻雷，是估算雷暴距离的经典办法。\",\n\"lightning\":\"画面：一道锯齿状的白光劈开夜空，瞬间照亮云层——lightning「闪电」。云层放电的光；lightning strike 雷击，as fast as lightning 快如闪电。\",\n\"rainbow\":\"画面：雨刚停太阳出来，天边架起一道七色弧——rainbow「彩虹」。阳光被雨滴折射色散成的弧；虹的尽头有金罐是传说，物理上它只是光谱展开。\",\n\"breeze\":\"画面：窗帘被轻轻托起，树叶微微晃动，皮肤感到凉意——breeze「微风」。轻柔的小风；sea breeze 海风，a gentle breeze，比 gust、storm 都温和。\",\n\"gust\":\"画面：行人忽然被一阵风推得踉跄，帽子被掀飞——gust「阵风」。短促猛烈的风；a gust of wind 一阵狂风，风速表上跳起的尖峰就是它。\",\n\"storm\":\"画面：狂风卷着暴雨，闪电雷声一起压下来——storm「暴风雨」。强风加降水的恶劣天气总称；thunderstorm 雷暴，storm surge 风暴潮。\",\n\"blizzard\":\"画面：大雪被狂风卷成白幕，能见度不足一臂——blizzard「暴风雪」。强风加大量降雪的极端天气；出行禁令常因它发布，和普通 snowfall 不是一个量级。\",\n\"avalanche\":\"画面：山腰的积雪整块崩塌，轰鸣着滚下山坡越滚越大——avalanche「雪崩」。大量雪体顺坡奔泻；引申为『蜂拥而至』：an avalanche of emails。\",\n\"landslide\":\"画面：雨后山体一侧整片土石滑下来，埋住了山路——landslide「山体滑坡」。土石整体下滑；选举里 landslide victory 压倒性胜利，借的是『势不可挡』。\",\n\"terrain\":\"画面：军事地图上山地、沼泽、平原用不同符号标着——terrain「地形」。一块地面的具体特征；rough terrain 崎岖地形，all-terrain vehicle 全地形车。\",\n\"landscape\":\"画面：站在高处望去，山、河、田、村一整幅铺开——landscape「地貌；景观」。一眼所见的整片景色地貌；landscape painting 风景画，园林美化也叫 landscaping。\",\n\"zenith\":\"画面：正午太阳爬到头顶正上方，影子缩到脚底——zenith「天顶」。观察者正上方的天球点；引申为巅峰：the zenith of his career 事业巅峰。\",\n\"meridian\":\"画面：地球仪上一条竖圈穿过南北极和格林尼治——meridian「子午线」。连接两极的大圆线，即经线；prime meridian 本初子午线是 0°经线。\",\n\"tropic\":\"画面：地图上赤道两侧各有一条虚线，圈住终年炎热的地带——tropic「热带」。南北回归线之间的地带；tropical 热带的，tropical rainforest 热带雨林。\",\n\"temperate\":\"画面：四季分明、冬不酷冷夏不酷热的地带，种着麦田果园——temperate「温带的」。气候温和不走极端；temperate zone 温带，和 tropical、arctic 三分天下。\",\n\"arctic\":\"画面：北极圈内极夜漫长，海面结冰，白熊在浮冰上走——arctic「北极的」。地球最北的极区；the Arctic 北极地区，Arctic Ocean 北冰洋，首字母常大写。\",\n\"antarctic\":\"画面：南极大陆被厚冰盖压着，企鹅在海岸列队——antarctic「南极的」。地球最南端；Antarctica 南极洲，是大陆；Arctic 则是海洋——南北极正相反。\",\n\"aurora\":\"画面：极地夜空里绿紫色的光带像窗帘一样舞动——aurora「极光」。太阳带电粒子撞进大气发的光；北极光 aurora borealis，南极光 aurora australis。\",\n\"constellation\":\"画面：猎户座的星被线连起来，像举着盾的猎人——constellation「星座」。人们把亮星连成的图案区域；88 个官方星座，猎户 Orion、大熊 Ursa Major 最有名。\",\n\"galaxy\":\"画面：旋涡状的星盘缓缓旋转，里面挤着千亿颗恒星——galaxy「星系」。恒星的大集团；我们所在的叫 the Milky Way 银河系，galaxy 一词源于希腊『乳汁』。\",\n\"nebula\":\"画面：望远镜里一团彩色云雾，里面正有恒星诞生——nebula「星云」。气体和尘埃组成的云雾状天体；恒星的育婴室，猎户座大星云最著名。\",\n\"satellite\":\"画面：一颗人造卫星展开太阳能板，绕着地球一圈圈转——satellite「卫星」。绕行星运行的天体：月亮是天然卫星，通信卫星是人造的；satellite TV 卫星电视。\",\n\"crustal\":\"画面：剖面图上最薄的那层被标红，注释写着地壳运动——crustal「地壳的」。crust（地壳）的形容词；crustal movement 地壳运动，crustal plate 地壳板块。\",\n\"tectonic\":\"画面：两块大陆板块缓缓相撞，边缘隆起成山脉——tectonic「构造的；板块的」。地壳结构与运动的；plate tectonics 板块构造学说，地震火山分布靠它解释。\",\n\"drift\":\"画面：一块浮木顺着水流慢慢漂离岸边，越漂越远——drift「漂移」。缓慢无定向地移动；continental drift 大陆漂移，snowdrift 是被风吹堆的雪堆。\",\n\"atom\":\"画面：一个小球中心是核，外面电子绕着转——atom「原子」。希腊语『不可再分』：保持元素性质的最小单位；atomic 原子的，atom bomb 原子弹。\",\n\"molecule\":\"画面：两个氢原子牵着一个氧原子，就是一个水分子——molecule「分子」。保持物质性质的最小微粒，由原子组合；molecular 分子的，molecular biology 分子生物学。\",\n\"nucleus\":\"画面：原子正中央那颗致密的核，几乎占了全部质量——nucleus「原子核」。nucle-『小核桃』：原子和细胞都有个『核』；细胞核 nucleus 决定遗传。\",\n\"electron\":\"画面：带负电的小粒子在核外轨道上飞速绕行——electron「电子」。电荷为负的基本粒子；electronic 电子的，电流就是电子的定向移动。\",\n\"proton\":\"画面：原子核里带正电的粒子，数目决定了这是哪种元素——proton「质子」。质子数 = 原子序数；proton 的电量与 electron 相等、符号相反。\",\n\"neutron\":\"画面：核里和质子挤在一起、却不带电的粒子——neutron「中子」。neutr-『中性的』：电中性的核内粒子；中子数不同就成同位素 isotope。\",\n\"ion\":\"画面：一个原子丢掉电子，头上顶着一个『+』号——ion「离子」。带电的原子或原子团；positive ion 阳离子，negative ion 阴离子，电池靠离子搬运电荷。\",\n\"isotope\":\"画面：同一种元素的两个原子，质子数一样、中子数差一个——isotope「同位素」。iso-（相同）+ tope（位置）：在元素周期表占同一格；碳-14 测年用的就是它。\",\n\"compound\":\"画面：氢和氧按 2:1 化合，变成性质全新的水——compound「化合物」。两种以上元素按固定比例化合的纯净物；和 mixture（混合物）相对，后者比例不定、无新物质。\",\n\"mixture\":\"画面：沙子和铁屑倒在一起搅匀，还能用磁铁分开——mixture「混合物」。只是物理混合、没有化学键；各成分保持原性，用过滤、蒸馏就能分开。\",\n\"solution\":\"画面：糖倒进水里搅一搅，消失得无影无踪，整杯均匀透明——solution「溶液」。溶质均匀分散在溶剂里；solution 还有『解答』义——把问题『化开』也是它。\",\n\"solvent\":\"画面：油漆被香蕉水一擦就化开溶解——solvent「溶剂」。能溶解其他物质的液体，通常是溶液里量多的那个；水是万能溶剂 universal solvent。\",\n\"solute\":\"画面：一勺盐在水里消失，它就是被溶掉的那个——solute「溶质」。溶液中被溶解的成分，量相对少；solute + solvent = solution，一对搭档词。\",\n\"acid\":\"画面：柠檬汁滴到石蕊试纸上，试纸变红，舌头一尝发酸——acid「酸」。水溶液能电离出 H⁺、使石蕊变红；acid rain 酸雨，胃酸 stomach acid。\",\n\"base\":\"画面：肥皂水摸着滑溜溜的，滴上酚酞变粉红——base「碱」。能中和酸、使石蕊变蓝的物质是碱（base 在化学里作碱）；acid + base → salt + water 是招牌反应。\",\n\"alkaline\":\"画面：pH 试纸比色卡显示 9，颜色偏蓝紫——alkaline「碱性的」。pH 大于 7 的性质；alkaline batteries 碱性电池，土壤 alkaline 对作物是大事。\",\n\"neutral\":\"画面：酸碱正好抵消，pH 停在 7，试纸不变色——neutral「中性的」。既不酸也不碱；neutral 的日常义『中立』也是『不偏向任何一边』。\",\n\"oxide\":\"画面：铁钉在潮湿空气里生出一层红锈——oxide「氧化物」。氧与另一元素化合的产物；iron oxide 氧化铁（铁锈主成分），carbon dioxide 里 dioxide 是二氧化物。\",\n\"sulfate\":\"画面：石膏和芒硝都带着 SO₄²⁻ 的标签——sulfate「硫酸盐」。含硫酸根的盐；copper sulfate 硫酸铜是蓝色晶体，农药波尔多液的主角。\",\n\"nitrate\":\"画面：化肥袋上标着高氮含量，硝酸盐为庄稼供氮——nitrate「硝酸盐」。含 NO₃⁻ 的盐；硝酸盐既是肥料，过量流入水体又会造成污染。\",\n\"chloride\":\"画面：食盐就是最常见的氯化物，晶体里 Na⁺ 和 Cl⁻ 整齐排队——chloride「氯化物」。含氯离子的化合物；sodium chloride 氯化钠 = 食盐本身。\",\n\"sodium\":\"画面：一小块银白金属丢进水里，滋滋作响还冒火花——sodium「钠」。符号 Na，活泼的碱金属；人体靠 sodium 维持体液平衡，食盐的钠是摄入大头。\",\n\"potassium\":\"画面：香蕉和土豆都富含这种元素，缺了它肌肉会乏力——potassium「钾」。符号 K，植物生长三大元素之一（氮磷钾）；potassium 在神经传导中也关键。\",\n\"iron\":\"画面：烧红的铁块在铁砧上被锤打成型——iron「铁」。符号 Fe，最常用的金属；体内 iron 帮血红蛋白运氧，缺铁会贫血；iron 还是熨斗——都要加热。\",\n\"copper\":\"画面：电线芯是紫红色的金属，导电发亮——copper「铜」。符号 Cu，导电性极佳的红金属；铜像氧化变绿（铜绿），老电线、硬币都是它。\",\n\"zinc\":\"画面：铁皮表面镀了一层蓝白金属，防锈靠它——zinc「锌」。符号 Zn，镀锌防锈是它的主业；人体缺 zinc 影响免疫和味觉，干电池里也有它。\",\n\"aluminum\":\"画面：飞机蒙皮银白轻盈，捏易拉罐薄而轻——aluminum「铝」。符号 Al，地壳里最多的金属，轻且耐腐蚀；美式 spelling 是 aluminum，英式 aluminium。\",\n\"lead\":\"画面：沉甸甸的灰色金属块，软到能用指甲划出痕——lead「铅」。符号 Pb，有毒的重金属；铅笔芯其实是石墨不是铅——名字是历史误会，别被带偏。\",\n\"tin\":\"画面：罐头盒的马口铁亮闪闪，焊点也是软软的银白金属——tin「锡」。符号 Sn，抗腐蚀，常镀在铁罐内壁；锡焊 soldering、锡纸都靠它。\",\n\"mercury\":\"画面：温度计摔碎，银亮的液珠在地上滚来滚去——mercury「汞」。符号 Hg，常温下唯一的液态金属，有毒；Mercury 还是水星——都『跑得快』（罗马信使神）。\",\n\"gold\":\"画面：金条在灯下发出沉甸甸的黄色光泽——gold「金」。符号 Au，贵金属之王，不生锈；gold medal 金牌，gold rush 淘金热，golden 金色的。\",\n\"silver\":\"画面：银镯子擦一擦就亮，月光一样的灰白色——silver「银」。符号 Ag，自古的贵金属；silver medal 银牌总排第二，silver lining 是乌云的银边=逆境中的希望。\",\n\"hydrogen\":\"画面：气球灌满这种最轻的气体，一松手就往上窜——hydrogen「氢」。符号 H，最轻、最多的元素；hydro-（水）+ gen（产生）：燃烧能生成水，氢能 hydrogen energy。\",\n\"nitrogen\":\"画面：空气里七成八是这种无色无味气体，植物却直接吸不了——nitrogen「氮」。符号 N₂，极稳定；要靠固氮变成氮肥，nitrogen cycle 氮循环是生态考点。\",\n\"helium\":\"画面：氦气球比氢气球还稳，不会燃烧，声音吸了会变尖——helium「氦」。符号 He，惰性气体，化学性质极稳；heli- 源于希腊太阳神，最早在太阳光谱里发现它。\",\n\"silicon\":\"画面：沙子和石英的主要成分，做成芯片就是计算机的大脑——silicon「硅」。符号 Si，地壳第二多的元素、半导体之王；Silicon Valley 硅谷因它得名，和 silicone（硅胶）别混。\",\n\"sulfur\":\"画面：火山泉边结着一层黄色粉末，闻着有臭鸡蛋味——sulfur「硫」。符号 S，黄色非金属；sulfur dioxide 二氧化硫是酸雨元凶之一，硫磺自古用于火药。\",\n\"phosphorus\":\"画面：火柴头和骨骼牙齿里都有它，暗处能微微发光——phosphorus「磷」。符号 P，phosphor-『带光者』：白磷在暗处发磷光；植物三大元素氮磷钾之一。\",\n\"iodine\":\"画面：碘酒涂在皮肤上是棕黄色的，海带里也含它——iodine「碘」。符号 I，甲状腺必需元素，缺碘会大脖子病；iodized salt 加碘盐就是补它的。\",\n\"bromine\":\"画面：棕红色的液体在瓶子里冒着呛人的烟——bromine「溴」。符号 Br，常温下呈液态的非金属（只有它和汞）；brom- 源于希腊『恶臭』，名副其实。\",\n\"reaction\":\"画面：两种试剂一混合，试管里冒泡变色还发烫——reaction「化学反应」。物质变成新物质的过程；chain reaction 链式反应，reaction rate 反应速率。\",\n\"catalyst\":\"画面：加了一勺粉末后反应猛地加速，粉末本身却一点没少——catalyst「催化剂」。改变化学反应速率而自身不被消耗；酶 enzyme 就是生物体内的催化剂。\",\n\"oxidation\":\"画面：切开的苹果放一会儿，果肉变成褐色——oxidation「氧化」。物质得氧或失电子的过程；生锈、呼吸、燃烧都是它，和 reduction（还原）永远成对出现。\",\n\"reduction\":\"画面：炼铁炉里氧化铁被一氧化碳夺走氧，变成铁——reduction「还原」。物质失氧或得电子；reduction 日常义『减少』和化学义同源——都是『往回拿』。\",\n\"combustion\":\"画面：蜡烛在氧气里猛烈燃烧，发出光和热——combustion「燃烧」。物质与氧气反应放热发光；发动机 internal combustion engine 内燃机就是靠它驱动。\",\n\"evaporation\":\"画面：晾着的湿衣服水汽悄悄散走，衣服变干——evaporation「蒸发」。液体表面分子逸出成气体，要吸热；蒸发是水循环和人体散热的关键一环。\",\n\"condensation\":\"画面：冰镇饮料瓶外壁挂满水珠——condensation「凝结」。气体遇冷变回液体；水汽凝结成云、露、雾都是它，和 evaporation 正好一来一回。\",\n\"fusion\":\"画面：太阳核心里氢核被压到一起合成氦，放出巨大能量——fusion「熔合；核聚变」。轻核合成重核；fusion 还有『熔化、融合』义，都是『合到一起』。\",\n\"fission\":\"画面：一个重原子核被中子撞开，裂成两半并放出能量——fission「裂变」。重核分裂；原子弹和核电站靠它，与 fusion（聚变）方向相反，考试最爱对比。\",\n\"radiation\":\"画面：放射源符号像风扇叶片，射线从中心向外散出——radiation「辐射」。能量以波或粒子形式传播；核辐射、太阳辐射都用它，radiation therapy 放疗。\",\n\"radioactive\":\"画面：标着黄黑放射符号的金属罐，仪器靠近就滴滴响——radioactive「放射性的」。原子核不稳定、自发放射线的性质；radioactive decay 放射性衰变。\",\n\"wavelength\":\"画面：波浪线上两个相邻波峰之间的距离被尺子量出——wavelength「波长」。相邻两峰的间距；波长越短频率越高，红光长、紫光短，光谱按它排队。\",\n\"amplitude\":\"画面：波形图上波峰离中线最高的那一段被标出——amplitude「振幅」。振动偏离平衡的最大距离；声音振幅大 = 响，地震振幅大 = 震级高。\",\n\"resonance\":\"画面：唱歌的声音震碎了酒杯——频率对上了——resonance「共振」。外力频率与固有频率对上时振幅猛增；音箱共鸣、桥梁共振都是它。\",\n\"refraction\":\"画面：筷子插进水里，看起来在水面处折断了——refraction「折射」。光进入新介质时方向偏折；彩虹、透镜、海市蜃楼都是折射的作品。\",\n\"reflection\":\"画面：平静湖面像镜子，山影一毫不差地映在水里——reflection「反射」。光在界面上返回；reflection 也是镜中『影像』和『反思』——都是『折回来』。\",\n\"lens\":\"画面：放大镜把阳光聚成一个点，纸被烧出洞——lens「透镜」。能聚光或散光的透明器件；眼球里的晶状体也叫 lens，隐形眼镜 contact lens。\",\n\"prism\":\"画面：一束白光穿过三棱镜，散开成一条彩虹带——prism「棱镜」。透明多面体，牛顿用它分解出光谱；prism 的画面就是白光变彩虹。\",\n\"spectrum\":\"画面：棱镜后展开一条从红到紫的色带——spectrum「光谱」。按波长排开的连续带；spectrum 引申为『范围』：a broad spectrum of opinions 各种意见。\",\n\"circuit\":\"画面：电池、导线、灯泡接成一个闭合的圈，灯亮了——circuit「电路」。电流必须走通的回路；断开一处全灭，circuit breaker 断路器由此得名。\",\n\"voltage\":\"画面：电池上标着 1.5 V，像水压一样推着电流走——voltage「电压」。驱动电流的『电势差』，单位 volt 伏特；high voltage 高压电有触电危险。\",\n\"resistance\":\"画面：细导线里的电流被挤得费劲，像水流过窄管——resistance「电阻」。导体阻碍电流的程度，单位 ohm；resistance 还有『抵抗力、反抗』义，都是『顶着不让过』。\",\n\"conductor\":\"画面：铜线一接上，电流顺畅跑过，灯泡大亮——conductor「导体」。善于传导电或热的物质，金属是典型；乐队指挥也叫 conductor——都是『引导通过』。\",\n\"insulator\":\"画面：电线外面包着橡胶皮，手摸上去不触电——insulator「绝缘体」。几乎不导电、不导热的材料，玻璃、橡胶、陶瓷都是；insulate 是动词『使绝缘、隔离』。\",\n\"semiconductor\":\"画面：硅片做成的芯片，导电能力可被精确调控——semiconductor「半导体」。导电性介于导体与绝缘体之间，可控是关键；semiconductor industry 半导体产业。\",\n\"battery\":\"画面：两节电池装进遥控器，电视就能换台了——battery「电池」。把化学能变电能的装置；battery 的另一义是『炮兵连、一系列』，靠语境分。\",\n\"generator\":\"画面：水电站里水流冲击，机器旋转着发出电来——generator「发电机」。把机械能变电能；和 motor（电动机）正相反：一个发电、一个用电转。\",\n\"motor\":\"画面：通电后小风扇的叶片立刻转起来——motor「电动机」。把电能变成机械运动；motor car 汽车、motorcycle 摩托都源于『会动的机器』。\",\n\"turbine\":\"画面：蒸汽猛吹叶轮，轴飞快旋转带动发电机——turbine「涡轮机」。流体推动带叶片的转子；wind turbine 风力发电机，gas turbine 燃气轮机。\",\n\"lever\":\"画面：一根硬杆架在石头上，他一压长端，大石头被撬起——lever「杠杆」。绕支点转动的硬杆，省力神器；阿基米德『给我支点，我能撬动地球』说的就是它。\",\n\"pulley\":\"画面：绳子绕过高处滑轮，他往下拉，货物往上升——pulley「滑轮」。带槽的轮子改变力的方向；定滑轮省不了力但顺手，滑轮组才省力。\",\n\"gear\":\"画面：两个带齿的轮子咬合着转，一个快一个慢——gear「齿轮」。靠齿啮合传动的零件；汽车的『挡位』也叫 gear，换挡就是换齿轮组合。\",\n\"piston\":\"画面：气缸里的活塞被燃气推着上下往复，带动车轮——piston「活塞」。在缸内往复运动的塞子；发动机、蒸汽机、水泵的心脏部件。\",\n\"spring\":\"画面：弹簧被压扁，一松手立刻弹回原样——spring「弹簧」。能储存弹性势能的金属器件；spring 还有『春天、泉水』义——都有『跳出来』的劲。\",\n\"pendulum\":\"画面：大摆锤在最低点来回摆，周期纹丝不变——pendulum「摆；钟摆」。悬挂着自由摆动的重物；摆钟靠它计时，周期只跟摆长有关。\",\n\"momentum\":\"画面：满载的大货车刹车距离很长——速度同等下它更难停——momentum「动量」。质量 × 速度，衡量运动的『分量』；momentum 也比喻势头：gain momentum 声势渐长。\",\n\"inertia\":\"画面：公交车猛起步，站着的人齐刷刷往后仰——inertia「惯性」。物体保持原运动状态的脾气；牛顿第一定律又叫惯性定律，inertia 也引申为『惰性、迟钝』。\",\n\"acceleration\":\"画面：跑车起步，速度表指针飞快往上扫——acceleration「加速度」。速度变化的快慢，单位 m/s²；accelerate 是动词『加速』，油门叫 accelerator。\",\n\"deceleration\":\"画面：列车进站前速度表一路回落，车身轻轻前倾——deceleration「减速」。速度减小，也就是加速度为负；decelerate 减速，和 acceleration 正相对。\",\n\"centrifugal\":\"画面：洗衣机脱水时水被甩向滚筒壁，衣服贴在边上——centrifugal「离心的」。centri（中心）+ fug（逃）：往远离中心的方向跑；centrifugal force 离心力。\",\n\"elastic\":\"画面：橡皮筋拉长一倍，松手啪地缩回去——elastic「有弹性的」。受力变形、撤力复原；elastic band 橡皮筋，elastic 还比喻『灵活可伸缩的』安排。\",\n\"rigid\":\"画面：一根钢尺怎么掰都不弯，硬邦邦的——rigid「刚性的；僵硬的」。不易变形的；rigid rules 死板的规定，rigid 和 flexible（灵活的）是一对反义。\",\n\"malleable\":\"画面：金匠把金片反复捶打，延展成薄薄的金箔——malleable「可锻的；可塑的」。能锤打延展而不裂，金属的延展性；性格 malleable 是『易受影响、可塑造』。\",\n\"viscosity\":\"画面：蜂蜜倒出来拉成长丝慢慢流，机油比水稠得多——viscosity「黏度」。液体内部阻碍流动的程度；viscous 黏稠的，血液黏度是医学指标。\",\n\"buoyancy\":\"画面：木块按进水里一松手，立刻浮回水面——buoyancy「浮力」。液体向上托的力，等于排开液体的重量；buoyant 漂浮的，也比喻心情『轻快上扬』。\",\n\"pressure\":\"画面：潜得越深，耳膜被压得越疼——pressure「压力」。单位面积上的力，单位 pascal；pressure 的日常义『精神压力』也是被『压』着的感觉。\",\n\"vacuum\":\"画面：抽掉空气的瓶子里，羽毛和铁球同时落地——vacuum「真空」。没有物质的空间；vacuum cleaner 真空吸尘器靠负压吸灰，nature abhors a vacuum 自然厌恶真空。\",\n\"vector\":\"画面：黑板上画着一条带箭头的线段，长短和方向都标着——vector「矢量」。既有大小又有方向的量，力、速度都是；和 scalar（只有大小）成对出现。\",\n\"scalar\":\"画面：温度计上只有数字 25，没有箭头——方向无从谈起——scalar「标量」。只有大小、没有方向的量：质量、温度、时间；scalar 的画面就是纯数字。\",\n\"quantum\":\"画面：能量不是流水而是一份份小包裹，一份就是最小单位——quantum「量子」。物理量最小的离散单位；quantum mechanics 量子力学，quantum leap 量子跃迁→巨大飞跃。\",\n\"relativity\":\"画面：高速列车上的人看站台钟变慢——快慢取决于参照系——relativity「相对论」。爱因斯坦的理论：时空相对而非绝对；relative 亲戚、相对的同源。\",\n\"thermometer\":\"画面：细管里的红液柱随温度升降，旁边刻着刻度——thermometer「温度计」。测温仪器，therm（热）+ meter（测）：测热的尺子；thermostat 恒温器是亲戚。\",\n\"calorie\":\"画面：让 1 克水升温 1℃ 所需的那一小份热量——calorie「卡路里」。热量单位；食物热量常说的大卡是 kilocalorie，calorie counting 数卡路里减肥。\",\n\"kilogram\":\"画面：天平一端放着标准砝码，一千克整——kilogram「千克」。kilo-（千）+ gram（克）：1000 克，国际质量基本单位；缩写 kg。\",\n\"meter\":\"画面：一把标准尺的长度，就是它——meter「米」。国际长度基本单位，约 1.09 码；meter 还有『仪表』义（测量的器），词根都是『测』。\",\n\"liter\":\"画面：一瓶矿泉水标着 1 L，恰好装满量杯——liter「升」。容积单位，等于 1000 立方厘米；英式 litre，美式 liter，缩写 L。\",\n\"watt\":\"画面：灯泡上印着 60 W，亮度与耗电一目了然——watt「瓦特」。功率单位，纪念蒸汽机改良者瓦特；1 W = 1 焦耳/秒，电费按 kilowatt-hour（度）算。\",\n\"joule\":\"画面：把 1 牛的力推着物体走 1 米，做功就是它——joule「焦耳」。能量与功的单位，纪念物理学家焦耳；热量、功、电能都用它统一计量。\",\n\"newton\":\"画面：让 1 千克物体获得 1 m/s² 加速度的力——newton「牛顿（单位）」。力的单位，纪念牛顿本人；符号 N，苹果落地的故事和他绑在一起。\",\n\"hertz\":\"画面：波形一秒内重复一次，就是 1 Hz——hertz「赫兹」。频率单位，纪念物理学家赫兹；CPU 的 GHz、广播的 MHz 都用它，数字越大振动越快。\",\n\"ampere\":\"画面：电流表指针指向 1，导线里每秒流过的电量是标准量——ampere「安培」。电流单位，纪念安培；缩写 A，电压 volt、电阻 ohm 与它组成欧姆定律三角。\",\n\"volt\":\"画面：干电池标着 1.5 V，电路里的『推力』就是这么大——volt「伏特」。电压单位，纪念伏特（发明电池）；high voltage 高压，voltage 就是电的『水压』。\",\n\"ohm\":\"画面：电阻器上色环算出的阻值，单位就是它——ohm「欧姆」。电阻单位，符号 Ω，纪念物理学家欧姆；V = I × R 里的 R 就用 ohm 衡量。\",\n\"alloy\":\"画面：铁里掺进碳和铬，熔成一炉不锈钢——alloy「合金」。两种以上金属（或金属与非金属）熔合的材料；钢、青铜、黄铜都是合金，性能胜过单一金属。\",\n\"steel\":\"画面：钢梁吊上高楼骨架，坚硬又韧——steel「钢」。铁碳合金，建筑与工具之王；stainless steel 不锈钢，steel 还有『钢铁般的意志』比喻义。\",\n\"bronze\":\"画面：博物馆里青绿锈迹的古代鼎，沉稳庄重——bronze「青铜」。铜锡合金，人类最早的合金之一；Bronze Age 青铜时代，bronze medal 铜牌排第三。\",\n\"brass\":\"画面：小号在灯下闪着金黄的光，擦得锃亮——brass「黄铜」。铜锌合金，色泽金黄；管乐器、门把手爱用它，brass 和 bronze 一黄一青别混。\",\n\"ceramic\":\"画面：陶土在转盘上成型，进窑烧后变得坚硬光滑——ceramic「陶瓷」。无机非金属材料高温烧制；ceramics 陶瓷制品，绝缘、耐热是它的强项。\",\n\"polymer\":\"画面：许多小珠子串成一条长链，链越长材料越韧——polymer「聚合物」。小分子（单体）重复连接成的大分子；塑料、橡胶、DNA 都是 polymer。\",\n\"plastic\":\"画面：加热后软软的材料被压进模具，冷却成各种形状——plastic「塑料」。可塑成型的合成材料；plastic 本义『可塑的』，塑料只是它最出名的产品。\",\n\"fiber\":\"画面：拉出一根细长的丝，纺成线再织成布——fiber「纤维」。细长可纺的物质；optical fiber 光纤传信号，dietary fiber 膳食纤维助消化。\",\n\"synthetic\":\"画面：实验室里用石油原料人工合成出自然界没有的新材料——synthetic「合成的」。人工化学合成的；synthetic fiber 合成纤维，与 natural（天然的）相对。\",\n\"organic\":\"画面：标着碳骨架的分子式，来自生物体或含碳化合物——organic「有机的」。化学里指含碳化合物；organic food 有机食品借的是『天然生长』那层意思。\",\n\"inorganic\":\"画面：食盐、水、金属矿石——不含碳骨架的物质摆成一排——inorganic「无机的」。不含碳（少数除外）的化合物世界；inorganic chemistry 无机化学与 organic 相对。\",\n\"symptom\":\"画面：病人指着额头说发烧、嗓子疼——这些都是身体发出的信号——symptom「症状」。患者能感受到的异常表现；医生靠 symptom 追 diagnosis（诊断），sign 是医生查出的体征。\",\n\"diagnosis\":\"画面：医生看完化验单，在病历上写下病名——diagnosis「诊断」。dia-（贯穿）+ gnosis（知道）：看透病情下结论；diagnose 是动词，误诊 misdiagnosis。\",\n\"therapy\":\"画面：治疗师带着病人一步步做康复训练——therapy「疗法」。不特指药物的治疗总称；physical therapy 物理治疗，chemotherapy 化疗，therapist 治疗师。\",\n\"treatment\":\"画面：从吃药、输液到复查，一整套方案写在医嘱上——treatment「治疗」。对病人的处置全过程；under treatment 在治疗中，treatment 还可指『对待方式』。\",\n\"cure\":\"画面：疗程结束，复查指标全部正常，医生说：好了——cure「治愈」。让病彻底好；cure 还作名词『疗法、解药』：a cure for cancer 治癌的方法。\",\n\"remedy\":\"画面：药柜里一瓶止咳糖浆，标签写着见效快——remedy「药物；疗法」。缓解或治病的药/办法；home remedy 家庭偏方，remedy 还引申为『补救措施』。\",\n\"vaccine\":\"画面：护士把一针疫苗打进胳膊，免疫系统开始练兵——vaccine「疫苗」。用减毒/灭活病原训练免疫；vaccinate 接种，vaccination 疫苗接种。\",\n\"antibiotic\":\"画面：青霉素一到，细菌成片倒下——antibiotic「抗生素」。专杀细菌的药物，对病毒无效；滥用会养出耐药菌，antibiotic resistance 是全球议题。\",\n\"antibody\":\"画面：Y 形的蛋白质精准抱住病毒表面的刺突，把它锁死——antibody「抗体」。免疫系统针对 antigen 造的专属武器；测 antibody 就能知道感染过没有。\",\n\"antigen\":\"画面：病毒表面的刺突蛋白就是被免疫系统通缉的『面孔』——antigen「抗原」。能触发免疫反应的物质；antigen test 抗原检测就是抓这张『脸』。\",\n\"virus\":\"画面：一个带刺突的小颗粒钻进细胞，借细胞的机器复制自己——virus「病毒」。没有细胞结构、只能寄生复制；computer virus 电脑病毒借了同样的传播逻辑。\",\n\"bacterium\":\"画面：显微镜下一根杆状小体自己分裂成两个——bacterium「细菌」。单细胞微生物，有好有坏；复数 bacteria，肠道菌群、致病菌都是它。\",\n\"infection\":\"画面：伤口没处理好，又红又肿——病原体在里面繁殖——infection「感染」。病原体入侵并增殖；infect 是动词，infectious 传染性的。\",\n\"inflammation\":\"画面：崴脚处又红又肿又热又痛，四件套齐了——inflammation「炎症」。身体对损伤/感染的防御反应：红肿热痛；anti-inflammatory 消炎的。\",\n\"fever\":\"画面：体温计升到 39℃，额头烫手，盖着被子还发抖——fever「发烧」。体温升高的症状，常是感染信号；have a fever 发烧，fever 作为动词少用。\",\n\"chill\":\"画面：发烧前先一阵恶寒，牙关打颤裹紧被子——chill「寒战」。感染起病时的发冷颤抖；chill 的日常义是『寒意、使冷却』——冻得发抖是同一感觉。\",\n\"cough\":\"画面：气道受刺激，他猛地咳出声，捂着胸口——cough「咳嗽」。肺里空气爆发性排出清道；dry cough 干咳，cough medicine 止咳药，咳嗽既是症状也是反射。\",\n\"sneeze\":\"画面：鼻子一痒，阿嚏——飞沫喷出老远——sneeze「喷嚏」。鼻黏膜受刺激的反射；sneeze 是疾病传播名场面，cover your sneeze 捂住喷嚏是卫生课重点。\",\n\"headache\":\"画面：他揉着太阳穴，眉头拧成一团，眼前发胀——headache「头痛」。头部疼痛；headache 还比喻『头疼的事』：a real headache 棘手难题。\",\n\"nausea\":\"画面：胃里翻江倒海，一阵阵想吐，脸色发白——nausea「恶心」。呕吐前的不适感；nauseous 作呕的，晕车晕船、化疗、孕吐都伴它出现。\",\n\"dizzy\":\"画面：站起来太猛，眼前发黑天旋地转，赶紧扶墙——dizzy「头晕的」。感觉旋转、站不稳；dizziness 头晕（名词），高空画面也常用 dizzy heights 令人眩晕的高度。\",\n\"fatigue\":\"画面：连轴工作后他瘫在椅子上，眼皮都抬不动——fatigue「疲劳」。身心耗竭的乏力感；chronic fatigue 慢性疲劳，比 tired 更深、恢复更慢。\",\n\"pulse\":\"画面：医生三指搭在手腕上，数着一下下的跳动——pulse「脉搏」。心脏搏动推动的动脉波动；take the pulse 诊脉，pulse rate 脉率即每分钟次数。\",\n\"bloodstream\":\"画面：红细胞随着血流像船队一样在血管里航行——bloodstream「血流」。循环中的血液本身；药物、激素都搭 bloodstream 的船到达全身。\",\n\"artery\":\"画面：鲜红的血从心脏出发，沿粗管奔向全身——artery「动脉」。把血送出心脏的血管，管壁厚、压力高；交通大动脉也叫 artery——都是主干道。\",\n\"vein\":\"画面：手背上青色的血管把血送回心脏方向——vein「静脉」。收集血液回心脏的血管，血色较暗；和 artery 一出一回，varicose veins 静脉曲张。\",\n\"capillary\":\"画面：细到只容红细胞排队通过的小管，氧气在这里交接——capillary「毛细血管」。连接动脉静脉的最细血管，物质交换的现场；capillary 现象是毛细现象。\",\n\"hemoglobin\":\"画面：红细胞里满载的红色蛋白，抱着氧分子送货——hemoglobin「血红蛋白」。负责运氧的蛋白，含铁所以血是红的；化验单上的 Hb 就是它，低了就是贫血。\",\n\"plasma\":\"画面：血液离心后上层淡黄色的液体，细胞沉在下面——plasma「血浆」。血液的液体部分，占一半多；输血浆 plasma transfusion，物理里的等离子体也叫 plasma。\",\n\"platelet\":\"画面：伤口处小碎片细胞聚成一团，堵住出血口——platelet「血小板」。负责凝血的细胞碎片；platelet count 血小板计数，太低伤口止不住血。\",\n\"transfusion\":\"画面：血袋挂在架子上，血液顺着管子缓缓输入病人体内——transfusion「输血」。把血液或成分输入静脉；blood transfusion 输血，输血前必须配型。\",\n\"liver\":\"画面：右上腹深红的大器官默默解毒、储糖、造胆汁——liver「肝脏」。人体最大的腺体、化工厂；liver disease 肝病，酒精伤肝先伤它。\",\n\"kidney\":\"画面：一对蚕豆形的器官过滤血液，废物变成尿液排出——kidney「肾脏」。过滤血液的净水器；kidney failure 肾衰竭，kidney beans 红腰豆因形似得名。\",\n\"lung\":\"画面：两片海绵样的器官随呼吸一胀一缩——lung「肺」。气体交换的场所，氧气进、二氧化碳出；lung cancer 肺癌，吸烟伤的是它。\",\n\"heart\":\"画面：拳头大的肌肉泵日夜跳动，把血推向全身——heart「心脏」。循环系统的发动机；heart rate 心率，heart attack 心脏病发作，heart 也是『内心』。\",\n\"brain\":\"画面：颅骨里沟回密布的器官，念头、记忆、指令都在这里——brain「大脑」。神经中枢；brain wave 脑电波，brain drain 人才流失借了『大脑外流』。\",\n\"muscle\":\"画面：他一握拳，前臂的肌群鼓起来收缩发力——muscle「肌肉」。能收缩产生运动的组织；build muscle 增肌，muscle strain 肌肉拉伤。\",\n\"nerve\":\"画面：一束电线般的纤维把信号从脚趾传到大脑——nerve「神经」。传递信号的纤维束；nerve 还指『胆量』：have the nerve 有胆量，get on one's nerves 惹人烦。\",\n\"neuron\":\"画面：一个带长尾的细胞把电信号传给下一个同伴——neuron「神经元」。神经系统的基本单位，树突收、轴突传；近千亿个 neuron 织成大脑网络。\",\n\"skeleton\":\"画面：全身骨头拼成的架子立在教室角落——skeleton「骨骼」。支撑身体的硬框架；skeleton key 万能钥匙、skeleton staff 骨干人员都借『骨架』义。\",\n\"skull\":\"画面：圆圆的头盖骨护着大脑，眼眶鼻梁都是它的一部分——skull「头骨」。颅骨总称；解剖图上的 skull 最易认，skull fracture 颅骨骨折是重伤。\",\n\"rib\":\"画面：胸腔两侧一根根弯骨像笼子护着心肺——rib「肋骨」。12 对弧形骨构成胸廓；rib cage 胸廓，排骨菜里的 spare ribs 就是它。\",\n\"spine\":\"画面：一串椎骨叠成的柱子从脖子延伸到腰，神经在里面穿行——spine「脊柱」。身体的中轴；spinal cord 脊髓在其中，spine 也是书脊——都是『中轴』。\",\n\"joint\":\"画面：膝盖处两根骨头相接，弯腿时它灵活转动——joint「关节」。骨与骨的连接点；joint pain 关节痛，joint 还指『接头、合办的』，都是『连起来』。\",\n\"cartilage\":\"画面：骨头末端垫着一层光滑发亮的软垫，减震又防磨——cartilage「软骨」。有弹性的结缔组织，耳廓、鼻尖、关节垫都是它；磨损了就是关节炎的源头之一。\",\n\"tendon\":\"画面：小腿肌肉下端收成一条结实的白索，连在脚跟上——tendon「肌腱」。把肌肉连到骨头的索带；跟腱 Achilles tendon 最有名，tendon 拉伤运动讲座常见。\",\n\"ligament\":\"画面：膝关节里十字形的带子把两根骨头绑稳——ligament「韧带」。连接骨与骨、稳定关节的纤维带；韧带撕裂 ligament tear 是运动员的大伤。\",\n\"skin\":\"画面：全身包着一层能出汗、能感知冷热的屏障——skin「皮肤」。人体最大的器官、第一道防线；skin care 护肤，skin 还作动词『去皮』。\",\n\"epidermis\":\"画面：显微镜下皮肤最外那层薄膜，细胞不断新生脱落——epidermis「表皮」。epi-（在上）+ dermis（皮肤）：皮肤的最外层；表皮之下是 dermis 真皮。\",\n\"gland\":\"画面：小器官把分泌物顺着导管送出去，有的是汗有的是激素——gland「腺体」。负责分泌的器官总称；汗腺、唾液腺、甲状腺 thyroid gland 都是 gland。\",\n\"hormone\":\"画面：信使分子搭血液的船到达远处器官，轻轻按下开关——hormone「激素」。内分泌腺分泌的化学信使，微量却高效；hormone therapy 激素治疗，青春期靠它发动变化。\",\n\"insulin\":\"画面：血糖一升，胰岛就放出这把钥匙，把葡萄糖送进细胞——insulin「胰岛素」。胰腺分泌、降低血糖的激素；糖尿病治疗的核心药，insulin resistance 胰岛素抵抗。\",\n\"digestion\":\"画面：食物从胃到肠被一步步拆成小分子——digestion「消化」。把食物分解为可吸收成分的过程；digest 消化（动词），digestive system 消化系统。\",\n\"absorption\":\"画面：小肠绒毛像无数小手，把营养从肠腔抓进血液——absorption「吸收」。物质被摄入体内的过程；absorb 是动词，吸收水分、营养、知识都用它。\",\n\"nutrition\":\"画面：餐盘里谷物、蔬果、蛋白搭配均衡，供身体长与修——nutrition「营养」。摄取和利用食物的全过程；nutritionist 营养师，malnutrition 营养不良。\",\n\"obesity\":\"画面：体重指数越过 30，脂肪堆积带来一串健康风险——obesity「肥胖」。脂肪过量堆积的状态，是疾病而非单纯体型；obese 肥胖的，childhood obesity 儿童肥胖。\",\n\"diabetes\":\"画面：血糖表上的数字居高不下，胰岛素这把钥匙失灵了——diabetes「糖尿病」。血糖调节失常的代谢病；分 1 型（缺胰岛素）和 2 型（抵抗），diabetic 糖尿病患者。\",\n\"cancer\":\"画面：一团细胞不受控制地疯长，还向别处扩散——cancer「癌症」。恶性肿瘤的总称；cancer cell 癌细胞，Cancer 还是巨蟹座——蟹爪般扩散是古人命名来源。\",\n\"tumor\":\"画面：影像片上多出一团不该有的组织块——tumor「肿瘤」。异常增生的组织团块，分 benign（良性）和 malignant（恶性）；发现 tumor 先要定性。\",\n\"benign\":\"画面：体检报告写着良性，医生说定期复查即可——benign「良性的」。不扩散、不致命的（肿瘤）；benign 还指『温和无害的』：benign climate 宜人气候。\",\n\"malignant\":\"画面：肿瘤细胞像蟹脚一样侵入周围组织，还搭血流转移——malignant「恶性的」。会浸润转移、危及生命的；和 benign 正相对，是病理报告最关键的区分。\",\n\"stroke\":\"画面：大脑一条血管突然堵住，一侧手脚立刻不听使唤——stroke「中风」。脑血管堵塞或破裂致脑缺氧；抢救讲 time is brain，stroke 也是『一击、划水动作』。\",\n\"asthma\":\"画面：气道一受刺激就收窄，他喘得像拉风箱——asthma「哮喘」。气道慢性炎症性疾病，发作时喘息；asthma attack 哮喘发作，吸入器 inhaler 是救命药。\",\n\"allergy\":\"画面：别人没事的花粉，让他喷嚏连天眼睛红肿——allergy「过敏」。免疫系统对无害物质过度反应；allergic to 对…过敏，花粉、花生、青霉素都可能是 allergen。\",\n\"immune\":\"画面：打过疫苗后再遇病毒，免疫系统认得出打得赢——immune「免疫的」。对某种病有抵抗力；immune system 免疫系统，immunity 免疫力。\",\n\"hygiene\":\"画面：饭前洗手、餐具消毒、伤口清洁——一套防病习惯——hygiene「卫生」。保持清洁防病的实践；personal hygiene 个人卫生，hygiene 在公共卫生讲座里是地基词。\",\n\"sanitation\":\"画面：干净的自来水、排污管道和垃圾处理让整座城少生病——sanitation「卫生设施」。城市层面的清洁系统；sanitary 卫生的，sanitation worker 环卫工。\",\n\"contagious\":\"画面：一个人在车厢里咳嗽，邻座几天后也病倒——contagious「传染性的」。能接触传播的；contagious disease 传染病，它也比喻笑声『有感染力』。\",\n\"epidemic\":\"画面：短短几周，一座城里病例数字陡然爬升——epidemic「流行病」。某地某时发病异常增多；epi-（在…之上）+ dem（人群）：压到人群头上的病。\",\n\"pandemic\":\"画面：世界地图上各大洲先后亮起红点——pandemic「大流行」。流行范围跨国跨洲；pan-（全部）：全球性的 epidemic，COVID-19 就是 pandemic。\",\n\"quarantine\":\"画面：确诊者被单独安置，与外界隔开直到没有传染性——quarantine「隔离」。为阻断传播的强制隔离；源于威尼斯对入港船只的 40 天（quaranta）检疫。\",\n\"incubation\":\"画面：病毒已进身体却毫无感觉，几天后才突然发烧——incubation「潜伏期」。病原入侵到症状出现的间隔；incubation period 潜伏期，无症状也能传播是防控难点。\",\n\"recovery\":\"画面：术后第三天他能下床走动，指标一天比一天好——recovery「康复」。身体逐渐恢复健康的过程；recover 是动词，recovery 也指经济『复苏』。\",\n\"relapse\":\"画面：病情刚稳住，指标又反弹回去了——relapse「复发」。好转后再次发作；relapse 在戒瘾治疗里也指复吸、复发，是康复路上的坎。\",\n\"chronic\":\"画面：这病不急不重，却拖了好几年反复发作——chronic「慢性的」。病程长、进展慢；chron-『时间』：时间拖出来的病，与 acute（急性）相对。\",\n\"acute\":\"画面：半夜突发剧痛被送急诊，起病又急又猛——acute「急性的」。发病急、病程短而重；acute 的另一义是『敏锐的』（听觉敏锐）和几何的『锐角』。\",\n\"severe\":\"画面：伤情等级表上他的名字被标在最重一档——severe「严重的」。程度深、后果重；severe pain 剧痛，severe weather 恶劣天气，比 serious 更重一档。\",\n\"mild\":\"画面：只是轻微咳嗽，医生说多喝水就能好——mild「轻微的；温和的」。程度轻；mild symptoms 轻症，mild climate 温和气候，和 severe 正相对。\",\n\"fatal\":\"画面：报告上写着致命伤，抢救最终没能挽回——fatal「致命的」。能导致死亡的；fatal accident 致命事故，fatal 也比喻『酿成大祸的』决定。\",\n\"mortality\":\"画面：统计表上每千人每年的死亡数字，就是这一项——mortality「死亡率」。特定人群的死亡比例；infant mortality 婴儿死亡率是衡量医疗水平的硬指标。\",\n\"longevity\":\"画面：百岁老人吹灭生日蜡烛，子孙围了四代人——longevity「长寿」。寿命长；long（长）+ ev（生命，aevum）：生命的长度，养生与遗传学都谈它。\",\n\"physician\":\"画面：诊室里穿白大褂的医生听诊、开方、解释病情——physician「内科医生」。有执照的医生，尤指内科；和 surgeon（外科）分工，primary care physician 全科/家庭医生。\",\n\"surgeon\":\"画面：无影灯下，他握着手术刀进行精细操作——surgeon「外科医生」。专做手术的医生；surgery 外科/手术，surgeon 的手要稳——这是它的画面核心。\",\n\"nurse\":\"画面：病房里她量体温、换药、记录病情，动作利落温和——nurse「护士」。照护病人的专业人员；nurse 还作动词『护理、哺育』，nursing 护理专业。\",\n\"patient\":\"画面：诊室椅子上等着看病的人，手里攥着化验单——patient「病人」。接受医疗的人；patient 还有形容词义『耐心的』——病人和耐心都要『能等、能忍』。\",\n\"clinic\":\"画面：社区小楼里几个科室，街坊们排队看常见病——clinic「诊所」。小型医疗机构，门诊为主；和 hospital（医院）比，clinic 规模小、不住院。\",\n\"hospital\":\"画面：高楼里急诊、病房、手术室一应俱全，救护车停在门口——hospital「医院」。综合治疗机构；be in hospital 住院（英式），hospitalize 送医。\",\n\"ward\":\"画面：一排病床整齐排开，护士站就在中间——ward「病房」。医院里同科病人的房间区；儿科病房 pediatric ward，ward 还有『行政区』义。\",\n\"emergency\":\"画面：救护车鸣笛冲进急诊通道，医护推床迎上去——emergency「急诊；紧急情况」。需要立即处理的危急事；emergency room 急诊室（ER），emergency exit 紧急出口。\",\n\"operation\":\"画面：手术台上团队协作，器械递得无声而精准——operation「手术」。切开身体治疗的操作；have an operation 做手术，operation 还有『行动、企业经营』义。\",\n\"incision\":\"画面：手术刀在皮肤上划开一道整齐的口子——incision「切口」。外科切开的口；incise 切开，incision 要缝 stitch 收尾，是手术的第一步画面。\",\n\"stitch\":\"画面：医生一针一线把伤口边缘对齐缝合——stitch「缝针；缝线」。缝合伤口的针脚；get stitches 缝针，stitch 也指编织的一针。\",\n\"bandage\":\"画面：纱布一圈圈缠住伤口，最后打个结固定——bandage「绷带」。包扎伤口的软材料；bandage 还作动词『包扎』，急救第一课就是它。\",\n\"ointment\":\"画面：挤出一点油膏抹在患处，凉凉的很舒服——ointment「药膏」。涂抹用的半固体药剂；antibiotic ointment 抗生素软膏，和 cream（乳膏）质地不同。\",\n\"pill\":\"画面：掌心一粒小小的圆片药，就水吞下——pill「药丸」。小片状口服药；take a pill 吃药，the Pill 特指避孕药，是家庭讲座词汇。\",\n\"capsule\":\"画面：透明的胶囊壳里装着彩色小颗粒，吞下去在胃里化开——capsule「胶囊」。药装在可溶外壳里；space capsule 太空舱也是『胶囊』形——形状命名。\",\n\"dose\":\"画面：量杯刻度停在 5 毫升——不多不少正好一次量——dose「剂量」。一次服用的药量；daily dose 每日剂量，overdose 过量是危险词。\",\n\"prescription\":\"画面：医生在处方笺上写下药名和用法，药房照方抓药——prescription「处方」。医生开具的用药指令；prescription drugs 处方药，与非处方药 OTC 相对。\",\n\"pharmacy\":\"画面：柜台后一排排药盒，药剂师核对处方递出药袋——pharmacy「药房」。卖药的零售店，也指药剂学；pharmacist 药剂师，别和 farm（农场）看混。\",\n\"side-effect\":\"画面：药治好了病，却让人犯困又口干——side-effect「副作用」。药物治疗作用之外的不良反应；说明书上 side effects 一栏必读，任何药都有。\",\n\"addiction\":\"画面：明知有害却停不下来，手一次次伸向烟盒——addiction「成瘾」。对物质或行为的依赖失控；addicted 上瘾的，addiction 是医学问题不是意志问题。\",\n\"withdrawal\":\"画面：戒断头几天他坐立不安、出汗失眠——withdrawal「戒断（反应）」。停用成瘾物后的身心反应；withdrawal symptoms 戒断症状，withdraw 还有『撤回、取款』义。\",\n\"rehabilitation\":\"画面：治疗师陪他从扶墙站立练到独立行走——rehabilitation「康复治疗」。恢复功能与社会生活的系统训练；rehab 是简称，戒瘾康复也用它。\",\n\"physiotherapy\":\"画面：治疗师用热敷、电疗和训练帮他恢复关节活动——physiotherapy「物理治疗」。用运动、按摩、光电等物理手段治疗；简称 physio，运动损伤康复主力。\",\n\"insomnia\":\"画面：凌晨三点他盯着天花板，数了几百只羊还是清醒——insomnia「失眠」。长期难以入睡或维持睡眠；in-（不）+ somn（睡）：睡不着，与 somnolent（昏昏欲睡）同根。\",\n\"trauma\":\"画面：一场事故后，他听见刹车声还会心跳加速——trauma「创伤」。身体或心理的重创；trauma 既指外伤（急诊创伤科），也指心理创伤，PTSD 与它相关。\",\n\"disorder\":\"画面：该整齐排列的东西乱成一团，功能也跟着失常——disorder「紊乱；障碍」。系统失去正常秩序的状态；eating disorder 饮食障碍，mental disorder 精神障碍。\",\n\"syndrome\":\"画面：一组症状总是成套出现，医生据此认出病名——syndrome「综合征」。一组共同出现的症状群；Down syndrome 唐氏综合征，syndrome 的关键是『成套』。\",\n\"hereditary\":\"画面：父亲的卷发、祖母的眼疾，沿着家谱一代代传下来——hereditary「遗传的」。由基因从亲代传给子代；hereditary disease 遗传病，heir 继承人同根。\",\n\"congenital\":\"画面：宝宝出生时就带着的心脏缺损——congenital「先天性的」。出生时已存在的（不一定是遗传）；congenital heart disease 先天性心脏病，和 hereditary（遗传）要分清。\",\n\"deficiency\":\"画面：化验单上维生素 D 一栏标着向下的箭头——deficiency「缺乏症；不足」。身体缺某种必需物质的状态；vitamin deficiency 维生素缺乏，deficient 不足的。\",\n\"surplus\":\"画面：仓库里堆着卖不完的余粮，比需要多出一大截——surplus「过剩」。超过所需的多余量；营养 surplus 热量过剩，贸易顺差 trade surplus 同一个词。\",\n\"crystal\":\"画面：显微镜下盐粒是整齐的立方体，石英内部原子排成规则阵列——crystal「晶体」。原子规则排列的固体；crystal clear 清澈透明，crystallize 结晶、（想法）成形。\",\n\"anxiety\":\"画面：考试前他手心冒汗、心跳快，脑子里全是最坏结果——anxiety「焦虑症；焦虑」。持续的担忧紧张状态；anxious 焦虑的，anxiety disorder 焦虑障碍是临床诊断名。\",\n\"depression\":\"画面：连着几周提不起劲，最喜欢的事也索然无味——depression「抑郁症」。持续低落、兴趣丧失的心理障碍；depression 还有『萧条、低气压、洼地』义，都是『压下去』。\",\n\"stress\":\"画面：deadline 压顶，他肩颈僵硬头隐隐作痛——stress「压力」。身心紧张状态；stress management 压力管理，stressed out 筋疲力尽，stress 也是物理的『应力』。\",\n\"genetic\":\"画面：化验报告指向某个基因的突变，病因写在 DNA 里——genetic「遗传的；基因的」。与基因有关；genetic disease 遗传病，genetic engineering 基因工程，gene 是词根。\",\n\"university\":\"画面：几所学院、一座图书馆和上万名学生组成一座小城——university「大学」。uni- 是『一』：许多学院合成一个整体；综合性大学才叫 university，单独的 college 规模小一号。\",\n\"college\":\"画面：大学城里其中一所学院，自己的楼、自己的院长——college「学院」。它既可指大学里的学院，也可指独立的学院；牛津剑桥的 college 就是住宿学院。\",\n\"campus\":\"画面：草坪、教学楼和宿舍围成的一大片地——campus「校园」。源于拉丁 campus『原野』：学校占的那片地；on campus 在校园里，别和 camp 帐篷混。\",\n\"seminar\":\"画面：十来个人围着长桌，人人面前摊着论文轮流发言——seminar「研讨会」。semin- 源于『种子』：小班里播下观点再互相催芽，不同于大课 lecture 的单向灌输。\",\n\"workshop\":\"画面：学员围着工作台边做边学，老师傅手把手纠正——workshop「工作坊」。work + shop：动手做的场所；学术里的 workshop 也是参与式的小型研讨，重点在练。\",\n\"curriculum\":\"画面：从一年级到毕业的全部课程排成一张总表——curriculum「课程体系」。源于拉丁 currere『跑』：学生要跑完的整条赛道；单门课是 course，整套安排才是 curriculum，复数 curricula。\",\n\"syllabus\":\"画面：开学第一课老师发的两页纸：每周讲什么、何时考试一目了然——syllabus「教学大纲」。一门课的纲要清单；它管一门课，curriculum 管整个专业，别混。\",\n\"course\":\"画面：一学期十二周、每周两次的课排进课表——course「课程」。它本义是『跑的路程』：一门课就是一段要走完的进程；of course 当然也是走熟路的意思。\",\n\"subject\":\"画面：课表上语文、数学、物理各占一格——subject「学科；科目」。sub-『下』+ ject『扔』：被放到面前的研究对象；它兼指学科与主语，靠语境分。\",\n\"degree\":\"画面：毕业典礼上校长把卷轴递到毕业生手里——degree「学位」。grad『步、级』（grade）：学业爬到的台阶等级；degree 也表温度的『度』，都是刻度上的级。\",\n\"bachelor\":\"画面：毕业生戴方帽拿卷轴，学位服上还没有更高学位的标记——bachelor「学士」。bachelor 是第一级学位；它也指单身汉：古时学士多未婚，两义同源。\",\n\"doctorate\":\"画面：答辩通过，教授在他名字前添上 Dr.——doctorate「博士学位」。doctor 源于拉丁『教师』：最高学位；PhD 是 doctorate 的一种。\",\n\"diploma\":\"画面：装裱起来挂在墙上的那张硬纸证书——diploma「文凭」。源于希腊语『对折的纸』：成绩被官方封存承认；diploma 偏指毕业文凭，certificate 泛指各种证书。\",\n\"certificate\":\"画面：盖着红章、写明某项资格已通过的证明纸——certificate「证书」。cert- 是『确定』（certain）：被权威确认属实的凭证；birth certificate 出生证明就是它。\",\n\"scholarship\":\"画面：成绩单换来一封信：本学年学费全免——scholarship「奖学金」。scholar（学者）+ -ship（身份、状态）：以学术表现换来的资助；fellowship 偏研究津贴。\",\n\"tuition\":\"画面：缴费窗口贴着价目：每学分多少钱——tuition「学费」。它源于『看护、教导』：为教学付的钱；美式直接说 tuition，英式常说 tuition fees。\",\n\"enrollment\":\"画面：新生在登记处签下名字，学籍系统里多了一个人——enrollment「注册；入学人数」。en- + roll（名单卷轴）：名字被写进名册；动词是 enroll。\",\n\"admission\":\"画面：邮箱里躺着录取通知，宿舍门禁从此刷得开——admission「入学（许可）」。ad- + miss『送』：被送进门内；admission 也指入场与承认，核心都是放进来。\",\n\"application\":\"画面：表格、成绩单、推荐信装订成一册寄往招生办——application「申请」。apply 的名词：把请求正式递上去；application form 申请表，它还指应用与应用程序。\",\n\"deadline\":\"画面：日历上那一天被红笔圈死，午夜一过系统就关——deadline「截止日期」。dead + line：逾越即死的线；meet the deadline 是赶在截止前完成。\",\n\"semester\":\"画面：学年被切成秋、春两段——semester「学期」。源于拉丁『六个月』：半年一期；一年两学期制叫 semester system，每段也可泛称 term。\",\n\"quarter\":\"画面：一个圆被十字切成四等份，学年取其中一份——quarter「学季；四分之一」。quart- 是『四』（quartet 四重奏）：四分之一的学年；它最常用的还是四分之一义。\",\n\"academic\":\"画面：图书馆深夜的灯、期刊里严谨的脚注——academic「学术的」。源于柏拉图的学园 Akademia：与学院研究有关的；academic year 学年，academic performance 学业表现。\",\n\"dean\":\"画面：院系大楼里管全院事务的那间办公室——dean「院长」。源于拉丁 decanus『十人长』：管一个学院的人；别和 principal（中学校长）混。\",\n\"professor\":\"画面：讲台上白发教授对着几百人讲授专业——professor「教授」。pro- + fess『公开说』（confess 坦白）：公开宣讲学问的人，大学教师最高职称；讲师是 lecturer。\",\n\"tutor\":\"画面：放学后一对一坐在书桌旁，哪里不懂讲哪里——tutor「辅导老师；导师」。源于拉丁『看护者』：盯住一个人教；牛津的导师制 tutorial 就靠 tutor 运转。\",\n\"superintendent\":\"画面：开学日他站在学区办公室，巡视辖区所有学校的报表——superintendent「学监；教育局长」。super-『在上』+ intend『监督』：管着许多学校校长的人。\",\n\"kindergarten\":\"画面：小朋友在花园里唱歌做游戏，像苗圃里的幼苗——kindergarten「幼儿园」。德语原词就是『儿童花园』：kinder 儿童 + garten 花园；入学前的园地。\",\n\"preschool\":\"画面：还没到入学年龄的孩子，先在这里学排队和分享——preschool「学前班」。pre-『在前』+ school：正式上学之前的教育；preschooler 是学龄前儿童。\",\n\"elementary\":\"画面：小学课本第一页：从最基本的笔画和数字讲起——elementary「初等的；基础的」。element 是『元素』：从最基础的元素学起；elementary school 就是小学。\",\n\"secondary\":\"画面：小学毕业，升上下一级台阶——secondary「中等的；次要的」。second 的形容词：排在第二位的；secondary school 是中学，它也作次要的，别只记学校义。\",\n\"literacy\":\"画面：老人戴着老花镜，第一次自己读完一封信——literacy「读写能力」。liter- 是『字母』（literature 文学）：认字读书的能力；literacy rate 识字率，illiteracy 是文盲状态。\",\n\"numeracy\":\"画面：买菜时心算找零，分毫不差——numeracy「计算能力」。numer- 是『数字』（numerous 众多的）：和数字打交道的能力，与 literacy 并称两大基本功。\",\n\"arithmetic\":\"画面：竖式纸上加减乘除一步步演算——arithmetic「算术」。源于希腊 arithmos『数字』：最基础的数字运算；它只是 mathematics 的入门部分。\",\n\"geometry\":\"画面：圆规和直尺在纸上画出圆与三角形——geometry「几何学」。geo-『地』+ -metry『测量』：源于丈量土地，研究点线面的形状；geometric 几何的。\",\n\"algebra\":\"画面：等式里 x 和 y 代替了具体数字——algebra「代数」。源于阿拉伯语 al-jabr『还原』：用字母代替数来列方程；algebraic 代数的。\",\n\"calculus\":\"画面：曲线下的面积被切成无数小片再加总——calculus「微积分」。源于拉丁『小石头』（古人用石子计数）：微分积分的统称；它在医学里还有结石义，靠语境分。\",\n\"statistics\":\"画面：一万份问卷汇成一张分布图——statistics「统计学」。源于『国家』（state）：为治理国家收集数据而生的学问；作学科是单数概念，statistic 是单个数据。\",\n\"physics\":\"画面：斜面上小球滚下，公式写满黑板——physics「物理学」。源于希腊 physis『自然』：研究物质与能量规律的学问；physicist 物理学家，physical 是身体的、物理的。\",\n\"chemistry\":\"画面：试管里液体变色、气泡咕咕冒——chemistry「化学」。研究物质组成与反应的学问；chemical 化学的、化学品，chemist 是化学家（英式还指药剂师）。\",\n\"biology\":\"画面：从细胞到雨林，凡是活物都在研究范围——biology「生物学」。bio-『生命』+ -logy『学问』：研究生命的学科；biological 生物学的。\",\n\"geology\":\"画面：敲开岩石看年轮般的纹层，推算地球的年龄——geology「地质学」。geo-『地』+ -logy：研究地球历史的学问，化石与岩层是它的档案；geologist 地质学家。\",\n\"astronomy\":\"画面：望远镜对准星空，行星轨道画满星图——astronomy「天文学」。astr-『星』（astronaut 宇航员）+ -nomy『法则』：研究天体与宇宙的学问；别和 astrology 占星术混，后者不是科学。\",\n\"botany\":\"画面：夹在标本册里的叶片被逐种编号命名——botany「植物学」。源于希腊『草、牧草』：专研植物的学科；botanical garden 是植物园。\",\n\"zoology\":\"画面：图鉴里从昆虫到鲸按纲目排开——zoology「动物学」。zoo-『动物』（zoo 动物园）+ -logy：专研动物的学科；zoologist 动物学家。\",\n\"psychology\":\"画面：实验者记录被试在镜子前的每一个反应——psychology「心理学」。psych-『心灵』+ -logy：研究心理与行为的学问；psychologist 心理学家。\",\n\"sociology\":\"画面：调查员走进社区，记录人群如何组织与流动——sociology「社会学」。soci-『社会』（society）+ -logy：研究人类社会结构与变迁的学问。\",\n\"anthropology\":\"画面：田野笔记、骨骼化石和不同部落的器物并排陈列——anthropology「人类学」。anthropo-『人』：研究人类起源与文化的学问；它比 sociology 更偏源头与文化比较。\",\n\"archaeology\":\"画面：探方里刷子拂去泥土，陶片露出花纹——archaeology「考古学」。archaeo-『古代』+ -logy：靠实物遗存研究古代人类的学问；archaeologist 考古学家，挖的是证据不是宝藏。\",\n\"linguistics\":\"画面：同一句问候被转写成几十种语言的音标——linguistics「语言学」。lingu-『舌头、语言』（bilingual 双语的）：研究语言结构与演变的学问；linguist 语言学家。\",\n\"philosophy\":\"画面：苏格拉底式追问，从『什么是正义』一路问到底——philosophy「哲学」。philo-『爱』+ sophia『智慧』：爱智慧之学；它也作人生信条讲（my philosophy）。\",\n\"theology\":\"画面：神学院课堂上逐句研读经典与教义——theology「神学」。theo-『神』（atheist 无神论者）+ -logy：系统研究宗教与神性的学问；theological 神学的。\",\n\"economics\":\"画面：供需曲线的交叉点随消息上下移动——economics「经济学」。eco- 源于希腊 oikos『家』：治家之术放大为治国，研究生产、分配与消费；economist 经济学家。\",\n\"accounting\":\"画面：账本上每一笔进出都有借贷两栏对着——accounting「会计学」。account 本是『账目』：记账核算的学问与工作；accountant 会计师。\",\n\"marketing\":\"画面：新品上市前，团队研究人群、定价与广告位——marketing「市场营销」。market『市场』的动名词：把产品推向市场的全套活动；它不等于 sales（销售环节），范围更宽。\",\n\"management\":\"画面：经理把人、钱、时间排成一张甘特图——management「管理」。manage『处理、驾驭』的名词：管人管事的活动，也指管理层本身。\",\n\"engineering\":\"画面：图纸上的桥变成横跨江面的实体——engineering「工程学」。engine『引擎、机械』的学问：把科学知识落成实际工程；engineer 工程师，civil engineering 土木工程。\",\n\"architecture\":\"画面：建筑师展开蓝图，结构与美学在一张图上交锋——architecture「建筑学」。archi-『主』+ tect『建造者』：设计建筑的学科与艺术；它也指建筑风格与计算机架构。\",\n\"medicine\":\"画面：医学院的解剖室与病房之间，学生来回奔走——medicine「医学」。研究防病治病的学问；medicine 也直接指药（take medicine 吃药），靠语境分。\",\n\"dentistry\":\"画面：牙科诊室的灯对准一颗蛀牙——dentistry「牙科」。dent-『牙』（dental 牙齿的）：专管牙齿的医学分支；dentist 是牙医。\",\n\"nursing\":\"画面：护士夜班巡房，逐床查看体温与输液——nursing「护理学」。nurse『哺育、护理』的学问：照顾病患的专业；nursing home 是养老院，别混。\",\n\"veterinary\":\"画面：诊台上躺的是猫狗和牧场的牛——veterinary「兽医学的」。给动物看病的医学；veterinary medicine 是兽医学全称，兽医口语叫 vet。\",\n\"agriculture\":\"画面：从播种到收割，一片农田的完整年轮——agriculture「农业」。agri-『田』+ culture『耕作』：耕作土地与饲养牲畜的产业与学问；agricultural 农业的。\",\n\"forestry\":\"画面：林务员给树木编号，哪片砍、哪片补种都有计划——forestry「林业」。forest『森林』的行当：植树护林与木材管理的科学与产业；forester 林务员。\",\n\"journalism\":\"画面：记者跑现场、核事实、赶截稿——journalism「新闻学；新闻业」。journal 源于『日报』：采写报道新闻的学问与职业；journalist 是记者。\",\n\"broadcasting\":\"画面：演播室红灯亮起，声音同时传进千家万户——broadcasting「广播学；播送」。broad + cast『撒播』：像撒种一样把信号撒向大众；BBC 的 B 就是 broadcast。\",\n\"photography\":\"画面：暗房里相纸在药水中慢慢显出影像——photography「摄影学」。photo-『光』+ -graphy『记录』：用光作画的技艺；photographer 摄影师，photograph 是照片。\",\n\"calligraphy\":\"画面：毛笔悬腕，一横一竖都讲骨法——calligraphy「书法」。calli-『美』+ -graphy『写』：把字写成艺术；calligrapher 书法家。\",\n\"pottery\":\"画面：陶轮飞转，湿泥在掌心升成一只碗——pottery「陶艺；陶器」。pot 是『罐』：制陶的手艺与成品的统称；potter 陶工，陶器区别于瓷器 porcelain。\",\n\"sculpture\":\"画面：凿子一点点削去多余石料，人像从石头里浮出来——sculpture「雕塑（学）」。源于拉丁『雕刻』：三维造型艺术；sculptor 雕塑家，作品本身也叫 sculpture。\",\n\"choreography\":\"画面：编舞者把队形图钉满墙，舞者按图走位——choreography「编舞」。choreo-『舞蹈』+ -graphy『记录』：设计并记录舞步的艺术；choreographer 编舞者。\",\n\"thesis\":\"画面：三万字论稿在答辩前夜还在改脚注——thesis「论文；论点」。学位论文是它最常见的身份；thesis 本义『摆出的观点』，所以也指论文要捍卫的核心论点。\",\n\"dissertation\":\"画面：比硕士论文厚三倍的书稿，专为博士学位而写——dissertation「学位论文（尤指博士）」。英式泛指长篇学位论文，美式专指博士论文；比 thesis 默认更长更专。\",\n\"essay\":\"画面：一篇短文围绕一个观点层层展开——essay「文章；短文」。源于法语 essayer『尝试』：试着把想法说清的短篇论说；托福大作文就是 essay。\",\n\"assignment\":\"画面：课后任务单发下来，周五前交——assignment「作业；任务」。assign『分派』的名词：被分派下来的活；homework 特指带回家做的那部分。\",\n\"homework\":\"画面：台灯下摊开的练习册，是白天课堂的延续——homework「家庭作业」。home + work：在家完成的那份课业；它是不可数名词，不说 a homework。\",\n\"exercise\":\"画面：课本每节后面都跟着十道巩固题——exercise「练习（题）」。成套的练习题；它也指体育锻炼，共性是反复练。\",\n\"exam\":\"画面：考场里只剩笔尖沙沙声——exam「考试」。examination 的口语缩写：成套试题的正式测验；final exam 期末考，entrance exam 入学考。\",\n\"quiz\":\"画面：课前老师突然说：拿出一张纸——quiz「小测验」。题量少、出其不意是它的标志；pop quiz 是突击小测，和 exam 的大阵仗正好对照。\",\n\"score\":\"画面：试卷右上角红笔写着 95——score「分数」。老师给出的量化成绩；score 作动词是进球，乐谱也叫 score，三义都源于『刻痕计数』。\",\n\"feedback\":\"画面：作文发回来，页边密密麻麻是老师的批注——feedback「反馈」。feed + back：信息回流；constructive feedback 是建设性反馈，能修正下一步。\",\n\"attendance\":\"画面：老师点名，答到的举手——attendance「出勤」。attend『出席』的名词：在场记录；attendance rate 是出勤率。\",\n\"absence\":\"画面：座位表上他的位置空着，点名无人应——absence「缺勤；缺席」。absent 的名词：不在场；absence 与 presence（出席）相对，leave of absence 是请假。\",\n\"tardy\":\"画面：上课铃响过五分钟，他才抱着书包冲进教室——tardy「迟到的」。专指上学上班迟到（美式校园高频词）；tardy slip 是迟到证明单，它比 late 更正式。\",\n\"detention\":\"画面：放学后别人都回家，他被留在空教室写检讨——detention「留校」。学校罚迟到违纪的经典手段；它也指拘留、扣押，核心都是把人留住不放。\",\n\"expulsion\":\"画面：处分通知寄到家里：学籍被取消——expulsion「开除」。ex-『出』+ puls『推』（pulse 脉搏同根）：把人推出门外的最重校纪处分；动词是 expel。\",\n\"suspension\":\"画面：处分栏写着停课三天，日期被单独圈出——suspension「停学」。suspend『悬挂、暂停』的名词：暂时停掉在读状态，比 expulsion 轻、比 detention 重。\",\n\"graduation\":\"画面：方帽抛向空中的那一刻，四年结束——graduation「毕业」。grad-『步、级』（grade）：走完最后一级台阶；graduate 是毕业生、毕业。\",\n\"commencement\":\"画面：毕业典礼请柬上印着 commencement 而非 graduation——commencement「毕业典礼」。它本义是『开始』：学业结束即人生新程开始，美式大学用它称毕业典礼，别猜成开学。\",\n\"reunion\":\"画面：毕业十年的人重新挤进同一间教室——reunion「同学聚会；重聚」。re-『再』+ union『合一』：分开的人再聚到一起；class reunion 校友聚会，family reunion 家庭团聚。\",\n\"orientation\":\"画面：开学第一周，新生拿着地图认教学楼和食堂——orientation「迎新」。orient- 源于『东方、日出方向』：先认清方向再出发；新生迎新周叫 orientation week，它还指方向与取向。\",\n\"registration\":\"画面：开学日队伍排到楼外，人人手里攥着登记表——registration「报到；注册」。register『登记册』的动作名词：把名字写进官方名单；course registration 是选课注册。\",\n\"transcript\":\"画面：密封信封里，四年的每门成绩一行行列齐——transcript「成绩单」。trans- + script『写』：把成绩转写成官方记录；申请学校寄的就是 official transcript。\",\n\"recommendation\":\"画面：教授在信里写：我毫不犹豫地推荐他——recommendation「推荐信」。recommend『推荐』的名词；letter of recommendation 是完整说法。\",\n\"interview\":\"画面：招生官隔桌提问，他逐条作答——interview「面试」。inter- + view『看』：面对面互相看清；interviewer 是提问方，interviewee 是受访方。\",\n\"portfolio\":\"画面：申请艺术院校的学生展开一本本作品——portfolio「作品集」。源于『携带纸张的夹子』：把代表作装成一册展示；金融里 portfolio 是投资组合，都是成套展示的集合。\",\n\"internship\":\"画面：假期里他以实习生身份进了公司项目组——internship「实习」。intern『实习生』+ -ship：为积累经验的短期实践岗位，常是转正的前站。\",\n\"apprenticeship\":\"画面：学徒跟着师傅一招一式练了三年才出师——apprenticeship「学徒制」。apprentice『学徒』的制度：边干边学的传统职业训练，电工、木匠至今还在用；比 internship 更长更专。\",\n\"vocational\":\"画面：课程表上全是实操：焊接、护理、汽修——vocational「职业的」。vocation 是『职业、天职』：vocational education 职业教育，与 academic 学术路径对照。\",\n\"technical\":\"画面：说明书里全是参数与术语，外行看得头大——technical「技术的；专门的」。techn- 源于希腊『技艺』：与专门技艺有关的；technical school 技校，technical term 术语。\",\n\"abundant\":\"画面：果园丰年，枝头果子多到压弯树枝——abundant「丰富的」。abund- 源于拉丁『溢出』：多到满溢；abundance 是名词丰盛，in abundance 大量地。\",\n\"adequate\":\"画面：水杯倒到七分满，够喝，不多不少——adequate「充足的」。ad- + equ『相等』（equal）：量刚好等于需要；它只保证够用，不夸富余，比 sufficient 口语一点。\",\n\"admirable\":\"画面：他默默照顾病母十年，邻里无不竖起拇指——admirable「令人钦佩的」。admire『钦佩』的形容词：值得敬佩的；admiration 是钦佩。\",\n\"adverse\":\"画面：顶着逆风走路，每一步都被往回推——adverse「不利的」。ad- + vers『转』：转向与你作对的一面；adverse effect 不良影响，adversity 是逆境本身。\",\n\"affluent\":\"画面：社区里家家有庭院泳池，车库停着两辆车——affluent「富裕的」。af- + flu『流』（fluent 流利）：财富如流水涌来；affluent society 富裕社会，wealthy 是常用近义。\",\n\"agile\":\"画面：体操运动员在平衡木上轻巧翻转——agile「敏捷的」。动作快而轻；agility 是敏捷性，它也可指思维敏捷与敏捷开发（agile development）。\",\n\"aggressive\":\"画面：拳击手步步紧逼，拳头先于哨声挥出——aggressive「好斗的；进取的」。ag- + gress『行走』（progress 前进）：主动压上来的；褒义可指积极进取（aggressive marketing），贬义才是攻击性。\",\n\"agreeable\":\"画面：春日微风拂面，人人点头说舒服——agreeable「宜人的；令人愉快的」。agree『同意』的延伸：让人愿意点头接受的；天气、气味、人都可 agreeable。\",\n\"alike\":\"画面：双胞胎穿同款衣服站在一起，难分彼此——alike「相似的」。a- + like：像到一个样；look alike 长得像，它多作表语（they are alike）。\",\n\"alive\":\"画面：心电图上的波形还在跳动——alive「活着的」。a- + life：有生命的；alive and well 活得好好的，它还可指热闹活跃（streets alive with people）。\",\n\"alleged\":\"画面：报道里每个说法前都加着『据称』二字，尚未证实——alleged「所谓的；被指称的」。allege『声称』的形容词：只是有人这么说；定罪之前，嫌疑人只能叫 alleged thief。\",\n\"allergic\":\"画面：他刚吃一口花生就起疹子、呼吸急促——allergic「过敏的」。免疫系统反应过头；be allergic to… 对…过敏，花粉热 hay fever 就是它。\",\n\"aloof\":\"画面：聚会上众人热聊，他独自站在窗边不搭话——aloof「冷漠疏远的」。源于航海词『远离』：故意保持距离；stand aloof 置身事外，aloof 不是害羞，是刻意的疏离。\",\n\"altruistic\":\"画面：他匿名捐出大半积蓄，自己仍住小屋——altruistic「利他的；无私的」。源于法语 autre『他人』：先人后己；与 egoistic 利己的正相对，altruism 是利他主义。\",\n\"amiable\":\"画面：老爷爷笑眯眯地给每个邻居打招呼——amiable「和蔼可亲的」。ami- 是『爱、友』（amigo 朋友）：让人想亲近的好脾气；amicable 多形容关系友好。\",\n\"ample\":\"画面：仓库货架堆得满满当当，还富余一排——ample「充足的；充裕的」。源于拉丁『宽大』：不止够用还有余量；ample time 充裕时间，比 adequate 多一层从容。\",\n\"amusing\":\"画面：小丑一个滑步，全场孩子笑倒——amusing「有趣的；好笑的」。amuse『逗乐』的形容词：能引人发笑的；amusement park 是游乐园。\",\n\"angular\":\"画面：折纸棱角分明，每条边都成尖角——angular「有角的；棱角分明的」。angle『角』的形容词：带尖角的形状；也可形容人瘦骨嶙峋。\",\n\"anonymous\":\"画面：捐款名单上写着『佚名』，没人知道是谁——anonymous「匿名的」。an-『无』+ -onym『名字』（synonym 同义词的 nym）：没有名字的；anonymous letter 匿名信。\",\n\"antagonistic\":\"画面：两队球迷隔栏对骂，火药味十足——antagonistic「敌对的；对抗的」。anti-『对抗』+ agon『竞赛』：站在对立面较劲的态度；antagonist 是对手、反派。\",\n\"anterior\":\"画面：解剖图上身体前侧被涂成红色标注——anterior「前面的；前部的」。ante-『在前』（anticipate 提前）：位置在前的；anterior 与 posterior（后面的）成对，解剖学高频。\",\n\"anxious\":\"画面：考场外他来回踱步、手心全是汗——anxious「焦虑的；渴望的」。心里像被揪住的状态；anxious about 为…焦虑，anxious to do 又可表渴望做，别只记坏义。\",\n\"apathetic\":\"画面：天大的消息传来，他眼皮都没抬——apathetic「冷漠的；无动于衷的」。a-『无』+ path『感受』（sympathy 同情）：没有感觉的；apathy 是冷漠，voter apathy 选民冷漠是社会学常客。\",\n\"apologetic\":\"画面：迟到的人低着头连声说抱歉——apologetic「道歉的；愧疚的」。apology『道歉』的形容词：带着歉意的；an apologetic smile 歉然一笑，动词是 apologize。\",\n\"appealing\":\"画面：橱窗里的蛋糕让人挪不开眼——appealing「有吸引力的」。appeal 本是『呼吁、上诉』，引申为投合心意：对感官有呼召力的；appealing design 吸引人的设计。\",\n\"applicable\":\"画面：这条规则贴到新案例上，条条对得上——applicable「适用的；可应用的」。apply『应用』的形容词：能套用的；applicable to… 适用于…，反义 inapplicable。\",\n\"appreciative\":\"画面：收到帮助后，他郑重写下感谢信——appreciative「感激的；赏识的」。appreciate 既是感激也是欣赏：心怀谢意并懂价值；appreciative audience 是懂行的观众。\",\n\"apprehensive\":\"画面：体检报告未拆封前，他整夜睡不着——apprehensive「忧虑的；担心的」。心里先抓住了坏的可能；apprehension 是忧虑，与 anxious 近，但更偏对未来的预感。\",\n\"approachable\":\"画面：校长蹲下来和孩子平视说话，一点架子没有——approachable「平易近人的」。approach『走近』+ -able：敢走近、好接近的；也可指问题易懂。\",\n\"archaic\":\"画面：甲骨文一样的古字，今人认不出几个——archaic「古老的；过时的」。archae-『古代』（archaeology 考古）：属于远古时代的；archaic word 是古语词。\",\n\"ardent\":\"画面：球迷脸上画着队徽，嗓子喊哑也不停——ardent「热情的；热烈的」。ard- 源于拉丁『燃烧』（arson 纵火）：心里有火的热忱；ardent supporter 狂热支持者。\",\n\"arduous\":\"画面：登山队在稀薄空气里一步一喘往上挪——arduous「艰巨的；费力的」。源于拉丁『陡峭』：像爬陡坡一样吃力；arduous task 艰巨任务，比 difficult 更强调耗力。\",\n\"arid\":\"画面：大地干裂成网，仙人掌是唯一的绿——arid「干旱的」。缺水到寸草难生；arid climate 干旱气候，它也可形容内容枯燥（arid discussion）。\",\n\"aristocratic\":\"画面：庄园晚宴上银器烛台，礼仪一丝不苟——aristocratic「贵族的」。aristo-『最优』+ -crat『统治』（democratic 的 crat）：贵族阶层的做派；aristocrat 是贵族本人。\",\n\"aromatic\":\"画面：香料摊前，八角桂皮的香气扑面——aromatic「芳香的」。aroma『香气』的形容词：散发香味的；aromatic herbs 香草香料，化学里 aromatic 另指芳香烃，靠语境分。\",\n\"arrogant\":\"画面：他下巴扬得老高，话都不让人说完——arrogant「傲慢的」。把自己抬过头的自大；arrogance 是傲慢，与 humble 谦逊相对。\",\n\"artistic\":\"画面：随手涂鸦都自带构图感——artistic「艺术的；有艺术天赋的」。art 的形容词：属于艺术的，或天生会创作的；artistic talent 艺术天赋，artist 是艺术家。\",\n\"assertive\":\"画面：会上他平静地说：这个方案我不同意，理由有三——assertive「坚定自信的」。assert『断言、主张』的形容词：敢于明确表达立场；它自信不退缩，与 aggressive 好斗要分清。\",\n\"assorted\":\"画面：糖果盒打开，各种口味颜色一应俱全——assorted「各种各样的；什锦的」。sort『分类』：各类别都来一点的混装；assorted chocolates 什锦巧克力。\",\n\"astonished\":\"画面：魔术师从帽子里拎出兔子，他嘴巴张成圆形——astonished「吃惊的」。像被惊雷击中般愣住；astonish 使惊讶，比 surprised 更强一档。\",\n\"astounding\":\"画面：成绩公布：长期垫底的人逆袭到第一，全班哗然——astounding「惊人的」。能把人震住的程度；astounding news 惊人消息，与 astonishing 基本同义。\",\n\"athletic\":\"画面：运动员体态匀称，起跑爆发力十足——athletic「运动的；健壮的」。athlete『运动员』的形容词：与运动有关的，或身材运动型的；athletic shoes 运动鞋，athletics 是田径。\",\n\"atrocious\":\"画面：新闻里的暴行令人发指，不忍细看——atrocious「残暴的；恶劣的」。坏到极点的残忍；atrocious weather 是糟透的天气，引申义也常用。\",\n\"attentive\":\"画面：护士守在床边，仪器数字一变她立刻察觉——attentive「体贴周到的；专心的」。attend『照料、出席』：心思放在对方身上；attentive service 周到服务。\",\n\"attractive\":\"画面：花香引来成群蝴蝶绕着不散——attractive「迷人的；有吸引力的」。at- + tract『拉』（tractor 拖拉机）：能把目光拉过来的；attractive offer 是诱人的条件，不止形容人。\",\n\"audacious\":\"画面：所有人说不可能，他偏第一个跳出来报名——audacious「大胆的；无畏的」。敢为天下先的胆量；audacity 是大胆，褒义时近 daring。\",\n\"audible\":\"画面：安静的教室里，连手表滴答声都清晰可闻——audible「听得见的」。aud-『听』（audience 听众）：音量达到耳朵能捕捉的程度；inaudible 是听不见的。\",\n\"authentic\":\"画面：鉴定师点头：这幅字是真迹，不是临摹——authentic「真实可靠的；正宗的」。源于希腊『亲手做的』：不是赝品的；authentic cuisine 地道菜，authenticity 是真实性。\",\n\"authoritative\":\"画面：词典编者的话被所有人当作定论引用——authoritative「权威的」。authority『权威』的形容词：有权威分量的；authoritative source 权威来源，也可指命令口气。\",\n\"autonomous\":\"画面：自治区自己立法自己管理，不等上级批示——autonomous「自治的；自主的」。auto-『自己』+ -nom『法则』：自己给自己立法；autonomous vehicle 是自动驾驶车。\",\n\"averse\":\"画面：一提香菜他就摆手，碰都不碰——averse「厌恶的；反对的」。a- + vers『转开』：把脸转开的不情愿；be averse to… 反感…，risk-averse 是厌恶风险的，金融高频。\",\n\"avid\":\"画面：书虫抱着新书一夜读到天亮——avid「热切的；酷爱的」。源于拉丁『渴望』：贪求般的热望；avid reader 如饥似渴的读者，avid for knowledge 求知若渴。\",\n\"aware\":\"画面：走夜路的他对身后脚步声异常警觉——aware「意识到的；知道的」。意识上线了的状态；be aware of… 意识到…，awareness 是意识（environmental awareness 环保意识）。\",\n\"awkward\":\"画面：新手端盘子摇摇晃晃，杯子直打滑——awkward「笨拙的；尴尬的」。动作不顺手、场面不自在都是它；awkward silence 尴尬的沉默，awkward moment 是社死瞬间。\",\n\"awful\":\"画面：暴雨把帐篷掀翻，整夜狼狈不堪——awful「可怕的；糟糕的」。awe 本是『敬畏』：坏到令人发怵；口语里 awfully 是『非常』（awfully sorry 非常抱歉）。\",\n\"balanced\":\"画面：天平两端砝码对等，指针稳稳指中——balanced「均衡的」。balance『平衡』的定格状态；balanced diet 均衡饮食，balanced view 公允看法，都贵在不偏。\",\n\"banal\":\"画面：致辞里全是听过一百遍的套话——banal「平庸的；陈腐的」。毫无新意的平淡；banality 是平庸，与 original 独创相对。\",\n\"barbaric\":\"画面：活人祭祀的记载读来毛骨悚然——barbaric「野蛮的；残暴的」。barbar- 源于希腊人对外国语的拟声：未开化的粗野；barbaric act 野蛮行径。\",\n\"bashful\":\"画面：被点名的孩子躲到老师身后，只露半张脸——bashful「害羞的」。遇人就往回缩的羞怯；比 shy 多一层局促不安，bashfulness 是羞怯。\",\n\"basic\":\"画面：搭积木先铺最底层那一块——basic「基本的；基础的」。base『根基』的形容词：最底层、最必需的；basic needs 基本需求，basically 是口头禅『基本上』。\",\n\"bearable\":\"画面：疼痛还在，但咬咬牙能撑过去——bearable「可忍受的」。bear『忍受』+ -able：能扛得住的；unbearable 是忍无可忍。\",\n\"believable\":\"画面：证词细节前后咬合，陪审团频频点头——believable「可信的」。believe 的 -able 形：经得起相信的；反义 unbelievable 难以置信。\",\n\"beloved\":\"画面：全镇人给老教师送行，队伍排了两条街——beloved「深爱的；心爱的」。be- + loved：被深深爱着的；beloved 作名词是心爱之人。\",\n\"beneficial\":\"画面：晨练三个月，体检数字全面好转——beneficial「有益的」。bene-『好』（benevolent 仁慈）+ -fic『做』：能产生好处的；beneficial to health 有益健康。\",\n\"benevolent\":\"画面：老院长一辈子资助穷学生，从不留名——benevolent「仁慈的；善意的」。bene-『好』+ vol『意愿』（volunteer 志愿者）：心怀善意的；benevolent dictator 开明专制者是政治学词组。\",\n\"bent\":\"画面：老树枝被雪压成一张弓——bent「弯曲的」。bend 的定格状态：成了弯的形状；bent on doing 是铁了心要做（be bent on success 志在成功），引申义高频。\",\n\"berserk\":\"画面：他双眼通红掀翻桌子，谁拦砸谁——berserk「狂怒的；失控发疯的」。源于北欧『熊皮战士』：战斗中癫狂的状态；go berserk 暴怒失控是固定说法。\",\n\"besides\":\"画面：清单上三样已打钩，旁边又添上第四样——besides「此外；除了」。be- + side『旁边』：在旁边再加一笔；作介词是『除…之外（还）』，作副词是『而且』，与 beside（在旁边）只差一个 s。\",\n\"bewildered\":\"画面：站在七岔路口，指示牌全是外文——bewildered「困惑的；茫然的」。be- + wilder『荒野』：像迷失荒野般摸不着头脑；bewilder 使迷惑，比 confused 更茫然。\",\n\"biased\":\"画面：裁判是主队球迷，哨子明显偏向一边——biased「有偏见的；偏袒的」。bias『偏斜』的形容词：天平歪向一方的；biased report 失实报道，unbiased 是不偏不倚。\",\n\"biblical\":\"画面：洪水故事在好几种古文明里都有影子——biblical「圣经的」。Bible『圣经』的形容词：出自或关乎圣经的；biblical proportions 是史诗级规模的夸张说法。\",\n\"bigoted\":\"画面：谁的话都听不进，只认自己那一套——bigoted「偏执的；顽固抱偏见的」。bigot『偏执者』的形容词：死抱成见且容不得异见；bigotry 是偏执，多与种族宗教语境连用。\",\n\"bilingual\":\"画面：孩子在中文和英语之间切换自如——bilingual「双语的」。bi-『二』+ lingu『语言』：能用两种语言的；bilingual education 双语教育，trilingual 是三语。\",\n\"binding\":\"画面：合同签完字，双方律师说这字一落就有法律效力——binding「有约束力的」。bind『捆绑』：像被绳子绑住般逃不掉的义务；legally binding 具有法律约束力。\",\n\"biodegradable\":\"画面：埋进土里的袋子三个月烂成泥——biodegradable「可生物降解的」。bio-『生命』+ degrade『降解』：能被微生物分解掉的；环保材料标签高频词。\",\n\"bitter\":\"画面：刚嚼一口莲子心，眉头皱成一团——bitter「苦的」。舌尖的苦味是本义；引申 bitter cold 刺骨严寒、bitter dispute 激烈争执，苦味蔓延到情绪与天气。\",\n\"bizarre\":\"画面：一条鱼骑自行车的画挂在展厅正中央——bizarre「奇异的；怪诞的」。怪到出格的非常规；bizarre behavior 怪异举动，发音后半近『扎尔』。\",\n\"blameless\":\"画面：事故调查结论：他全程合规，无可指摘——blameless「无可责备的；无辜的」。blame『责备』+ -less：挑不出错的清白；blameless life 无可指摘的一生。\",\n\"bland\":\"画面：白粥忘了放盐，淡得没一点滋味——bland「平淡的；乏味的」。味道寡淡是本义，引申内容与性格平淡无奇；bland diet 清淡饮食是医嘱词。\",\n\"blank\":\"画面：试卷最后一页的大题区一片空白——blank「空白的」。什么都没写的空；blank page 白纸，go blank 是脑子一片空白。\",\n\"blatant\":\"画面：作弊的人把小抄摊在桌面上，毫不遮掩——blatant「明目张胆的」。坏得明目张胆、不加掩饰；blatant lie 弥天大谎，blatantly 是副词。\",\n\"bleak\":\"画面：寒冬荒原上孤树一棵，灰天压顶——bleak「荒凉的；暗淡的」。景与前景同凉：bleak landscape 荒凉景色，bleak future 黯淡前途，狄更斯《荒凉山庄》原名 Bleak House。\",\n\"blessed\":\"画面：老人子孙满堂，晚年安详——blessed「有福的；蒙福的」。bless『祝福』的定格：被福气罩着的；日常 bless you 是打喷嚏后的祝福语。\",\n\"blind\":\"画面：他靠指尖读盲文的凸点——blind「失明的」。看不见是本义；引申 blind spot 盲点、blind faith 盲目信任，blind alley 里的 blind 是无出口。\",\n\"bloody\":\"画面：战场绷带被鲜血浸透——bloody「流血的；血腥的」。blood 的形容词：带血的；英式口语 bloody 还是粗口加强词，正式写作要避开那个用法。\",\n\"blooming\":\"画面：四月花园里牡丹次第炸开——blooming「盛开的；旺盛的」。bloom『开花』的进行态：正值盛放；blooming health 是气色红润。\",\n\"blunt\":\"画面：钝刀切番茄，皮都压瘪了还没破——blunt「钝的；直率的」。刀口不锋利是本义，引申说话不绕弯；blunt refusal 直截了当的拒绝，to be blunt 是『坦白说』。\",\n\"blurred\":\"画面：老照片里的人脸糊成一团——blurred「模糊的」。轮廓看不清的状态；blurred vision 视力模糊，blurred lines 是界限模糊。\",\n\"boastful\":\"画面：刚赢一局就满场吹嘘自己天下无敌——boastful「自夸的；好吹牛的」。boast『吹嘘』+ -ful：满口大话的；boast 可中性（以…自豪），boastful 一定是贬义的吹。\",\n\"boiling\":\"画面：壶嘴白气冲天，水在锅里翻滚——boiling「沸腾的；炎热的」。boil『煮沸』的进行态；boiling point 沸点，天气热到 boiling 是口语夸张。\",\n\"bold\":\"画面：别人不敢举手时，他第一个站起来——bold「勇敢的；大胆的」。无所畏惧是本义；bold 还指粗体字与醒目色彩（bold colors），都是敢跳出来的气势。\",\n\"bolted\":\"画面：大门插销横着落下，推也推不开——bolted「闩上的；用螺栓固定的」。bolt 本是门闩与螺栓：被闩死的；bolt 作动词还有 bolted from the room 夺门而逃，语境决定是哪义。\",\n\"bonded\":\"画面：两块板用胶粘死，掰也掰不开——bonded「粘合的；结成一体的」。bond『黏合、纽带』的定格：牢牢连在一起的；bonded warehouse 保税仓库是海关术语，别硬套粘合义。\",\n\"bony\":\"画面：老人手背青筋与骨节根根分明——bony「骨瘦的；多骨的」。bone『骨头』的形容词：瘦到见骨；bony fish 硬骨鱼是生物学分类词。\",\n\"bookish\":\"画面：他鼻梁上架着厚眼镜，假期全泡在图书馆——bookish「书呆子气的；书本气的」。book + -ish：满身书卷气，多带只会纸上谈兵的贬义；bookish knowledge 是书本知识。\",\n\"booming\":\"画面：开发区塔吊林立，订单电话响个不停——booming「繁荣的；蓬勃发展的」。boom 本是『隆隆声、激增』：像炮声一样爆发的繁荣；booming economy 蓬勃的经济，baby boom 婴儿潮同根。\",\n\"boorish\":\"画面：宴席上他大声咀嚼还随地吐痰——boorish「粗野的；粗俗无礼的」。boor『粗人』的形容词：没教养的粗鲁；boorish behavior 粗野举止，纯贬义。\",\n\"boosted\":\"画面：火箭助推器点火，速度猛地往上窜——boosted「增强的；被提升的」。boost『助推』的定格：被外力抬高一截的；boosted sales 被拉高的销量，booster 是助推器、加强针。\",\n\"borderline\":\"画面：成绩卡在及格线上下一分，老师反复核对——borderline「边缘的；临界的」。border『边界』+ line：贴着界线、归类两难的；borderline case 临界病例。\",\n\"bored\":\"画面：会议第三个小时，他在本子上画满小圈——bored「无聊的；厌倦的」。人的感受是 bored，事的性质是 boring，先分清：I am bored with this boring lecture。\",\n\"boring\":\"画面：讲座单调到听众一片打哈欠——boring「乏味的；令人厌倦的」。让人生厌的是事物属性；a boring lecture 乏味的讲座，与 bored（人的感受）成对。\",\n\"bossy\":\"画面：小组里她对谁都发号施令——bossy「专横的；好指挥人的」。boss『老板』+ -y：爱摆老板架子的；多形容小孩与同事，是贬义的指挥欲。\",\n\"shoe\":\"画面：一只鞋摆在鞋柜里，鞋带系成蝴蝶结——shoe「鞋子」。穿在脚踝以下的鞋统称；a pair of shoes 一双鞋，马掌铁 horseshoe 是同名亲戚。\",\n\"boot\":\"画面：雨靴筒高到小腿，踩进泥水不湿脚——boot「靴子」。包住脚和小腿的高筒鞋，筒高是它的标志；它也是英式汽车后备厢和电脑开机（boot up），看语境分。\",\n\"sock\":\"画面：一只袜子套在脚上，口沿到脚踝上方——sock「袜子」。穿在鞋里面的脚衣；windsock 风向袋借的就是它的筒形。\",\n\"underwear\":\"画面：贴身穿在衬衫里面的一层——underwear「内衣」。under + wear：穿在最里面的衣物总称，不可数名词；thermal underwear 是保暖内衣。\",\n\"pajamas\":\"画面：睡前换上宽松睡衣裤准备上床——pajamas「睡衣」。源于波斯语『腿衣』：成套的睡眠服装；美式拼 pajamas，英式 pyjamas，两种都认。\",\n\"oregano\":\"画面：披萨出炉前撒上一把碎绿香草叶——oregano「牛至」。披萨与意面酱的灵魂香草；名字源于希腊语『山之喜悦』，叶片小而香。\",\n\"meticulous\":\"画面：修复师用镊子夹起比米粒还小的碎片，对照原图一格格拼——meticulous「一丝不苟的；极为细致的」。细致到近乎怕出错（源于拉丁 metu 恐惧）：不放过任何细节；meticulous records 一丝不苟的记录。\",\n\"ambiguous\":\"画面：同一句『我去方便一下』，听的人猜不出是哪个意思——ambiguous「模棱两可的；含糊不清的」。ambi-『两边』：可往两边解释的含糊；ambiguity 是名词歧义。\",\n\"proliferate\":\"画面：池塘里的浮萍一周铺满整个水面——proliferate「激增；迅速繁殖」。像繁殖一样越变越多；nuclear proliferation 核扩散是政治高频搭配。\",\n\"resilient\":\"画面：被雪压弯的竹子，雪化后又弹回挺直——resilient「有韧性的；能迅速恢复的」。被压下去还能弹回来；resilience 是韧性，心理与材料两界通吃。\",\n\"ubiquitous\":\"画面：街角有监控，口袋里有手机——它无处不在——ubiquitous「无处不在的」。ubi- 是拉丁『何处』：哪里都有的普遍存在；ubiquitous computing 普适计算是科技词。\",\n\"pragmatic\":\"画面：不争论哪种理论更美，先挑能落地的方案干起来——pragmatic「务实的；实用的」。源于希腊 pragma『行动、事务』：以实际效果为准绳；pragmatism 是实用主义。\",\n\"hypothesis\":\"画面：实验前他在本子上写下预测，等数据来验真假——hypothesis「假设；假说」。hypo-『在下』+ thesis『论点』：垫在研究底下待验证的论点；复数 hypotheses，通过检验才升级为 theory。\",\n\"intricate\":\"画面：钟表机芯几百个齿轮咬合，错一齿全停——intricate「错综复杂的；精细的」。源于拉丁『缠结』：细密交织到难拆解的复杂；intricate pattern 精细纹样。\",\n\"alleviate\":\"画面：药下去半小时，头痛从十分退到三分——alleviate「减轻；缓解」。ad- + lev『轻』（levitate 悬浮）：把重负变轻；alleviate pain 缓解疼痛、alleviate poverty 缓解贫困是两大招牌搭配。\",\n\"ephemeral\":\"画面：蜉蝣清晨孵化，日落前已经死去——ephemeral「短暂的；朝生暮死的」。源于希腊『一天』：只活一天的短暂；托福生物讲蜉蝣必用它。\",\n\"deteriorate\":\"画面：无人维护的老屋油漆剥落、木梁蛀空——deteriorate「恶化；变坏；退化」。源于拉丁『更坏』：状态一路向下；deterioration 是恶化，病情、关系、环境都会 deteriorate。\",\n\"eloquent\":\"画面：演讲者一段排比说完，全场起立鼓掌——eloquent「雄辩的；口才出众的」。e- + loqu『说』（loquacious 健谈）：说得出彩动人的；eloquence 是口才。\",\n\"blissful\":\"画面：躺在吊床上晒太阳，烦恼全忘光——blissful「极乐的；幸福至极的」。bliss 是『极乐、大福』：幸福到极致的陶醉；blissful ignorance 是无知的幸福，blissfully unaware 是浑然不觉地快乐。\",\n\"antithesis\":\"画面：黑夜与白天同框对峙，一半亮一半暗——antithesis「对立面」。anti-『反对』+ thesis『论点』：与正题针锋相对的反题；辩证法里正—反—合的那个『反』就是它。\",\n\"archetype\":\"画面：所有同类人物的源头模板立在最前面，后面的形象都从它拓印——archetype「原型」。arche-『最初』+ type『类型』：一切同类的最初范本；文学批评的原型意象就用它。\",\n\"axiom\":\"画面：几何课本第一页，不用证明就直接立住的那条命题——axiom「公理」。源于希腊语『值得相信的』：不证自明、整个学科拿它当出发点；欧几里得公理是代表。\",\n\"canon\":\"画面：书架最里层上锁的一排，全是公认必读的经典——canon「经典规范；正典」。源于希腊语『尺子、标准』：被权威定为标准的那批作品；莎士比亚稳坐英语文学 canon 的核心。\",\n\"chronology\":\"画面：一条长长的时间轴，事件按年份钉成一串——chronology「年表；年代顺序」。chron『时间』（chronic 慢性的）：把事件按先后排队的清单；历史题先理 chronology 再谈因果。\",\n\"circumference\":\"画面：用软尺绕圆盘一整圈量出长度——circumference「圆周；周长」。circum-『环绕』+ fer『带』：绕一圈带回来的长度；公式 C = 2πr 量的就是它。\",\n\"citation\":\"画面：论文脚注里一行小字，作者、年份、页码清清楚楚——citation「引文；引用出处」。cite『引用』的名词：注明来源的那条标注；学术写作没有 citation 就有抄袭嫌疑。\",\n\"classification\":\"画面：图书管理员把一堆杂书按标签分进不同书架格——classification「分类」。class『类别』+ -fication『化』：把事物分门别类的体系；生物学分类是它的主战场。\",\n\"codex\":\"画面：修道院里装订成册的古手稿，一页页翻，不是卷轴——codex「手抄本；古抄本」。古代装订成书册的手写本；玛雅 codex、达·芬奇 codex 都是考古高频词。\",\n\"coherence\":\"画面：一篇文章段段相扣，读下来一口气不断——coherence「连贯性」。co-『一起』+ her『黏』（adhere 黏附）：思想黏在一起不散架；它指逻辑连贯，与 cohesion 的形式衔接相对。\",\n\"collaboration\":\"画面：两支团队围着同一张图纸改方案——collaboration「协作；合作」。col-『共同』+ labor『劳动』：一起干活；在二战语境里还有『通敌』的贬义面，看上下文。\",\n\"collage\":\"画面：剪报、照片、布片被胶水拼成一幅新画——collage「拼贴画」。源于法语『粘贴』：把现成材料剪贴重组；毕加索的拼贴是艺术史考点。\",\n\"commentary\":\"画面：球赛直播间里解说员跟着画面一句接一句点评——commentary「评论；实况解说」。comment『评论』的名词总量：连续成段的评述；学术版还有经典注疏的意思。\",\n\"compromise\":\"画面：谈判桌两边各退一步，握手成交——compromise「妥协；折中」。com-『共同』+ promise『承诺』：双方共同承诺让步；动词还有『使陷入险境』义，如 compromise security 危害安全。\",\n\"computation\":\"画面：草稿纸上密密麻麻的竖式，一步不错地往下算——computation「计算」。put『算』（compute 计算）：一步步推算的过程；computational 是计算机科学的招牌形容词。\",\n\"concession\":\"画面：房东把租金从三千降到两千八，合同上签了字——concession「让步」。con- + cede『让』（recede 后退）：退让出的那一步；贸易谈判里 concession 是交换的条件。\",\n\"concord\":\"画面：两个声部高低不同却严丝合缝地唱在一起——concord「和谐一致」。con- + cord『心』（cordial 衷心的）：心往一处想的和谐；语法里还有主谓一致的意思。\",\n\"configuration\":\"画面：工程师把零件按图组装成一台机器的整体形态——configuration「构造；配置」。con- + figure『形状』：各部分拼成的整体格局；软件的 configuration file 就是配置文件。\",\n\"conjecture\":\"画面：侦探看着半块脚印，在本子上写下推断、后面打个问号——conjecture「推测；猜测」。con- + ject『抛』：把想法先抛出去、手里还没有证据；哥德巴赫猜想英文就是 Goldbach's conjecture。\",\n\"consensus\":\"画面：会议室里所有人一起点头，没有一只手举反对——consensus「共识」。con- + sens『感觉』（sense 感觉）：大家感觉一致；reach a consensus 达成共识是会议高频句。\",\n\"conservation\":\"画面：护林员在湿地边立起禁止开发的牌子——conservation「保护；保存」。con- + serv『保留』（preserve 保护）：把自然与资源守住不让耗尽；物理里 energy conservation 是能量守恒，看语境。\",\n\"consistency\":\"画面：他每天六点起床跑步，三年没断过——consistency「一致性」。con- + sist『站立』：立得稳、前后不矛盾；也指物质的稠度，如酱汁的 consistency。\",\n\"constituent\":\"画面：一杯混合饮料被拆成基液、果汁、冰块摆成一排——constituent「组成部分」。con- + stitu『设立』：构成整体的每一份；政治里它还是『选民』——设立代表的人。\",\n\"contingency\":\"画面：户外婚礼方案旁边永远备着一顶帐篷的 B 计划——contingency「偶然事件；应急情况」。源于『碰巧发生』：还没发生但可能发生的变数；contingency plan 就是应急预案。\",\n\"continuum\":\"画面：光谱从红渐变到紫，没有一处断口——continuum「连续体；连续统一体」。continu『连续』的名词化：中间没有任何断裂的连续整体；space-time continuum 时空连续体是物理大词。\",\n\"contradiction\":\"画面：同一个人上午说从不说谎，下午就被当场抓包——contradiction「矛盾」。contra-『反对』+ dict『说』：两种说法互相打架；a contradiction in terms 是自相矛盾的说法。\",\n\"conversion\":\"画面：一笔美元在柜台换成一沓欧元——conversion「转换；兑换」。con- + vers『转』（reverse 反转）：从一种形态转成另一种；货币兑换、宗教皈依、单位换算都用它。\",\n\"corollary\":\"画面：大定理刚证完，旁边顺手推出一条不用再证的小结论——corollary「推论；必然结果」。源于拉丁语『小花环』，是给胜利者的添头：由已证命题白送的结论；a natural corollary 自然推论。\",\n\"correlation\":\"画面：散点图上的点排成一条斜线，一个涨另一个也涨——correlation「相关性」。cor- + relation『关系』：两个变量同涨同落的关联；correlation is not causation——相关不等于因果，是统计课名言。\",\n\"criterion\":\"画面：评委手里一张评分表，每一条都是打分的尺子——criterion「标准；准则」。源于希腊语『判断』：用来评判的那把尺；复数是 criteria，单复数混用是考试陷阱。\",\n\"critique\":\"画面：影评人把一部电影的镜头、剧本、表演逐项拆开点评——critique「批评文章；评论」。与 criticism 不同，它是成篇的系统评析；文学课作业常是 write a critique 写一篇评论。\",\n\"crux\":\"画面：整道难题卡在十字路口中央的那一个点上——crux「关键点；症结」。源于拉丁语『十字』：问题交汇的核心处；the crux of the matter 事情的要害。\",\n\"culmination\":\"画面：烟花升到最高点砰地绽开，全场抬头——culmination「顶点；高潮」。源于拉丁语 culmen『山顶』：一路攀升到的最高点；多年努力的 culmination 是成果的高峰时刻。\",\n\"deliberation\":\"画面：陪审团关在小屋里一轮轮讨论，迟迟不出结果——deliberation「审议；深思熟虑」。源于『称量』：把利弊在心里反复称；after much deliberation 深思熟虑之后。\",\n\"delineation\":\"画面：画家用细线把湖岸的轮廓一笔笔勾出来——delineation「描绘；勾勒」。de- + line『线』：用线条把形状描清楚；学术写作里指对概念的清晰界定。\",\n\"dependence\":\"画面：藤蔓离开大树就瘫倒在地，整株都挂在树干上——dependence「依赖」。de- + pend『挂』（pendulum 钟摆）：挂在别人身上过活的状态；与 independence 独立正反相对。\",\n\"deployment\":\"画面：指挥官把棋子般的部队标记推到地图各要点——deployment「部署；调度」。源于『展开』（employ 雇用同源）：把力量展开摆到位；软件 deployment 是上线部署。\",\n\"deprivation\":\"画面：牢房没有窗，一连几周见不到阳光——deprivation「剥夺；匮乏」。de- + priv『剥夺』：本该有的东西被拿走；sleep deprivation 睡眠剥夺是医学高频搭配。\",\n\"derivative\":\"画面：一条曲线旁边长出一条新曲线，由原图的变化率画成——derivative「衍生物；导数」。de- + riv『支流』：从源头分出来的东西；金融衍生品、化学衍生物、数学导数共用它。\",\n\"descent\":\"画面：飞机广播说我们开始下降，机头缓缓压低——descent「下降；血统」。de- + scend『爬』（ascend 上升）：往下走的那条路；of Chinese descent 是华裔，血统一路向下传。\",\n\"description\":\"画面：目击者对着警察把嫌疑人的长相一处处说出来——description「描述；描写」。de- + scrib『写』（scribe 书写员）：用文字把样子写下来；job description 是职位说明。\",\n\"destruction\":\"画面：爆破后整栋楼在烟尘里塌成一堆瓦砾——destruction「破坏；毁灭」。de- + struct『建造』反着来：把建好的拆毁；habitat destruction 栖息地破坏是生态文章的常客。\",\n\"detection\":\"画面：安检仪扫过行李箱，屏幕上亮起可疑阴影——detection「探测；察觉」。de- + tect『遮盖』反着来：把盖住的东西揭出来；early detection 是医学的早发现。\",\n\"determination\":\"画面：她擦掉眼泪盯着终点线说爬也要爬过去——determination「决心；决定」。de- + termin『界限』：把界限划死、不回头；也有『测定』义，如 determination of the value 测定数值。\",\n\"deterrent\":\"画面：院子的告示牌上画着狗头，写着内有恶犬——deterrent「威慑物；制止因素」。de- + terr『吓』（terror 恐惧）：让对方不敢动的东西；nuclear deterrent 核威慑。\",\n\"deviation\":\"画面：飞机偏离航线，仪表上的箭头一点点歪出中心——deviation「偏差；偏离」。de- + via『路』：走离了正路；统计里的 standard deviation 标准差是同源词。\",\n\"devotion\":\"画面：老园丁三十年如一日，天不亮就去照看那片玫瑰——devotion「奉献；忠诚」。de- + vot『誓言』（vote 投票同源）：发过誓般的全身心投入；devotion to duty 恪尽职守。\",\n\"dialect\":\"画面：同是一个土豆，这村叫洋芋、那村叫马铃薯——dialect「方言」。dia- + lect『说』（lecture 讲课）：一个地方一种说法；方言与语言的界线是语言学经典话题。\",\n\"diameter\":\"画面：一把尺横穿圆心，量出圆盘最宽的那条线——diameter「直径」。dia-『穿过』+ meter『量』：穿过圆心的量度，正好是半径 radius 的两倍。\",\n\"dichotomy\":\"画面：一把刀把苹果正中劈成两半，再没有第三块——dichotomy「二分法；一分为二」。dicho-『两半』+ tom『切』（atom 原子是不可切）：非此即彼的两分；false dichotomy 假两难。\",\n\"dictation\":\"画面：老师念一句学生写一句，教室里只剩沙沙声——dictation「听写；口述」。dict『说』（dictator 独裁者）：一个人出口、另一个人落笔；听写是它的课堂义。\",\n\"diction\":\"画面：演讲稿上每个词都被红笔圈改，换成更准的那一个——diction「措辞；用词」。dict『说』的名词面：说话选词的功夫；诗人的 diction 是文学分析的切入点。\",\n\"difference\":\"画面：两张照片并排找不同，圈出五处不一样——difference「差异；差额」。dif- + fer『带』：把两者拉开的那段距离；make a difference 是产生影响、有所作为。\",\n\"diffusion\":\"画面：一滴墨落进清水，蓝色一丝丝晕满整杯——diffusion「扩散」。dif- + fus『流』（fusion 融合）：从一处向四处流散；文化扩散、技术扩散都同理。\",\n\"dignity\":\"画面：老教授衣衫旧却腰板挺直，不卑不亢——dignity「尊严」。源于拉丁语 dignus『值得的』：一个人值得被尊重的那份体面；human dignity 人的尊严是人权文章的底线词。\",\n\"diminution\":\"画面：冰山一年比一年小，老照片和现在完全对不上——diminution「减少；缩小」。di- + minu『小』（minute 微小的）：一点点变少的过程；动词是 diminish。\",\n\"dioxide\":\"画面：化学式 CO₂ 写在黑板上，一个碳抱着两个氧——dioxide「二氧化物」。di-『二』+ oxide『氧化物』：含两个氧原子的化合物；carbon dioxide 二氧化碳是气候文章的主角。\",\n\"direction\":\"画面：指南针的针稳稳指向北，岔路口立着方向牌——direction「方向；指导」。di- + rect『直』（correct 正确的）：指向的那条直线；舞台上的 direction 是导演的调度指令。\",\n\"disability\":\"画面：轮椅标志画在坡道入口，通道比台阶更宽——disability「残疾；障碍」。dis- + ability『能力』：某种能力受限的状态；learning disability 是学习障碍。\",\n\"disagreement\":\"画面：两人对着同一份方案，一个摇头一个点头——disagreement「分歧；意见不合」。dis- + agree『同意』反着来：同意不了的那道缝；有分歧不等于吵架，可以理性讨论。\",\n\"disaster\":\"画面：洪水过后街道成了河，救援船在屋顶间接人——disaster「灾难」。dis- + aster『星』：古人以为灾祸是凶星作祟；natural disaster 自然灾害，a disaster waiting to happen 是迟早要爆的隐患。\",\n\"discernment\":\"画面：鉴赏家在一排仿品里一眼挑出真迹——discernment「洞察力；辨别力」。dis- + cern『筛、分』（certain 确定的）：能把真假好坏筛出来的眼光，靠阅历养成。\",\n\"discourse\":\"画面：学术会议上学者们围绕一个议题接连长篇发言——discourse「论述；话语」。dis- + cours『跑』：思想来回跑动的成篇言论；discourse analysis 话语分析是语言学分支。\",\n\"discrepancy\":\"画面：账本上的数字和库存对不上，差了整整一箱——discrepancy「差异；不一致」。dis- + crep『声响』：两种说法声音对不上；数据 discrepancy 是审计要追的线索。\",\n\"discretion\":\"画面：秘书把会上听到的内容锁进心里，出门只字不提——discretion「谨慎」。源于『分开看清』：看清什么该说什么不该说的分寸；at your discretion 由你自行决定。\",\n\"discussion\":\"画面：圆桌旁每个人轮流发言，问题越辩越明——discussion「讨论」。dis- + cuss『敲击』（percussion 打击乐）：把问题敲打来回的谈；under discussion 在讨论中。\",\n\"disease\":\"画面：显微镜下细菌在培养皿里成团生长——disease「疾病」。dis- + ease『安逸』反着来：身体不安逸就是病；infectious disease 传染病是医学阅读常客。\",\n\"disgrace\":\"画面：作弊被揭穿的选手低着头走下领奖台——disgrace「耻辱；丢脸」。dis- + grace『体面、恩典』反着来：体面尽失；bring disgrace on 是给……抹黑。\",\n\"disguise\":\"画面：侦探戴上假发和墨镜混进人群，谁也认不出——disguise「伪装」。dis- + guise『外表』：换一副外表藏起真身；a blessing in disguise 是塞翁失马式的伪装的好事。\",\n\"displacement\":\"画面：石头扔进量筒，水面涨起来的那段就是它的体积——displacement「位移；移置」。dis- + place『位置』：被挤离原位置的量；阿基米德排水法量的就是它，心理上还有情感转移义。\",\n\"disposal\":\"画面：过期药品被投进专门的回收桶，不敢乱扔——disposal「处理；处置」。dis- + pos『放』：把东西安排掉；at your disposal 听你支配是常用句。\",\n\"disposition\":\"画面：她天生见谁都先笑，生气也超不过三分钟——disposition「性情；倾向」。dis- + pos『摆放』：心里零件的摆放方式就是性情；a cheerful disposition 乐天的性情。\",\n\"dispute\":\"画面：两家对着同一块地界各执一词，闹到要上法庭——dispute「争端；纠纷」。dis- + put『想』：想法对不上的争执；territorial dispute 领土争端是新闻词。\",\n\"disruption\":\"画面：演讲讲到一半突然断电，会场秩序全乱——disruption「中断；扰乱」。dis- + rupt『断裂』（erupt 爆发）：把流程从中打断；disruptive technology 颠覆性技术。\",\n\"dissemination\":\"画面：蒲公英的种子被风带走，落满整片草原——dissemination「传播；散布」。dis- + semin『种子』（seminar 研讨会同源）：像撒种子一样把信息撒出去。\",\n\"dissent\":\"画面：全场举手通过，只有一只手举着反对牌——dissent「异议；不同意见」。dis- + sent『感觉』，正是 consent 同意的反面：感觉不一致发出的声音；法官的 dissenting opinion 是异议意见。\",\n\"dissipation\":\"画面：晨雾在阳光里一点点变薄，最后消失——dissipation「消散；挥霍」。源于拉丁语『散开』：能量或财物慢慢散尽；物理里 energy dissipation 是能量耗散。\",\n\"distance\":\"画面：地图上两座城市之间拉着一条虚线，标着公里数——distance「距离」。di- + st『站』：两点站开的间隔；keep a distance 保持距离，long-distance 是长距离、长途。\",\n\"distortion\":\"画面：哈哈镜里的人又高又瘦，完全不是本人——distortion「扭曲；歪曲」。dis- + tort『扭』（torture 折磨）：把形状或事实扭变形；新闻报道的 distortion 是歪曲事实。\",\n\"disturbance\":\"画面：平静的湖面被石子打破，涟漪一圈圈扩散——disturbance「骚扰；扰动」。dis- + turb『搅』（turbulent 湍流的）：把安宁搅乱的那一下；气象学里 disturbance 是气流扰动。\",\n\"ditch\":\"画面：公路边一条土沟，雨水顺着它流走——ditch「沟渠」。与 dike 堤同源：地面上挖出的长沟；动词义是抛弃，如 ditch a plan 把计划撂下。\",\n\"diversity\":\"画面：一片雨林里藤、鸟、虫、兽各占一层——diversity「多样性」。di- + vers『转』：朝不同方向转出的丰富；biodiversity 生物多样性是生态文章的主词。\",\n\"division\":\"画面：一间大办公室挂起市场、财务、人事几块牌子——division「部门；分开；除法」。di- + vid『分』（individual 个体就是不可分）：分是核心；division of labor 是分工。\",\n\"doctrine\":\"画面：信条被刻在石碑上，一代代人照着行事——doctrine「教义；主义」。源于拉丁语『教导』（doctor 博士同源）：一套成体系的信条；Monroe Doctrine 门罗主义是历史考点。\",\n\"donation\":\"画面：衣物一箱箱搬上卡车，送往灾区——donation「捐赠」。don『给』（donate 捐赠）：无偿给出的财物；blood donation 献血、organ donation 器官捐献都用它。\",\n\"doubt\":\"画面：证人席上的人皱起眉说我不能确定就是他——doubt「怀疑」。源于拉丁语『在两者之间摇摆』（duo 是二）：拿不准时的摇摆；no doubt 是毫无疑问，别看反了。\",\n\"drainage\":\"画面：雨水顺着一整套暗管排走，街道不再积水——drainage「排水；排水系统」。drain『排干』：把水导走的整套系统；drainage basin 是流域。\",\n\"droplet\":\"画面：叶尖上一颗水珠，圆得能照出人影——droplet「小滴」。drop『滴』+ -let『小』（booklet 小册子）：小号的水滴；防疫文章里的 droplet 就是飞沫。\",\n\"dynamite\":\"画面：山体爆破一声巨响，碎石飞起——dynamite「炸药」。源于希腊语 dynamis『力量』：诺贝尔发明的强力炸药；也形容效果炸裂的人或事，如 a dynamite idea 绝妙的主意。\",\n\"earnestness\":\"画面：他说话时身体前倾，眼睛一眨不眨——earnestness「认真；诚挚」。earnest 是『当真』：不是客套的较真；in earnest 是认真的、正式开始的。\",\n\"eccentricity\":\"画面：老教授穿着拖鞋去颁奖礼，口袋里还装着橡皮鸭——eccentricity「古怪；离心率」。ec-『出』+ center『中心』：偏离圆心的怪；天文里轨道的 eccentricity 是偏心率，同源。\",\n\"ecosystem\":\"画面：一块湿地里水、草、鱼、鸟互相咬合转成圈——ecosystem「生态系统」。eco-『环境』+ system『系统』：生物与环境组成的整套循环；ecology 生态学是它的学科名。\",\n\"edge\":\"画面：刀刃在光下闪成一条细线，手指不敢碰——edge「边缘；刀刃」。源于古英语『锋刃』：物体的边线与锋口；on edge 是紧张得坐不住，have an edge over 是胜过一筹。\",\n\"edition\":\"画面：书店里同名书排成一排，第二版封面多了一行修订字样——edition「版本」。源于『出版、给出』：出版一次就是一个 edition；limited edition 是限量版。\",\n\"effectiveness\":\"画面：新药试验里服药组的好转率明显高于对照组——effectiveness「有效性」。effect『效果』的名词化：到底有没有用；与 efficiency 的区别是它问对不对头，效率问省不省。\",\n\"efficiency\":\"画面：新机器一小时干完旧机器三小时的活——efficiency「效率」。ef- + fic『做』：做事的产出投入比；efficient 高效的，fuel efficiency 是燃油经济性。\",\n\"ego\":\"画面：镜子前的人只看得见自己，别人都在画面边缘——ego「自我」。拉丁语就是『我』：弗洛伊德人格三层 id、ego、superego 里的现实自我；口语里 ego 大是自负。\",\n\"ejection\":\"画面：战斗机座舱盖弹开，座椅带着飞行员冲上天——ejection「弹出；喷出」。e- + ject『抛』（reject 拒绝）：被猛力抛出去的动作；eject button 是弹出键。\",\n\"elaboration\":\"画面：一句提纲被他展开成三页纸，细节全补齐——elaboration「详细阐述」。e- + labor『劳动』：下功夫把粗坯加工细；elaborate 既是动词详述，也是形容词精细的。\",\n\"elasticity\":\"画面：橡皮筋拉长三倍，松手立刻缩回原样——elasticity「弹性」。源于希腊语『弹回』：变形后能弹回的性质；经济学里 price elasticity 价格弹性是同名概念。\",\n\"elicitation\":\"画面：访谈者一个问题接一个问题，把专家肚子里的经验掏出来——elicitation「引出；诱出」。e- + lic『引』：把藏着的反应或信息引出来；语言学收集语料的方法就叫 elicitation。\",\n\"eligibility\":\"画面：报名表上年龄、学历两栏都打了勾——eligibility「资格；合格」。源于『挑选』（elect 选举）：够格被选中的条件；eligible 是形容词，有资格的。\",\n\"elimination\":\"画面：淘汰赛名单上的名字一个个被划掉——elimination「消除；淘汰」。e- + limin『门槛』：把东西请出门外；process of elimination 是排除法。\",\n\"elite\":\"画面：选拔营几千人里最后留下的十个人站在台上——elite「精英」。源于法语『被选出的』：各行各业挑出来的尖子；elite athletes 是顶尖运动员。\",\n\"eloquence\":\"画面：台上的人没带稿子，说得台下鸦雀无声又掌声雷动——eloquence「口才；雄辩」。e- + loqu『说』：把话说到人心里去的本事；eloquent 是它的形容词。\",\n\"elucidation\":\"画面：教授把一段晦涩原文逐句讲解，学生恍然大悟——elucidation「阐明；说明」。e- + lucid『明亮的』：把暗处照亮的解释；动词是 elucidate。\",\n\"emancipation\":\"画面：1863 年公告宣读完毕，枷锁当场被砸断——emancipation「解放」。e- + mancip『抓握』：从被攥住的手里放出来；林肯的 Emancipation Proclamation 就是解放宣言。\",\n\"embargo\":\"画面：港口大门落锁，货轮排着队却不许进出——embargo「禁运；禁止贸易」。源于西班牙语『扣押』：官方下令断绝贸易；oil embargo 石油禁运是历史考点。\",\n\"embarkation\":\"画面：乘客排着队踩着舷梯登上大船——embarkation「登船；登机」。em- + bark『船』：上船的那一刻；embark on 还比喻着手一项新事业。\",\n\"embarrassment\":\"画面：他上台才发现裤子拉链没拉，全场目光聚过来——embarrassment「尴尬；窘迫」。源于法语『设下障碍』：进退不得的难堪；an embarrassment of riches 是多到发愁的富余。\",\n\"embellishment\":\"画面：素蛋糕被裱上奶油花边和果粒，一下子华丽起来——embellishment「装饰；润色」。em- + bell『美』（belle 美人）：往好看里加料；给故事加 embellishment 就是添油加醋。\",\n\"embodiment\":\"画面：雕塑家把正义雕成蒙眼持天秤的女子——embodiment「体现；化身」。em- + body『身体』：抽象的东西有了身体；the embodiment of courage 勇气的化身。\",\n\"embrace\":\"画面：久别的母女在机场紧紧抱在一起——embrace「拥抱；欣然接受」。em- + brace『手臂』：用双臂圈住；embrace change 拥抱变化，不只是肢体动作。\",\n\"embryo\":\"画面：显微镜下小小的胚胎，心脏刚刚开始跳动——embryo「胚胎」。em- + bryo『生长』：生命最初几周的形态；in embryo 是萌芽状态的比喻说法。\",\n\"emerald\":\"画面：绿宝石在灯下透出深邃的绿色——emerald「祖母绿；翡翠绿」。源于希腊语 smaragdos：绿色宝石之王；Emerald Isle 翡翠岛是爱尔兰的别称。\",\n\"emigration\":\"画面：一家人提着行李离开故乡的港口，背影越来越小——emigration「移出；移居外国」。e-『出』+ migrate『迁移』：往外走是 emigration，走进来是 immigration，视角决定用词。\",\n\"empiricism\":\"画面：他不信书本上的结论，只认自己实验台上量出的数据——empiricism「经验主义」。源于希腊语『经验』：知识只能来自观察与实验的哲学立场；培根与洛克是代表人物。\",\n\"employment\":\"画面：招聘会散场，他口袋里多了一份录用通知——employment「就业；雇用」。employ『雇用、使用』的名词：有工作可做的状态；full employment 充分就业是经济目标。\",\n\"emptiness\":\"画面：散场后的剧场空无一人，座椅排排对着空舞台——emptiness「空虚；空无」。empty『空的』的名词：物理的空与心里的空都用它。\",\n\"enactment\":\"画面：议长敲下木槌，新法案正式成为法律——enactment「制定；颁布」。en- + act『行动』：把条文变成生效法律的动作；动词 enact 是通过并颁布。\",\n\"enamel\":\"画面：浴缸表面一层光滑坚硬的白釉，敲上去当当响——enamel「搪瓷；牙釉质」。源于『熔铸』：烧结在金属或牙齿表面的硬壳；tooth enamel 是护牙广告的常客。\",\n\"enclosure\":\"画面：牧场四周一圈木栅栏，羊群在里面吃草——enclosure「围地；圈地」。en- + clos『关』（close 关闭）：围起来的那块地；英国历史上的圈地运动就叫 Enclosure Movement。\",\n\"encore\":\"画面：演出结束观众齐声喊再来一个，歌手返场——encore「再演；安可」。法语『再一次』：观众喊出来的返场表演，是演唱会散场前的保留节目。\",\n\"encouragement\":\"画面：跑道边教练喊还差一百米稳住——encouragement「鼓励」。en- + courage『勇气』：往人心里注入勇气；words of encouragement 鼓励的话。\",\n\"encroachment\":\"画面：邻居的院墙一年往外挪一尺，自家地盘越来越小——encroachment「侵占；蚕食」。源于『钩住、抓取』：一点点往别人地界里伸；城市 encroachment on farmland 是侵占农田。\",\n\"encyclopedia\":\"画面：书架上一整排厚重的大书，从 A 到 Z 什么都有——encyclopedia「百科全书」。源于希腊语『通才教育』：把各科知识收齐的工具书；Encyclopaedia Britannica 大英百科是代表。\",\n\"endangerment\":\"画面：化工厂的废水管正对着河流，鱼群翻起白肚——endangerment「危害；危及」。en- + danger『危险』：把人或物种推向危险的行为；endangered species 濒危物种是同源词。\",\n\"endeavor\":\"画面：探险队顶着风雪往极点一步步挪——endeavor「努力；尝试」。源于『尽本分』：郑重其事的努力；奋进号航天飞机 Endeavour 取的就是这个词。\",\n\"endorsement\":\"画面：支票背面签上名字，这笔钱才能转给别人——endorsement「背书；公开支持」。en- + dors『背』（dorsal 背部的）：在背面签字表态；明星的 endorsement 是代言。\",\n\"endurance\":\"画面：马拉松选手在三十五公里处咬牙撑住——endurance「耐力；忍耐」。en- + dur『持久』（durable 耐用的）：撑得久的本事；endurance test 耐力测试。\",\n\"enforcement\":\"画面：交警在路口拦下超速车，罚单当场开出——enforcement「执行；强制」。en- + force『力量』：让规则真正落地的那股力；law enforcement 是执法部门的统称。\",\n\"engagement\":\"画面：他单膝跪地打开戒指盒，她捂着嘴点头——engagement「订婚；参与」。en- + gage『承诺』：许下婚约；课堂上的 engagement 是学生的投入度，军事上是交火。\",\n\"engineer\":\"画面：工程师戴着安全帽在桥墩旁核对图纸——engineer「工程师」。engine『引擎』+ -eer『从事者』：与机器和结构打交道的人；动词义是策划，如 engineer a deal 促成一笔交易。\",\n\"engraving\":\"画面：匠人在铜版上刻出细密线条，印出来是一幅版画——engraving「雕刻版画；雕刻术」。en- + grave『刻』：在硬面上刻图成画的技艺。\",\n\"enhancement\":\"画面：老照片经修复后，褪色的脸重新清晰起来——enhancement「增强；提升」。源于拉丁语『更高』：把原有质量往上提；image enhancement 是图像增强。\",\n\"enigma\":\"画面：一封全是乱码的电报摆在桌上，没人能读懂——enigma「谜；费解的事」。源于希腊语『谜语』：二战德军的 Enigma 密码机就以它命名；a complete enigma 彻底的谜。\",\n\"enjoyment\":\"画面：孩子在喷泉里跑来跑去，笑得停不下来——enjoyment「享受；乐趣」。en- + joy『快乐』：从事情里实实在在得到的快乐；for enjoyment 为了开心。\",\n\"enlargement\":\"画面：小照片放进放大机，投出整面墙的人像——enlargement「扩大；放大」。en- + large『大』：尺寸往大里走；医学里心脏 enlargement 是心脏肥大。\",\n\"enlightenment\":\"画面：烛光被一排镜子接力放大，整间屋子亮起来——enlightenment「启蒙」。en- + light『光』：理性之光照进蒙昧；18 世纪的启蒙运动 the Enlightenment 是历史大词。\",\n\"enmity\":\"画面：两个家族几十年不说话，见面就绕道——enmity「敌意；仇恨」。源于拉丁语 inimicus『敌人』：深入骨髓的对立；与它相对的是 amity 和睦。\",\n\"enormity\":\"画面：站在巨型水坝脚下，人小得像蚂蚁——enormity「巨大；暴行」。e- + norm『规范』：超出常规的程度；既指规模之大，也指罪行之重，如 the enormity of the crime。\",\n\"enrichment\":\"画面：给贫瘠的土壤掺入腐殖质，来年庄稼明显壮了——enrichment「丰富；浓缩」。en- + rich『富』：让成分更丰足；uranium enrichment 铀浓缩是核议题的关键词。\",\n\"ensemble\":\"画面：弦乐四重奏四个人呼吸同步，琴声合成一体——ensemble「合奏团；整体搭配」。法语『一起』：多人成团的整体；服装上 a matching ensemble 是成套搭配。\",\n\"enslavement\":\"画面：锁链拖在地上，人被当作货物标价出售——enslavement「奴役」。en- + slave『奴隶』：把自由人变成奴隶的过程，是废奴史文章的核心词。\",\n\"entertainment\":\"画面：周末的广场上乐队、魔术、小吃摊围满了人——entertainment「娱乐」。源于『让人保持开心』：娱乐产业就是 entertainment industry。\",\n\"enthusiasm\":\"画面：他讲起自己的课题眼睛发亮，语速都快了——enthusiasm「热情；热忱」。源于希腊语『神灵附体』：热到藏不住的劲头；enthusiastic 是形容词，充满热情的。\",\n\"entirety\":\"画面：一整块蛋糕没切，原封不动端上桌——entirety「全部；整体」。entire『整个的』的名词化：in its entirety 是完整无删减地，如读完整本原著。\",\n\"entrance\":\"画面：剧院大门上方亮着灯，人流正往里涌——entrance「入口；进入」。enter『进入』的名词：进门的地方；重音移到后面读 en-TRANCE 时是动词使入迷。\",\n\"entry\":\"画面：词典里每个词都是一小段独立的条目——entry「条目；参赛」。enter 的名词面：写进名录的一条；日记 entry、词条 entry、参赛 entry 都用它。\",\n\"environs\":\"画面：古城墙外一圈村镇和田野，都算它的地界——environs「周边地区；近郊」。源于法语『周围』：城市边缘的一圈地带，常用复数形式 environs。\",\n\"envoy\":\"画面：使节带着国书走进对方宫廷，双手呈上——envoy「使节；使者」。源于法语『被派出去的人』：代表国家出面交涉的人；特使是 special envoy。\",\n\"envy\":\"画面：看着同事升职，他手里的咖啡突然不香了——envy「嫉妒；羡慕」。源于拉丁语『斜眼看』：别人有我没有时的酸；与 jealousy 的区别是 envy 更侧重想要同样的东西。\",\n\"epilogue\":\"画面：小说最后一页写着故事结束十年后小镇的模样——epilogue「结尾；后记」。epi-『在…之后』+ log『言』：正文之后补的那段话，是序言 prologue 的对头。\",\n\"episode\":\"画面：连续剧播到第十二集，结尾又留了个悬念——episode「插曲；一集」。epi- + 进入：插进主线的一段；电视剧的一集、人生的一段经历都叫 episode。\",\n\"epitaph\":\"画面：墓碑上刻着一行字，概括了逝者的一生——epitaph「墓志铭」。epi- + taph『坟墓』：刻在墓上的短文；牛顿的墓志铭是科学史名篇。\",\n\"epitome\":\"画面：他把那种刻板印象全集齐了，一眼就能看穿——epitome「缩影；典型」。epi- + tom『切』：切出来的精华样本；the epitome of elegance 优雅的典范。注意读音 ih-PIT-uh-mee。\",\n\"epoch\":\"画面：史书翻开新的一章，一个时代落幕另一个开始——epoch「纪元；时代」。以某件大事为界的新时期；an epoch-making event 是划时代的事件。\",\n\"equality\":\"画面：天平两端完全持平，不偏一克——equality「平等」。equal『相等的』的名词：权利与机会的等齐；gender equality 性别平等是社会议题常客。\",\n\"equipment\":\"画面：实验室的仪器、试剂、防护服整齐码放——equipment「设备；装备」。equip『装备』的名词总量，不可数，没有 equipments 这个复数；a piece of equipment 一件设备。\",\n\"equity\":\"画面：分蛋糕不只看大小，还照顾谁更饿——equity「公平；公正」。equal 是数值相等，equity 是按理应得的公平；金融里 equity 还指股东权益。\",\n\"era\":\"画面：蒸汽机轰鸣，工厂取代了手工作坊——era「时代；年代」。源于拉丁语『纪年起点』：以某种特征命名的一大段历史；the digital era 数字时代。\",\n\"eradication\":\"画面：天花病毒在全球被扫清，1980 年世卫组织宣布灭绝——eradication「根除；消灭」。e- + radic『根』（radish 萝卜）：连根拔除；eradicate polio 根除小儿麻痹症。\",\n\"erasure\":\"画面：黑板上的字被板擦一过，只剩淡淡白影——erasure「擦除；删去」。e- + ras『刮』（razor 剃刀）：把痕迹刮掉的动作；数据 erasure 是彻底删除。\",\n\"erection\":\"画面：工地上的塔吊把钢梁一根根立起来——erection「竖立；建造」。e- + rect『直』：把东西直立起来的工程义；纪念碑的 erection 是落成竖立。\",\n\"errand\":\"画面：妈妈塞给他一张清单，去巷口买酱油和葱——errand「差事；跑腿」。源于古英语『使命』：出门替人办一件小事；run an errand 是跑一趟腿。\",\n\"escalation\":\"画面：两个人的争吵从瞪眼升级到摔门——escalation「升级；逐步扩大」。源于 scala『梯子』：一级一级往上爬的紧张；贸易摩擦的 escalation 是新闻词。\",\n\"escape\":\"画面：囚犯趁夜色翻过围墙，探照灯扫了个空——escape「逃跑；逃避」。相传源于『把斗篷留在追兵手里脱身』：金蝉脱壳式的跑掉；键盘上的 Esc 键就是它。\",\n\"essence\":\"画面：一大瓶香水蒸馏到最后只剩几滴浓缩香精——essence「本质；精华」。源于拉丁语 esse『存在』：事物最核心的那一点；in essence 是本质上、说到底。\",\n\"establishment\":\"画面：奠基石被砌进墙角，公司正式挂牌——establishment「建立；机构」。establish『建立』的名词：既指建立的动作，也指成规模的机构，如 a medical establishment 医疗机构。\",\n\"esteem\":\"画面：老工匠退休那天，全厂人起立鼓掌——esteem「尊重；敬重」。源于拉丁语『估价』：在心里给人高估值的敬意；self-esteem 是自尊，hold in high esteem 是敬重。\",\n\"estrangement\":\"画面：曾经无话不谈的兄弟，如今过年也只发一条群发消息——estrangement「疏远」。e- + strange『陌生』：亲密关系变陌生的过程；夫妻间的 estrangement 是感情疏离。\",\n\"estuary\":\"画面：大河在入海口张开成喇叭口，淡水与海水交汇——estuary「河口湾」。源于拉丁语『潮汐』：河海交汇的宽阔水口；长江口、泰晤士河口都是 estuary，生态富集。\",\n\"etching\":\"画面：酸液在铜版上咬出线条，印出的画细如发丝——etching「蚀刻版画」。源于『腐蚀』：用酸在金属版上蚀刻的版画技法；伦勃朗的 etching 是版画史高峰。\",\n\"eternity\":\"画面：钟表的指针停了，时间却没有尽头——eternity「永恒」。把『时代』拉到无限长：没有终点的时间；口语里 an eternity 是漫长的等待。\",\n\"baker\":\"画面：面包师凌晨四点开炉，第一批面包的香气飘上街——baker「面包师」。bake『烘烤』+ -er：把面团烤成面包的人；a baker's dozen 是面包师的一打，等于 13 个。\",\n\"banker\":\"画面：银行家在玻璃幕墙的办公室里审阅贷款文件——banker「银行家」。bank『银行』+ -er：经营银行业的高层人士；普通柜员是 clerk，不是 banker。\",\n\"captain\":\"画面：队长站在队伍最前面，袖标戴在左臂——captain「队长；船长；机长」。源于拉丁语 caput『头』：一队人的头；船上、飞机上、军队里带队的都叫 captain。\",\n\"carpenter\":\"画面：木匠的刨子推过木板，卷起薄薄的刨花——carpenter「木匠」。源于拉丁语『马车匠』：跟木头打交道的手艺人。\",\n\"chairman\":\"画面：主席敲下小木槌，会议正式开始——chairman「主席」。chair『椅子』+ man：坐主位主持会议的人；现在多用更中性的 chair 或 chairperson。\",\n\"champion\":\"画面：冠军举起奖杯，彩带从天而降——champion「冠军」。源于拉丁语『战场』：赛场上赢到最后的人；动词义是捍卫，如 champion a cause 为事业奔走。\",\n\"chef\":\"画面：主厨在出餐口尝一口汤，点头才准端走——chef「主厨」。法语『头、首领』：厨房里的头儿；与 cook 的区别是 chef 专业且带团队。\",\n\"consultant\":\"画面：顾问翻开企业的报表，指出问题出在哪一页——consultant「顾问」。consult『咨询』+ -ant：出主意收费的专家；英式英语里 consultant 还指主任医师。\",\n\"devil\":\"画面：魔鬼在十字路口提出交易，用灵魂换一切——devil「魔鬼」。源于希腊语『诽谤者』：邪恶的化身；习语 speak of the devil 是说曹操曹操到。\",\n\"diplomat\":\"画面：外交官在谈判桌两端之间来回传递立场——diplomat「外交官」。源于希腊语『折叠的文件』即国书：代表国家打交道的人；说话圆融也形容为 diplomatic。\",\n\"driver\":\"画面：司机握紧方向盘，卡车在夜色里赶路——driver「司机」。drive『驾驶』+ -er：开车的人；电脑里的 driver 是驱动程序，同一个带动者的逻辑。\",\n\"duke\":\"画面：公爵的城堡立在领地中央，纹章挂在门楣上——duke「公爵」。源于拉丁语 dux『领袖』：贵族爵位里仅次于王室的一级；英国 duke 的领地叫 duchy。\",\n\"electrician\":\"画面：电工站在梯子上接电线，用电笔测出哪根带电——electrician「电工」。electric『电的』+ -ician『从业者』，与 musician 音乐家同款后缀：专管电路的人。\",\n\"emperor\":\"画面：皇帝坐在龙椅上，殿下百官跪拜——emperor「皇帝」。源于拉丁语『统帅』：帝国之主，位阶高于 king；拿破仑称帝、明治天皇都是 emperor。\",\n\"empress\":\"画面：女皇批阅奏折到深夜，印章重重落下——empress「女皇」。emperor 的女性形式：常指执政的女性君主，如武则天、叶卡捷琳娜大帝。\",\n\"ethnicity\":\"画面：人口普查表上有一栏，让人填写自己的族裔——ethnicity「种族性；族裔归属」。源于希腊语 ethnos『民族』：一个人所属族群的身份属性；ethnic 是形容词，族裔的。\",\n\"ethos\":\"画面：一所百年老校没写在墙上的规矩，人人却都遵守——ethos「精神特质；风气」。源于希腊语『性格、习惯』：一个群体共有的气质与信条；校园 ethos、职业 ethos 都用它。\",\n\"etiquette\":\"画面：餐桌上刀叉从外向内取用，没人出声提醒——etiquette「礼仪；礼节」。源于法语『小标签』：宫廷里贴出来的规矩清单；餐桌 etiquette、网络 etiquette 都有成套规矩。\",\n\"etymology\":\"画面：词典里每个词条后面都跟着它的出生地和旅行路线——etymology「词源学」。etym『真实』+ log『言』：追查一个词真正来历的学问；词根记忆法靠的就是它。\",\n\"eulogy\":\"画面：葬礼上老友哽咽着念完悼词，讲的全是逝者的好——eulogy「颂词；悼词」。eu-『好』+ log『言』：专说好话的正式演讲；婚礼祝酒词与悼词都属于它。\",\n\"euphemism\":\"画面：不直说去世，改说去了更好的地方——euphemism「委婉语」。eu-『好』+ phem『说』：把刺耳的话说得好听；passed away 代替 died 是经典例子。\",\n\"euthanasia\":\"画面：绝症病人只剩痛苦，家人围在病床边讨论最艰难的决定——euthanasia「安乐死」。eu-『好』+ thanatos『死』：字面是安然的死；伦理与法律上的争论从未停过。\",\n\"evacuation\":\"画面：火山预警响起，整村人连夜撤往山外——evacuation「疏散；撤离」。e- + vacu『空』（vacuum 真空）：把危险区撤空；动词是 evacuate。\",\n\"evasion\":\"画面：记者连问三遍，他都绕开问题去谈天气——evasion「逃避；规避」。e- + vad『走』：绕着走开；tax evasion 是逃税，它的法律面。\",\n\"eventuality\":\"画面：活动方案最后一页写着若下雨转室内——eventuality「可能性事件；不测」。event『事件』的延伸：可能发生的那种情况；prepare for every eventuality 是做好万全准备。\",\n\"evil\":\"画面：童话里的大反派笑着把全城的光都掐灭——evil「邪恶」。善的对极；the lesser of two evils 是两害相权取其轻。\",\n\"evolution\":\"画面：从鱼到两栖再到哺乳，化石一层层排成链——evolution「演化；进化」。e- + volu『卷』（volume 卷册）：像卷轴展开一样渐变；达尔文的 evolution 是生物文章的根。\",\n\"exactness\":\"画面：钟表匠把误差控制在一秒以内，分毫不让——exactness「精确」。做到一丝不差的程度；科学测量追求的就是 exactness。\",\n\"exaggeration\":\"画面：他说钓到的鱼有胳膊那么长，比划时手越张越大——exaggeration「夸张」。往上加堆的说法；not an exaggeration to say 是毫不夸张地说。\",\n\"exaltation\":\"画面：获奖消息传来，整个科室的人都欢呼起来——exaltation「赞誉；兴高采烈」。ex- + alt『高』（altitude 高度）：被捧到高处的激动，既有颂扬义也有情绪高涨义。\",\n\"examination\":\"画面：医生拿着听诊器从头到脚细细检查——examination「检查；考试」。既是试卷上的考试，也是身体的 medical examination，看语境分。\",\n\"example\":\"画面：老师讲完规则，立刻在黑板上写出一道同款题——example「例子」。源于拉丁语『取出的样本』：从一堆里取出来作示范的那个；set an example 是树立榜样。\",\n\"excellence\":\"画面：这所学校几十年里每一届都名列前茅——excellence「卓越」。高出平均线一大截的好；a center of excellence 是卓越中心。\",\n\"exception\":\"画面：全班都穿校服，只有他穿着自己的外套——exception「例外」。ex- + cept『取』：被单独取出来不算数的那个；例外恰能反证规则的存在。\",\n\"excess\":\"画面：行李箱超重，秤上的数字红得刺眼——excess「过剩；过量」。ex- + cess『走』：走过头的那部分；excess baggage 超额行李，in excess of 超过。\",\n\"excitement\":\"画面：过山车爬到最高点，全车人屏住呼吸——excitement「兴奋；激动」。ex- + cit『唤起』：情绪被唤起的高点；cause great excitement 是引起轰动。\",\n\"exclamation\":\"画面：他看见海豚跃出水面，脱口而出一声惊叹——exclamation「感叹；惊呼」。ex- + clam『喊』（claim 声称）：喊出口的惊叹；感叹号 exclamation mark 就以它命名。\",\n\"exclusion\":\"画面：名单贴出来，所有人都在上面，唯独没有他的名字——exclusion「排斥；排除」。ex- + clud『关』：被关在门外的状态；social exclusion 社会排斥是社会学词。\",\n\"excrement\":\"画面：草原上动物的粪便被甲虫滚成球推走——excrement「排泄物；粪便」。ex- + cern『筛分』：身体筛出去的废物；生态学里它是能量循环的一环。\",\n\"excursion\":\"画面：周末一车人开去郊外湖边野餐，当天往返——excursion「远足；短途旅行」。ex- + curs『跑』：跑出去一圈就回的短程；school excursion 是学校组织的郊游。\",\n\"excuse\":\"画面：他迟到了，站在门口飞快地编理由——excuse「借口；理由」。ex- + caus『原因』：为自己找的那个原因；名词重音在后，读 ex-CUSE，make excuses 是找借口。\",\n\"exemplar\":\"画面：全班传看的那本作文，被老师批了范文两个字——exemplar「典范；范本」。与 example 同一家：被挑出来当标准的样本；品行上的 exemplar 是楷模。\",\n\"exemption\":\"画面：他的名字在缴费名单旁边标着免缴——exemption「豁免；免除」。ex- + empt『拿』：被从义务名单里拿出来的待遇；tax exemption 是免税。\",\n\"exertion\":\"画面：他扛着箱子爬五楼，额头青筋都鼓起来——exertion「努力；用力」。把力气使出来的过程；physical exertion 是体力消耗。\",\n\"exhalation\":\"画面：冬晨呵出一口气，白雾在面前散开——exhalation「呼气」。ex- + hal『呼吸』，正是 inhale 吸入的反面：把肺里的气送出去；呼吸一循环就是 inhalation 加 exhalation。\",\n\"exhaustion\":\"画面：跑完马拉松他直接躺倒在草坪上动不了——exhaustion「精疲力竭；耗尽」。ex- + haust『汲水』：像井被抽干一样干透；资源 exhaustion 是资源枯竭。\",\n\"exhilaration\":\"画面：冲浪者踩着浪尖冲下，忍不住大喊——exhilaration「兴奋感；畅快」。ex- + hilar『欢笑』（hilarious 爆笑的）：乐到发飘的感觉；速度与高空最容易触发它。\",\n\"exhortation\":\"画面：出征前将军站在高台上喊话，士兵齐声回应——exhortation「劝告；激励」。ex- + hort『催促』：带着力度的劝勉；教练的赛前 exhortation 就是动员令。\",\n\"exile\":\"画面：诗人抱着手稿离开故国，船越开越远——exile「流放；流亡」。源于拉丁语 exilium『流放』（词源后半尚无定论）：被迫离乡的惩罚；拿破仑被流放到圣赫勒拿岛是历史名场面。\",\n\"existence\":\"画面：深海探测器拍下从没见过的发光鱼，证明它真实存在——existence「存在」。ex- + sist『站立』：站立于世界之中的状态；come into existence 是诞生、出现。\",\n\"exit\":\"画面：影院散场，绿色指示灯下的门被人推开——exit「出口」。ex-『出』+ it『走』：走出去的门；高速公路的 exit 是出口匝道，exit strategy 是退出策略。\",\n\"exodus\":\"画面：长长的队伍拖着行李离开城市，望不到尾——exodus「大批离开；出走」。ex- + hodos『路』：源于《出埃及记》的大迁徙；人才 exodus 是人才外流。\",\n\"expansion\":\"画面：连锁店地图上的红点一年比一年多——expansion「扩张；膨胀」。ex- + pand『展开』：地盘或体积往外长；气体受热的 expansion、经济 expansion 都用它。\",\n\"expectancy\":\"画面：产房外一家人盯着门上的灯，等新生命降临——expectancy「预期；期望」。ex- + spect『看』：望着等的那份期盼；life expectancy 是预期寿命，高频搭配。\",\n\"expectation\":\"画面：他把目标定在九十分，结果出来前一直惦记——expectation「期望；预期」。比 expectancy 更指具体的预期值；meet expectations 是达到预期。\",\n\"expedience\":\"画面：明知绕路不光彩，但赶时间只能抄近道——expedience「权宜；方便」。脚下最顺的那条路；政治上的 expediency 是权宜之计，不问对错只问管用不管用。\",\n\"expedition\":\"画面：一支队伍带着仪器向南极内陆进发——expedition「远征；考察」。ex- + ped『脚』：迈开脚的长途行动；科学 expedition 是科考，军事 expedition 是远征。\",\n\"experience\":\"画面：老船员看一眼云就知道风暴要来——experience「经验」。ex- + peri『尝试』（experiment 实验同源）：亲身试过攒下的本事；也可指一次具体的经历。\",\n\"expertise\":\"画面：修复古画的人屏住呼吸，笔尖只动毫米——expertise「专长；专门知识」。expert『专家』的名词：某个领域深到家的功夫；area of expertise 是专长领域。\",\n\"expiration\":\"画面：牛奶盒上的日期过了，奶只能倒进水槽——expiration「到期；过期」。ex- + spir『呼吸』：气息断了期限就到了；expiration date 是保质期截止日。\",\n\"explanation\":\"画面：老师把公式拆成三步，台下终于点头——explanation「解释；说明」。ex- + plan『摊平』：把卷着的道理摊平摆开；a detailed explanation 详细解释。\",\n\"exploitation\":\"画面：矿工每天干十四小时，工资却少得可怜——exploitation「剥削；开发利用」。把资源或人力用到尽：用在资源上是中性的开发，用在人身上是贬义的剥削。\",\n\"exploration\":\"画面：潜水器打着灯，缓缓驶进从未有人到过的海沟——exploration「探索；勘探」。向未知处摸索；太空 exploration、石油 exploration 都用它。\",\n\"explorer\":\"画面：探险家划着小船驶进地图上的空白区——explorer「探险家」。ex- + plor『探寻』：去未知之地的人；大航海时代的 explorer 改写了世界地图。\",\n\"explosion\":\"画面：气球胀到极限砰一声碎片四溅——explosion「爆炸」。瞬间释放的巨响；population explosion 是人口激增的比喻。\",\n\"explosive\":\"画面：仓库门口画着骷髅标志，写着易爆品——explosive「炸药；爆炸性的」。explosion 的名词面：能爆的物质总称；形容性情 explosive 是火爆易怒。\",\n\"exposure\":\"画面：胶片在暗房的灯光下，影像慢慢显形——exposure「暴露；曝光」。ex- + pos『放』：把东西放到光天化日之下；媒体 exposure 是曝光度，cold exposure 是暴露于寒冷。\",\n\"expression\":\"画面：她听到消息时眉头一挑，什么都写在脸上——expression「表达；表情」。ex- + press『压』：把心里的东西压出来；facial expression 面部表情，代数里的 expression 是式子。\",\n\"expropriation\":\"画面：政府修路征地，文件送到农户手里签字——expropriation「征用；没收」。ex- + propri『自有』（property 财产）：把私有财产收归公有；补偿是否公平是争议点。\",\n\"extension\":\"画面：老房后面接出一间小屋，面积大了三分之一——extension「扩展；延期；分机」。ex- + tens『拉伸』：往外拉长的一截；电话的 extension 是分机号，文件 extension 是扩展名。\",\n\"extent\":\"画面：洪水淹到哪里，地图上就涂红到哪里——extent「范围；程度」。ex- + tent『拉伸』：拉伸到的边界；to a large extent 是在很大程度上，高频句型。\",\n\"exterior\":\"画面：老宅外墙爬满藤蔓，里面却收拾得干净——exterior「外部；外观」。exter『外面的』：朝外的那一面；与 interior 内部成对，建筑与汽车都用。\",\n\"extermination\":\"画面：白蚁把木屋蛀空后，灭虫队进场彻底清除——extermination「灭绝；根除」。ex- + termin『终结』：把某种生物清零；灭虫的 extermination 与物种灭绝语境不同，注意对象。\",\n\"externality\":\"画面：工厂排烟自己省了钱，治污的账却记在全城人头上——externality「外部性」。external『外部的』的名词：成本或好处漏到交易之外的人身上；负外部性是经济学经典考点。\",\n\"extinguisher\":\"画面：墙上挂着红色钢瓶，拉环一拔白雾喷出——extinguisher「灭火器」。全称 fire extinguisher；干粉、泡沫都是它的型号。\",\n\"extraction\":\"画面：牙医用钳子稳稳夹住坏牙，慢慢拔出——extraction「拔出；提取」。ex- + tract『拉』（tractor 拖拉机）：把东西从里面拉出来；数据 extraction、精油 extraction 同理。\",\n\"extravagance\":\"画面：婚礼包下整个岛，烟花放了整整一夜——extravagance「奢侈；挥霍」。extra-『超出』+ vag『漫游』：花钱漫出了边界；extravagant 是形容词，奢侈的。\",\n\"extremity\":\"画面：探险者冻伤的指尖发黑，那是身体的最末端——extremity「极端；末端」。extrem『最外』：既指身体末端的手脚，也指处境到了极点，如 in extremity 危急关头。\",\n\"extremum\":\"画面：曲线爬到峰顶又跌入谷底，两个点被红笔圈出——extremum「极值」。函数的最大值与最小值的统称；微积分求 extremum 是常规题。\",\n\"extrication\":\"画面：救援人员用液压剪剪开变形的车门，把司机拉出来——extrication「解救；脱身」。ex- + tric『纠缠』（intricate 错综复杂）：从纠缠的困境里解脱出来，是事故救援的专业词。\",\n\"exuberance\":\"画面：小狗第一次见到雪，在雪地里疯跑打滚——exuberance「热情洋溢；繁茂」。多到溢出来的活力；形容植物 exuberant 是枝繁叶茂。\",\n\"exultation\":\"画面：夺冠哨响，全队把队长抛向空中——exultation「欢欣；狂喜」。ex- + sal『跳』：高兴得要跳起来；胜利时刻的 exultation 藏不住。\",\n\"eyebrow\":\"画面：她听到报价时一边眉毛高高挑起——eyebrow「眉毛」。eye + brow『眉骨』：眼睛上方的那道毛；raise an eyebrow 是挑眉，表示惊讶或不以为然。\",\n\"eyelash\":\"画面：一根睫毛落在脸颊上，他轻轻把它吹走许愿——eyelash「睫毛」。eye + lash『鞭梢』：眼睑边的一排细毛；假睫毛是 false eyelashes。\",\n\"eyelid\":\"画面：困意袭来，眼皮一点点往下坠——eyelid「眼皮」。eye + lid『盖子』，和锅盖是同一个 lid：眼睛的盖子；眼皮跳是 eyelid twitch。\",\n\"eyesight\":\"画面：视力表最后一行的小字，他眯着眼也看不清——eyesight「视力」。eye + sight『看见』：眼睛看东西的能力；poor eyesight 视力差，与 vision 的视野、远见侧重不同。\",\n\"farmer\":\"画面：农民在田里扶着犁，身后是整齐的垄沟——farmer「农民」。farm『农场』+ -er：在土地上耕作的人；与 peasant 不同，farmer 是现代农业的经营者。\",\n\"firefighter\":\"画面：消防员抱着水枪冲进浓烟，身后是熊熊火光——firefighter「消防员」。fire + fighter『战斗者』：与火作战的人；旧称 fireman，现在多用中性的 firefighter。\",\n\"god\":\"画面：神庙高处，信徒抬头仰望神像——god「神」。被崇拜的至高存在；小写 god 指多神教的神，大写 God 特指一神教的上帝。\",\n\"goddess\":\"画面：女神像手持麦穗，站在丰收的田野中央——goddess「女神」。god + -ess 女性后缀，与 actress 同款：女性神祇；雅典娜、维纳斯都是 goddess。\",\n\"guard\":\"画面：警卫站在金库门口，目光扫过来往的人——guard「警卫；守卫」。守门护院的人；bodyguard 保镖、lifeguard 救生员都是 guard 一家。\",\n\"hero\":\"画面：英雄从火场里抱出孩子，人群爆发出掌声——hero「英雄」。源于希腊语：危难中挺身而出的人；文学里 hero 也指男主角，与 heroine 相对。\",\n\"heroine\":\"画面：女英雄站在城墙上指挥守城——heroine「女英雄；女主角」。hero 的女性形式：小说电影的女主角也叫 heroine；与毒品 heroin 只差一个字母，别混。\",\n\"investigator\":\"画面：调查员蹲在地上，用放大镜看脚印的方向——investigator「调查员」。in- + vestig『足迹』：循着足迹查真相的人；private investigator 是私家侦探。\",\n\"janitor\":\"画面：看门人提着一大串钥匙，逐层关灯锁门——janitor「看门人；管理员」。源于拉丁语 Janus『门神』：管门与楼宇杂务的人，学校的 janitor 还负责维修清洁。\",\n\"king\":\"画面：国王戴着王冠坐在宝座上，权杖在手——king「国王」。一国的君主；国际象棋里的 king 被将死就输了全盘。\",\n\"librarian\":\"画面：图书管理员推着小车，把归还的书一本本上架——librarian「图书管理员」。libr『书』（library 图书馆）：管书的人；后缀 -arian 表示从事某种行当的人。\",\n\"mechanic\":\"画面：技工从车底滑出来，手上沾满机油——mechanic「机械技工」。源于希腊语『机器』：修机器的人；与 mechanics 力学同根，一个是人，一个是学问。\",\n\"miner\":\"画面：矿工头灯的光在漆黑的巷道里晃动——miner「矿工」。mine『矿』+ -er：在地下采掘的人；mineral 矿物是它的亲戚。\",\n\"murderer\":\"画面：侦探小说里所有人都在猜凶手到底是谁——murderer「凶手」。murder『谋杀』+ -er：实施谋杀的人；注意 murder 是蓄意杀人，过失杀人是 manslaughter。\",\n\"musician\":\"画面：音乐家闭着眼拉小提琴，整个人跟着旋律晃——musician「音乐家」。music『音乐』+ -ician：演奏或创作音乐的专业人士。\",\n\"painter\":\"画面：画家退后两步眯眼看画布，再补上一笔——painter「画家；油漆工」。paint『绘画』+ -er：以画为业的人；house painter 是刷墙的油漆工，看语境。\",\n\"passenger\":\"画面：乘客拖着箱子在登机口排队检票——passenger「乘客」。源于 passage『通行』：搭乘交通工具出行的人；passenger seat 是副驾驶座。\",\n\"pharmacist\":\"画面：药剂师核对处方，数好药片装进小瓶——pharmacist「药剂师」。源于希腊语 pharmakon『药物』：在药房配药发药的专业人员；pharmacy 是药房。\",\n\"pilot\":\"画面：飞行员推动油门杆，飞机加速冲上跑道——pilot「飞行员」。源于希腊语『舵』：掌舵飞行的人；也可指领航员，pilot program 是试点项目。\",\n\"pioneer\":\"画面：先驱者走在无人走过的荒原上，身后才渐渐有了路——pioneer「先驱；拓荒者」。源于法语『先行者』：第一个吃螃蟹的人；科学领域的 pioneer 是开山鼻祖。\",\n\"plumber\":\"画面：水管工钻进水槽底下，用扳手拧紧漏水的接口——plumber「水管工」。源于拉丁语 plumbum『铅』：古代水管是铅做的，管道一漏就找他。\",\n\"prince\":\"画面：王子骑着白马穿过城门，卫兵行礼——prince「王子」。源于拉丁语 princeps『第一人』：君主之子；马基雅维利《君主论》的英文名 The Prince 就是它。\",\n\"princess\":\"画面：公主在舞会上旋转，长裙像花瓣散开——princess「公主」。prince + -ess：王室的女儿；童话里的 princess 是小读者认识的第一个王室词。\",\n\"queen\":\"画面：王后走过红毯，宝石在灯下闪烁——queen「王后；女王」。king 的女性对应：可以是国王的妻子，也可以是执政的女王。\",\n\"referee\":\"画面：裁判哨响掏出黄牌，全场都看着他的手势——referee「裁判」。refer『提交裁断』：被双方共同推举作裁断的人；学术期刊的 referee 是审稿人。\",\n\"robber\":\"画面：强盗蒙着面冲进银行，大喊不许动——robber「强盗」。rob『抢劫』+ -er：明火执仗抢的人；与 thief 的区别是 robber 用暴力或威胁当面抢。\",\n\"sailor\":\"画面：水手站在桅杆旁拉帆，咸风灌满衣袖——sailor「水手」。sail『帆、航行』+ -or：在船上干活的人；海军水兵也叫 sailor。\",\n\"scientist\":\"画面：科学家在实验室里记录数据，试管排成一列——scientist「科学家」。sci『知』（science 科学）：以实验求知为职业的人。\",\n\"secretary\":\"画面：秘书把会议纪要打成文稿，按轻重缓急排好——secretary「秘书」。源于拉丁语『保密』：替上司管文书、守秘密的人；Secretary of State 是国务卿，级别完全不同。\",\n\"singer\":\"画面：歌手握着麦克风唱到高音，全场起鸡皮疙瘩——singer「歌手」。sing『唱』+ -er：以歌声为业的人；lead singer 是主唱。\",\n\"thief\":\"画面：小偷踮着脚从窗口翻出，手里攥着首饰盒——thief「小偷」。偷偷摸摸拿人东西的人；复数是 thieves，对应的动词概念是 steal。\",\n\"tourist\":\"画面：游客举着自拍杆在地标前合影——tourist「游客」。tour『巡游』+ -ist：为游览而旅行的人；tourist attraction 是旅游景点。\",\n\"veterinarian\":\"画面：兽医给小狗听诊，主人抱着它轻声安抚——veterinarian「兽医」。源于拉丁语『牲畜』：给动物看病的医生；常简称为 vet，与老兵 vet 同形不同义。\",\n\"villain\":\"画面：恶棍在暗处冷笑，计划又被主角搅黄——villain「恶棍；反派」。源于拉丁语『农庄仆役』，词义一路变贬：故事里干坏事的人；英雄片的 villain 越强，戏越好看。\",\n\"visitor\":\"画面：参观者举着相机在展厅里慢慢走——visitor「参观者；访客」。visit『访问』+ -or：来访的人；博物馆的 visitor、网站的 visitor 访客量都用它。\",\n\"witch\":\"画面：女巫骑着扫帚掠过月亮，尖顶帽压得低低的——witch「女巫」。童话与万圣节的常客；witch hunt 猎巫行动，比喻无端迫害。\",\n\"ability\":\"画面：举重台上，选手稳稳把杠铃举过头顶——ability「能力」。able『能』的名词形：能做成某件事的本事；the ability to do sth 是托福写作高频搭配。\",\n\"abnormality\":\"画面：体检报告上一个指标飘红，箭头远远偏出正常范围——abnormality「异常」。ab-（偏离）+ norm（规范）：偏离正常的东西；normal 的反面就是 abnormal。\",\n\"absurdity\":\"画面：一个人给鱼撑伞防雨，全街人看傻了眼——absurdity「荒谬」。absurd『荒唐的』+ -ity：不合逻辑到可笑的程度；荒谬的事听着就像荒诞剧。\",\n\"abyss\":\"画面：站在悬崖边往下望，黑得看不见底，手电光都被吞掉——abyss「深渊」。希腊语 a-（无）+ byssos（底）：无底之洞；常用比喻义是绝境，如 stare into the abyss。\",\n\"academy\":\"画面：柏拉图在他雅典的学园里边散步边讲学——academy「学院」。词源就是柏拉图讲学的园子 Academus；现在的 academy 多指专科院校或学会，如军事科学院。\",\n\"accent\":\"画面：两个人说同一句英语，一个带着浓浓的苏格兰味——accent「口音」。ad- + cant（唱）：说话自带的『调子』；也指重音符号，说哪儿的人一听口音就知道。\",\n\"acceptance\":\"画面：录取通知书拆开，『我们很高兴录取你』映入眼帘——acceptance「接受」。accept『接受』+ -ance：被接收、被认可这件事本身；大学的 acceptance letter 就是录取信。\",\n\"access\":\"画面：刷门禁卡，绿灯亮起，门咔哒一声开——access「通道；使用权」。ac- + cess（走）：能走进去的路；have access to 是『能接触到』，托福听力常考。\",\n\"accident\":\"画面：路口两车轻轻一蹭，司机下车交换保险信息——accident「事故」。词里藏着 cad『落下』：祸从天降般偶然发生的事；by accident 是『偶然地』。\",\n\"acclaim\":\"画面：新书发布，全场起立鼓掌，报纸头条全是好评——acclaim「赞誉」。ac- + claim（喊）：众人齐声叫好；critical acclaim 是评论界的一致好评。\",\n\"accommodation\":\"画面：出差订的酒店房间，床铺整洁，窗外是陌生城市的灯——accommodation「住宿」。accommodate 本义『使适应、容纳』：人住下被『容纳』的地方就是住所；常作复数 accommodations。\",\n\"accompaniment\":\"画面：歌手在台前唱，钢琴在身后轻轻垫着和弦——accompaniment「伴奏」。accompany『陪伴』的名词形：音乐里陪着主旋律走的那一部分；也可指伴随物。\",\n\"accord\":\"画面：两国代表在长桌两侧同时落笔签字——accord「协议」。词里有 cord『心』（concord 和谐）：两颗心想到一块儿，就是达成一致；peace accord 和平协议。\",\n\"accountability\":\"画面：听证会上，负责人站在麦克风前，一条条回答质询——accountability「问责」。account 本是『账目』：做过的事要能『交账』，出了问题就得有人负责。\",\n\"accuracy\":\"画面：射箭场上，十支箭全钉在靶心一圈——accuracy「准确性」。accurate 的名词形：分毫不差的程度；测量、翻译、预测都讲 accuracy。\",\n\"accusation\":\"画面：法庭上检察官起身，手指指向被告席——accusation「指控」。accuse『指控』的名词形；cause 藏在词里：把某人说成是祸事的『原因』，就是指控。\",\n\"achievement\":\"画面：登山者终于站上峰顶，把旗子插进雪里——achievement「成就」。achieve『实现』的名词形；a sense of achievement 成就感，是努力到顶的那一刻。\",\n\"acquisition\":\"画面：大公司签约吞下小公司，新闻标题写着『史上最大收购』——acquisition「收购」。acquire『获得』的名词形；也可指知识技能的习得，如 language acquisition 语言习得。\",\n\"acre\":\"画面：站在乡间田埂上，眼前一大片麦田约等于一个足球场——acre「英亩」。英美面积单位，约 4047 平方米；托福听力讲农场、土地时常出现，别和公顷 hectare 混。\",\n\"action\":\"画面：导演一拍板，演员立刻动起来——action「行动」。act『做』的名词形；take action 采取行动；电影开拍那声『Action!』就是『开始行动』。\",\n\"activity\":\"画面：周末的公园，跑步的、放风筝的、野餐的，到处都在动——activity「活动」。active『活跃的』的名词形；既指具体活动，也指活跃的程度。\",\n\"actuality\":\"画面：传闻说得天花乱坠，记者实地一查，真相平平无奇——actuality「现实性」。actual『真实的』+ -ity：事情实际存在的样子；in actuality 是『实际上』。\",\n\"adaptability\":\"画面：变色龙爬到绿叶上变绿，爬到枯枝上变褐——adaptability「适应性」。adapt『适应』+ -ability『能力』：随环境调整自己的本事，生物进化话题高频词。\",\n\"addition\":\"画面：账本最后一行把所有数字加起来，得出总和——addition「加法；增加」。add『加』+ -ition：数学的加法运算，也泛指添加物；in addition 是『此外』。\",\n\"adequacy\":\"画面：水库的水位线刚好压在『够用』刻度上，不多不少——adequacy「充分性」。adequate『足够的』的名词形：不多不少，恰好满足需要的程度。\",\n\"adjacency\":\"画面：两块拼图严丝合缝地贴在一起，中间没有缝隙——adjacency「邻近」。adjacent『相邻的』的名词形：紧挨着的状态；ad- 是『向着』，jac 是『躺、卧』——躺在旁边的就是邻居。\",\n\"adjustment\":\"画面：新到一个城市，头一周时差没倒过来，第二周就适应了节奏——adjustment「调整」。adjust『调整』的名词形；小到调座椅，大到适应新环境，都叫 adjustment。\",\n\"admiration\":\"画面：小球迷仰头看着球星，眼里全是星星——admiration「钦佩」。admire『钦佩』的名词形；ad- + mir『惊奇』（miracle 奇迹）：看得心生惊叹，就是钦佩。\",\n\"adolescent\":\"画面：十四五岁的少年，个子蹿得比爸爸还高，嗓音却还在变——adolescent「青少年」。词源是拉丁语『正在长大』：处于青春期、还没成年的孩子；青春期是 adolescence。\",\n\"adoption\":\"画面：一对夫妇在福利院文件上签字，把小女孩正式接回家——adoption「收养」。adopt『收养；采纳』的名词形；词里有 opt『选择』：主动选择成为一家人。\",\n\"advantage\":\"画面：赛跑时他站在内道，起跑就比别人省了半步——advantage「优势」。词源是法语 avant『在前面』：站得比别人靠前，就是占先；take advantage of 是『利用』。\",\n\"adventure\":\"画面：背起行囊走进未知雨林，地图上前面全是空白——adventure「冒险」。ad- + vent『来』（event 事件）：迎着要来的事走出去；vent 本义『即将到来的事』，敢迎上去就是冒险。\",\n\"advertiser\":\"画面：品牌经理在会议室里拍板：今年的广告预算翻倍——advertiser「广告商」。advertise『打广告』+ -er：花钱投放广告的企业或人，与做广告的 agency 分工不同。\",\n\"advice\":\"画面：临行前，老师拉住你：『到了那边，先办这三件事』——advice「建议」。不可数名词：一条建议是 a piece of advice；advise 是动词『建议』，注意 s 和 c 的拼写分工。\",\n\"advisor\":\"画面：研究生第一次见导师，导师在研究计划上圈出三个问题——advisor「顾问」。advise『建议』+ -or：专门给人出主意的人；学术语境里就是导师，美式也拼 adviser。\",\n\"advocacy\":\"画面：她在市政厅门前举着标语，为社区图书馆的存留发声——advocacy「倡导」。词根 voc『声音』（voice）：替某个主张『出声』；advocate 是倡导者，替人发声的人。\",\n\"aerial\":\"画面：老房子的屋顶上竖着一根鱼骨状天线——aerial「天线」。aer 是『空气』（aeroplane 飞机）：伸进空气里收信号的杆；英式英语里电视天线就叫 aerial，美式多用 antenna。\",\n\"aesthetic\":\"画面：美术馆里，一束光恰好打在雕塑的弧线上——aesthetic「美学」。希腊语源是『感知』：研究什么是美的学问；作形容词是『审美的』，aesthetic value 审美价值。\",\n\"affair\":\"画面：外交官的日程表排得满满当当，全是待处理的公务——affair「事务」。最常指事情、事务：current affairs 时事；另一个常见义是婚外情，语境决定，别一概而论。\",\n\"affection\":\"画面：奶奶见到孙子，一把搂进怀里亲了亲额头——affection「感情」。affect 本义『触动』：心里被触动生出的喜爱；常与 for 搭配，affection for sb 对某人的 affection。\",\n\"affiliation\":\"画面：简历上写着他所属的学会和研究机构——affiliation「隶属关系」：affiliate『附属』的名词形；学术论文作者名下印的单位就是 affiliation。\",\n\"affinity\":\"画面：第一次见面就聊得停不下来，像认识了十年——affinity「亲和力」。词源是拉丁语『邻近、姻亲』：天然的投合；化学里指物质间的亲和力，have an affinity for 对……有天然好感。\",\n\"affirmation\":\"画面：他站在镜子前，每天对自己念一遍积极的肯定句——affirmation「肯定」。affirm『肯定、断言』的名词形；firm 藏在词里：把话说『实』、说『定』，就是肯定。\",\n\"affluence\":\"画面：社区里家家是独栋别墅，车库里停着两辆车——affluence「富裕」。词根 flu『流』（fluent 流利）：财富像水一样涌进来；affluent 是『富裕的』。\",\n\"affordability\":\"画面：年轻人盯着房价牌算了又算，月供刚好压在工资三成——affordability「可负担性」。afford『负担得起』的名词形：价格相对于收入能不能扛得住。\",\n\"aftermath\":\"画面：台风过境第二天，街道上全是倒伏的树和积水——aftermath「余波」。after + math（古英语『收割』）：风暴收场之后留下的场面；多指灾难、战争的后果。\",\n\"agency\":\"画面：旅行社的门店里，顾问正帮一家人订机票酒店——agency「机构」。agent『代理人』集合成的办事机构：中介、代理商、政府机构都可叫 agency，如 travel agency。\",\n\"agenda\":\"画面：会议开始前，投影上列着今天要议的五项——agenda「议程」。拉丁语原义『要做的事（复数）』：按顺序排好的待议事项；set the agenda 定议程，也比喻主导话题。\",\n\"agent\":\"画面：房产经纪人拿着钥匙，带客户去看第三套房——agent「代理」。ag『做、行动』：替别人办事的人；也可指化学作用剂，如 cleaning agent 清洁剂。\",\n\"agility\":\"画面：体操运动员在平衡木上轻轻一跃，落地纹丝不动——agility「敏捷性」。agile『敏捷的』的名词形；词根 ag『动』：动得又快又稳，就是敏捷。\",\n\"aging\":\"画面：老照片里年轻的脸庞，如今添了皱纹和白发——aging「老化」。age『年龄』的动名词：人、酒、设备随时间变老的过程；anti-aging 是抗衰老。\",\n\"ailment\":\"画面：老人总说腰酸背痛，去医院又查不出大毛病——ailment「小病」。ail 是古英语『疼痛、烦恼』：不算重病、却总缠着人的小毛病，常说 minor ailment。\",\n\"aircraft\":\"画面：停机坪上，客机、货机、直升机排成一排整装待发——aircraft「飞行器」。air + craft『器』：一切能在空中飞的机器的统称，单复数同形，一架也是 aircraft。\",\n\"airline\":\"画面：机场大屏上滚动着各家公司的航班，尾翼涂着不同的标志——airline「航空公司」。air + line『线路』：经营空中航线的公司；问『你坐哪家航空公司』就用它。\",\n\"airport\":\"画面：航站楼里人流如织，大屏翻着起飞信息——airport「机场」。air + port『港』：飞机起降的『空港』；小的简易机场叫 airfield，别混。\",\n\"aisle\":\"画面：婚礼上，新娘挽着父亲，沿着红毯通道缓缓走来——aisle「过道」。座椅之间、货架之间的通道；拼写别和 isle（小岛）混，发音也相近，靠语境分。\",\n\"album\":\"画面：翻开厚厚的相册，每页塑封里都是小时候的照片——album「相册」。拉丁语原义『白板』：收纳照片、邮票的册子；音乐专辑也叫 album，一张专辑就是一册歌。\",\n\"alcohol\":\"画面：消毒时棉球蘸着酒精擦过皮肤，凉丝丝地挥发——alcohol「酒精」。源于阿拉伯语，原指一种细粉，后专指酒里的乙醇；消毒、燃料、饮品里都有它。\",\n\"alertness\":\"画面：夜哨士兵竖着耳朵，一点风吹草动都逃不过——alertness「警觉」。alert『警觉的』+ -ness：时刻保持戒备、不松懈的状态；站岗、驾驶都需要它。\",\n\"alignment\":\"画面：修车师傅做四轮定位，四个轮子的角度被校准到一条线——alignment「对齐」。align『排齐』的名词形；也比喻立场一致，如 political alignment 政治结盟。\",\n\"alimony\":\"画面：离婚判决书上写明，每月固定打一笔钱给前妻——alimony「赡养费」。词源拉丁语『供养』：离婚后一方依法付给另一方的生活费，注意是判给配偶的，不是给孩子的抚养费 child support。\",\n\"allegation\":\"画面：报纸标题写着『据指控……』，文末却注明尚未证实——allegation「指控说法」。allege『声称（未证实）』的名词形：只是提出的说法，未经证实，与确凿的证据 evidence 分开。\",\n\"allegiance\":\"画面：新公民举起右手，宣誓效忠这个国家——allegiance「忠诚」。词源与封建领主有关：宣誓效忠的对象可以是国家、君主或信念；pledge allegiance 是效忠宣誓。\",\n\"alley\":\"画面：两排老楼之间夹着一条窄巷，晾着衣服，飘着饭香——alley「小巷」。比 street 窄得多的小道，常在楼后；bowling alley 是保龄球馆，别按字面猜。\",\n\"allocation\":\"画面：预算表上，总经费被切成几块，分给各个项目——allocation「分配」。allocate『分配』的名词形；把有限的资源按规则分出去这件事，经济学高频词。\",\n\"allotment\":\"画面：蛋糕切好了，每人盘里分到同样大的一块——allotment「分配额」。allot『分配』+ -ment：分到手的那一份额度，强调份额本身。\",\n\"ally\":\"画面：战时，两国元首握手结盟，同进同退——ally「盟友」。词源拉丁语『绑在一起』（lig 绑，如 ligament 韧带）：绑在同一条船上的人；动词重音在后，名词在前。\",\n\"almond\":\"画面：剥开淡褐色的薄皮，露出乳白扁长的果仁——almond「杏仁」。注意 l 不发音，读作『阿门德』近似；almond milk 杏仁奶，almond tree 杏树，果仁形状像水滴。\",\n\"alphabet\":\"画面：小朋友指着字母表，从 A 一路念到 Z——alphabet「字母表」。alpha + beta：希腊字母的头两个，正是 alphabet 的来源；一套语言的全部字母就是它的字母表。\",\n\"altar\":\"画面：神庙中央的石台上摆着供品，烟雾缓缓升起——altar「祭坛」。拉丁语原义『高台』：祭祀时放供品的高台；婚礼上新人站的地方也叫 altar。\",\n\"alteration\":\"画面：裁缝在裙摆上别了几根针，准备改短两寸——alteration「改动」。alter『改变』的名词形；多指对衣服、计划、建筑的小幅修改，不是推倒重来。\",\n\"aluminium\":\"画面：飞机蒙皮闪着银白的光，轻得能用手掰弯薄片——aluminium「铝」。英式拼写，多一个 i，美式是 aluminum；最常用的轻金属，饮料罐、飞机都用它。\",\n\"amazement\":\"画面：魔术师从帽子里拎出一只兔子，孩子们张大了嘴——amazement「惊奇」。amaze『使惊奇』的名词形；in amazement 是『惊讶地』，眼睛瞪圆的那种感觉。\",\n\"ambiguity\":\"画面：一句话能读出两种意思，评论区吵翻了天——ambiguity「歧义」。ambiguous『模棱两可的』的名词形；词根 ambi『两边』：一句话两头都能靠，就是有歧义。\",\n\"ambition\":\"画面：少年在日记本上写下：『总有一天，我要站上那个舞台』——ambition「雄心」。词源拉丁语『四处奔走拉票』：想往上走的强烈渴望；ambitious 是『有雄心的』。\",\n\"ambulance\":\"画面：白车红十字，鸣着笛从车流里穿过去——ambulance「救护车」。词根 ambul『行走』（amble 漫步）：源于『流动医院』，能跑到病人身边的车；拼写认准 ambul 开头。\",\n\"amenity\":\"画面：小区里泳池、健身房、儿童乐园一应俱全——amenity「便利设施」。词源拉丁语『愉快』：让生活舒服方便的设施；酒店介绍里 amenities 常指洗漱用品等配备。\",\n\"amusement\":\"画面：过山车俯冲而下，全车人又叫又笑——amusement「娱乐」。amuse『逗乐』的名词形；amusement park 就是游乐园，专门制造快乐的地方。\",\n\"anecdote\":\"画面：教授讲到兴起，顺口说起牛顿苹果的那个小故事——anecdote「轶事」。希腊语原义『未发表的事』：短小有趣的真实小故事，常用来佐证观点，与系统的证据相对。\",\n\"angel\":\"画面：圣诞树顶上站着一个小天使，摊开的翅膀闪着金光——angel「天使」。宗教里侍奉神的灵体；比喻义是善良热心的人，如 angel investor 天使投资人。\",\n\"angle\":\"画面：量角器压在三角形上，正好量出 60 度——angle「角度」。两条边张开的口就是角；也指看问题的角度：from a different angle 换个角度看。\",\n\"animal\":\"画面：纪录片里，狮子、斑马、长颈鹿在草原上各过各的日子——animal「动物」。anim 是『生命、气息』（animate 使生动）：会动的活物；与植物 plant 相对。\",\n\"ankle\":\"画面：跑步崴了脚，脚踝肿起一个包，走路一瘸一拐——ankle「脚踝」。小腿和脚之间能转动的关节；sprain one's ankle 是崴脚，高频生活表达。\",\n\"anniversary\":\"画面：日历上圈着结婚纪念日，桌上摆好了蛋糕和花——anniversary「周年纪念」。anni 是『年』（annual 每年的）+ vers『转』：日子转完一整年又回到同一天。\",\n\"announcement\":\"画面：校长走上台，清清嗓子：『我宣布一个好消息』——announcement「公告」。announce『宣布』的名词形；nunti 是『传信』（annunciation 报喜）：把消息正式传给所有人。\",\n\"annoyance\":\"画面：蚊子整夜在耳边嗡嗡，翻来覆去睡不着——annoyance「烦恼」。annoy『使烦恼』的名词形；那种不大不小、却挥之不去的烦人事或东西。\",\n\"anomaly\":\"画面：一排整齐的气温数据里，突然窜出一个高得离谱的点——anomaly「异常」。a-『无』+ homal『平整』（homogeneous 同质的）：不合常规、跳出规律的那一个，科学阅读高频词。\",\n\"answer\":\"画面：试卷最后一道大题，他写下了流畅的解答——answer「答案」。名词是『答案』，动词是『回答』；in answer to 是『作为对……的回应』。\",\n\"antenna\":\"画面：昆虫头上两根触角左右探着，感知周围的动静——antenna「触角」。昆虫、甲壳动物头上的感官；引申到电子设备就是天线，与英式 aerial 同义。\",\n\"anthem\":\"画面：奥运会颁奖台上，国歌奏响，运动员眼含热泪——anthem「国歌」。national anthem 是国歌全称；anthem 本指赞美诗，唱给国家听的赞美诗就是国歌。\",\n\"anthology\":\"画面：书架上那本《唐诗选》，薄薄一册收尽三百首精华——anthology「选集」。antho『花』（anther 花药）+ log『收集』：像采花一样把好作品收成一册；诗歌、短篇小说常出选集。\",\n\"anticipation\":\"画面：出发前一晚，行李箱摊开，兴奋得睡不着——anticipation「期待」。anticipate『预料、期待』的名词形；anti- 在这里是『提前』：心提前飞到了那件事上。\",\n\"antique\":\"画面：拍卖会上，一把明代的椅子被小心翼翼抬上台——antique「古董」。anti『在前』（ante 前）：前代留下来、因年代和工艺而值钱的物件；antique shop 古董店。\",\n\"apartment\":\"画面：一栋楼里隔成许多户，每户一扇门、一个门铃——apartment「公寓」。apart『分开』：被分隔开的独立居住单元；美式叫 apartment，英式多叫 flat。\",\n\"apathy\":\"画面：宣布了和全班有关的新政策，台下却没人抬头——apathy「冷漠」。a-『无』+ path『感受』（sympathy 同情）：没有感受、不关心的状态，政治新闻里常指选民冷漠。\",\n\"ape\":\"画面：黑猩猩蹲在树枝上，学着饲养员的样子挠头——ape「猿」。没有尾巴的大型灵长类，如 chimpanzee、gorilla；也可作动词『模仿』，由猿学人引申而来。\",\n\"aperture\":\"画面：转动相机镜头，光圈叶片收成一个小孔——aperture「孔径」。aper 是『打开』（open 同源）：镜头上让光进来的开口大小；摄影术语里决定进光量。\",\n\"apex\":\"画面：金字塔的塔尖直指蓝天，站在下面只看得见一个点——apex「顶峰」。最高的那个点；at the apex of one's career 是事业巅峰，与 base 底部相对。\",\n\"apology\":\"画面：他低下头：『对不起，是我弄错了。』——apology「道歉」。apo + log『言说』（logic 逻辑）：为自己说的话——替过错辩解、致歉；make an apology 是正式道歉。\",\n\"apostrophe\":\"画面：课本上标着红圈：don't 里那一撇不能丢——apostrophe「撇号」。英语标点 ' ，表示字母省略或所属关系；和引号 quotation mark 别混，位置在字母右上方。\",\n\"apparatus\":\"画面：实验室台面上一整套玻璃仪器，管子连着瓶子连着冷凝管——apparatus「器械」。一整套为某个用途配齐的设备；也可指机构，如 state apparatus 国家机器。\",\n\"apparel\":\"画面：服装店的招牌上写着 women's apparel——apparel「服装」。比 clothes 更正式的总称，多见于商店和行业用语：服饰、衣着；日常口语多用 clothes。\",\n\"appearance\":\"画面：他一身皱巴巴的衬衫，第一印象就扣了分——appearance「外貌」。appear『出现』的名词形；人或物看上去的样子；judge by appearances 是以貌取人。\",\n\"appetite\":\"画面：跑完十公里，闻到饭菜香，肚子立刻咕咕叫——appetite「食欲」。词根 pet『追求』（compete 竞争）：身体对食物的渴望；也可比喻对知识、权力的胃口。\",\n\"apple\":\"画面：从树上摘下红苹果，咔嚓咬一口，果汁迸出来——apple「苹果」。an apple a day keeps the doctor away 是谚语；纽约别称 the Big Apple 也源于此。\",\n\"appliance\":\"画面：厨房里电饭煲、微波炉、烤箱各就各位——appliance「器具」。apply『应用』的亲戚：把电用起来的家用设备，home appliances 就是家用电器。\",\n\"appointment\":\"画面：日历上写着『周三下午三点，看牙医』——appointment「约会；预约」。appoint『约定、任命』的名词形；make an appointment 是预约，医生的、理发的都要先约。\",\n\"appraisal\":\"画面：估价师绕着老房子走了一圈，在表格上写下数字——appraisal「评估」。appraise『估价』的名词形；对房产、员工、古董的价值评定都用它。\",\n\"appreciation\":\"画面：观众静静听完钢琴独奏，掌声从心底涌出来——appreciation「欣赏」。appreciate 的名词形；既是懂得欣赏，也是表示感激，还可指资产升值——语境定意思。\",\n\"appropriateness\":\"画面：葬礼上他穿了黑西装，没穿那件花衬衫——appropriateness「适当性」。appropriate『适当的』的名词形：言行与场合合不合拍的程度。\",\n\"approval\":\"画面：申请表右上角盖上红红的『批准』印章——approval「批准」。approve『批准』的名词形；get approval from sb 得到某人批准，正式文件必经这一步。\",\n\"approximation\":\"画面：圆周率写成 3.14，够用了，不必写三百位——approximation「近似值」。approximate『接近的』的名词形；proxim 是『最近』（proximity 接近）：离真值最近的那个估计。\",\n\"apricot\":\"画面：初夏的果摊上，一筐杏子黄里透红，毛茸茸的——apricot「杏」。比桃子小、带绒毛的核果；注意和 peach 桃、plum 李子分开，颜色是橙黄色。\",\n\"apron\":\"画面：妈妈系着围裙在灶台前翻炒，油星子全挡在裙面上——apron「围裙」。做饭、做工时系在腰间护衣服的布；拼写注意 a 开头，别和动词混。\",\n\"aquarium\":\"画面：巨大的玻璃水箱里，鲨鱼从头顶缓缓游过——aquarium「水族馆」。aqua 是『水』（aquatic 水生的）：装着水生生物的玻璃世界；家里的小鱼缸也叫 aquarium。\",\n\"arc\":\"画面：篮球出手，在空中划出一道漂亮的弧线——arc「弧」。圆周上的一段弯线；彩虹、抛物线都是 arc；electric arc 是电弧。\",\n\"archery\":\"画面：射手拉满弓，屏住呼吸，箭直奔靶心——archery「射箭」。arch 本是『弓、拱』：用弓射箭的运动；archer 是射手，奥运会项目之一。\",\n\"arena\":\"画面：古罗马竞技场中央，角斗士站在黄沙地上——arena「竞技场」。拉丁语原义『沙地』：铺着沙的格斗场；现泛指比赛场地，也比喻政治舞台 political arena。\",\n\"argument\":\"画面：两个人面红耳赤，各说各的理——argument「论点；争论」。argue 的名词形有两个面孔：学术里是『论点、论证』，生活里是『吵架』，看语境区分。\",\n\"aristocracy\":\"画面：舞会上，世袭贵族们端着香槟，头衔一个比一个长——aristocracy「贵族」。aristo『最好』+ cracy『统治』（democracy 民主）：由『最优秀者』（出身贵族）统治的阶层；aristocrat 是单个贵族。\",\n\"arm\":\"画面：他伸出手臂，把高处货架上的箱子够了下来——arm「手臂」。肩膀到手腕的整条胳膊；另一个高频义是武器（arms 军火），lay down arms 是放下武器。\",\n\"armada\":\"画面：海面上战舰排开阵势，桅杆遮住了半个天——armada「舰队」。西班牙语专指西班牙无敌舰队，后泛指大规模舰队；arm 藏在词里：武装起来的船队。\",\n\"armchair\":\"画面：爷爷陷在扶手椅里，膝上摊着报纸，茶杯放在扶手边——armchair「扶手椅」。arm + chair：两边有扶手托胳膊的椅子；armchair critic 是『坐着空谈的评论家』。\",\n\"army\":\"画面：阅兵式上，方阵步伐整齐，脚步声像鼓点——army「军队」。arm 是『武器』：武装起来的人组成的陆军总称；an army of 还可形容一大群，如 an army of ants。\",\n\"arrangement\":\"画面：花艺师把玫瑰和满天星错落插好，退后一步端详——arrangement「安排」。arrange 的名词形；事情的安排、花艺的布置、音乐的编曲都可叫 arrangement。\",\n\"array\":\"画面：展台上，望远镜按口径一字排开，整整齐齐——array「阵列」。整齐排列的一大批；a vast array of 是『各种各样的』，科技文里还有天线阵列、数据阵列。\",\n\"arrears\":\"画面：账单上红字标着『逾期未付』，利息一天天涨——arrears「欠款」。arrear 源于『落在后面』：拖欠着没还的钱；in arrears 是拖欠状态，房租、水电费都会出现。\",\n\"arrival\":\"画面：机场到达大厅的门一开，拖着行李的人涌出来——arrival「到达」。arrive 的名词形；arrival time 到达时间，与 departure 出发相对成对出现。\",\n\"arrow\":\"画面：弓弦一松，箭嗖地钉进靶心——arrow「箭」。细杆、箭头、尾羽的射箭武器；也指箭头符号 →，指示方向时 everywhere 都在用。\",\n\"arson\":\"画面：深夜仓库火光冲天，消防员在废墟里找到汽油桶——arson「纵火」。词根 ars 是『烧』（ardent 热烈的）：故意放火烧毁财物的罪行；放火者是 arsonist。\",\n\"art\":\"画面：画布上寥寥几笔，勾出一匹马的神韵——art「艺术」。创造美与表达的活动总称；the arts 是艺术门类，art 还可指技艺，如 the art of negotiation 谈判的艺术。\",\n\"article\":\"画面：报纸头版刊着一篇长篇调查报道——article「文章」。报刊上的一篇独立文字；语法里还有『冠词』义（a、an、the），日用品义是『物品』，一篇 article 别只认一个意思。\",\n\"artifice\":\"画面：魔术师手法快得看不清，硬币就这样没了——artifice「诡计」。art + fic『做』（fiction 虚构）：做出来的花招；指骗人的巧妙手法，贬义居多。\",\n\"artillery\":\"画面：山坡后一排火炮齐射，地面都在震——artillery「大炮」。军队里的大型火器总称；artilleryman 是炮兵，重武器话题常见词。\",\n\"artist\":\"画面：画家在画布前站了一上午，只为调对那一抹蓝——artist「艺术家」。art + -ist：以艺术创作为业的人；与 artisan 手艺人不同，artist 重在创作表达。\",\n\"artistry\":\"画面：舞者一个旋转，裙摆的弧线像水波一样展开——artistry「艺术性」。artist 的抽象名词形：作品或表演里那种高超的艺术造诣、表现功力。\",\n\"artwork\":\"画面：画廊的白墙上，灯光只打在那一幅画上——artwork「艺术品」。art + work：创作出来的作品本身；书刊里的插图、版面图也统称 artwork。\",\n\"asbestos\":\"画面：老房子的隔热层里，灰白纤维一捏成粉——asbestos「石棉」。希腊语原义『不灭的』：耐火的纤维矿物，过去用作防火材料，后证实吸入致癌，多国禁用。\",\n\"ascent\":\"画面：登山队沿着陡坡一步步往上，营地旗子越来越近——ascent「上升」。ascend『上升』的名词形；scend 是『爬』（descend 下降）：往高处走的这段路或过程。\",\n\"ash\":\"画面：篝火熄灭后，只剩一堆灰白的余烬——ash「灰烬」。东西烧完剩下的灰；火山灰是 volcanic ash；注意 ash tree 是梣树，别和灰烬混。\",\n\"asphalt\":\"画面：夏天的柏油路晒得发软，修路机正铺下新的一层——asphalt「沥青」。铺路的黑亮材料；asphalt road 就是柏油马路，城市建设话题常出现。\",\n\"aspiration\":\"画面：小镇青年望着远方城市的灯光，在心里立下志向——aspiration「抱负」。词根 spir 是『呼吸』（inspire 鼓舞）：心里憋着的那口气，就是想抵达的远方；aspire 是『渴望』。\",\n\"assassin\":\"画面：史书上记载，那位君主在剧场门口遇刺——assassin「刺客」。专指刺杀政要名人的杀手；源于十字军时期一个派别的传说，assassinate 是刺杀。\",\n\"assembly\":\"画面：周一清晨，全校师生在操场集合升旗——assembly「集会」。assemble『集合』的名词形；也可指装配（如 assembly line 流水线）和议会（如 National Assembly 国民议会）。\",\n\"assent\":\"画面：主席问『同意吗』，他微微点了点头——assent「同意」。比 agree 更正式的赞同、批准；sent 藏在词里是『感觉』（sense 感觉）：心里觉得行，就是同意。\",\n\"assertion\":\"画面：他在会上拍着桌子说：『这一点，我敢打包票。』——assertion「断言」。assert『断言』的名词形；把话说得斩钉截铁、未必给出证据的那种声明。\",\n\"assessment\":\"画面：老师批完一摞试卷，在成绩单上写下评语——assessment「评估」。assess『评估』的名词形；考试测评、房产估价、风险评估都叫 assessment。\",\n\"assortment\":\"画面：礼品盒打开，里面巧克力、饼干、果干一格一格摆着——assortment「各式各样」。assort『分类搭配』：混在一起的多种多样；an assortment of 是『各种各样的』。\",\n\"assumption\":\"画面：他想当然以为会议改期了，结果扑了个空——assumption「假设」。assume『假定』的名词形；未经证实先当真的前提；make an assumption 是作假设，科学写作要标明。\",\n\"assurance\":\"画面：厂家拍胸脯保证：『十年之内，免费维修。』——assurance「保证」。assure『保证』的名词形；给人吃定心丸的承诺；另一种高频义是保险（英式 life assurance 人寿保险）。\",\n\"asterisk\":\"画面：合同小字上标着一个星号 *，脚注写着附加条件——asterisk「星号」。希腊语原义『小星星』（astronomy 天文学同源）：印刷符号 *，提示读者去看注释。\",\n\"astonishment\":\"画面：魔术师把大象变没了，观众嘴巴张成圆形——astonishment「惊讶」。astonish『使惊讶』的名词形；程度比 surprise 更重，是那种目瞪口呆的吃惊。\",\n\"astrology\":\"画面：报纸角落印着今日星座运势，他一笑置之——astrology「占星术」。astro『星』+ logy『学问』：靠星象占卜命运，被归为伪科学；与正经的天文学 astronomy 一字之差，别混。\",\n\"athlete\":\"画面：起跑线上，短跑运动员蹬着起跑器，肌肉紧绷——athlete「运动员」。希腊语原义『参赛者』：受过专业训练、参加竞技的人；athletics 是田径运动。\",\n\"athletics\":\"画面：体育场里，跑道、沙坑、投掷区同时开赛——athletics「田径」。跑、跳、投等运动的总称；英式英语里 athletics 就是田径，美式多说 track and field。\",\n\"atlas\":\"画面：他翻开厚厚的地图册，找到那条要走的山路——atlas「地图册」。书名源于擎天巨神 Atlas：传说他扛着天穹，后来地图册封面常印他扛地球的样子。\",\n\"attachment\":\"画面：邮件右上角有个回形针图标，点开是合同附件——attachment「附件」。attach『附上』的名词形；电子邮件的附件，也可指情感上的依恋。\",\n\"attic\":\"画面：顺着窄楼梯爬上阁楼，全是落灰的旧箱子——attic「阁楼」。屋顶下、楼层上的那个小空间，常堆杂物；与 basement 地下室上下相对。\",\n\"attraction\":\"画面：磁铁一靠近，铁钉立刻被吸了过去——attraction「吸引力」。attract『吸引』的名词形；旅游景点的『景点』也叫 tourist attraction，被人吸引而去的地方。\",\n\"attractiveness\":\"画面：同样价格的两家店，人们总往装修好看的那家走——attractiveness「吸引魅力」。attractive『有吸引力的』的名词形；某人或某物招人喜欢的程度。\",\n\"audio\":\"画面：剪辑软件里，音轨的波形随着说话声起伏——audio「音频」。aud 是『听』（audience 听众）：与声音有关的部分；audio file 是音频文件，与 video 视频相对。\",\n\"auditorium\":\"画面：剧场里一排排红色座椅，全部朝着舞台——auditorium「礼堂」。aud『听』：供人坐着听、看的地方，学校礼堂、音乐厅的观众席区域。\",\n\"aunt\":\"画面：过年时，姑姑拎着大包小包来家里拜年——aunt「阿姨」。父亲或母亲的姐妹，以及叔伯的妻子，英语里统一叫 aunt；uncle 是对应的男性称呼。\",\n\"authenticity\":\"画面：专家拿着放大镜验了半天，点头：『是真迹。』——authenticity「真实性」。authentic『真实的』的名词形；auth 是『作者、本人』（author 作者）：出自本人、非赝品的成色。\",\n\"authorization\":\"画面：没有盖章的批文，财务说什么也不肯放款——authorization「授权」。authorize『授权』的名词形；官方许可的文书或行为本身，上级批了才算数。\",\n\"autograph\":\"画面：球迷挤到场边，举着球衣求签名——autograph「亲笔签名」。auto『自己』+ graph『写』（graph 图表）：本人亲手写下的名字，名人签名最常见。\",\n\"automobile\":\"画面：流水线上，机器人手臂把车门装到车身上——automobile「汽车」。auto『自己』+ mobile『能动』：能自己跑的车；正式用词，日常多用 car。\",\n\"autonomy\":\"画面：自治区有自己的议会，能决定本地的事务——autonomy「自治」。auto『自己』+ nom『法则』（economy 经济）：自己给自己立法、自己管自己的权力。\",\n\"autumn\":\"画面：枫叶红了，风一吹，落叶铺满小路——autumn「秋天」。收获与落叶的季节；美式更常用 fall（落叶的季节），英式多用 autumn。\",\n\"availability\":\"画面：订票页面上，周五的班次标着『仅剩 3 席』——availability「可用性」。available『可用的』的名词形；有货、没货，有空、没空，都看 availability。\",\n\"avenue\":\"画面：宽阔的大道两旁种满梧桐，车水马龙——avenue「大街」。比 street 更宽的主干道；纽约的 Fifth Avenue 第五大道最出名；也可比喻途径，如 an avenue for change。\",\n\"aviation\":\"画面：塔台里，管制员盯着雷达屏调度起降——aviation「航空」。avi 是『鸟』（aviary 鸟舍）：与飞行器运营、飞行有关的整个行业；aviation industry 航空业。\",\n\"avoidance\":\"画面：他远远看见不想见的人，低头绕道走——avoidance「回避」。avoid『避免』的名词形；有意躲开某人某事，tax avoidance 是合法避税，与逃税 evasion 不同。\",\n\"awkwardness\":\"画面：电梯里和陌生人面面相觑，谁也不说话——awkwardness「尴尬」。awkward『尴尬的、笨拙的』的名词形；场面或动作那种说不出的别扭感。\",\n\"axle\":\"画面：车轮装在车轴两端，轴一转，轮子跟着转——axle「车轴」。穿过车轮中心的那根杆；自行车、汽车都有 axle，是轮子转动的支点。\",\n\"abandon\":\"画面：船要沉了，船长下令弃船，大家跳上救生艇——abandon「放弃」。a + bandon（古法语『支配』）：撒手不再管；abandon a plan 是放弃计划，abandon ship 是弃船。\",\n\"abolish\":\"画面：议会投票通过，存在百年的旧税制一夜废除——abolish「废除」。正式废止法律、制度、习俗；abolish slavery 废除奴隶制是历史课高频句。\",\n\"abuse\":\"画面：经理把职权当私器，给亲戚开后门——abuse「滥用」。ab-『偏离』+ use『用』：把东西用错方向；abuse power 滥用权力，也可指虐待和辱骂。\",\n\"accelerate\":\"画面：绿灯亮起，车子一脚油门窜了出去——accelerate「加速」。celer 是『快』（法语同源）：让速度快起来；经济、衰老、变化都可以 accelerate。\",\n\"accept\":\"画面：她双手接过录取通知书，点了点头——accept「接受」。ac- + cept『拿』（receive 接收）：伸手把递来的东西拿下；注意与 except『除……之外』只差一字母，意思完全不同。\",\n\"accompany\":\"画面：钢琴家为独唱者伴奏，两人一起谢幕——accompany「陪伴」。com + pan『面包』（company 公司）：古义是『同桌吃面包的人』——陪着一起走、一起做就是陪伴。\",\n\"accomplish\":\"画面：历时三年，团队终于把大桥合龙——accomplish「完成」。com + plish『填满』：把任务填满、做到圆满；accomplishment 是成就感满满的那个成果。\",\n\"accuse\":\"画面：法庭上，原告律师站起来指控被告欺诈——accuse「指控」。cause 藏在词里：把祸事的原因扣到某人头上；accuse sb of sth 是标准搭配。\",\n\"addict\":\"画面：他一放下手机就心慌，一天要点开几百次——addict「使沉溺」。dict 是『说、宣判』：古罗马指被宣判给债主的人——被某物牢牢拴住，戒不掉，就是沉溺；addicted to 是『上瘾于』。\",\n\"address\":\"画面：新任市长上任第一件事，是处理积压的交通问题——address「处理问题」。除了『地址、演讲』，address 还有『着手解决』义：address a problem 着手处理问题，托福阅读常见。\",\n\"adhere\":\"画面：胶带牢牢粘在纸箱上，撕都撕不下来——adhere「黏附」。ad- + haer『粘』（adhesive 胶粘剂、cohesive 有凝聚力的）：紧紧贴住；引申义 adhere to rules 是遵守规则。\",\n\"administer\":\"画面：院长每天巡视各科室，调配人手和预算——administer「管理」。mini 是『服务』（minister 部长）：管人管事、组织运转；也可指施行药物、主持考试，如 administer a test。\",\n\"admire\":\"画面：游客仰头看着大教堂的穹顶，半天说不出话——admire「钦佩」。ad- + mir『惊奇』（miracle 奇迹）：看得心生惊叹而佩服；admire sb for sth 因某事佩服某人。\",\n\"admit\":\"画面：他低着头承认，数据确实是自己改的——admit「承认」。ad- + mit『送、放』（permit 允许）：把事实放出来；还有『准许进入、入院』义，be admitted to 是被录取、被收治。\",\n\"adopt\":\"画面：他们从福利院接回一个小女孩，从此是一家人——adopt「收养」。opt 是『选择』（option 选项）：主动选来当自己的孩子；也可指采纳政策、采用方法 adopt a policy。\",\n\"advance\":\"画面：部队向前推进了二十公里，地图上的箭头又挪了一截——advance「推进」。avant 是『前面』：往前走、往前推；名词义是进步、预付款，in advance 是『提前』。\",\n\"affirm\":\"画面：证人举起右手，郑重宣誓所言属实——affirm「肯定」。firm 是『坚定』（confirm 确认）：把话说得坚定确凿；法庭宣誓、重申立场都用 affirm。\",\n\"afford\":\"画面：她算了算工资，咬咬牙还是没买那辆车——afford「负担得起」。通常与 can 连用：can afford to do 买得起、花得起时间；价格与收入的较量就是 afford。\",\n\"aggravate\":\"画面：他本就咳嗽，还跑去抽烟，咳得更厉害了——aggravate「加重」。grav 是『重』（gravity 重力）：往伤口上再加重量；aggravate a problem 是使问题恶化，别和 annoy 混。\",\n\"aggregate\":\"画面：把各店的销售额加总，报表最后一行是总数——aggregate「合计」。greg 是『群』（congregate 聚集）：把散的拢成一堆算总数；in aggregate 总的来说。\",\n\"agitate\":\"画面：洗衣机滚筒哗啦哗啦地搅动着衣物——agitate「搅动」。ag 是『动』（agent 代理人）：来回搅使之不安；也可指鼓动情绪 agitate for reform 鼓动改革。\",\n\"agree\":\"画面：谈判双方同时点头，握手成交——agree「同意」。agree with sb 同意某人，agree on sth 就某事达成一致，agree to do 同意做某事——三个搭配各管一摊。\",\n\"aid\":\"画面：地震后，救援物资从各地源源不断送来——aid「援助」。简短有力的词：first aid 急救，foreign aid 外援；作动词是帮助、援助，与 help 近义但更正式。\",\n\"aim\":\"画面：射手屏住呼吸，枪口对准靶心——aim「旨在；瞄准」。本义是瞄准目标，引申为目的：aim to do 打算做某事，aim at 对准、针对。\",\n\"alarm\":\"画面：半夜烟雾报警器尖叫，全楼人披衣逃出——alarm「使惊恐」。原是意大利语『拿起武器！』的呼喊：突发危险让人惊起；名词就是警报、闹钟。\",\n\"alert\":\"画面：哨兵眼睛一眨不眨地盯着山口——alert「使警觉」。法语源是『上瞭望塔』：保持警戒的状态；alert sb to sth 是提醒某人注意某事。\",\n\"alienate\":\"画面：他说话越来越刻薄，老朋友一个个不再联系——alienate「疏远」。alien 是『外星人、外人』：把亲近的人推成外人；alienation 是疏离感，社会学话题词。\",\n\"align\":\"画面：排字工人把每行字的左边对得整整齐齐——align「对齐」。a + line『线』：把东西排到一条线上；引申为立场一致 align with 与……结盟、保持一致。\",\n\"allowance\":\"画面：父母每月给孩子五十块零花钱，月初一次给清——allowance「津贴」。allow『允许给』的名词形：定期给的一笔钱或配额；make allowance for 是『体谅、考虑到』。\",\n\"alternate\":\"画面：路灯一盏亮一盏灭，红绿灯交替闪烁——alternate「交替」。alter 是『改变、另一个』：轮流替换着来；alternate days 是隔天，alternate current 是交流电。\",\n\"amalgamate\":\"画面：两家小公司合并成一家，招牌换成了新名字——amalgamate「合并」。原指用水银 amalgam 把金属黏合：合二为一；企业、团体合并都用它，正式用词。\",\n\"amass\":\"画面：松鼠整个秋天往树洞里攒坚果，堆成了小山——amass「积聚」。mass 是『一堆』（massive 巨大的）：一点点攒成一大堆；amass wealth 积累财富，amass data 积累数据。\",\n\"amaze\":\"画面：魔术师从空帽子里变出鸽子，孩子们哇地叫出声——amaze「使惊奇」。maze 是『迷宫』：惊奇得像走进迷宫一样晕头转向；amazing 是『惊人的』，amazed 是『感到惊奇的』。\",\n\"ambush\":\"画面：士兵埋伏在灌木后，等敌军走进山口——ambush「伏击」。amb + bush『灌木丛』：藏在暗处突然袭击；新闻里 ambush 常指伏击事件本身。\",\n\"amount\":\"画面：把零钱罐倒空数了数，总共凑了三百多——amount「总计」。作动词是『合计达到』：amount to 总计、等于；作名词是数量、金额，a large amount of 是大量。\",\n\"amplify\":\"画面：音响师推高推子，吉他的声音灌满全场——amplify「放大声音」。ampli 是『大、宽』（ample 充足的）：把声音、信号、影响放大；也可指详述：amplify a point 展开说明。\",\n\"amuse\":\"画面：小丑一个鬼脸，全场孩子笑作一团——amuse「逗乐」。muse 本是『沉思』：让人出神发笑；amusement park 游乐园，amused 是『觉得好笑的』，注意与 amusing『有趣的』分工。\",\n\"analyse\":\"画面：化验员把水样拆成一项项指标逐个查——analyse「分析」。ana-『向上、彻底』+ lyse『松开』（analysis 分析）：把整体松开、拆透；英式拼 analyse，美式 analyze。\",\n\"anchor\":\"画面：船抛下铁锚，锚爪钩住海底，船稳稳停住——anchor「锚定」。锚让船不漂走；引申义是一切让人稳住的东西，新闻主播也叫 anchor。\",\n\"animate\":\"画面：画师一张张画下去，纸上的小人跑了起来——animate「使生动」。anim 是『生命、气息』（animal 动物）：给无生命的东西注入生命；animated film 就是动画片。\",\n\"announce\":\"画面：广播里传来通知：列车晚点二十分钟——announce「宣布」。nunti 是『传信』：把消息公之于众；announcement 是公告，announcer 是播音员。\",\n\"annoy\":\"画面：耳边蚊子嗡嗡个不停，他烦躁地挥手赶——annoy「使烦恼」。不大不小、持续不断的惹人烦；annoying 是『讨厌的』，annoyed 是『感到恼火的』，主被动分清。\",\n\"apologize\":\"画面：他红着脸对同事说：『昨天的事，是我不对。』——apologize「道歉」。apo + log『言说』：为过错开口认错；apologize to sb for sth 是『因某事向某人道歉』。\",\n\"appear\":\"画面：雾散开，远处的灯塔慢慢显出来——appear「出现」。ap- + par『显现』（apparent 明显的）：进入视线、露面；也可指『似乎』：it appears that 看来……。\",\n\"applaud\":\"画面：演出结束，观众全体起立鼓掌——applaud「鼓掌」。plaud 是『拍手』（plausible 貌似合理的，源于博得喝彩）：拍手叫好；引申为赞许 applaud the decision。\",\n\"apply\":\"画面：她填好申请表，附上成绩单寄了出去——apply「申请」。ap- + ply『折叠、贴上』（plywood 胶合板）：把自己贴到岗位上去；apply for 申请，apply to 适用于，apply oneself 专心致志。\",\n\"appoint\":\"画面：董事会宣布，任命她为新任校长——appoint「任命」。point 是『指定一点』：指定某人担任某职；appointment 既是任命，也是约好的会面时间。\",\n\"appraise\":\"画面：鉴定师对着花瓶看了又看，给出估价——appraise「评价鉴定」。与 praise『赞美』形近：praise 是夸，appraise 是估价评定价值，房产、员工业绩都可 appraise。\",\n\"approve\":\"画面：经理看完方案，在末尾签了字——approve「批准」。prove 是『证明』：审过、证实可行才点头；approve of 是赞成，approve a plan 是批准计划，语气不同。\",\n\"approximate\":\"画面：他估算了一下路程：『大概十公里。』——approximate「接近于」。proxim 是『最近』（proximity 邻近）：与真值接近但不完全相等；作形容词读尾 -ət，动词读 -eɪt。\",\n\"arch\":\"画面：猫伸了个懒腰，把背高高拱起——arch「拱起」。拱形的东西天然是弯的；作动词就是把身子、眉毛弯成拱形，arch one's back 弓起背。\",\n\"argue\":\"画面：两人为方案争得面红耳赤，谁也说不服谁——argue「争论」。arg 是『使清楚』（argument 论点）：摆理由讲清楚；argue for/against 是主张/反对，学术写作高频。\",\n\"arise\":\"画面：讨论正热烈，一个新问题冒了出来——arise「发生」。a + rise『升起』：问题、困难像冒泡一样浮现；arise from 是『由……引起』，注意与 rise、arouse 区分。\",\n\"arrange\":\"画面：她把书按大小在架子上码整齐——arrange「安排」。range 是『行列』（range 范围）：把东西排进秩序里；arrange a meeting 是安排、筹备会议。\",\n\"arrive\":\"画面：列车缓缓进站，广播响起：终点站到了——arrive「到达」。法语源是『到达岸边』（rive 岸）：抵达目的地；arrive at/in 的 at 配小地点、in 配大地方。\",\n\"articulate\":\"画面：他把复杂的想法说得条条清楚——articulate「清晰表达」。articul 是『关节、小节』（article 文章）：把话像关节一样一节节接清楚；作形容词读 -ət，是『善于表达的』。\",\n\"ascend\":\"画面：登山者沿着冰坡一步步往上爬——ascend「上升」。a + scend『爬』（descend 下降）：向上攀登；ascend the throne 是登基，ascend to 是升到。\",\n\"ascertain\":\"画面：侦探核对了三处监控，终于查明真相——ascertain「查明」。certain 是『确定』：通过调查把事情弄确实；正式用词，比 find out 更书面。\",\n\"ashamed\":\"画面：他弄坏了妹妹的玩具，低着头不敢看她——ashamed「感到羞耻」。为自己做错的事脸红；be ashamed of 对……感到羞愧，与 shy『害羞』不同，ashamed 带着自责。\",\n\"askew\":\"画面：墙上的画框歪向一边，怎么看怎么别扭——askew「歪斜」。a + skew『斜』：挂歪了、放斜了的状态；计划出岔子也可说 go askew。\",\n\"assert\":\"画面：他挺直腰板，一字一顿地说：『这是我的权利。』——assert「断言」。as- + sert『放、断言』：把话放得斩钉截铁；assert oneself 是坚持自己的主张，assert that 是断言。\",\n\"assimilate\":\"画面：新移民慢慢学会了当地的语言和习惯——assimilate「同化」。simil 是『相似』（similar 相似的）：变得和周围一样；也可指吸收知识 assimilate information。\",\n\"associate\":\"画面：提到夏天，他立刻想到西瓜和蝉鸣——associate「联想」。soci 是『同伴』（society 社会）：把两样东西结成伴；associate A with B 把 A 和 B 联系起来。\",\n\"assure\":\"画面：医生拍拍他的手：『放心，手术很成熟。』——assure「保证」。sure 是『确定』：向人打包票让其安心；assure sb of sth 保证某事，与 ensure、insure 三兄弟要分清：assure 对人，ensure 保事成，insure 上保险。\",\n\"attach\":\"画面：她把照片用回形针别在简历后面——attach「附加」。tach 是『钉』（tack 图钉）：把一物固定在另一物上；邮件附件 attachment 就由此来；attach importance to 是『重视』。\",\n\"attack\":\"画面：狼群从侧翼扑向羊群——attack「攻击」。突然发力打过去；疾病发作也叫 attack，如 heart attack 心脏病发作；attack a problem 是着手攻克难题。\",\n\"attempt\":\"画面：他深吸一口气，第一次尝试后空翻——attempt「尝试」。tempt 是『试探』（temptation 诱惑）：试着去做成某事；attempt to do 是尝试做，名词 attempt 是努力本身。\",\n\"attend\":\"画面：会议室座无虚席，他准时到场——attend「出席」。tend 是『伸向、趋向』（intend 打算）：身心趋向某场合；attend a lecture 听讲座，attend to 是『处理、照料』，一词两义靠搭配分。\",\n\"attract\":\"画面：磁铁隔着纸就把回形针吸得跳起来——attract「吸引」。tract 是『拉』（extract 拔出、tractor 拖拉机）：像磁铁一样把人拉过来；attract attention 是吸引注意。\",\n\"audit\":\"画面：审计员抱着一摞账本，一笔笔核对——audit「审计」。aud 是『听』（audience 听众）：古代查账靠听人念账；现在指系统核查账目，也可指旁听课程。\",\n\"augment\":\"画面：公司又招了五十人，团队规模再扩一圈——augment「增加」。aug 是『增长』（author 创始者同源）：在原有基础上添量；augment income 是增加收入，正式用词。\",\n\"authenticate\":\"画面：专家比对了签名笔迹，确认信件是真迹——authenticate「证实真实」。auth 是『本人、作者』（author 作者）：验明正身；现在也指身份验证，如 two-factor authentication 双重验证。\",\n\"authorise\":\"画面：经理在报销单上签字放行——authorise「授权（英）」。author『创始者』+ -ise：授予做事的权力；这是英式拼写，美式是 authorize，意思完全相同。\",\n\"authorize\":\"画面：议会通过法案，授权政府动用储备金——authorize「授权」。正式给予批准或权力；authorized personnel 是『授权人员』，闲人免进的那种。\",\n\"automate\":\"画面：工厂装上机械臂，整条产线不用人手了——automate「使自动化」。auto『自己』+ mat『动』：让机器自己动起来；automation 是自动化本身。\",\n\"avail\":\"画面：他翻遍了所有办法，还是无济于事——avail「有用」。多出现在固定说法里：to no avail 徒劳无功，avail oneself of 是『利用』；单独使用很少见，记住搭配最稳。\",\n\"avenge\":\"画面：他苦练十年，只为给家人报仇——avenge「报仇」。veng 是『报复』（revenge 报复）：替受害者讨回公道；avenge 是替别人报仇，revenge 多指为自己，语境细微差别。\",\n\"average\":\"画面：五次测验加起来一除，他平均考 82 分——average「平均为」。作动词是算出或达到平均数；average out 是最终平均为，形容词 average 还有『平庸的』一义。\",\n\"avert\":\"画面：司机猛打方向盘，险险避开横穿的行人——avert「避免灾祸」。a + vert『转』（convert 转换）：把脸、把车头转开——avert disaster 避免灾难，avert one's eyes 移开目光。\",\n\"avoid\":\"画面：他特意绕开那条施工的路——avoid「避免」。void 是『空』（void 无效的）：让某事落空、不发生；avoid doing sth 是避免做某事，搭配是动名词。\",\n\"await\":\"画面：站台上，人们望着铁轨尽头等车来——await「等待（正式）」。比 wait 更正式、书面：await a reply 等待回复；语法上直接带宾语，不加 for。\",\n\"awake\":\"画面：闹钟一响，她揉着眼睛坐起来——awake「唤醒」。醒来或唤醒；多作 be awake『醒着』；注意 awake、awaken、wake、waken 四亲戚里 awake 最常用作形容词。\",\n\"award\":\"画面：颁奖礼上，他接过金杯，高高举起——award「授予」。ward 是『判定、守护』：经评定把荣誉、奖金判给某人；award 既是动词『授予』也是名词『奖项』。\",\n\"backfire\":\"画面：他设计的圈套反而把自己套了进去——backfire「适得其反」。back + fire：枪向后走火；计划、言论反噬到自己头上，常说 the plan backfired。\",\n\"backpack\":\"画面：背上大包，沿着山间小路徒步三天——backpack「背包旅行」。back + pack：背包客的玩法就是这个词；作名词是双肩背包，作动词是背包徒步旅行。\",\n\"backtrack\":\"画面：走到死胡同，只好沿原路退回去——backtrack「原路返回」。track 是『足迹、小路』：沿着自己的脚印往回走；也可指收回先前的话、改口。\",\n\"badge\":\"画面：警察亮出胸前的警徽，围观人群让开一条路——badge「徽章」。表明身份、等级的标志物；动词义是『标记』：把东西打上记号。注意这里列的是动词用法，名词更常见。\",\n\"baffle\":\"画面：魔术师的手法快得全场抓耳挠腮，谁也看不懂——baffle「使困惑」。把人彻底难住；baffling 是『令人费解的』，科学家面对反常数据时常用这个词。\",\n\"bag\":\"画面：猎人把猎物装进袋子，扛上肩往回走——bag「装袋」。名词是袋子，动词就是往袋里装；口语 bag a prize 是『把奖收入囊中』。\",\n\"bake\":\"画面：烤箱里，面团慢慢鼓起，表面烤成金黄色——bake「烘烤」。用干热烤熟；baker 面包师，bakery 面包房；烈日暴晒也可戏说 be baked。\",\n\"balance\":\"画面：走钢丝的人张开双臂，身体微微左右晃——balance「平衡」。天平两端一样重就是平衡；作动词是保持平衡、权衡，balance work and life 是平衡工作与生活。\",\n\"ban\":\"画面：市政府贴出告示：湖区禁止游泳——ban「禁止」。官方明令不许；ban sb from doing 是禁止某人做某事，名词 ban 是禁令本身。\",\n\"bang\":\"画面：门被风猛地摔上，发出砰的一声巨响——bang「猛击」。拟声词成真词：重击、巨响都是它；bang on the door 是砰砰砸门。\",\n\"banish\":\"画面：古代臣子被贬，一路被送往千里之外的边地——banish「放逐」。ban 是『宣告』：被官方宣告赶出本土；也可比喻驱散情绪 banish fear 驱散恐惧。\",\n\"bankrupt\":\"画面：工厂大门贴上封条，老板宣布破产——bankrupt「使破产」。bank + rupt『断裂』（erupt 喷发）：钱柜断了底；go bankrupt 是破产，作形容词是『破产的』。\",\n\"bar\":\"画面：酒吧门口保安伸手拦住未成年者——bar「禁止进入」。bar 本是『横木、栅栏』：像栏杆一样挡住；bar sb from entering 是禁止某人进入；律师界 the Bar 指律师职业。\",\n\"bare\":\"画面：冬天的大树落光叶子，只剩光秃秃的枝桠——bare「露出」。把遮盖物去掉露出本来面目；bare feet 是赤脚，别和 bear（忍受、熊）混，读音相同。\",\n\"bargain\":\"画面：集市上，买家和摊主你来我往，最后各让一步成交——bargain「讨价还价」。谈出双方都接受的价格；名词 bargain 还指划算的买卖，a real bargain 是真捡漏。\",\n\"barge\":\"画面：他推门就往里冲，肩膀撞开了两个人——barge「闯入」。barge 本是『驳船』：像大船一样横冲直撞地挤进来；barge into a room 是贸然闯入。\",\n\"barrel\":\"画面：酒窖里，橡木桶一排排码着，陈酿在黑暗里沉睡——barrel「桶」。圆肚子的容器；作动词是把东西装桶，也指飞速冲（车辆 barrel down the road 疾驰而下）。\",\n\"barricade\":\"画面：街口堆起桌椅沙袋，堵成一道临时墙——barricade「设路障；路障」。bar 是『横木』：用杂物堆成的障碍；动词就是堆路障堵路。\",\n\"barter\":\"画面：集市上，他用一筐鸡蛋换了邻居的一袋面粉——barter「以物易物」。不用钱、物物交换；古代贸易的原形，现在也可指交换服务、技能。\",\n\"bask\":\"画面：猫趴在阳台的阳光里，眯着眼一动不动——bask「晒太阳取暖」。惬意地享受温暖；引申 bask in glory 是沉浸在荣耀里，bask in praise 是陶醉于赞美。\",\n\"batch\":\"画面：面包房里，一盘盘面团分批送进烤箱——batch「分批处理」。一炉、一批的数量单位；batch process 是批处理，a batch of 是一批。\",\n\"bath\":\"画面：忙碌一天，整个人泡进热水里，长舒一口气——bath「洗澡」。英式里 bath 既是浴缸也是洗澡这件事；take a bath 是洗个澡，美式多用 bathe 或 shower 分工。\",\n\"batter\":\"画面：拳击台上，他被连续重拳打得连连后退——batter「连续猛击」。bat 是『球棒』：一下接一下地猛打；也可指把东西打坏、虐待，battered 是『破旧受损的』。\",\n\"bawl\":\"画面：摔了一跤的孩子坐在地上，扯着嗓子大哭——bawl「放声大哭」。嗓门全开的嚎哭；也可指大声喊叫 bawl orders 扯着嗓子下命令。\",\n\"beacon\":\"画面：暴风雨夜，灯塔的光柱在海面上缓缓旋转——beacon「作灯塔指引」。beacon 本是灯塔、信号灯：指引方向的亮光；作动词是像灯塔一样指引。\",\n\"bead\":\"画面：额头上的汗珠一颗颗滚下来——bead「用珠装饰；珠状物」。bead 是小珠子：汗珠、水珠都叫 beads of sweat；作动词是把东西串成珠或使成珠状。\",\n\"bean\":\"画面：棒球飞来，正砸在击球手头盔上——bean「用球击中头部」。这是棒球俚语义；bean 的本行是『豆子』，coffee bean 咖啡豆、bean curd 豆腐，全靠语境分。\",\n\"bear\":\"画面：牙医钻牙再疼，他也咬咬牙忍着——bear「忍受」。一个词两副面孔：作名词是熊，作动词是忍受、承担、生育；bear with me 是『请耐心等我一下』。\",\n\"beast\":\"画面：猎人对捕获的野兽毫不留情——beast「野兽」。beast 是凶猛的野兽；这里的动词义『野兽般对待』很少见，beast 更常见的是名词，也可指讨厌的人或难缠的事。\",\n\"beat\":\"画面：终场哨响，他以一分险胜卫冕冠军——beat「击败」。打败对手；本义是敲打：心跳 heart beat、打鸡蛋 beat eggs、打节拍，全是『打』的引申。\",\n\"beautify\":\"画面：老街改造后种上花坛，老房子焕然一新——beautify「美化」。beauty + -fy『使……化』：让地方、环境变得好看；城市 beautification 是美化工程。\",\n\"beckon\":\"画面：导游站在路口，向散开的游客招手示意跟上——beckon「召唤示意」。用手势或点头叫人过来；机会、未来也可 beckon，像在远处招手。\",\n\"become\":\"画面：毛毛虫在茧里沉睡，醒来成了蝴蝶——become「变成」。最核心的变化动词：become + 形容词/名词；过去式 became，过去分词 become，变形要记牢。\",\n\"bed\":\"画面：旅途劳顿，他早早铺好床躺下——bed「安置睡觉」。bed 本是床，作动词是上床睡觉、安置住宿；go to bed 是就寝，bed down 是临时睡下。\",\n\"beep\":\"画面：微波炉叮地一响，提示加热完成——beep「发出哔声」。电子设备短促的提示音；倒车、按键都会 beep，名词 beep 就是那一声。\",\n\"befall\":\"画面：谁也没料到，那样的厄运会落到他头上——befall「降临发生」。be + fall『落下』：祸事、命运落在某人身上；书面词，多用于不好的事，现代英语少见。\",\n\"beforehand\":\"画面：出发前一晚，他把证件、行李全部提前备好——beforehand「预先」。hand 在前面：事先、提前做好准备；多作副词，正式说法是 in advance。\",\n\"befriend\":\"画面：转学第一天，同桌主动带他熟悉校园——befriend「与人交友」。be- 使动 + friend：主动和某人成为朋友；多指在人困难、孤单时伸出的友谊。\",\n\"beg\":\"画面：他双手合十，恳求对方再给一次机会——beg「乞求」。beg 是恳切请求，程度比 ask 重得多；beg for mercy 求饶，beg to differ 是『恕我不同意』的礼貌说法。\",\n\"beget\":\"画面：史书上写着：亚伯拉罕生以撒，以撒生雅各——beget「产生后代」。古旧书面词，指父亲生育子女；引申义是引发：violence begets violence 暴力滋生暴力。\",\n\"begin\":\"画面：指挥棒落下，乐团奏响第一个音符——begin「开始」。begin to do / begin doing 都可；与 start 近义，begin 更正式；变形 began、begun 必背。\",\n\"behave\":\"画面：老师一进教室，吵闹的孩子们立刻规矩坐好——behave「表现」。behave oneself 是『守规矩』；behave well/badly 表现好坏；物理、材料在条件下的反应也用 behave。\",\n\"belch\":\"画面：他喝完汽水，打了一个响亮的饱嗝——belch「打嗝」。胃里的气从口排出；火山、烟囱喷吐烟火也可说 belch out，形象得很。\",\n\"belie\":\"画面：她笑着说话，颤抖的手却暴露了紧张——belie「掩饰真相」。lie 是『谎言』：表面与真相相矛盾、给人假象；belie one's age 是『看起来不像实际年龄』。\",\n\"believe\":\"画面：他看着老友的眼睛：『这事，我信你。』——believe「相信」。believe in 是相信存在、信任（神、理念、某人），believe sb 是相信某人说的话，分工靠 in。\",\n\"bellow\":\"画面：公牛仰起头，吼声震得草地发颤——bellow「吼叫」。牛的大声吼叫；人扯着嗓子怒吼也用它，比 shout 更粗重、更原始。\",\n\"belong\":\"画面：这本书放回图书馆三层的架子上，各归其位——belong「属于」。belong to sb 属于某人；belong in 是『应该放在、属于（某处）』，归属感 a sense of belonging。\",\n\"belt\":\"画面：他把腰带又勒紧一格，裤子才不往下掉——belt「用带系」。belt 本是腰带，作动词是系紧；口语 belt out 是放声高歌，belt along 是飞速行驶。\",\n\"bemuse\":\"画面：新魔术一个接一个，他看得一脸茫然——bemuse「使迷惑」。muse 是『沉思』：让人陷入迷糊、反应不过来；bemused 是『困惑的』，注意和 amused『觉得好笑』只差一字母。\",\n\"bend\":\"画面：他弯下腰，系紧鞋带——bend「弯曲」。把直的弄弯；bend down 弯腰，bend the rules 是『变通规则』，bend over backwards 是竭尽全力。\",\n\"bendable\":\"画面：这种塑料尺弯成 U 形也不会断——bendable「可弯曲的」。bend + -able『能……的』：能弯折而不折断的性质；柔性材料、瑜伽动作都可形容。\",\n\"bequeath\":\"画面：老人立下遗嘱，把藏书全留给母校图书馆——bequeath「遗赠」。正式法律用词：以遗嘱把财产留给某人；名词 bequest 是遗产、遗赠物。\",\n\"bereave\":\"画面：噩耗传来，她一夜之间失去了丈夫——bereave「丧亲」。使人失去至亲的正式词；bereaved 是『丧亲者』，多用于慰问语境，如 the bereaved family。\",\n\"beset\":\"画面：登山队刚出营地，就被暴风雪和缺氧轮番围困——beset「围攻困扰」。be + set『围住』：问题、困难从四面八方压过来；beset by problems 是被问题困扰。\",\n\"besiege\":\"画面：大军把城池围得水泄不通，断了粮道——besiege「围攻」。siege 是『围城』（siege 本义坐守）：围住逼降；引申为记者、粉丝团团围住某人提问。\",\n\"besmirch\":\"画面：谣言像墨汁泼在白衬衫上，名声一下子脏了——besmirch「玷污」。smirch 是『污点』：败坏名誉；多用于 reputation、honor 等抽象对象，正式书面词。\",\n\"bestow\":\"画面：校长把荣誉勋章郑重别在教授胸前——bestow「授予荣誉」。正式的『授予、赐予』：bestow an honor on sb 把荣誉授予某人，语气庄重，多见于典礼与文学。\",\n\"bet\":\"画面：他掏出十块钱：『我赌这匹马赢。』——bet「打赌」。下注赌输赢；I bet 是口头禅『我敢肯定』：I bet you're tired 我猜你累了——不是真赌博。\",\n\"betray\":\"画面：他把秘密告诉了对手，多年交情毁于一旦——betray「背叛」。出卖信任、泄露秘密；也可指不经意暴露：her voice betrayed her nervousness 声音出卖了她的紧张。\",\n\"beware\":\"画面：草地边立着牌子：Beware of the dog——beware「当心」。只用在祈使句和不定式里的特殊动词：beware of sth 提防某物；没有时态变化，记住整块搭配。\",\n\"bewilder\":\"画面：迷宫般的巷子转了三圈，他彻底晕了方向——bewilder「使迷惑不解」。wilder 是『荒野』（wilderness 荒野）：像把人丢进荒野般摸不着头脑；bewildered 是『不知所措的』。\",\n\"bewitch\":\"画面：她的歌声一起，满场观众像被施了魔法——bewitch「使着魔」。witch 是『女巫』：像巫术一样让人着迷、神魂颠倒；bewitching 是『迷人的』，文学语气。\",\n\"bind\":\"画面：他把一摞书用绳子捆紧，拎起来就走——bind「绑定」。捆、绑、装订（书）都是它；引申为约束：be bound by 受……约束；bound 还有『注定、前往』等多个义项，靠语境分。\",\n\"binge\":\"画面：假期里他一口气追完三季剧，零食袋堆成山——binge「狂欢放纵」。短时间内过度地吃、喝、看：binge-watch 是刷剧，binge eating 是暴食；名词 binge 是放纵的一阵。\",\n\"biodegrade\":\"画面：埋进土里的香蕉皮，几周后被微生物分解得只剩渣——biodegrade「生物降解」。bio『生命』+ degrade『降解』：被细菌、真菌吃掉分解；biodegradable 是『可生物降解的』，环保话题高频。\",\n\"bite\":\"画面：他咬了一大口辣椒，眼泪瞬间涌出来——bite「咬」。用牙齿切断、夹住；蚊虫叮咬、严寒刺骨（biting wind）都用 bite；bite the bullet 是咬紧牙关硬扛。\",\n\"blab\":\"画面：她嘴一快，把惊喜派对的计划全说漏了——blab「泄密」。管不住嘴说出不该说的；blab about 是喋喋不休地抖搂，带贬义。\",\n\"blacken\":\"画面：烤糊的吐司边缘焦黑，冒着苦味——blacken「变黑」。black + -en『使……』：使变黑；也可比喻败坏名声 blacken sb's name，与 besmirch 同路。\",\n\"blacklist\":\"画面：违规公司的名字被列进黑名单，再也不能投标——blacklist「列入黑名单」。black + list：被各家共同抵制的名单；作动词就是把某人打入这份名单。\",\n\"blackmail\":\"画面：他攥着别人的把柄，威胁不给钱就抖出去——blackmail「勒索」。mail 在此是古语『租金、贡金』：以揭短相威胁索财；既是名词也是动词，犯罪新闻常见。\",\n\"blame\":\"画面：项目黄了，他把责任全推到实习生头上——blame「责备」。blame sb for sth 因某事怪某人；be to blame 是『该负责』，主语是出问题的人或事，别用错方向。\",\n\"blare\":\"画面：卡车喇叭长鸣，震得行人捂耳朵——blare「高声鸣响」。刺耳地大声响：喇叭、警笛、广播都可 blare；名词 blare 是那阵刺耳声。\",\n\"blast\":\"画面：工兵按下起爆器，山体轰然被炸开——blast「爆破」。爆炸、爆破都是它；名词 blast 是爆炸、冲击波，也可指一阵强风 a blast of cold air。\",\n\"bleach\":\"画面：白衬衫泡进漂白水，顽渍一点点褪掉——bleach「漂白」。使颜色褪去变白；bleach 本身就是漂白剂，晒褪色、染发漂色都用它。\",\n\"bleed\":\"画面：手指被纸划开，血珠慢慢渗出来——bleed「流血」。blood 的动词亲戚：出血、放血；引申 bleed money 是大把往外淌钱，心疼得像在流血。\",\n\"blemish\":\"画面：一块美玉上有一道小裂纹，价格大打折扣——blemish「玷污损害」。名词是瑕疵、污点，动词是给完美之物添上瑕疵；blemish one's record 是给记录抹黑。\",\n\"analyze\":\"画面：研究员把一团乱麻拆成一根根线，逐根贴标签——analyze「分析」。分析不是笼统地看，而是拆成部分再看关系；名词 analysis、形容词 analytical 是它的一家人。\",\n\"approach\":\"画面：同一座山，登山队选了北坡这条路线慢慢往上走——approach「方法；途径」。approach 本义是『走近』，处理问题时选的那条走近之路，就是方法；approach a problem 是着手处理问题。\",\n\"assess\":\"画面：估价师绕着房子走一圈，量面积、看房龄，最后在表格上写下价值——assess「评估」。assess 不是随口评价，而是按标准衡量价值、程度或影响；assessment 是评估结果。\",\n\"assume\":\"画面：桥还没做承重检测，工程师先在图纸上写『假定能承重 10 吨』继续计算——assume「假设」。assume 是先当作真的用，但尚未证实；论文里 assume 之后往往还要验证，别把它当事实。\",\n\"concept\":\"画面：老师没有先背定义，而是在黑板上画了鸟、飞机和风筝，问全班『它们共同的想法是什么』——concept「概念」。概念是把许多具体例子抽出来的共同想法；conceptual 是概念上的。\",\n\"economic\":\"画面：一座城市的工厂、商店、工资和物价被画成一张互相牵动的网——economic「经济的」。economic 只谈经济体系与钱货运行；表示『划算、节约』要用 economical，别混。\",\n\"estimate\":\"画面：施工队没等精确测量，先量了房间长宽，在本子上写下『大约需要 12 卷壁纸』——estimate「估计」。estimate 是有依据的粗算，不是乱猜；作名词时重音在后，estimate of cost 是成本估算。\",\n\"income\":\"画面：每个月工资、租金和稿费像三条小溪汇进同一个账户——income「收入」。income 看一段时间流入的钱；工资单上的 gross income 是税前总收入，和一次性的 prize money 不一样。\",\n\"issue\":\"画面：会议桌中央放着一张写着『水资源短缺』的牌子，所有人围着它争论——issue「议题；问题」。issue 是摆上台面、必须讨论解决的事项；an issue of a magazine 才是『一期杂志』。\",\n\"legal\":\"画面：合同最后一页盖着公章，律师逐条核对是否符合法规——legal「法律的；合法的」。legal 来自 law；在法律框架内就是 legal，越过边界则是 illegal。\",\n\"legislation\":\"画面：议会大厅里，一部新法案经过辩论和表决，正式被写进法典——legislation「立法；法规」。legis- 是『法律』，legislation 既可指制定法律的过程，也可指已经通过的法规总称。\",\n\"research\":\"画面：实验室的灯亮了一整夜，研究员把同一组数据反复核对、推翻、再验证——research「研究」。research 是系统地查清事实；do research on a topic 是研究某个课题，它通常不加 a、不用复数。\",\n\"similar\":\"画面：两片叶子并排放在灯下，叶脉走向几乎一模一样，只有一处缺口不同——similar「相似的」。similar to 是『与……相似』；similar 只说像，identical 才说完全相同。\",\n\"structure\":\"画面：一座桥的桥墩、钢梁和拉索被拆成透视图，每根梁都撑着别的部分——structure「结构」。structure 是部分如何搭成整体；楼房、句子和组织都有自己的 structure。\",\n\"theory\":\"画面：科学家在黑板上写出一套能解释所有实验现象的推导，但角落标注着『尚待验证』——theory「理论」。theory 不是随口猜想，而是能解释现象、等待检验的系统说法；hypothesis 比它更初步。\",\n\"achieve\":\"画面：登山者在暴风雪里一步一步挪，终于把旗插上山顶——achieve「实现；达到」。achieve 强调费力后真正做到；achieve a goal、achieve success 都是『付出努力换来的达成』。\",\n\"commission\":\"画面：事故发生后，七位专家被正式任命，围坐在长桌旁独立调查——commission「委员会」。这个 commission 是受委托办事的一组人；销售提成也是 commission，但托福文章里先想『专门委员会』。\",\n\"community\":\"画面：一条街上住着几十户人家，共用学校、公园和图书馆，节庆时一起聚餐——community「社区」。community 是住在一起、生活相连的一群人；学术写作里也有 scientific community『科学界』。\",\n\"evaluation\":\"画面：评审团拿着评分表，从创新、成本到风险一项项打分，最后给出总评——evaluation「评估」。evaluation 比普通 opinion 更系统：先有标准，再下判断；evaluate 是它的动词。\",\n\"facility\":\"画面：新建的体育中心里有泳池、实验室和无障碍通道，专为训练和研究而建——facility「设施」。facility 是为某项活动专门配备的场所或设备，常作复数 facilities，如 medical facilities 医疗设施。\",\n\"impact\":\"画面：陡坡上滚下的巨石重重砸进湖面，水花和波纹向四周扩散——impact「影响；冲击」。impact 本义是撞击，引申为强而明显的影响；have an impact on 是最常见的搭配。\",\n\"injury\":\"画面：运动员落地时脚踝扭成不自然的角度，队医立刻上场固定——injury「伤害」。injury 是身体受到的损伤；serious injury 是重伤。别和 insult『侮辱』混，前者伤身，后者伤脸面。\",\n\"investment\":\"画面：农夫把今年最好的种子留下一半，没有吃掉，而是播进地里等来年收获——investment「投资」。investment 是把钱或资源先投进去、期待将来回报；invest in education 是投资教育。\",\n\"relevant\":\"画面：法官敲了敲桌子：『这份证据和本案有什么关系？』律师立刻指出关键时间点——relevant「相关的」。relevant to the topic 是『与主题相关』；无关的是 irrelevant，少了这个词，材料再好也用不上。\",\n\"security\":\"画面：机场安检口，行李过机、证件核验、警犬巡逻，一层一层把关——security「安全；安保」。security 既是『安全状态』，也是负责安全的措施和人员；financial security 是经济上的安全感。\",\n\"strategy\":\"画面：教练没有盯着下一分钟，而是把整场比赛的换人和进攻路线画满白板——strategy「策略」。strategy 看全局和长期安排；临时应付的小办法是 tactic，别把两者调换。\",\n\"survey\":\"画面：调查员拿着问卷站在社区门口，挨家挨户问居民对新公园的看法——survey「调查」。survey 是系统地收集许多人的回答或实地勘测；conduct a survey 是开展调查。\",\n\"text\":\"画面：教授把一篇文章投到大屏幕上，逐段标出论点和证据——text「文本」。text 是写下来的文字整体；课本是 textbook，手机短信也是 text，但学术阅读里先想『篇章文本』。\",\n\"transfer\":\"画面：货物从卡车卸下，转装到火车上继续运往内陆——transfer「转移；转运」。transfer 是把人、钱、物或权利从一处移到另一处；bank transfer 是银行转账，transfer schools 是转学。\",\n\"bacteria\":\"画面：显微镜下，一群杆状小点挤在培养皿里，一分裂二、二分裂四——bacteria「细菌」。bacteria 是 bacterium 的复数；它们小到肉眼看不见，却能致病，也能帮人做酸奶。\",\n\"climate\":\"画面：气象站把三十年的降雨和气温画成曲线，而不是只看今天下没下雨——climate「气候」。climate 是一地长期的天气规律；今天的天气是 weather，一次下雨不能代表 climate。\",\n\"consequence\":\"画面：第一块多米诺骨牌倒下，后面一长排跟着倒——consequence「后果」。consequence 是前面事情必然带出的结果，常指坏结果；as a consequence 是『因此』。\",\n\"constant\":\"画面：实验室的恒温箱一整周都显示 25°C，指示灯从不跳动——constant「持续的；恒定的」。constant 是不间断、不变化；constant noise 是持续噪音，a constant temperature 是恒温。\",\n\"expand\":\"画面：气球被一点点吹大，表面向四面八方撑开——expand「扩张；扩大」。expand 是体积、范围或业务变大；expand on a topic 还可以是『详细阐述某个话题』。\",\n\"experiment\":\"画面：科学家只改变一个变量：两盆植物一盆照光、一盆遮光，其余条件全一样——experiment「实验」。experiment 的关键是控制条件来验证想法；conduct an experiment 是做实验。\",\n\"friction\":\"画面：两只手掌用力来回搓，很快就发热、发红——friction「摩擦」。friction 是表面接触时阻碍滑动的力；物体之间、人与人之间的不和也可叫 friction，先记物理画面。\",\n\"hazardous\":\"画面：仓库门口贴着骷髅标志，工人必须戴手套和护目镜才能进去——hazardous「危险的」。hazardous waste 是危险废物；hazard 是危险源，hazardous 是『具有危险的』。\",\n\"humid\":\"画面：梅雨季的房间里，镜子蒙上一层水雾，晾的衣服三天不干——humid「潮湿的」。humid 说空气里水汽多；humidity 是湿度。南方夏天的闷热就是 hot and humid。\",\n\"magnet\":\"画面：一块 U 形磁铁刚靠近桌面，回形针『唰』地全被吸了过去——magnet「磁体」。magnet 的本事是吸铁并形成磁场；像磁铁一样吸引人的地方也可比喻为 magnet。\",\n\"particle\":\"画面：一束阳光斜射进屋，灰尘的微粒在光柱里慢慢漂浮——particle「粒子；微粒」。particle 是极小的颗粒；物理学里 particle physics 是粒子物理，语法里的『小品词』也是它。\",\n\"pollute\":\"画面：清澈的河水流经排污口后变黑，鱼翻着肚皮浮上水面——pollute「污染」。pollute 是把脏东西放进水、空气或土壤；pollution 是污染这件事，pollutant 是污染物本身。\",\n\"temperature\":\"画面：温度计里的红色液柱随着热水升起，停在 60 度刻度上——temperature「温度」。temperature 量的是冷热程度；take someone's temperature 是量体温，a high temperature 也可指发烧。\",\n\"transform\":\"画面：毛毛虫在茧里沉睡数周，破茧时展开一对翅膀——transform「变形；转变」。transform 是从里到外变成另一种形态；改革把旧仓库 transform 成图书馆，也是这种彻底改变。\",\n\"visible\":\"画面：雾散开后，远处的灯塔清清楚楚地露出来——visible「看得见的」。visible 是眼睛能捕捉到的；visible evidence 是看得见的证据。反义词 invisible 是藏在眼前的空气一样看不见。\",\n\"collapse\":\"画面：年久失修的脚手架突然失去支撑，整排轰然倒塌——collapse「坍塌；崩溃」。collapse 是结构撑不住后整体塌下；价格、谈判和人累到倒下，也都可用 collapse。\",\n\"detect\":\"画面：烟雾报警器捕捉到一丝烟，立刻发出尖锐的蜂鸣——detect「察觉；检测出」。detect 是发现原本不易察觉的信号或变化；detect a change、detect a disease 都靠敏锐的探查。\",\n\"duration\":\"画面：计时器从按下开始一路走到影片结束，显示整整两小时——duration「持续时间」。duration 回答『持续多久』；for the duration of the war 是『在整个战争期间』。\",\n\"eliminate\":\"画面：排查电路时，工程师逐个排除不可能的故障点，最后只剩真正的元凶——eliminate「消除；淘汰」。eliminate 是彻底除掉；比赛里被淘汰、体内排出废物，也都用它。\",\n\"empirical\":\"画面：教授不接受『我觉得』，要求学生摆出实验数据和观察记录——empirical「经验的；实证的」。empirical evidence 是靠观察和实验得来的证据，不是纯理论推导；这是托福学术阅读的高频词。\",\n\"equilibrium\":\"画面：天平两端各放砝码，指针稳稳停在正中央，谁也不压过谁——equilibrium「平衡」。equilibrium 是力量或供需互相抵消的稳定状态；一旦打破，系统就会动起来。\",\n\"global\":\"画面：卫星镜头拉远，整颗蓝色地球出现在屏幕上——global「全球的」。global 不是某一个国家，而是全世界范围；global warming 是全球变暖，global market 是全球市场。\",\n\"inspect\":\"画面：质检员戴着白手套，把每个零件翻过来对着灯光仔细看——inspect「检查」。inspect 比 look 更认真、更官方，是为发现问题而查；inspect the factory 是视察工厂。\",\n\"investigate\":\"画面：侦探把现场照片、时间线和证词摊满桌面，一条条追查——investigate「调查」。investigate 是深入查清真相，常用于事故、犯罪和科学问题；investigation 是它的名词。\",\n\"invisible\":\"画面：玻璃门太干净了，走路的人没看见，一头撞了上去——invisible「看不见的」。invisible 是眼睛捕捉不到；空气、细菌和隐形的影响都可以用它，别和 blind『失明』混。\",\n\"isolate\":\"画面：实验室把感染样本单独放进隔离箱，不让它接触其他样本——isolate「使孤立；隔离」。isolate 是把一个从整体中分开单独放置；isolate a problem 是单独拎出某个问题来处理。\",\n\"lecture\":\"画面：大教室里，教授站在讲台上连续讲了五十分钟，学生在台下记笔记——lecture「演讲；讲课」。lecture 是老师单向讲授的课；give a lecture 是做讲座，听众通常不插话。\",\n\"magnetic\":\"画面：小铁钉刚靠近那块石头就被牢牢粘住，拿都拿不下来——magnetic「磁性的」。magnetic 来自 magnet；magnetic field 是磁场。一个人很有吸引力，也可说有 magnetic personality。\",\n\"cease\":\"画面：工厂的机器轰鸣了一整天，按下停止键后，车间突然安静下来——cease「停止」。cease 比 stop 更正式，常用于协议和文章；cease production 是停产，ceasefire 是停火。\",\n\"conflict\":\"画面：两支队伍都想用同一块场地，时间表撞在一起，谁也不肯让——conflict「冲突」。conflict 是利益、意见或力量正面相撞；a conflict of interest 是利益冲突。\",\n\"controversy\":\"画面：一项新政策公布后，报纸一半支持、一半反对，电视辩论吵了整整一周——controversy「争论；争议」。controversy 是引起公众强烈分歧的话题；controversial 是『有争议的』。\",\n\"criteria\":\"画面：评委手里有一张清单：创新、成本、可行性，三项都达标才能通过——criteria「标准」。criteria 是 criterion 的复数；评判任何东西都要先有 criteria，再逐项对照。\",\n\"currency\":\"画面：旅客在机场把一叠人民币换成当地纸币，准备在市集上买东西——currency「货币」。currency 是一国通用的钱；foreign currency 是外币。表示『流行、时效』时也是这个词。\",\n\"debate\":\"画面：正反两方站在讲台两侧，一方刚说完，另一方立刻举牌反驳——debate「辩论」。debate 是有规则的公开争论；debate over a policy 是围绕政策展开辩论。\",\n\"decade\":\"画面：日历被一页页撕下，整整十本年历叠成一摞——decade「十年」。decade 就是 ten years；in recent decades 是『近几十年来』，托福历史类文章里极常见。\",\n\"decline\":\"画面：工厂订单一年比一年少，生产线从三条减到一条——decline「衰退；下降」。decline 是逐渐变弱、变少；作动词也可表示婉拒邀请，但经济文章里先想『下滑』。\",\n\"dilemma\":\"画面：岔路口两块牌子，一边是洪水、一边是悬崖，走哪边都不对——dilemma「窘境；两难」。dilemma 是两个选项都不好、必须选一个的处境；in a dilemma 就是进退两难。\",\n\"diverse\":\"画面：一张世界地图餐桌旁坐着不同肤色、说不同语言的人，端上来的菜各不相同——diverse「多种多样的」。diverse 强调种类丰富、彼此不同；a diverse community 是多元社区，diversity 是多样性。\",\n\"evaluate\":\"画面：老师拿着量规表，逐项核对作文的论点、证据和语言，最后写下总评——evaluate「评价；评估」。evaluate 和 assess 意思相近，都要按标准判断价值；evaluation 是名词。\",\n\"eventually\":\"画面：队伍在山里绕了三天，翻过最后一道山口，终于看见了城市的灯——eventually「最后；终于」。eventually 强调经过漫长过程后的最终结果，不是『立刻』；雨 eventually 会停，路 eventually 会走到头。\",\n\"fee\":\"画面：咨询结束时，前台递来一张单子：服务费 200 元，明码标价——fee「费用」。fee 是为专业服务或权利付的钱，如 tuition fee 学费、entrance fee 门票费；比 price 更正式。\",\n\"generation\":\"画面：全家福里，祖父母、父母和孩子三排人站在一起，中间一排正当壮年——generation「一代人」。generation 既是同龄的一代人，也可指发电和产生；the younger generation 是年轻一代。\",\n\"initial\":\"画面：报告打回来时只写了第一页，后面的数据还没补上——initial「最初的」。initial 是开始阶段的、第一步的；initial reaction 是第一反应。作名词时是姓名的首字母。\",\n\"innovation\":\"画面：老工厂引进一条从没人用过的自动化产线，产品一下领先同行——innovation「革新；创新」。innovation 是把新想法真正做成新方法或新产品；innovative 是『创新的』。\",\n\"liberal\":\"画面：市政辩论上，他主张保障言论自由、推动改革，不守旧规矩——liberal「自由的；开明的」。政治语境里 liberal 指主张进步改革的一派；liberal arts 是博雅教育，别只按党派理解。\",\n\"link\":\"画面：两节车厢之间扣上一只结实的铁环，一列火车就连成了整体——link「联系；连接」。link 本义是链条的一环；网上点的链接也是 link，因为它把两页连起来。\",\n\"modify\":\"画面：建筑师没有推倒重来，只把图纸上的窗户改大、楼梯改向——modify「修改」。modify 是局部调整使之更合适；重写全文是 rewrite，小改小动才是 modify。\",\n\"monitor\":\"画面：控制室的大屏幕实时跳动着每条管线的压力，一有异常就闪红灯——monitor「监视；监测」。monitor 是持续盯着并记录变化；作名词也是显示器，但动词义在学术文中更常见。\",\n\"nevertheless\":\"画面：天气预报说暴雨，比赛 nevertheless 照常开场——nevertheless「不过；仍然」。nevertheless = nonetheless，表示『尽管如此，后半句依然成立』；它转折的是让步，不是因果。\",\n\"notion\":\"画面：他脑子里一直有个模糊的想法：『也许城市可以建在海上』，还没有任何图纸——notion「观念；想法」。notion 是尚未成形的念头或看法，比 theory 轻得多；have a notion that… 是心里有个想法。\",\n\"ongoing\":\"画面：大桥修了两年还没合龙，工地上的塔吊今天仍在转——ongoing「持续的；进行中的」。ongoing 是现在仍在继续、没有结束；an ongoing project 是正在进行的项目。\",\n\"origin\":\"画面：顺着小河一直往上游走，水越来越细，最后找到山泉的源头——origin「起源；源头」。origin 是事物开始的地方或原因；country of origin 是原产国，original 是『最初的』。\",\n\"outcome\":\"画面：实验做了三个月，数据汇总成一张表，最终结论就写在这一页上——outcome「结果」。outcome 是事情发展到最后的结局，常用于实验、选举和治疗；它只问最后怎样，不问过程。\",\n\"overseas\":\"画面：货轮装满集装箱，鸣笛离港，驶向大洋对岸的港口——overseas「海外的」。overseas = over the sea，在海的另一边；study overseas 是出国留学，overseas markets 是海外市场。\",\n\"accumulate\":\"画面：屋檐下的水桶一夜接满了雨水，雪也是一层一层堆成雪山——accumulate「积累」。accumulate 是少量多次、慢慢攒多；灰尘、财富和证据都可以 accumulate。\",\n\"alter\":\"画面：裁缝把西装的腰身收紧了一寸，衣服还是那件，人穿上却精神多了——alter「改变」。alter 是改变某物的样子或性质，但本质还在；alter a plan 是修改计划。\",\n\"appreciate\":\"画面：观众在画前站了十分钟，越看越懂画家的用心，轻轻点头——appreciate「欣赏；感激」。appreciate 一是懂得价值而欣赏，二是心存感激；I appreciate your help 是『多谢你的帮助』。\",\n\"arbitrary\":\"画面：裁判没有规则，掷骰子决定谁赢，全场哗然——arbitrary「任意的；武断的」。arbitrary 是凭个人意气、没有依据地做决定；arbitrary rules 是随意定下的规矩。\",\n\"chart\":\"画面：十年销量被画成一根根升高的柱子贴在会议室墙上——chart「图表」。chart 是把数字画成看得懂的图；柱状、折线、饼图都可叫 chart，别和 map 地图混。\",\n\"coincide\":\"画面：两场会议偏偏排在同一天下午三点，日历上两个方框完全重叠——coincide「同时发生；巧合」。coincide 是时间或位置恰好对上；coincidence 是『巧合』这件事。\",\n\"commence\":\"画面：仪式上锣声一响，典礼正式拉开帷幕——commence「开始」。commence 是 begin 的正式说法，多用于典礼、工程和法律文件；commence work 是开工。\",\n\"conclude\":\"画面：侦探把所有线索拼完，指着白板说：『所以，凶手只能是他』——conclude「推断；得出结论」。conclude 是根据证据推出结论；也可指会议结束。conclusion 是结论本身。\",\n\"concurrent\":\"画面：三台服务器在同一秒内处理同一批请求，日志时间完全重合——concurrent「同时的；并发的」。concurrent 是两件事在同一时间段一起发生；concurrent events 是同时发生的事件。\",\n\"construct\":\"画面：工人们按图纸先立钢架、再封墙，一栋楼从地基长起来——construct「建造；构建」。construct 既是盖楼，也是搭起理论和论证；construct an argument 是构建论证。\",\n\"consult\":\"画面：病情复杂，主治医生请来三位专家围桌会诊——consult「咨询；商议」。consult 是拿不准时去问专业的人；consult a dictionary 是查词典，consult a doctor 是看医生请教。\",\n\"contact\":\"画面：两根电线轻轻碰到一起，电路瞬间接通，灯亮了——contact「联系；接触」。contact 本义是碰到；保持联系是 keep in contact，打电话或写信都是为了碰上对方。\",\n\"contrary\":\"画面：天气预报说晴天，他偏说要下雨，两人的说法正好相反——contrary「相反的」。on the contrary 是『恰恰相反』；contrary to popular belief 是『与普遍看法相反』。\",\n\"contrast\":\"画面：黑纸和白纸并排一放，差别一下子跳进眼睛——contrast「对比；对照」。contrast 是把两样东西并置看差异；in contrast 是『相比之下』，重音作动词在后、作名词在前。\",\n\"convert\":\"画面：旧仓库拆掉隔墙、装上书架，摇身变成社区图书馆——convert「转换；改建」。convert 是把 A 变成另一种形态的 B；convert dollars into euros 是换汇，convert a file 是转格式。\",\n\"cycle\":\"画面：水蒸发成云、云变成雨、雨汇成河、河水再蒸发，绕成一圈——cycle「循环；周期」。cycle 是回到起点的重复过程；water cycle 水循环、life cycle 生命周期都靠这张圈图记。\",\n\"deduce\":\"画面：地上只有湿脚印和半开的窗，侦探一步步推出昨晚有人来过——deduce「推论；演绎」。deduce 是从已知前提逻辑地推出结论，比 guess 有根有据；deduction 是演绎过程。\",\n\"degrade\":\"画面：原本清澈的湖泊年年被排污，水质一级一级往下掉——degrade「降级；退化」。degrade 是质量、地位或环境变差；土壤退化是 soil degradation，人格受辱也是 degrade。\",\n\"depress\":\"画面：连绵阴雨一个月，他望着窗外，肩膀一点点垮下去——depress「使沮丧」。depress 本义是『往下压』：心情被压低是沮丧，价格被压低是下跌；depression 是抑郁，也是经济大萧条。\",\n\"device\":\"画面：工程师把传感器、电池和芯片装进一个小盒子，做成能自动浇水的装置——device「装置；设备」。device 是为特定用途造的小器械；手机、平板这类电子产品统称 devices。\",\n\"diagnose\":\"画面：医生把化验单、影像和症状一项项对上，最后圈出病因——diagnose「诊断」。diagnose 是通过检查判断病或问题出在哪；diagnosis 是诊断结论，复数是 diagnoses。\",\n\"diagram\":\"画面：课本上，一台发动机的剖面图把每个零件和管线都标得清清楚楚——diagram「图表；图解」。diagram 是解释结构或流程的示意图，比 chart 更重『画出关系』；流程图、电路图都是它。\",\n\"dictate\":\"画面：经理对着录音笔一条条说要点，助理在旁边飞快地打字——dictate「口授；口述」。dictate 是说出来让人记录；也可指『支配、规定』，如 terms dictate 条件决定。\",\n\"diminish\":\"画面：湖水一年比一年少，岸边的刻度线露出一截又一截——diminish「减少；减弱」。diminish 是量或重要性逐渐变小；diminish the risk 是降低风险，别和 eliminate『彻底消除』混。\",\n\"equate\":\"画面：老师在黑板上画了个等号：左边的『努力』和右边的『天赋』被划上等号，全班摇头——equate「等同；使相等」。equate 是把两样东西看作相等；equate wealth with happiness 是把财富等同于幸福。\",\n\"equivalent\":\"画面：天平两端，一边放 1 公斤铁，另一边放 1 公斤棉花，指针纹丝不动——equivalent「等价物；等值的」。equivalent 是价值、作用或意义相同；the equivalent of 是『相当于……的东西』。\",\n\"erode\":\"画面：海浪日复一日拍打崖壁，岩石被啃出一个个凹洞——erode「侵蚀」。erode 是水、风或时间慢慢啃掉表面；信任被侵蚀、购买力被通胀侵蚀，也用 erode。\",\n\"error\":\"画面：程序跑到一半弹出红字：第 38 行少了个括号——error「错误」。error 是正式说法里的差错；an error in judgment 是判断失误。比 mistake 更书面，实验误差也是 error。\",\n\"exchange\":\"画面：集市上，农夫用一筐苹果换回陶匠的一只陶罐，各取所需——exchange「交换」。exchange 是有来有往地换；exchange students 是交换生，exchange rate 是汇率。\",\n\"exhibit\":\"画面：博物馆把一幅真迹装进玻璃柜，灯光打亮，四周站满观众——exhibit「展览；展出」。exhibit 既可作动词『展出』，也可作名词『展品』；exhibit good behavior 则是『表现出好行为』。\",\n\"framework\":\"画面：大楼还没砌墙，钢架已经把整栋楼的轮廓撑了出来——framework「框架」。framework 是支撑整体的骨架；理论框架、法律框架都是先有骨架再填内容。\",\n\"identical\":\"画面：两枚指纹放在放大镜下，纹路一条不差地重合——identical「相同的」。identical 是完全一模一样，比 similar 强得多；identical twins 是同卵双胞胎。\",\n\"implicate\":\"画面：一封邮件把从没到场的人也拖进了案件名单，警方请他回来协助调查——implicate「牵连；涉及」。implicate 是把某人卷入坏事，常带『有罪牵连』的色彩；implicate A in B 是把 A 牵连进 B。\",\n\"incompatible\":\"画面：两种零件接口形状完全对不上，怎么用力也插不进去——incompatible「不相容的」。incompatible 是放在一起就冲突、无法共存；软件不兼容、血型不合、性格不合都用它。\",\n\"infect\":\"画面：一个感冒的人在密闭车厢里打了个喷嚏，三天后半车人开始咳嗽——infect「传染；感染」。infect 是病菌传给人或伤口；infection 是感染本身，infectious 是『传染性的』。\",\n\"infer\":\"画面：读到一半，读者合上书：作者虽然没明说，但字里行间已经指向那个结局——infer「推断」。infer 是读者根据暗示推出；imply 是作者暗示。考试最爱考这对词：说话者 imply，听话者 infer。\",\n\"innovate\":\"画面：团队把沿用了二十年的纸质流程整个推翻，换成一套新系统——innovate「改革；创新」。innovate 是动词『引入新方法』；innovation 是名词。只想不做，不算 innovate。\",\n\"inquire\":\"画面：旅客走到问询台，礼貌地问下一班火车的时间——inquire「询问；打听」。inquire 是正式地询问、调查；inquire about 是打听某事，inquiry 是调查或问询。\",\n\"memory\":\"画面：老人闭上眼，童年院子里的枣树立刻浮现在眼前——memory「记忆」。memory 是记住过去的能力和内容；in memory of 是『为纪念』，计算机的 memory 则是存储器。\",\n\"mood\":\"画面：清晨阳光洒进屋，他哼着歌做早餐，整个人都轻快——mood「心情」。mood 是持续一段时间的情绪状态；in a good mood 是心情好。语法里的『语气』也是 mood。\",\n\"fear\":\"画面：黑暗的走廊尽头传来脚步声，他后背发凉，下意识往后退——fear「恐惧」。fear 是对危险的害怕；fear of heights 是恐高。fear 也可作动词『害怕、担忧』。\",\n\"anger\":\"画面：听到不公的判决，他的脸涨红，拳头攥得发白——anger「愤怒」。anger 是对不公或冒犯的强烈情绪；in anger 是在气头上。动词 anger 是『激怒』。\",\n\"joy\":\"画面：孩子拆开礼物的一瞬间跳起来尖叫，眼睛都笑弯了——joy「喜悦」。joy 是纯粹而强烈的快乐，比 happiness 更鲜明；to one's joy 是『令人高兴的是』。\",\n\"sorrow\":\"画面：老人捧着亡妻的照片坐在空屋里，眼泪无声地往下掉——sorrow「悲伤」。sorrow 比 sadness 更深、更书面，常与 loss 相连；in sorrow 是沉浸在悲痛中。\",\n\"surprise\":\"画面：灯突然亮起，藏在屋里的朋友们齐声喊出生日快乐，他整个人愣住——surprise「惊讶」。surprise 是意料之外的冲击，可喜可惊；to one's surprise 是『出乎意料』。\",\n\"empathy\":\"画面：朋友哭着说不出话，她没有讲大道理，只是坐下来陪着一起难过——empathy「同理心」。empathy 是把自己放进对方处境去感受；和 sympathy『同情』不同，empathy 更强调感同身受。\",\n\"dream\":\"画面：深夜熟睡时，他的脑海里正飞过一片会发光的海——dream「梦」。dream 是睡梦，也是醒着时的梦想；dream of becoming a doctor 两个意思都通，看语境分辨。\",\n\"conscious\":\"画面：手术后病人睁开眼睛，能听懂医生的话并点头——conscious「有意识的；清醒的」。conscious 是意识清醒、能感知；be conscious of 是『意识到』。反义词 unconscious 是昏迷或无意识。\",\n\"reasoning\":\"画面：数学家在黑板上一步接一步写推导，每一步都有上一步撑着——reasoning「推理」。reasoning 是讲逻辑地想问题；logical reasoning 是逻辑推理，推理有漏洞就是 flawed reasoning。\",\n\"deduction\":\"画面：福尔摩斯看一眼鞋底的泥，就推出对方刚从河边回来——deduction「演绎；推论」。心理学和逻辑学里 deduction 是从一般规律推出具体结论；它还有『扣除额』的意思，靠语境分。\",\n\"analogy\":\"画面：老师说『心脏就像水泵』，全班立刻懂了血液为什么会被压向全身——analogy「类比」。analogy 是用熟悉的事物打比方讲清陌生的；draw an analogy 是作类比。\",\n\"inference\":\"画面：考古学家看着地层里的灰烬层，推断这里曾发生过大火——inference「推断；推论」。inference 是根据证据得出的推论结论；make an inference 是作出推断，和 infer 是同一家。\",\n\"judgment\":\"画面：法官听完双方陈词，沉默片刻，写下最终判定——judgment「判断；判决」。judgment 既是法庭判决，也是日常的判断力；good judgment 是明智的判断。\",\n\"problem-solving\":\"画面：桥断了，工程师围着图纸测、算、试，终于想出绕行加固的办法——problem-solving「解决问题」。problem-solving 是面对难题找方案的整个过程，是托福心理与教育文章里的高频复合词。\",\n\"aggression\":\"画面：两只公羊低头抵角，一步不让，尘土飞扬——aggression「攻击性」。aggression 是主动挑起冲突的敌对行为；aggressive 是『好斗的』，也可褒义指『积极进取的』。\",\n\"association\":\"画面：一闻到桂花香，她立刻想起外婆家的院子——association「联想」。association 是由一件事勾起另一件事的心理连接；作『协会』讲时是另一个常用义，别混。\",\n\"visual\":\"画面：老师把实验过程画成动画放给全班看，眼睛先于文字懂了——visual「视觉的」。visual 与眼睛和图像有关；visual aids 是直观教具，visual memory 是视觉记忆。\",\n\"auditory\":\"画面：盲人把耳朵贴在墙上，靠回声判断房间的大小——auditory「听觉的」。auditory 与耳朵和听力有关；auditory memory 是听觉记忆，和 visual 正好是一对。\",\n\"hallucination\":\"画面：高烧中，他指着空无一人的墙角说那里站着人——hallucination「幻觉」。hallucination 是没有外界刺激却『看见、听见』不存在的东西，是心理与医学文章的关键词。\",\n\"phobia\":\"画面：一只小蜘蛛爬上桌，她尖叫着跳上椅子，心跳失控——phobia「恐惧症」。phobia 是对特定事物不合常理的强烈恐惧，如 arachnophobia 恐蛛症；普通害怕用 fear 就够了。\",\n\"hypnosis\":\"画面：治疗师放低声音数着数，患者的眼皮越来越沉，进入似睡非睡的状态——hypnosis「催眠」。hypnosis 是由暗示诱导出的特殊意识状态；hypnotize 是动词『催眠』。\",\n\"meditation\":\"画面：清晨的湖边，他盘腿闭目，呼吸放慢，杂念一点点沉下去——meditation「冥想」。meditation 是长时间专注沉思以平静心神；meditate 是动词，和 medication『药物』只差几个字母，别混。\",\n\"childhood\":\"画面：老照片里，扎羊角辫的小女孩在院子里追蝴蝶——childhood「童年期」。childhood 是从小孩到成年前的一段人生；childhood memories 是童年记忆，in one's childhood 是『在童年时』。\",\n\"infancy\":\"画面：婴儿躺在摇篮里，只会哭、吃和睡，离不开照护——infancy「婴儿期」。infancy 是出生后最早的阶段；比喻义里 in its infancy 是某事还处在萌芽期。\",\n\"heredity\":\"画面：孩子卷曲的头发和爸爸年轻时一模一样，基因把特征一代代传下去——heredity「遗传因素」。heredity 是生物特征由亲代传给子代；与之相对的是 environment 后天环境，先天后天之争就是 heredity vs. environment。\",\n\"economy\":\"画面：一座城市里，工厂生产、卡车运输、商店消费像齿轮一样互相带动——economy「经济」。economy 是一个国家或地区生产、流通、消费的总系统；也可指节约，别和 economics『经济学』混。\",\n\"market\":\"画面：清晨的集市摊位排开，买家和卖家讨价还价，价格随供需起伏——market「市场」。market 既是卖东西的地方，也是买卖某种商品的整体环境；stock market 是股市，job market 是就业市场。\",\n\"trade\":\"画面：两个港口之间，货轮载着茶叶出港，又载着羊毛回港——trade「贸易」。trade 是买卖和交换货物；international trade 是国际贸易，trade balance 是贸易差额。\",\n\"commerce\":\"画面：一整条商业街上，银行、商场、物流公司同时开门营业——commerce「商业」。commerce 比 trade 更大，指整体商业活动体系；e-commerce 是电子商务，商会是 chamber of commerce。\",\n\"manufacturing\":\"画面：流水线上，钢板被冲压、焊接、组装，最后变成汽车开下产线——manufacturing「制造业」。manufacturing 是把原料加工成产品的行业；manufacture 是动词『制造』。\",\n\"service\":\"画面：理发师修好发型，修车师傅修好车，他们卖的不是实物而是手艺——service「服务业」。service sector 是不生产实物、提供帮助的行业；customer service 是客服。\",\n\"retail\":\"画面：顾客在小店里只买一瓶水，店员按瓶标价收款——retail「零售」。retail 是直接卖给最终消费者、一次卖少量；正好和 wholesale 批发相反。\",\n\"wholesale\":\"画面：经销商一口气订下一整仓库的饮料，再分批卖给各家小超市——wholesale「批发」。wholesale 是大批量、低单价地卖给商家；wholesale price 是批发价。\",\n\"supplier\":\"画面：面包房每天清晨等同一辆卡车送来面粉和酵母——supplier「供应商」。supplier 是稳定供货的一方；supply 是供应，supplier 是供应的公司或人。\",\n\"distributor\":\"画面：厂家把产品交给 regional distributor，再由它铺到各个城市的商店——distributor「分销商」。distributor 不生产，负责把货分发到销售网络；distribution 是分销。\",\n\"vendor\":\"画面：街角的小贩支起摊子，边吆喝边把水果递给路人——vendor「小贩；卖家」。vendor 是卖东西的人或公司，街头摊贩和软件供应商都可称 vendor；vend 是较少见的动词『出售』。\",\n\"customer\":\"画面：顾客试穿后走到收银台付款，店员把衣服装袋递过去——customer「顾客」。customer 是实际购买商品或服务的人；商店最关心的就是 regular customers 老顾客。\",\n\"client\":\"画面：律师事务所里，委托人把案情资料交给律师长期跟进——client「客户」。client 多指接受专业服务的一方，如律师、咨询顾问的客户；和 customer 相比，关系更长期、更专业。\",\n\"demand\":\"画面：演唱会门票开售一分钟就售罄，页面上全是没抢到的人——demand「需求」。demand 是消费者想买且买得起的量；demand for housing 是住房需求。作动词是『要求』。\",\n\"supply\":\"画面：仓库里货架堆满，卡车正把商品源源不断送往商店——supply「供给；供应」。supply 是市场上能提供的量；supply and demand 是经济学最核心的一对：供给与需求。\",\n\"shortage\":\"画面：超市货架只剩最后一瓶水，门外还排着长队——shortage「短缺」。shortage 是需要的多、有的太少；a shortage of doctors 是医生短缺，不是东西『短』。\",\n\"scarcity\":\"画面：沙漠里所有人都盯着同一口井，水比金子还珍贵——scarcity「稀缺」。scarcity 是资源天生有限、永远不够分的状态，是经济学的出发点；shortage 更偏暂时缺货。\",\n\"abundance\":\"画面：秋天的果园里，苹果多得压弯枝头，筐子装满了还摘不完——abundance「丰富；充足」。abundance 是数量多到富余；an abundance of evidence 是大量证据。反义词是 scarcity。\",\n\"price\":\"画面：货架标签上写着 19.9 元，顾客看了一眼放进购物车——price「价格」。price 是买一样东西要付的钱；price tag 是价签。问价格永远是 What is the price of…?\",\n\"cost\":\"画面：餐馆老板算账：房租、食材、人工加起来，一盘菜的成本就出来了——cost「成本」。cost 是生产或获得某物花费的总代价；生活成本是 cost of living。\",\n\"expense\":\"画面：出差回来，他把机票、酒店和餐费发票一张张贴好报销——expense「开支；费用」。expense 是花出去的钱，尤其公司或个人日常支出；travel expenses 是差旅费。\",\n\"budget\":\"画面：项目开始前，表格里把每一笔钱都预先分好：设备多少、人工多少——budget「预算」。budget 是事先规划好的花钱上限；on a budget 是『精打细算地』，over budget 是超支。\",\n\"deficit\":\"画面：政府账本上，支出一栏比收入长出一大截，差额被红笔圈出——deficit「赤字」。deficit 是入不敷出的差额；budget deficit 是财政赤字，trade deficit 是贸易逆差。\",\n\"debt\":\"画面：他每个月工资一到账，先划走一笔还上学时欠下的贷款——debt「债务」。debt 是欠别人、必须还的钱；in debt 是负债中。字母 b 不发音，念作 /det/。\",\n\"loan\":\"画面：银行审核后把一笔钱打进账户，合同写明三年内连本带息还清——loan「贷款」。loan 是借出或借入的一笔钱；take out a loan 是申请贷款，student loan 是助学贷款。\",\n\"mortgage\":\"画面：年轻人签下三十年合约，房子归他住，银行保留抵押权——mortgage「按揭；抵押贷款」。mortgage 是买房专用贷款，房子本身作抵押；pay off a mortgage 是还清房贷。\",\n\"interest\":\"画面：存折上每年多出一小笔钱，那是银行为使用他的存款付的报酬——interest「利息」。interest 在金融里是借钱的代价；interest rate 是利率。它还有『兴趣』义，靠语境分。\",\n\"dividend\":\"画面：公司年终盈利，按股东持股比例把一笔笔钱发到账户——dividend「股息」。dividend 是公司分给股东的利润；数学里 dividend 还是『被除数』，托福经济文中先记股息。\",\n\"stock\":\"画面：交易所大屏上，一家家公司名字后面跳动着红红绿绿的数字——stock「股票」。stock 是公司所有权的一小份；buy stocks 是买股票。它还有『库存』义，和 inventory 相近。\",\n\"share\":\"画面：一块蛋糕被切成一百份，谁拿多少份，谁就占多少比例——share「股份；份额」。share 是整体中的一份；market share 是市场份额。作动词是『分享』。\",\n\"bond\":\"画面：政府发行一张凭证：借你的钱十年，到期连利息一起还——bond「债券」。bond 是借钱一方出具的正式借据，常由政府或公司发行；它还有『纽带、结合』义。\",\n\"profit\":\"画面：小店年底盘账：收入减去所有成本，剩下的那一叠才是赚到的——profit「利润」。profit = revenue − cost；make a profit 是盈利。和它相对的是 loss 亏损。\",\n\"loss\":\"画面：投资的股票一路跌到腰斩，账面上的数字缩水了一大半——loss「亏损；损失」。loss 是失去或亏掉的部分；a net loss 是净亏损。动词是 lose，别和 loose『松的』混。\",\n\"revenue\":\"画面：公司每个月把门票、广告和会员费全部加起来，得到一个大数字——revenue「收入；营收」。revenue 是企业或政府收进来的总钱数，还没扣成本；扣掉成本才是 profit。\",\n\"salary\":\"画面：白领每个月固定日期收到一笔按年薪折算的工资——salary「薪水」。salary 是按月或按年发的固定报酬，多指脑力工作；按小时或周结的体力报酬是 wage。\",\n\"wage\":\"画面：工地按周结薪，工人领到的是按小时累积的工钱——wage「工资」。wage 常按小时、天或周计算；minimum wage 是最低工资。它也可作动词『发动』，如 wage a war。\",\n\"bonus\":\"画面：年底公司宣布：今年业绩好，每人多发两个月工资——bonus「奖金」。bonus 是基本工资之外的额外奖励；额外好处也可叫 bonus，如 bonus points 加分。\",\n\"pension\":\"画面：退休后，每个月都有一笔钱准时打进老人的账户，不用再上班也有保障——pension「养老金」。pension 是工作多年换来的退休收入；pension fund 是养老基金。\",\n\"insurance\":\"画面：车主每月交一小笔钱，万一出事故，保险公司承担大额修车费——insurance「保险」。insurance 是用小额保费换大风险保障；health insurance 是医疗保险，insure 是动词。\",\n\"premium\":\"画面：保单上写着每月要交的金额，交了这笔钱，保障才生效——premium「保险费」。premium 在保险里专指投保人定期交的钱；它也可指『溢价、高端』，如 premium quality。\",\n\"claim\":\"画面：车被撞坏后，车主拍照、填表，向保险公司申请赔付——claim「索赔；索赔申请」。保险语境里 claim 是正式要求赔偿；它还可作动词『声称』，需要证据时要小心使用。\",\n\"tax\":\"画面：工资单上，税前一栏和到手一栏之间少掉的那部分被政府收走——tax「税」。tax 是公民和企业依法交给政府的钱；income tax 所得税、sales tax 销售税都是它。\",\n\"tariff\":\"画面：进口货物过海关时被加收一笔钱，本国同类产品价格优势立刻变大——tariff「关税」。tariff 是政府对进口商品征收的税，目的是保护本国产业；别和普通 tax 混为一谈。\",\n\"duty\":\"画面：海关柜台前，旅客为超出免税额的商品补交一笔钱——duty「税款；关税」。duty 在贸易里是进出口税；它更常见的意思是『职责』，如 on duty 值班，靠语境判断。\",\n\"subsidy\":\"画面：政府给每辆新能源车补一笔钱，标价立刻降了下来——subsidy「补贴」。subsidy 是政府为鼓励某行业或降低价格出的钱；agricultural subsidies 是农业补贴。\",\n\"fund\":\"画面：大家把钱放进一个共同的池子，专门用来修学校——fund「基金；资金」。fund 是一笔为特定目的攒起来的钱；作动词是『资助』，如 fund a project。\",\n\"capital\":\"画面：开店前，他凑齐了买设备、租店面和进货的第一笔钱——capital「资本」。capital 是用来再赚钱的钱和资产；它还可指首都和大写字母，经济文里先想『资本』。\",\n\"asset\":\"画面：公司盘点时把厂房、机器、专利和现金都列进一张表——asset「资产」。asset 是拥有且有价值的东西；固定资产和无形资产都是 asset。负债是 liability，正好相对。\",\n\"liability\":\"画面：账本右边列着还没还的贷款和应付的货款，压得老板睡不着——liability「负债；责任」。liability 在财务上是欠的钱，在法律上是应负的责任；和 asset 是一对。\",\n\"bankruptcy\":\"画面：公司资金链断裂，法院宣布它无力偿还所有债务，店铺关门清盘——bankruptcy「破产」。bankruptcy 是法律上宣告还不起债；go bankrupt 是破产，file for bankruptcy 是申请破产。\",\n\"auction\":\"画面：拍卖师举着小锤，台下买家轮番举牌，价高者得——auction「拍卖」。auction 是公开竞价、价高者得的卖法；auction off 是拍卖掉某物。\",\n\"bid\":\"画面：他举起牌子喊出比上一个人更高的价格，全场转头看他——bid「出价」。bid 是拍卖或投标时报出的价格；make a bid 是出价竞标。最高出价是 highest bid。\",\n\"negotiation\":\"画面：买卖双方在长桌两端坐下，你让一步、我让一步，谈了三天才签约——negotiation「谈判」。negotiation 是为达成一致而讨价还价；negotiate 是动词，negotiable 是『可协商的』。\",\n\"agreement\":\"画面：双方在合同最后一页签上名字，握手，条款正式生效——agreement「协议；协议书」。agreement 是谈妥后的一致意见或文件；reach an agreement 是达成协议。\",\n\"partnership\":\"画面：两个人出钱出力合伙开餐厅，共担风险、共享利润——partnership「合伙企业」。partnership 是合伙关系或合伙公司；partner 是合伙人，不只是『伴侣』。\",\n\"corporation\":\"画面：一栋总部大楼里，成千上万股东共同拥有这家大型公司——corporation「公司」。corporation 是依法成立、可独立签约和诉讼的大型企业，常缩略成 corp.，比普通 company 更正式。\",\n\"enterprise\":\"画面：兄妹俩从一间小作坊做起，几年后做成连锁品牌——enterprise「企业；事业」。enterprise 既指企业，也指有开创性的事业；small enterprises 是中小企业。\"\n,\n\"executive\":\"画面：会议室长桌尽头，他签字批准了整个季度的预算——executive「高管；行政人员」。executive 是公司里做决策的管理层；chief executive 是首席执行官。execute 是『执行』，坐在执行位置的人就是 executive。\",\n\"manager\":\"画面：门店开门前，她排班、查库存、处理投诉，把一天安排得井井有条——manager「经理」。manager 是负责管人管事的人；manage 是管理，management 是管理层或管理学。\",\n\"labor\":\"画面：工地和工厂里，成百上千名工人同时开工，城市靠他们的双手运转——labor「劳动；劳动力」。labor 既是体力或脑力劳动，也是劳动者整体；labor union 是工会。美式拼写 labor，英式 labour。\",\n\"union\":\"画面：工人们站到一起，推选代表和厂方谈工资——union「工会」。union 本义是『联合』；工会就是劳动者联合起来的组织。the Union 在美国历史文中还可指联邦。\",\n\"strike\":\"画面：工厂大门关上，工人们举着牌子站在门外，生产线全部停下——strike「罢工」。罢工是劳动者集体停工施压；go on strike 是举行罢工。它还可作动词『击打、袭击』。\",\n\"unemployment\":\"画面：招聘会散场后，不少人拿着简历失望地往外走——unemployment「失业」。unemployment 是没有工作的状态；unemployment rate 是失业率，是经济新闻的核心指标。\",\n\"inflation\":\"画面：同一篮子菜，去年 50 元，今年要 65 元，钱越来越不经花——inflation「通货膨胀」。inflation 是物价整体上涨、货币购买力下降；inflate 本义是『吹气球』，价格像气球一样胀大。\",\n\"deflation\":\"画面：商店一件件降价促销，顾客却都捂着钱包等更便宜——deflation「通货紧缩」。deflation 与 inflation 相反：物价整体持续下跌、货币更值钱，但经济可能停滞。\",\n\"recession\":\"画面：商场一家接一家关门，工厂减产，失业队伍变长——recession「衰退」。recession 是经济活动连续下滑的时期；比普通 slowdown 更重，比 depression 轻。\",\n\"growth\":\"画面：小树苗一年年抽出新枝，最后长成大树——growth「增长；生长」。growth 是量或规模变大；economic growth 是经济增长，growth rate 是增长率。\",\n\"stagnation\":\"画面：一潭死水几个月不流动，表面都长出了绿苔——stagnation「停滞」。stagnation 是经济或发展停住不动；stagnant 是『停滞的』，死水 stagnant water 就用这个词。\",\n\"fluctuation\":\"画面：折线图上的股价上蹿下跳，没有一条直线——fluctuation「波动」。fluctuation 是围绕某个水平上下起伏；fluctuate 是动词，价格、温度和情绪都能 fluctuate。\",\n\"stability\":\"画面：桌子四条腿稳稳着地，推它也纹丝不动——stability「稳定」。stability 是状态不轻易变化；price stability 是物价稳定。反义词是 instability。\",\n\"import\":\"画面：货轮从海外驶入港口，集装箱里装着国内不生产的芯片——import「进口」。import = im-（进入）+ port（搬运），把货搬进来；出口是 export，正好相反。\",\n\"customs\":\"画面：入境大厅里，海关人员打开行李箱逐件检查——customs「海关」。customs 是负责查验进出口货物和征税的机构；注意它常带 s。表示『习俗』的 custom 不带 s 或语境不同。\",\n\"quota\":\"画面：今年只允许进口一万辆车，名额一满，闸门立刻关闭——quota「配额」。quota 是分配或限制的固定份额；import quota 是进口配额，sales quota 是销售指标。\",\n\"monopoly\":\"画面：全城只有一家供水公司，居民没有第二家可选——monopoly「垄断」。mono- 是『一』，monopoly 是一家独占市场；have a monopoly on 是垄断某物。\",\n\"advertising\":\"画面：地铁站、电视和手机屏上，品牌轮番把同一句口号推到你眼前——advertising「广告；广告业」。advertising 是做广告这件事或行业；单个广告是 advertisement 或 ad。\",\n\"brand\":\"画面：同一款包，缝上那个熟悉的标志，价格立刻翻了几倍——brand「品牌」。brand 是消费者认得出、记得住的商业标识和形象；brand loyalty 是品牌忠诚度。\",\n\"logo\":\"画面：运动鞋侧面那个简洁的勾，一眼就能认出是哪家公司——logo「商标；标志」。logo 是图形化的品牌符号，来自 logotype；logo 不等于品牌全部，但最容易被记住。\",\n\"trademark\":\"画面：品牌名右上角标着小小的 ®，法律文件证明它已被注册——trademark「注册商标」。trademark 是受法律保护的商标；未注册的标志不能随便用 ®。\",\n\"patent\":\"画面：发明人拿到证书，二十年内别人未经许可不能仿造他的设计——patent「专利」。patent 是政府授予发明人的独占权；apply for a patent 是申请专利。\",\n\"copyright\":\"画面：书的扉页印着 © 和作者姓名，未经许可不得复制——copyright「版权」。copyright 是作者对作品复制和发行的权利；copy 是复制，right 是权利，意思就写在词里。\",\n\"franchise\":\"画面：街角新开的汉堡店从装修到菜单都和总店一模一样，它买下了经营权——franchise「特许经营」。franchise 是总部授权他人用自己品牌开店的模式；加盟商是 franchisee。\",\n\"franchisee\":\"画面：他交了加盟费，挂上连锁品牌的招牌，自己出钱经营这家店——franchisee「加盟商」。franchisee 是被授权的一方；授权方总部与它对应，别把两者弄反。\",\n\"inventory\":\"画面：仓库管理员拿着清单，一排排核对货架上还剩多少箱货——inventory「库存；存货清单」。inventory 既是存着的货，也是盘点清单；take inventory 是盘点库存。\",\n\"warehouse\":\"画面：一排排高货架望不到头，叉车在通道里来回穿梭——warehouse「仓库」。warehouse 是存放大宗货物的建筑；ware 是货物，house 是房子，词本身就是『货物的房子』。\",\n\"shipment\":\"画面：港口吊机把一批集装箱装上货轮，单据上写着启运日期——shipment「装运；一批货」。shipment 既是装运这件事，也是装好的那批货；ship 是船，但卡车运的货也叫 shipment。\",\n\"delivery\":\"画面：快递员把包裹送到门口，签收单上多了一个完成标记——delivery「交付；递送」。delivery 是把货或服务送到接收方手里；delivery fee 是配送费。\",\n\"logistics\":\"画面：调度中心的大屏上，车辆、仓库和订单被一条条路线连起来——logistics「物流」。logistics 不只是送货，而是仓储、运输、调度的整体安排；supply chain 的近亲。\",\n\"invoice\":\"画面：货送到后，供货商寄来一张列明数量和总价的单子，财务据此付款——invoice「发票；账单」。invoice 是卖方开给买方的付款清单；商业 invoice 和购物小票 receipt 不同。\",\n\"receipt\":\"画面：付款后收银机吐出一张小票，顾客把它塞进钱包留作凭证——receipt「收据」。receipt 是证明已收到钱或货的小票；receive 是『收到』，receipt 就是收到的凭据。\",\n\"discount\":\"画面：商场门口挂着『全场八折』，原价 100 元的东西 80 元拿走——discount「折扣」。discount 是从原价扣掉的一部分；at a discount 是打折出售。动词也可表示『打折、低估』。\",\n\"refund\":\"画面：顾客退回没穿过的外套，收银员把钱原路退回他的账户——refund「退款」。refund 是把已付的钱还回去；作名词重音在前，作动词重音在后。\",\n\"warranty\":\"画面：新手机的盒子里有一张卡：一年内非人为损坏免费修——warranty「保修；保证」。warranty 是厂家书面承诺的维修保证；under warranty 是在保修期内。\",\n\"guarantee\":\"画面：商家在广告里拍着胸脯承诺：三十天不满意全额退——guarantee「担保；保证」。guarantee 比 warranty 更宽，可指口头或书面的保证；也可作动词『保证做到』。\"\n,\n\"government\":\"画面：一座大楼里，议会制定规则、法院审理案件、行政部门执行政策——government「政府」。government 是治理国家的机构整体；govern 是『统治、管理』，government policies 是政府政策。\",\n\"state\":\"画面：地图上，一大片区域被边界围起来，有自己的州议会和州长——state「州」。美国的 state 是州；在政治文章里 state 也可指『国家』，如 a member state 成员国。先看语境，别只认州。\",\n\"nation\":\"画面：升旗仪式上，不同城市、不同职业的人唱着同一首国歌——nation「国家；民族」。nation 强调由共同历史、文化或政治认同组成的整体；national 是『国家的、民族的』。\",\n\"country\":\"画面：边境线以内有自己的政府、货币和军队，线外是另一个世界——country「国家」。country 是最日常的『国家』说法；它也可指乡下，如 the country 乡村地区。\",\n\"refugee\":\"画面：一家人背着仅剩的行李，穿过边境，在陌生的营地排队领食物——refugee「难民」。refugee 是因战争或迫害被迫逃离家园的人；refuge 是避难所，seek refuge 是寻求庇护。\",\n\"asylum\":\"画面：逃亡者敲开大使馆的门，请求在一个安全的地方被收留——asylum「庇护」。asylum 是国家给予外国逃亡者的保护；seek asylum 是申请庇护。它旧义还有『精神病院』，现代文本先想庇护。\",\n\"constitution\":\"画面：国家博物馆的玻璃柜里，放着建国时写下的那本根本大法——constitution「宪法」。constitution 规定政府如何组织、权力如何分配；constitutional 是『合宪的』，违反宪法是 unconstitutional。\",\n\"amendment\":\"画面：宪法原文旁边贴上一页正式增补条款，编号写着『第一修正案』——amendment「修正案」。amendment 是对法律或文件正式修改补充的部分；amend 是『修正』，来自 amend 一词的『改进』义。\",\n\"statute\":\"画面：法典里一条条编号的成文规定，法官判案时直接引用条号——statute「法令；成文法」。statute 是立法机关正式通过、写下来的法律；statutory 是『法定的』。\",\n\"ordinance\":\"画面：市议会通过规定：夜间施工不得超过十点，贴在社区公告栏上——ordinance「条例」。ordinance 多是地方政府制定的法规，范围比 national law 小；城市噪音、 zoning 条例都是它。\",\n\"decree\":\"画面：君主或政府首脑签下一纸命令，不经议会辩论立即执行——decree「法令；政令」。decree 是由最高权力直接发布的命令；by decree 是『以法令形式』。\",\n\"bill\":\"画面：一份提案在议会里被反复辩论、修改，还没通过前只能叫草案——bill「法案」。bill 在议会语境里是待审议的法案草案，通过后才成为 law；日常账单也是 bill，靠语境分。\",\n\"act\":\"画面：法案经过表决和签署，正式以『某某法』的名字生效——act「法案；法令」。议会通过的 act 是成文法，如 Clean Air Act；act 的日常义是『行为、行动』。\",\n\"law\":\"画面：红绿灯前，所有车都停下来，因为规则对每个人都一样——law「法律」。law 是约束全社会的规则体系；break the law 是违法，enforce the law 是执法。\",\n\"illegal\":\"画面：深夜有人翻过围栏倾倒废料，探照灯一亮，警车赶到——illegal「非法的」。il- 是『不』，legal 是合法；illegal 是法律明文禁止的，比 inappropriate『不合适』严重得多。\",\n\"court\":\"画面：法官坐在高台上，双方的律师轮流陈述，书记员记录每一句话——court「法庭；法院」。court 是审理案件的地方和机构；最高法院是 Supreme Court。球场也是 court，法律文里先想法庭。\",\n\"judge\":\"画面：审判席上，他敲下法槌，全场安静，等待最终裁定——judge「法官」。judge 是主持审判并作裁决的人；作动词是『判断』。托福里 judge 的动作就是 weigh evidence 后下结论。\",\n\"jury\":\"画面：十二个普通公民坐在陪审席上，听完证据后进小屋讨论是否有罪——jury「陪审团」。jury 是由普通人组成、负责认定事实的团体；法官负责法律，jury 负责判断事实是否成立。\",\n\"lawyer\":\"画面：开庭前，她把证据按时间顺序排好，准备替当事人辩护——lawyer「律师」。lawyer 是受过法律训练、替人打官司或提供法律意见的人；attorney 是美式近义词。\",\n\"trial\":\"画面：法庭上，证人宣誓、证据呈堂、双方交叉质询，一切都为查清事实——trial「审判」。trial 是一场完整的司法审理；on trial 是受审。它也可指试验，如 clinical trial 临床试验。\",\n\"verdict\":\"画面：陪审团回到法庭，代表起身宣读：『有罪』——verdict「裁决」。verdict 是陪审团或法庭给出的最终判定；guilty verdict 是有罪裁决，reach a verdict 是作出裁决。\",\n\"sentence\":\"画面：法官宣读：判处五年监禁，法庭里一片寂静——sentence「判决；判刑」。法律语境的 sentence 是对罪犯的量刑；语言学里它才是『句子』。托福法律段落先想判刑。\",\n\"penalty\":\"画面：球员犯规，裁判指向点球点，对方获得一次罚球机会——penalty「处罚；罚金」。penalty 是违反规则要付出的代价；法律里可指罚款或刑罚。death penalty 是死刑。\",\n\"fine\":\"画面：司机超速被拦下，警察开出一张罚单：两百元——fine「罚款」。fine 在法律里是罚金这个名词；日常口语 I am fine 是『我很好』，语境完全不同别混。\",\n\"imprisonment\":\"画面：铁门在身后重重关上，他的日子被关进一间小小的牢房——imprisonment「监禁」。imprisonment 是把人关进监狱的刑罚；life imprisonment 是终身监禁。prison 是监狱。\",\n\"execution\":\"画面：判决书上的日期到了，监狱按法律程序执行最后的刑罚——execution「死刑执行」。execution 在法律里特指执行死刑；商业里它还可指合同或计划的『执行』，语境决定意思。\",\n\"appeal\":\"画面：被告不服判决，律师把上诉书递交到更高一级法院——appeal「上诉」。appeal 是请求上级法院复审；也可指『呼吁、吸引力』，如 appeal to voters 争取选民。\",\n\"supreme\":\"画面：九位大法官坐在国家最高审判席上，他们的解释就是最终解释——supreme「最高的；至高无上的」。supreme 是最高等级；Supreme Court 是最高法院。CN 若写成法院，是因为它常和 Court 连用。\",\n\"justice\":\"画面：女神蒙着眼睛，一手持剑一手持天平，不看身份只看事实——justice「正义；司法」。justice 是公平得到伸张的状态；the justice system 是司法系统，a justice 也可指大法官。\",\n\"crime\":\"画面：深夜的巷子里，玻璃被砸碎，警灯划破黑暗——crime「罪行」。crime 是违反刑法、要受惩罚的行为；commit a crime 是犯罪，crime rate 是犯罪率。\",\n\"criminal\":\"画面：通缉令贴在警局墙上，照片下写着他的罪名——criminal「罪犯」。criminal 作名词是犯了罪的人，作形容词是『刑事的』，如 criminal law 刑法。\",\n\"theft\":\"画面：店员转身时，一只手悄悄把手机滑进自己的口袋——theft「盗窃」。theft 是偷窃行为这个总称；thief 是小偷。偷车、偷钱都可归入 theft。\",\n\"robbery\":\"画面：蒙面人冲进银行，用威胁逼柜员交出钱——robbery「抢劫」。robbery 是用暴力或威胁当面抢；没有暴力的偷是 theft，入室偷是 burglary，三者要分清。\",\n\"burglary\":\"画面：住户度假回来，发现窗户被撬、抽屉被翻得乱七八糟——burglary「入室盗窃」。burglary 的关键是非法闯入建筑行窃；闯入本身就是它的核心画面。\",\n\"murder\":\"画面：法医和警察围在现场拉起警戒线，这不是意外，而是蓄意夺命——murder「谋杀」。murder 是非法、故意地杀人；过失或正当防卫不叫 murder，法律定义非常严格。\",\n\"assault\":\"画面：酒吧里一人挥拳冲向另一人，保安立刻把他们拉开——assault「袭击；人身攻击」。assault 是对他人身体的攻击或攻击威胁；assault and battery 是殴打罪的常见组合。\",\n\"fraud\":\"画面：骗子伪造文件，把投资人的钱转进自己的账户——fraud「欺诈」。fraud 是用谎言骗取钱财或权利；credit card fraud 是信用卡欺诈，fraudulent 是『欺诈的』。\",\n\"bribery\":\"画面：信封里塞着厚厚的现金，被悄悄推过办公桌下面——bribery「贿赂」。bribery 是用钱或好处收买有权者；bribe 是贿赂物或动词『行贿』。\",\n\"corruption\":\"画面：本该修桥的公款被层层截留，桥没修成，有人却买了豪宅——corruption「腐败」。corruption 是掌权者滥用权力谋私；corrupt officials 是腐败官员。\",\n\"smuggling\":\"画面：深夜，船员把没有报关的货物藏在夹层里偷偷运入港口——smuggling「走私」。smuggling 是非法偷运违禁品或逃税货物进出境；smuggler 是走私者。\",\n\"treason\":\"画面：将军把军防地图交给了敌国，法庭以最重的罪名审判他——treason「叛国」。treason 是背叛自己国家、帮助敌人的重罪，是政治犯罪里最严重的一种。\",\n\"terrorism\":\"画面：人群密集的车站突然发生爆炸，恐慌瞬间蔓延全城——terrorism「恐怖主义」。terrorism 是用暴力制造恐惧以达到政治目的；terrorist 是恐怖分子。\",\n\"police\":\"画面：警车停在路口，警员下车维持秩序、处理事故——police「警察；警方」。police 是执法群体，通常作集合名词用复数动词；单个警察是 police officer。\",\n\"officer\":\"画面：警官胸前别着徽章，站在现场指挥疏散——officer「警官；官员」。officer 是有职位和职责的公职人员；police officer 是警官，军官也是 officer。\",\n\"detective\":\"画面：他拿着放大镜蹲在现场，不放过任何一根头发丝——detective「侦探」。detective 是专门查案的警探或私家侦探；detect 是『察觉』， detective 就是靠察觉破案的人。\",\n\"patrol\":\"画面：警车沿着社区街道缓慢巡行，车灯扫过每一栋楼——patrol「巡逻」。patrol 是为防止犯罪而定时巡查；on patrol 是在巡逻中，也可作名词指巡逻队。\",\n\"arrest\":\"画面：警察出示证件，给嫌疑人戴上手铐，宣布他被捕了——arrest「逮捕」。arrest 是依法把人抓起来带走；under arrest 是被捕状态。心脏骤停是 cardiac arrest，同词不同场。\",\n\"custody\":\"画面：嫌疑人被关在拘留室里，等待法庭决定下一步——custody「拘留；羁押」。custody 是被警方依法扣留的状态；抚养权之争里的 custody 是监护权，靠语境区分。\",\n\"prison\":\"画面：高墙、铁丝网和瞭望塔围着一片牢房，犯人在院里放风——prison「监狱」。prison 是关押已判刑罪犯的地方；in prison 是坐牢。比 jail 关押时间通常更长。\",\n\"jail\":\"画面：小镇警局后面有几间临时关押室，醉汉被关了一夜——jail「拘留所；监狱」。jail 多指短期关押或待审羁押的地方；和 prison 相比，jail 更小、刑期更短。\",\n\"probation\":\"画面：法官没有把他送进监狱，而是要求他定期向监管官报到——probation「缓刑；缓刑期」。probation 是判罪后暂不入狱、在监督下改过；违反条件就可能被收监。\",\n\"parole\":\"画面：服刑多年后，他因表现良好被提前释放，但每月必须向假释官报到——parole「假释」。parole 是刑期未满先放出、继续受监督；和 probation 不同，parole 是已经坐过牢之后的释放。\"\n,\n\"democracy\":\"画面：选举日，普通市民排队把选票投进箱子，决定谁来执政——democracy「民主」。democracy = demo-（人民）+ -cracy（统治），人民作主；democratic 是『民主的』。\",\n\"republic\":\"画面：国家元首由选举产生而不是世袭，王冠被放进博物馆——republic「共和国」。republic 是没有君主、主权属于人民的政体；the Republic 在美国文中常指美利坚合众国。\",\n\"monarchy\":\"画面：国王头戴王冠坐在王座上，王位传给他的长子——monarchy「君主制」。monarchy 是一人世袭统治的政体；君主本人是 monarch。英国是 constitutional monarchy 君主立宪制。\",\n\"dictatorship\":\"画面：一个人控制了军队、媒体和法院，没人敢公开反对——dictatorship「独裁」。dictatorship 是一人或一小群人无限掌权、没有制衡的统治；dictator 是独裁者。\",\n\"tyranny\":\"画面：统治者随意抓人、没收财产，百姓敢怒不敢言——tyranny「暴政」。tyranny 是残酷压迫的统治，重点在『暴虐』；tyrant 是暴君。\",\n\"election\":\"画面：计票站的大屏上，两位候选人的票数一点点拉开——election「选举」。election 是用投票选出公职人员的过程；elect 是动词『选举』，general election 是大选。\",\n\"vote\":\"画面：他郑重地把选票投进票箱，这一票将计入总数——vote「投票；选票」。vote 既是投票这个动作，也是那一张票；vote for 是投给，vote against 是反对。\",\n\"ballot\":\"画面：选民在隔间里勾选名字，再把这张纸投入箱中——ballot「选票」。ballot 是投票用的那张纸或电子选票；secret ballot 是无记名投票，ballot box 是票箱。\",\n\"party\":\"画面：大会会场里，同一颜色的旗帜和标语连成一片，成员为共同主张站台——party「政党」。政治语境的 party 是政党；日常 party 是聚会。the ruling party 是执政党。\",\n\"conservative\":\"画面：面对激进改革，他主张一步一步慢慢来，先守住传统制度——conservative「保守的」。政治上 conservative 倾向维护传统、反对剧变；也可形容穿着或估计『保守、不冒进』。\",\n\"radical\":\"画面：演讲者提出要把整个制度推倒重建，台下有人起立鼓掌有人摇头——radical「激进的」。radical 是要求根本性变革的；它来自 radix『根』，动到根部就是彻底。别只记成贬义。\",\n\"moderate\":\"画面：两派争吵不休时，他提出各让一步的中间方案——moderate「温和的；中间派的」。moderate 在政治里是不偏极端的一派或立场；作形容词还可指『适度的』，如 moderate exercise。\",\n\"senate\":\"画面：议事厅里，一百名议员按州就座，辩论国家大事——senate「参议院」。senate 是两院制议会的上院；美国 Senate 每州两名议员，senator 是参议员。\",\n\"congress\":\"画面：国会大厦的穹顶下，参众两院同时开会表决国家预算——congress「国会」。美国的 Congress 是立法机关总称，包括 Senate 和 House；congressional 是『国会的』。\",\n\"parliament\":\"画面：下议院里，首相和反对党领袖隔着长桌激烈交锋——parliament「议会」。parliament 是英国式议会的名称；member of parliament 是议员，缩写 MP。\",\n\"cabinet\":\"画面：首相和各部部长围坐在内阁会议室，逐项决定国家政策——cabinet「内阁」。cabinet 是政府最高行政团队；它日常还指橱柜，政治文里先想内阁。\",\n\"president\":\"画面：就职典礼上，他把手放在宪法上宣誓，成为国家元首——president「总统」。president 是共和国最高领导人；也可指大学校长或公司总裁，核心都是『坐在最前面主持的人』。\",\n\"governor\":\"画面：州政府大楼里，他签下本州的新预算案——governor「州长」。governor 是一州的最高行政长官；govern 是『治理』，管一州的人就是 governor。\",\n\"mayor\":\"画面：市政厅门前，他接过城市钥匙，成为这座城市的行政首长——mayor「市长」。mayor 管的是一座城市；mayor's office 是市长办公室，别和 major『主要的』混拼写。\",\n\"bureaucracy\":\"画面：一份申请盖了七个章，在五个窗口之间来回跑了三天——bureaucracy「官僚机构；官僚作风」。bureaucracy 是庞大的行政层级体系；常带贬义指手续繁琐、效率低。\",\n\"diplomacy\":\"画面：两国代表在谈判桌上措辞谨慎，一个词都不肯说错——diplomacy「外交」。diplomacy 是国家之间和平打交道的艺术；diplomat 是外交官，diplomatic 是『外交的、圆通的』。\",\n\"ambassador\":\"画面：他递交国书后，正式成为本国驻外国的最高代表——ambassador「大使」。ambassador 是派驻他国的大使；大使官邸和办公地在 embassy 大使馆。\",\n\"embassy\":\"画面：一栋挂着本国国旗的建筑，里面办理签证、保护本国公民——embassy「大使馆」。embassy 是大使和外交人员工作的机构建筑；领事馆是 consulate，级别和职能略有不同。\",\n\"consulate\":\"画面：旅居国外的公民护照丢了，走进一栋挂国旗的小楼求助——consulate「领事馆」。consulate 负责签证和侨民事务，设在大使馆之外的其他城市；consul 是领事。\",\n\"treaty\":\"画面：两国首脑在长桌两端签字，一份和平条约正式生效——treaty「条约」。treaty 是国家之间正式签署的书面协议，如 peace treaty 和平条约；违约就是违反国际法。\",\n\"alliance\":\"画面：几个国家签署共同防御协定，旗帜并排插在会场——alliance「同盟」。alliance 是为共同目标结成的正式联盟；ally 是盟友，form an alliance 是结盟。\",\n\"neutrality\":\"画面：两国开战，邻国宣布不站在任何一边，边境保持平静——neutrality「中立」。neutrality 是冲突中不选边的立场；neutral 是『中立的』，瑞士以永久中立闻名。\",\n\"sovereignty\":\"画面：一国国旗在联合国总部前升起，代表它独立决定自己的事务——sovereignty「主权」。sovereignty 是国家不受外来干涉的最高权力；sovereign 是『有主权的』。\",\n\"territory\":\"画面：地图上被同一种颜色涂满、由边界围住的整片土地——territory「领土」。territory 是一个国家或地区管辖的土地；领海和领空也包含在主权 territory 概念里。\",\n\"independence\":\"画面：广场上人群挥舞新国旗，宣布不再受殖民统治——independence「独立」。independence 是摆脱控制、自主自立；美国 Independence Day 是独立日。depend 是依赖，反着记最牢。\",\n\"rebellion\":\"画面：边境省份的民众拿起武器，公开反抗中央政府——rebellion「叛乱」。rebellion 是有组织的武装反抗；比 protest 大得多，rebel 是反叛者。\",\n\"protest\":\"画面：人群举着标语牌走上街头，向政府表达不满——protest「抗议」。protest 是公开表达反对；可和平进行。作动词重音在后，作名词重音在前。\",\n\"demonstration\":\"画面：成千上万人沿着大街游行，口号声传遍几个街区——demonstration「示威；游行」。demonstration 是公开集会表达诉求；它还可指演示，如 a cooking demonstration 做菜示范。\",\n\"petition\":\"画面：一张请愿书上签满了名字，被送到市政厅要求改变政策——petition「请愿」。petition 是许多人联名提出的正式请求；sign a petition 是签名请愿。\",\n\"referendum\":\"画面：全国选民走进投票站，不是选人，而是直接决定是否脱欧——referendum「公投；公民投票」。referendum 是把重大问题直接交给全体公民投票决定。\",\n\"census\":\"画面：调查员挨家挨户登记人口：几口人、年龄、职业，全部入表——census「人口普查」。census 是政府定期清点人口的官方统计；美国每十年做一次 census。\",\n\"reform\":\"画面：旧制度弊病丛生，新法案把选举规则一条条改掉——reform「改革」。reform 是为变好而修改制度；re-（重新）+ form（形状），把形状重新做好。reform 也可作名词。\",\n\"welfare\":\"画面：政府给失业家庭发补助、给老人提供医疗，保障基本生活——welfare「福利」。welfare 是政府提供的社会保障体系；也可指幸福安康，如 child welfare 儿童福利。\"\n,\n\"civilization\":\"画面：河流两岸出现城市、文字、历法和法律，人们不再四处流浪——civilization「文明」。civilization 是人类社会发展到有城市、制度和文化的阶段；civilized 是『文明的』。\",\n\"empire\":\"画面：地图上，一种颜色从首都不断向外扩张，吞并周边许多王国——empire「帝国」。empire 是皇帝统治的辽阔多民族国家；the Roman Empire 是罗马帝国，emperor 是皇帝。\",\n\"dynasty\":\"画面：王位在一家人的父子之间传了十几代，年号一个接一个——dynasty「王朝」。dynasty 是同一家族连续统治的时期；唐、宋都是中国历史上的 dynasty。\",\n\"kingdom\":\"画面：国王的旗帜飘在城堡上，这片土地上所有城镇都向他效忠——kingdom「王国」。kingdom 是国王统治的国家；生物分类里的『界』也是 kingdom，如 animal kingdom 动物界。\",\n\"tribe\":\"画面：草原上，几十个帐篷围着篝火，首领是大家共同的长辈——tribe「部落」。tribe 是以血缘和共同习俗结成的原始社会群体；tribal 是『部落的』。\",\n\"clan\":\"画面：一个村子里大半人都同姓，逢年过节一起祭拜同一位祖先——clan「氏族」。clan 是有共同祖先的大家族群体，比 tribe 更小、更重血缘。\",\n\"colonist\":\"画面：帆船靠岸，一群人带着种子和工具，在陌生土地上建起第一座木屋——colonist「殖民者」。colonist 是迁到殖民地定居的人；colony 是殖民地，colonize 是殖民。\",\n\"slavery\":\"画面：市场上，人被当作商品买卖，一生劳动却没有自由——slavery「奴隶制」。slavery 是把人当财产的制度；slave 是奴隶，abolish slavery 是废除奴隶制。\",\n\"feudal\":\"画面：领主把土地分给骑士，农民在土地上劳作并交租效忠——feudal「封建的」。feudal 指中世纪欧洲以土地换效忠的等级制度；feudal society 是封建社会。\",\n\"medieval\":\"画面：骑士、城堡和教堂主宰的欧洲，时间在罗马帝国之后、文艺复兴之前——medieval「中世纪的」。medieval 指约 5 到 15 世纪的中世纪；medieval castle 是中世纪城堡。\",\n\"ancient\":\"画面：黄沙之下埋着几千年前的城墙，石板上的文字已经斑驳——ancient「古代的；古老的」。ancient 是年代非常久远的；ancient Egypt 是古埃及。和 old 相比，ancient 更强调历史久远。\",\n\"pre-historic\":\"画面：山洞壁画上画着野牛，那时人类还没有发明文字——pre-historic「史前的」。pre- 是『在……之前』，pre-historic 是有文字记录之前的时代；常见拼写是 prehistoric。\",\n\"artifact\":\"画面：考古队员从土层里捧出一只陶罐，编号、拍照、装箱——artifact「文物；人工制品」。artifact 是古人亲手做出来的物件，是研究历史的一手材料；拼写也可作 artefact。\",\n\"relic\":\"画面：神殿深处保存着一件圣物，信徒排队瞻仰——relic「遗迹；遗物」。relic 是留存下来的古代物件或圣物；也可比喻过时的残留，如 a relic of the past。\",\n\"ruin\":\"画面：曾经宏伟的神庙只剩下断柱和倒塌的石墙，野草从缝里长出来——ruin「废墟」。ruin 作名词是建筑的残骸，常作复数 ruins；作动词是『毁坏』，如 ruin one's health。\",\n\"excavation\":\"画面：考古现场被分成一个个方格，队员蹲着用小刷子扫土——excavation「挖掘；发掘」。excavation 是科学地挖开遗址的过程，讲究记录土层；excavate 是动词。\",\n\"excavate\":\"画面：刷子轻轻扫开泥土，一块完整的甲骨渐渐露出全貌——excavate「挖掘文物」。excavate 是小心地挖出埋藏的东西；挖得越慢，信息保留得越多，这正是考古和盗掘的区别。\",\n\"tomb\":\"画面：石门之后是幽深的墓室，棺椁周围摆满陪葬品——tomb「坟墓」。tomb 是为死者建的墓室，多指较宏大的陵墓；the Tomb of the Unknown Soldier 是无名战士墓。\",\n\"pyramid\":\"画面：尼罗河岸，四面三角形的巨石建筑在沙漠里指向天空——pyramid「金字塔」。pyramid 是古埃及法老的陵墓；几何里 pyramid 是锥体，先记沙漠里的画面，形状自然记住。\",\n\"temple\":\"画面：高台上立着石柱，祭司在殿内主持仪式，信众在台下祈祷——temple「寺庙；神殿」。temple 是供奉神灵、举行宗教仪式的建筑；太阳穴也叫 temple，靠语境分。\",\n\"shrine\":\"画面：路边小小的神龛里供着一尊像，前面放着鲜花和香——shrine「神龛；圣祠」。shrine 是供奉圣物或神灵的小型圣地，比 temple 小得多；也可指纪念地。\",\n\"mosque\":\"画面：宣礼塔高耸，穹顶在阳光下发亮，信徒脱鞋进入祈祷——mosque「清真寺」。mosque 是伊斯兰教的礼拜场所；拼写里的 que 别按英语读音猜，整体记。\",\n\"cathedral\":\"画面：哥特式尖塔直插云霄，彩色玻璃窗把阳光染成斑斓——cathedral「大教堂」。cathedral 是主教所在的大型教堂，是一座城市宗教生活的中心。\",\n\"monastery\":\"画面：深山里，修士们住在简朴的石屋中，按钟声起居、诵经、劳作——monastery「修道院」。monastery 是修道士集体生活的场所；monk 是修士，修女住的叫 convent。\",\n\"castle\":\"画面：石墙、护城河和高塔围着领主的居所，易守难攻——castle「城堡」。castle 是中世纪兼居住与防御的建筑；sand castle 是沙堡，同一个词。\",\n\"fortress\":\"画面：山顶上厚墙环绕，炮口对着唯一的山路——fortress「堡垒」。fortress 只强调军事防御，比 castle 更纯粹是打仗用的；fort 是堡垒的简短说法。\",\n\"palace\":\"画面：金顶红墙的大殿连绵成片，皇帝在其中处理朝政——palace「宫殿」。palace 是君主居住和办公的宏伟建筑群；住的是君主，防的是敌人——那是 fortress。\",\n\"throne\":\"画面：大殿正中央，一把高背椅子空着，所有人都向它行礼——throne「王位」。throne 本是国王的座椅，引申为王权本身；ascend the throne 是登基。\",\n\"crown\":\"画面：加冕礼上，金冠被缓缓戴到新王头上——crown「王冠；王权」。crown 是圆环形的王权象征；它也可作动词『加冕』，牙冠和树冠也叫 crown。\",\n\"scepter\":\"画面：国王右手握着一根镶宝石的短杖，群臣肃立——scepter「权杖」。scepter 是君主手里代表权力的礼杖；它不是武器，象征的是发号施令的资格。美式拼写 scepter。\",\n\"knight\":\"画面：骑士披甲骑马，在国王面前单膝跪地受封——knight「骑士」。knight 是中世纪受封的武士；开头 k 不发音。国际象棋里的马也叫 knight。\",\n\"warrior\":\"画面：战士握紧武器站在阵前，眼神里没有退缩——warrior「武士；勇士」。warrior 是骁勇的战斗者，比 soldier 更强调勇武精神；古代部落和史诗里最常用。\",\n\"spear\":\"画面：士兵把长杆尖头的武器向前掷出，划破空气——spear「长矛」。spear 是长柄尖头武器，可刺可投；spearhead 还可比喻『先锋』。\",\n\"spearman\":\"画面：一排持矛士兵列成方阵，矛尖如林，等待冲锋号令——spearman「持矛者」。spearman 是以长矛为武器的士兵，是 spear + man 的合成词。\",\n\"shield\":\"画面：箭雨落下，士兵举起宽大的盾牌护住身体——shield「盾牌」。shield 是挡攻击的防护牌；引申为任何保护，如 heat shield 隔热罩。动词是『保护、遮挡』。\",\n\"sword\":\"画面：剑身出鞘，寒光一闪——sword「剑」。sword 的 w 不发音，念 /sɔːrd/；它是近身格斗的利刃。a double-edged sword 是双刃剑，常用作比喻。\",\n\"armor\":\"画面：骑士全身覆着金属铠甲，只露出眼睛——armor「盔甲」。armor 是保护身体的甲胄，也可指坦克的装甲；美式拼写 armor，英式 armour。\",\n\"battle\":\"画面：两军在平原上列阵厮杀，一天的胜负决定一座城的命运——battle「战役；战斗」。battle 是一次具体的战斗；war 是整场战争。battlefield 是战场。\",\n\"warfare\":\"画面：从步兵冲锋到炮火覆盖，整个国家机器都为战争运转——warfare「战争；作战」。warfare 是进行战争的方式与行为总称，如 guerrilla warfare 游击战。\",\n\"conquest\":\"画面：军队攻下城池后在城头插上自己的旗帜——conquest「征服」。conquest 是用武力夺取并统治；conquer 是动词。诺曼征服就是 the Norman Conquest。\",\n\"invasion\":\"画面：敌军越过边境线涌入，边境城镇一夜之间陷入战火——invasion「入侵」。invasion 是大批外来力量强行进入；物种入侵 invasive species 也是同一个词根画面。\",\n\"siege\":\"画面：大军把城围得水泄不通，断水断粮，等城里撑不住——siege「围攻」。siege 是长期围困迫降；lay siege to a city 是围攻一座城。\",\n\"retreat\":\"画面：号角响起，军队有序地向后撤，离开战场——retreat「撤退」。retreat 是主动或被迫后撤；也可指退隐和静修地。advance 是它的反义词。\",\n\"silk\":\"画面：蚕吃桑叶吐出细丝，织成光滑发亮的布匹，沿丝绸之路运往西方——silk「丝绸」。silk 来自蚕丝；silk road 是丝绸之路。摸起来光滑的东西常被形容为 silky。\",\n\"spice\":\"画面：港口的仓库里堆满胡椒、肉桂和丁香，空气里全是浓烈香气——spice「香料」。spice 是给食物添味的植物粉末或种子；中世纪香料贵如黄金，是贸易史的关键词。\",\n\"porcelain\":\"画面：一只薄得透光的青花瓷碗从窑里取出，敲一下声音清脆——porcelain「瓷器」。porcelain 是高温烧制的精细瓷器；China 大写是国名，小写 china 就是瓷器。\",\n\"wheel\":\"画面：一根圆木被装上轴，拉车的人立刻省了一半力气——wheel「轮子」。CN 写『轮子的发明』，是因为轮子是托福历史文章里的大发明之一；车轮、方向盘都是 wheel。\",\n\"plow\":\"画面：农夫扶着犁，牛在前面拉，土地被翻出一道道整齐的沟——plow「犁」。plow 既是犁地的农具，也是动词『犁地』；美式拼写 plow，英式 plough。\",\n\"irrigation\":\"画面：干旱的田地旁，沟渠把河水引进来，一块块农田喝饱了水——irrigation「灌溉」。irrigation 是人工引水浇地；irrigate crops 是灌溉作物，是农业文明兴起的关键技术。\",\n\"aqueduct\":\"画面：高高的石拱桥跨过山谷，山泉水沿着桥上的水槽流进罗马城——aqueduct「水渠；高架渠」。aqua 是水，duct 是管道；古罗马 aqueduct 把远处的水送进城市。\",\n\"dam\":\"画面：混凝土巨墙横在峡谷之间，上游形成一片大湖——dam「水坝」。dam 是拦水的坝；它也可作动词『筑坝拦水』。三峡大坝就是 a dam on the Yangtze。\",\n\"canal\":\"画面：工人挖出一条笔直的水道，船闸一开，货船缓缓通过——canal「运河」。canal 是人工开挖的航运水道，如 Suez Canal 苏伊士运河；天然水道是 river 或 channel。\",\n\"compass\":\"画面：航海者打开小盒子，指针无论怎么转都稳稳指向北方——compass「指南针」。compass 是中国古代四大发明之一；画圆的圆规也叫 compass，靠语境分。\",\n\"gunpowder\":\"画面：炼丹炉突然炸开，火光和烟雾冲天——gunpowder「火药」。gunpowder 是枪炮和烟花的黑色粉末；它的发明改变了战争形态，是历史文章的高频词。\",\n\"printing\":\"画面：活字排满版面，刷上墨、盖上纸，一本书的内容瞬间复制出上百份——printing「印刷术」。printing 让知识走出抄写时代；printing press 是印刷机。\",\n\"paper\":\"画面：工匠把植物纤维捣成浆、摊平、晒干，得到一张能写字的薄片——paper「纸」。CN 写『纸的发明』，因为纸是四大发明之一；日常 paper 还可指论文和试卷。\",\n\"scroll\":\"画面：使者展开一卷长长的卷轴，从右到左读完诏书再卷回去——scroll「卷轴」。scroll 是纸发明后、装订成书之前的书籍形态；手机上下滑也叫 scroll。\",\n\"manuscript\":\"画面：修道院里，抄写员蘸着墨水，在羊皮纸上一字一句抄经——manuscript「手稿」。manu- 是『手』，script 是『写』；manuscript 就是手写的那份原稿，也可指待出版的书稿。\",\n\"hieroglyph\":\"画面：神庙石墙上刻满鸟、眼和蛇形的符号，学者对着罗塞塔石碑逐字破译——hieroglyph「象形文字」。hieroglyph 是古埃及用图画表意的文字系统；每个符号都是一幅小画。\",\n\"inscription\":\"画面：石碑正面刻着一行行字，两千年后人们仍能读到当年的功绩——inscription「铭文」。inscription 是刻在石、金属或建筑上的文字；in- + scrib（写），写进石头里就是铭文。\",\n\"tablet\":\"画面：苏美尔人用芦苇笔在湿泥板上压出楔形符号，晒干保存——tablet「泥板」。古代 tablet 是写字的泥板或石板；现代 tablet 是平板电脑。历史文章里先想泥板。\",\n\"weaving\":\"画面：织布机上，经线和纬线一上一下交错，布面一点点长出来——weaving「织造」。weaving 是把线织成布的工艺；weave 是动词，织布和编辫子都是它。\",\n\"spinning\":\"画面：老妇人踩着纺车，棉花被抽成一根细细的线缠上锭子——spinning「纺纱」。spinning 是把纤维纺成线的工序；spin 本义是旋转，纺车转起来才有线。\",\n\"metallurgy\":\"画面：工匠把矿石丢进高温炉，金属液流出来铸成工具——metallurgy「冶金学」。metallurgy 是研究金属提取和加工的学问；青铜时代就是冶金改变文明的时代。\",\n\"mining\":\"画面：矿工戴着头灯深入地下，把矿石一筐筐运出矿井——mining「采矿」。mining 是从地下挖出矿产的行业；mine 是矿井，miner 是矿工。数据挖掘也是 data mining。\",\n\"domestication\":\"画面：猎人把抓到的野狼幼崽养在身边，几代之后，它成了守家的狗——domestication「驯化」。domestication 是把野生动植物变成家养的过程；domestic 本义是『家的』。\",\n\"harvest\":\"画面：金黄的麦田里，农人们挥镰收割，谷仓越堆越满——harvest「收获」。harvest 既是收割的季节和动作，也是收成的量；a good harvest 是丰收。\",\n\"granary\":\"画面：收获的粮食被运进高大的仓房，防潮防鼠，为冬天储备——granary「粮仓」。granary 是专门存粮的仓库；一个地区被称为 the granary of a country，就是它的粮仓。\",\n\"calendar\":\"画面：祭司观察太阳和月亮的运行，把播种和收获的日子刻成表——calendar「历法」。calendar 是把年月日系统编排的方法；日历表本身也叫 calendar。古代历法多从农业来。\",\n\"mathematics\":\"画面：从数星星到算金字塔的高度，人类把数量和形状变成了学问——mathematics「数学」。mathematics 是研究数、量和结构的学科总称，常缩写为 math；它是单数概念，动词用单数。\",\n\"gladiator\":\"画面：竞技场中央，持盾和短剑的角斗士在万人注视下搏斗——gladiator「角斗士」。gladiator 是古罗马被迫或自愿格斗表演的人；这个词来自 gladius『短剑』。\",\n\"olympic\":\"画面：五环旗升起，来自各国的运动员走进体育场——olympic「奥林匹克的」。Olympic Games 是奥运会，来自古希腊的 Olympia；Olympic 永远首字母大写作形容词。\",\n\"marathon\":\"画面：士兵从马拉松平原一路跑回雅典报捷，跑完最后一步倒下——marathon「马拉松」。marathon 源于这个传说，如今指 42.195 公里的长跑；也可比喻漫长的活动。\",\n\"myth\":\"画面：老人们围着火堆讲宙斯如何掷下闪电，孩子们听得入神——myth「神话」。myth 是古代流传的超自然故事，用来解释世界；也可指被误信的说法，如 a popular myth。\",\n\"legend\":\"画面：村民代代相传：湖底沉着一位英雄的宝剑——legend「传说」。legend 是流传久远、真假交织的故事；legendary 是『传奇的』。地图上的图例也叫 legend，靠语境分。\",\n\"epic\":\"画面：厚厚的一部诗，讲述英雄跨海远征十年的功业——epic「史诗」。epic 是描写英雄和民族大事的长篇叙事诗，如《荷马史诗》；也可形容『宏大的』。\",\n\"saga\":\"画面：一部跨越三代人的长篇故事，从祖父的航海讲到孙子的复仇——saga「传奇故事」。saga 原是北欧中世纪的家族长篇叙事；现代也可指任何漫长曲折的系列故事。\",\n\"folklore\":\"画面：奶奶讲的狐仙故事、村里过节的禁忌，都是书上查不到的——folklore「民俗；民间传说」。folk 是『民间的人们』，lore 是『传说知识』；folklore 是百姓口耳相传的文化。\",\n\"ritual\":\"画面：祭祀开始前，每个人按固定顺序净手、献花、行礼，一步都不能乱——ritual「仪式」。ritual 是按传统程式重复的仪式行为；日常固定习惯也可叫 ritual，如 morning ritual。\",\n\"ceremony\":\"画面：毕业礼上，校长逐个拨动学位帽的流苏，全场起立鼓掌——ceremony「典礼；仪式」。ceremony 是正式场合的典礼，比 ritual 更重场合感；opening ceremony 是开幕式。\",\n\"sacrifice\":\"画面：祭坛上，人们献上最好的牲畜和谷物，祈求神灵保佑丰收——sacrifice「祭祀；牺牲」。古代 sacrifice 是献祭；现代更常用『牺牲、舍弃』义，如 sacrifice time for family。\",\n\"ancestor\":\"画面：祠堂里供着历代先人的牌位，后辈逢年过节前来祭拜——ancestor「祖先」。CN 的『祖先崇拜』是托福常讲的 ancestor worship；ancestor 本人就是祖先，descendant 是后代，正好相反。\",\n\"worship\":\"画面：信众在神像前跪拜、献花、诵经，神情虔诚——worship「崇拜；敬拜」。worship 是对神灵或偶像的敬奉；也可指极度的崇拜，如 worship a singer。\",\n\"crusade\":\"画面：中世纪，披着十字标志的军队从欧洲远征地中海东岸——crusade「十字军东征」。crusade 特指 11–13 世纪的宗教远征，来自 cross『十字』；现代也可比喻争取正义的运动。\",\n\"painting\":\"画面：画家站在梯子上，一笔一笔把整面墙涂成一片星空——painting「绘画」。painting 既是绘画这门艺术和动作，也是画作本身；an oil painting 是一幅油画。\",\n\"portrait\":\"画面：画家盯着坐在椅子上的人，一笔笔描出他的眼神和皱纹——portrait「肖像」。portrait 是以人为主角的画像或照片；风景画是 landscape，静物是 still life。\",\n\"sketch\":\"画面：画家在速写本上用几根线条飞快勾出一座桥的轮廓——sketch「素描；速写」。sketch 是快速、粗略的第一稿；动词 sketch out 是『简要勾勒』计划或想法。\",\n\"canvas\":\"画面：一块绷在木框上的白布立在画架上，等着第一笔颜料——canvas「画布」。canvas 是油画的布面；说 a blank canvas，也可比喻『一张白纸般的新起点』。\",\n\"palette\":\"画面：画家左手托着木板，上面挤着一圈红黄蓝颜料，中间是调出的新色——palette「调色板」。palette 既是那块板，也是画家惯用的色彩范围，如 a limited palette 色彩克制。\",\n\"brush\":\"画面：画笔蘸饱颜料，在纸上拖出一道湿润的痕迹——brush「画笔；刷子」。brush 是带毛的刷具；牙刷 toothbrush、刷题无关。动词 brush 是『刷、轻触』。\",\n\"pigment\":\"画面：研钵里，矿物被磨成细细的红粉，加水就成了颜料——pigment「颜料；色素」。pigment 是让物质显色的粉末或成分；皮肤和树叶里的色素也叫 pigment。\",\n\"watercolor\":\"画面：清水在纸上晕开，颜料随水流动，边缘留下淡淡的水痕——watercolor「水彩」。watercolor 是用水调和的水性颜料画，特点是透明、流动；它也可指水彩画这门艺术。\",\n\"oil\":\"画面：画布上，厚厚的颜料堆出立体的笔触，干得很慢——oil「油画」。CN 写『油画』，是 oil painting 的简称；oil 本身是『油』，石油和食用油都用它，艺术语境里指油画颜料或作品。\",\n\"fresco\":\"画面：工匠在还没干的石灰墙面上抢着作画，颜料和墙融为一体——fresco「壁画」。fresco 是趁湿灰泥未干时画上去的壁画，干后千年不褪；西斯廷教堂天顶就是 fresco。\",\n\"mural\":\"画面：整栋楼的侧墙被画成一片森林，路过的人都停下脚步——mural「墙画；壁画」。mural 是直接画在大墙面上的公共艺术；和 fresco 不同，mural 不限技法，墙够大就行。\",\n\"statue\":\"画面：广场中央，青铜铸成的人像站在基座上，鸽子落在他肩头——statue「雕像」。statue 是立体的全身雕像，多为纪念人物；the Statue of Liberty 是自由女神像。\",\n\"bust\":\"画面：博物馆展柜里，只雕了头部和胸部的石像目光平视前方——bust「半身像」。bust 是只到胸部的雕像；它也可指胸围。看展时 bust 和 statue 的区别就在于完整程度。\",\n\"exhibition\":\"画面：展厅里，几十幅作品按主题挂好，开展第一天就排起长队——exhibition「展览」。exhibition 是公开展出作品的活动；exhibit 是展品或展出动作，场馆办的是 exhibition。\",\n\"gallery\":\"画面：安静的长廊里，一幅幅画间隔着挂在白墙上，射灯逐幅打亮——gallery「画廊」。gallery 是展出和出售艺术品的空间；也可指楼座观众席，先记画廊。\",\n\"museum\":\"画面：一栋大楼里，自然标本、古代文物和名画分层陈列——museum「博物馆」。museum 是收藏和展示文物、艺术与科学标本的机构；art museum 是美术馆。\",\n\"curator\":\"画面：开展前，她决定哪幅画挂 C 位、灯光打什么角度，写下展签——curator「馆长；策展人」。curator 是负责收藏与策划展览的专业人；现代艺术展里更常译为策展人。\",\n\"collection\":\"画面：收藏家一生的画作整齐地码在恒温库房里，每幅都有编号——collection「收藏；藏品」。collection 是有意识收集起来的成套物品；a collection of poems 还可指诗集。\",\n\"masterpiece\":\"画面：这幅画展出三百年，仍有无数人跨越海洋来看它一眼——masterpiece「杰作」。masterpiece 是艺术家最高水平的代表作；master 是大师，piece 是作品，合起来就是大师之作。\",\n\"genre\":\"画面：书店把书按悬疑、科幻、爱情分架摆放，各有各的读者——genre「体裁；类型」。genre 是艺术作品的分类，如小说、诗歌是文学 genre；电影和音乐也按 genre 分。\",\n\"style\":\"画面：同一座山，写实派画成照片，印象派画成光斑——style「风格」。style 是作品或人一贯的表现方式；艺术史就是一部 style 的变迁史，如 Baroque style 巴洛克风格。\",\n\"technique\":\"画面：老师傅手腕轻轻一转，拉坯的陶土立刻变得薄而均匀——technique「技法」。technique 是做某事的专门方法和手上功夫；painting technique 是绘画技法。\",\n\"composition\":\"画面：画家把人物放在画面左下角，右上角留一棵树，视线被引向远山——composition「构图」。composition 是元素在作品中如何安排；音乐里是作曲，作文里是构思布局。\",\n\"perspective\":\"画面：站在铁轨中央望去，两条铁轨在远方汇成一个点——perspective「透视；视角」。艺术里的 perspective 是让平面显出远近的画法；引申为看问题的角度，如 from my perspective。\",\n\"proportion\":\"画面：初学者画的人头太大身子太小，老师摇头：比例错了——proportion「比例」。proportion 是各部分大小之间的关系；人体素描最讲究 proportion，数学里的比例也是它。\",\n\"symmetry\":\"画面：一只蝴蝶展开翅膀，左右两边的花纹几乎完全镜像——symmetry「对称」。symmetry 是两边或多边形状对应相等；建筑和生物都爱 symmetry，asymmetry 是不对称。\",\n\"texture\":\"画面：手指摸过粗糙的树皮，又摸过光滑的丝绸，指尖感受完全不同——texture「质感；纹理」。texture 是表面摸起来或看起来粗细软硬的质地；画家用笔触造 texture，音乐也有织体义。\",\n\"color\":\"画面：调色盘上红黄蓝三原色混一混，变出几十种新颜色——color「色彩」。color 是绘画最基本的语言之一；warm colors 暖色、cool colors 冷色是托福艺术文章的常客。\",\n\"hue\":\"画面：色环上，红、橙、黄、绿、蓝、紫一格格排开，每一格是一种色相——hue「色调；色相」。hue 专指颜色的种类本身，不谈明暗；shade 和 tone 更偏明暗层次。\",\n\"shade\":\"画面：画家在苹果背光的一面涂上深色，苹果立刻立体起来——shade「阴影；深浅」。绘画里 shade 是颜色加黑后的深色部分；日常 shade 也是树荫和灯罩，艺术文里先想明暗。\",\n\"tone\":\"画面：整幅画偏冷灰，连人物的脸都笼罩在同一种色调里——tone「色调；语气」。tone 在绘画里是整体明暗色彩倾向，在文学里是作者语气；两个义都靠『整体氛围』这条线记。\",\n\"sketchbook\":\"画面：画家的本子里，有车站的人群速写、半页桥的轮廓和随手记的灵感——sketchbook「素描本」。sketchbook 是随身练习和记录灵感的本子，是 sketch 的集合地。\",\n\"easel\":\"画面：三条腿的木架撑起画布，画家可以站着平视作画——easel「画架」。easel 是画室里最不起眼但缺不了的道具；它只负责稳稳托住画布。\",\n\"studio\":\"画面：一间大窗的工作室里，画架、颜料和半成品画作摆满一地——studio「工作室」。studio 是艺术家创作的场所；摄影棚、录音室和电影制片厂也都叫 studio。\",\n\"photograph\":\"画面：快门一按，老人脸上的笑纹被永久定格在一张相纸上——photograph「照片」。photograph 是正式说法，日常说 photo；photography 是摄影艺术，photographer 是摄影师。\",\n\"camera\":\"画面：摄影师调好光圈和快门，对准迁徙的鸟群按下按钮——camera「相机」。camera 通过镜头记录影像；它来自 camera obscura『暗箱』，是绘画辅助工具演变来的。\",\n\"film\":\"画面：导演喊『开拍』，摄影机把演员的表演一段段记录下来——film「电影；胶片」。film 既是电影作品，也是老式胶片；film festival 是电影节。英式英语里电影多说 film。\",\n\"cinema\":\"画面：周末晚上，人们走进影院，在大银幕前坐成满场——cinema「电影院；电影艺术」。cinema 既是放映场所，也是电影这门艺术整体；go to the cinema 是去看电影。\",\n\"director\":\"画面：片场里，他坐在监视器后，一句『再来一条』决定全组重拍——director「导演」。director 是掌控作品整体的人；电影导演、乐团指挥之外的公司董事也叫 director，核心是『掌舵者』。\",\n\"actor\":\"画面：灯光下，他换上戏服，立刻变成了另一个人——actor「演员」。actor 是从事表演的人，现在男女演员都可用 actor；actress 专指女演员。\",\n\"actress\":\"画面：红毯上，她凭一部电影拿下最佳女主角——actress「女演员」。actress 是女性演员，词尾 -ess 表示女性；现代报道也常用 actor 统称，两个都要认得。\",\n\"stage\":\"画面：幕布拉开，演员站在聚光灯下，台下瞬间安静——stage「舞台」。stage 是表演发生的台子；on stage 是在台上。它也可指阶段，如 an early stage，靠语境分。\",\n\"audience\":\"画面：演出结束，观众席爆发出整齐的掌声——audience「观众」。audience 是观看或收听的人群总称，作集合名词；target audience 是目标受众。\",\n\"performance\":\"画面：钢琴家最后一个音落下，全场屏住呼吸两秒才鼓掌——performance「表演；演出」。performance 是一场完整的演出呈现；也可指表现或性能，如 job performance 工作表现。\",\n\"rehearsal\":\"画面：正式演出前一周，演员一遍遍走位、对台词，把失误提前犯完——rehearsal「排练」。rehearsal 是演出前的反复练习；rehearse 是动词。dress rehearsal 是彩排。\",\n\"script\":\"画面：演员人手一本册子，台词和动作提示都写在上面——script「剧本」。script 是演出要照着演的文字稿；电影剧本是 screenplay 也属 script。手写体也叫 script。\",\n\"plot\":\"画面：故事从平静小镇开始，一封信打破一切，主角被迫踏上旅程——plot「情节」。plot 是小说或戏剧里事件的安排链条；plot twist 是情节反转。它也可指小块土地和阴谋。\",\n\"antagonist\":\"画面：主角每前进一步，那个对手就出来设置一道障碍——antagonist「反派；对手」。antagonist 是与主角 protagonist 对立的力量；不一定是坏人，但一定站在主角对面。\",\n\"dialogue\":\"画面：舞台上两人你一句我一句，观众靠他们的对话拼出全部真相——dialogue「对话」。dialogue 是两人以上的交谈，也是小说戏剧里的对白部分；独白是 monologue。\",\n\"monologue\":\"画面：舞台上只剩一个人，对着空荡荡的观众席说出心里话——monologue「独白」。mono- 是『一』，monologue 是一个人的长篇独白；对话是 dialogue，自言自语特写是 soliloquy。\",\n\"soliloquy\":\"画面：哈姆雷特独自站在台上，把『生存还是毁灭』说给观众听——soliloquy「自言自语；独白」。soliloquy 是戏剧人物独自说出内心想法的独白，台上其他人物听不见。\",\n\"poetry\":\"画面：短短十四行，诗人把一生的离别写进韵脚里——poetry「诗歌」。poetry 是诗歌这种文学体裁的总称；一首具体的诗是 a poem，诗人是 poet。\",\n\"poem\":\"画面：一页纸上只有二十行字，却让读者读了一遍又一遍——poem「诗歌；一首诗」。poem 是单篇作品；poetry 是总称，就像 poem 是树、poetry 是林。\",\n\"verse\":\"画面：诗人写下四行，前两行和后两行在尾音上轻轻呼应——verse「诗句；诗节」。verse 是诗的一行或一节；散文是 prose，verse 专属于诗体。\",\n\"rhyme\":\"画面：诗的每行结尾，cat、hat、bat 一个个押着同样的尾音——rhyme「押韵」。rhyme 是诗行末尾声音的重复；rhyme scheme 是韵式，儿歌 nursery rhyme 也用它。\",\n\"rhythm\":\"画面：鼓点一起，诗句像有了心跳，读者的脚不自觉地打拍子——rhythm「节奏」。rhythm 是声音或动作有规律的起伏；诗歌、音乐和心跳都有 rhythm。\",\n\"stanza\":\"画面：一首诗被空行分成四块，每块四行，像房子的四个房间——stanza「诗节」。stanza 是诗中由若干行组成的一段，相当于散文里的段落；意大利语里 stanza 本义就是『房间』。\",\n\"metaphor\":\"画面：诗人写道『时间是条河』，没用 like，却把时间说成了河——metaphor「隐喻」。metaphor 是直接把 A 说成 B 的比喻，不带 like 或 as；带 like/as 的是 simile 明喻。\",\n\"simile\":\"画面：诗里写『她的笑像春天的风』，like 明明白白摆在句子里——simile「明喻」。simile 是用 like 或 as 把两样东西相比；和 metaphor 的区别就看有没有这两个词。\",\n\"imagery\":\"画面：读到『咸咸的海风、尖锐的鸥鸣』，读者眼前立刻浮现出海边——imagery「意象」。imagery 是文字在读者脑中唤起的感官画面；它不只是视觉，还包括声音、气味和触感。\",\n\"symbolism\":\"画面：小说里反复出现的白鸟，读者都懂它代表自由——symbolism「象征主义；象征手法」。symbolism 是用具体事物代表抽象意义的艺术手法，也是 19 世纪的文学流派；symbol 是象征物。\",\n\"allegory\":\"画面：一只狐狸和乌鸦的故事讲完，孩子懂得了不要被奉承骗——allegory「寓言；寓意故事」。allegory 是表面一个故事、底下藏一套道理的叙事；整篇都在『借事说理』。\",\n\"fable\":\"画面：龟兔赛跑的故事结尾，点明了那句人人皆知的道理——fable「寓言故事」。fable 是短小、主角常是动物的寓言，结尾必有 moral 教训；伊索寓言就是 Aesop's Fables。\",\n\"novel\":\"画面：一本三百页的虚构故事，陪读者度过整个冬天——novel「小说」。novel 是长篇虚构叙事；它还可作形容词『新颖的』，如 a novel idea 新奇的想法，靠语境分。\",\n\"fiction\":\"画面：书里的城市不存在，人物也全是编的，读者却为他们流泪——fiction「小说；虚构」。fiction 是虚构文学的总称；与之相对的 nonfiction 是真实写作，science fiction 是科幻。\",\n\"nonfiction\":\"画面：这本书里的每个事件都有采访和档案支撑，一个情节都没编——nonfiction「非虚构」。nonfiction 是基于事实的写作，如传记、历史和报道；non- 是『非』，fiction 是虚构。\",\n\"biography\":\"画面：作家查了三百封书信，写出科学家完整的一生——biography「传记」。biography 是别人为某人写的人生记录；bio- 是『生命』，-graphy 是『写』，写一生就是传记。\",\n\"autobiography\":\"画面：八十岁的将军亲自落笔，从童年写到退役——autobiography「自传」。auto- 是『自己』，autobiography 是自己写自己的一生；别人写的是 biography。\",\n\"memoir\":\"画面：老水手没有写完整一生，只写了那三年远航的日子——memoir「回忆录」。memoir 是亲历者回忆某段经历的写作，比 autobiography 更聚焦片段；来自 memory 的近亲 mémoire。\",\n\"prose\":\"画面：整页没有分行和韵脚，文字像说话一样自然流淌——prose「散文」。prose 是不用韵律的普通书面语言，小说和散文都属 prose；它与 verse 诗体相对。\",\n\"drama\":\"画面：舞台上，一家人多年的秘密在一顿晚饭上全部爆发——drama「戏剧」。drama 是为舞台写的剧种和作品；也可指生活中戏剧性的事件。dramatic 是『戏剧性的』。\",\n\"comedy\":\"画面：主角越想掩饰，误会闹得越大，观众笑得直不起腰——comedy「喜剧」。comedy 是以幽默和圆满结局为主的戏剧类型；与 tragedy 悲剧相对。stand-up comedy 是脱口秀。\",\n\"tragedy\":\"画面：英雄因一个性格缺陷一步步走向毁灭，观众含泪离场——tragedy「悲剧」。tragedy 是主角走向灾难结局的戏剧；现实中的重大不幸也叫 tragedy。\",\n\"opera\":\"画面：舞台上，演员不用说话，全部台词都用咏叹调唱出来——opera「歌剧」。opera 是把戏剧、音乐和舞台合在一起的综合艺术；opera house 是歌剧院。\",\n\"ballet\":\"画面：舞者踮起脚尖，在舞台上旋转、跳跃，用身体讲完整的故事——ballet「芭蕾」。ballet 是以足尖和程式化动作为特征的舞蹈戏剧；ballet dancer 是芭蕾舞者。\",\n\"orchestra\":\"画面：指挥棒落下，弦乐、管乐和打击乐同时响起——orchestra「管弦乐队」。orchestra 是由多组乐器组成的大型乐队；交响乐团是 symphony orchestra。\",\n\"composer\":\"画面：深夜，他在五线谱上写下最后一个音符，一首交响曲完成了——composer「作曲家」。composer 是创作音乐的人；compose 是『作曲、构成』，贝多芬就是 composer。\",\n\"symphony\":\"画面：上百人的乐队演奏四十分钟，四个乐章层层推进——symphony「交响乐」。symphony 是为大型管弦乐队写的多乐章作品；sym- 是『一起』，-phony 是声音，一起发声。\",\n\"melody\":\"画面：一段旋律听一遍就能哼出来，走在路上还在脑子里转——melody「旋律」。melody 是音乐里最抓耳的那条主线；和声 harmony 是陪衬的和弦层。\",\n\"harmony\":\"画面：三个歌手同时唱不同的音，高低交错却意外地好听——harmony「和声」。harmony 是不同音高同时发出的协和效果；引申为人与人之间的和谐。\",\n\"chorus\":\"画面：舞台后排，几十名歌者齐声唱出副歌，声浪扑面而来——chorus「合唱；合唱团」。chorus 是多人齐唱的部分或团体；歌曲反复的副歌也叫 chorus。领唱之外的大合唱就是它。\",\n\"solo\":\"画面：全场灯光暗下，只有一束光打在独唱者身上——solo「独唱；独奏」。solo 是一人完成的表演；solo 在意大利语里就是『独自』，a solo performance 是个人演出。\",\n\"computer\":\"画面：屏幕亮起，键盘敲击声中，数据被飞快地处理成图表——computer「计算机」。computer 本义是『计算者』，compute 是计算；如今它指能编程处理信息的电子机器。\",\n\"software\":\"画面：同一台电脑，装上新程序就能剪视频，换个程序就能做账——software「软件」。software 是看不见摸不着的程序部分；与之相对，摸得着的 hardware 是硬件。ware 是『器物』。\",\n\"hardware\":\"画面：他拧开电脑机箱，风扇、主板和硬盘全都摆在眼前——hardware「硬件」。hardware 是机器的实体部件；更新 hardware 是换零件，更新 software 只是装程序。\",\n\"program\":\"画面：程序员写下几百行指令，机器一步不差地照着执行——program「程序」。program 是让计算机按步骤工作的指令集；它也可指节目和计划，计算机语境里先想程序。\",\n\"code\":\"画面：屏幕上滚动着一行行由字母和符号组成的指令——code「代码」。code 是程序员写给机器的语言；也可指密码和法规，如 building code 建筑规范，先看语境。\",\n\"algorithm\":\"画面：导航软件在一秒内算出最快的路线：先比距离，再避堵车——algorithm「算法」。algorithm 是解决问题的固定步骤，像一份精确的菜谱；推荐算法就是按步骤算你喜欢什么。\",\n\"database\":\"画面：图书馆的书不再乱堆，而是按编号存进可检索的系统，秒速调出——database「数据库」。database 是结构化存放、可查询的数据集合；data 是数据，base 是基地。\",\n\"internet\":\"画面：一根根海底光缆把各大洲的电脑连成一张巨网——internet「互联网」。internet 是全球计算机网络的总互联；专有名词常大写 Internet，上网是 surf the internet。\",\n\"website\":\"画面：浏览器地址栏输入一行网址，一个完整的站点在屏幕上展开——website「网站」。website 是由多个网页组成的站点；单个页面是 webpage，别混。\",\n\"browser\":\"画面：他打开那个熟悉的窗口，输入网址，网页立刻加载出来——browser「浏览器」。browser 是浏览网页的软件，如 Chrome；browse 本义是『翻看、浏览』，羊吃草也叫 browse。\",\n\"server\":\"画面：机房里一排机器日夜运转，全球用户的请求都汇到这里处理——server「服务器」。server 是为其他电脑提供数据和服务的机器；serve 是『服务』，server 就是服务的提供方。\",\n\"password\":\"画面：登录框里，他输入一串只有自己知道的字符，门开了——password「密码」。password = pass（通过）+ word（词），说对这个词才放行；别和 passcode、PIN 弄混，用法相近。\",\n\"hacker\":\"画面：深夜，有人绕过防火墙，悄悄潜入公司的系统——hacker「黑客」。hacker 指擅自侵入计算机系统的人；白帽 hacker 帮企业找漏洞，黑帽则干坏事，语境定褒贬。\",\n\"encryption\":\"画面：信息发出前被锁进保险箱，没有钥匙的人只看到一串乱码——encryption「加密」。encryption 是把明文变成密文的过程；encrypt 是动词，反义 decryption 解密。\",\n\"decryption\":\"画面：收到一串乱码后，接收方输入密钥，文字一行行还原——decryption「解密」。decryption 是把密文变回可读信息；de- 是『去掉』，去掉加密就是解密。\",\n\"backup\":\"画面：硬盘损坏前一天，他刚把全部照片复制到另一块盘上——backup「备份」。backup 是为防丢失而留的副本；back up 是动词『备份、支持』。没有 backup，一次损坏就全没了。\",\n\"storage\":\"画面：仓库一样的机房里，数据被分门别类存进一排排硬盘——storage「存储」。storage 是存放数据或物品的空间与能力；storage capacity 是存储容量。\",\n\"processor\":\"画面：芯片中央，几十亿次计算在一秒内完成，像整台机器的大脑中枢在运转——processor「处理器」。processor 是执行指令的核心部件，常指 CPU；process 是『处理』，processor 是处理者。\",\n\"chip\":\"画面：指甲盖大小的硅片上，刻着密密麻麻的电路——chip「芯片」。chip 本义是『小薄片』；计算机芯片就是刻满电路的硅片。它也可指薯片和碎屑，靠语境分。\",\n\"sensor\":\"画面：烟雾一飘近天花板，小装置立刻感应到并发出警报——sensor「传感器」。sensor 是感知温度、光、压力等变化的器件；sense 是感觉，sensor 就是机器的『感觉器官』。\",\n\"robot\":\"画面：工厂里，机械臂不知疲倦地重复着焊接动作，分毫不差——robot「机器人」。robot 是能自动执行任务的机器；robotics 是机器人学。这个词来自捷克语 robota『劳役』。\",\n\"automation\":\"画面：整条产线没有一个工人，机器自己检测、自己装箱——automation「自动化」。automation 是让机器自动完成原本由人做的工作；auto- 是『自动』，automatic 是形容词。\",\n\"artificial\":\"画面：实验室里培育出的花香，和真花几乎一样，却不是花分泌的——artificial「人工的；人造的」。artificial 是人造而非天然的；artificial intelligence 是人工智能，artificial flowers 是假花。\",\n\"machine\":\"画面：蒸汽机带动皮带，整间工厂的设备一起转起来——machine「机器」。machine 是能代替人力完成工作的装置总称；machine learning 是让计算机从数据中学习的『机器学习』。\",\n\"neural\":\"画面：放大图里，神经元像树枝一样伸出触角彼此连接——neural「神经的」。neural 与神经系统有关；neural network 神经网络借的就是大脑神经元连接的图式。\",\n\"analysis\":\"画面：实验室报告上，样本被分解成十几种成分逐项列出——analysis「分析」。analysis 是 analyze 的名词，复数是 analyses；data analysis 数据分析就是把数据拆开看明白。\",\n\"visualization\":\"画面：一万个数字被画成一张地图，哪里密集哪里稀疏，一眼看清——visualization「可视化」。visualization 是把抽象数据变成图像；visual 是『视觉的』，看得见才好理解。\",\n\"simulation\":\"画面：飞行员坐在模拟舱里，经历暴雨和引擎故障，飞机却没离开地面——simulation「模拟」。simulation 是用模型重现真实场景来练习或预测；飞行模拟、气候模拟都用它。\",\n\"modeling\":\"画面：工程师在电脑里搭出大桥的三维模型，先在虚拟世界里压一压——modeling「建模」。modeling 是为真实事物建立模型的过程；气候 modeling 是托福科技文的高频词。\",\n\"virtual\":\"画面：戴上头显，他明明站在客厅，却看见自己站在火星表面——virtual「虚拟的」。virtual 是由计算机造出的、非实体的；virtual reality 是虚拟现实。virtual 还可指『实质上的』。\",\n\"reality\":\"画面：摘下头显，客厅的沙发和茶几还是原来的样子——reality「现实」。reality 是真实存在的世界；in reality 是『实际上』。和 virtual 放在一起，正好一真一假。\",\n\"augmented\":\"画面：手机镜头对准街道，屏幕上叠出了餐厅评分和导航箭头——augmented「增强的」。augmented reality 是增强现实：在真实画面上叠加信息。augment 是『增加、扩大』。\",\n\"digital\":\"画面：老式钟表指针消失，取而代之的是跳动的数字——digital「数字的」。digital 是以离散数字形式处理信息的方式；digital camera 数码相机。反义是 analog 模拟的。\",\n\"analog\":\"画面：黑胶唱片转动，唱针顺着纹路把连续的声波读出来——analog「模拟信号的」。analog 用连续变化的物理量记录信息，如老式表盘；与 digital 的离散数字相对。\",\n\"signal\":\"画面：手机屏幕角落，信号格从一格跳到满格，电话终于打通——signal「信号」。signal 是传递信息的电波、光或动作；交通信号和神经信号都叫 signal。\",\n\"transmission\":\"画面：广播塔把节目变成电波，越过城市送到千家万户的收音机——transmission「传输；传送」。transmission 是把信号、动力或疾病传过去的过程；transmit 是动词，汽车变速箱也叫 transmission。\",\n\"bandwidth\":\"画面：一条窄水管和一条宽水管同时放水，宽的瞬间流量大得多——bandwidth「带宽」。bandwidth 是单位时间能通过的数据量；带宽越大，网速越快。它也可比喻人的精力上限。\",\n\"latency\":\"画面：按下按钮后，画面停顿了半秒才动，长途通话总是慢半拍——latency「延迟」。latency 是发出指令到得到响应之间的等待时间；游戏和视频会议最怕 high latency。\",\n\"protocol\":\"画面：两台电脑握手时，先按约定的格式互报身份，一步都不能乱——protocol「协议」。protocol 是通信双方共同遵守的规则；外交礼仪也叫 protocol，核心都是『约定好的规矩』。\",\n\"interface\":\"画面：手指点在屏幕的图标上，机器立刻明白要做什么——interface「界面；接口」。interface 是人与机器、系统与系统之间接触的那一层；user interface 是用户界面。\",\n\"operating\":\"画面：电脑一开机，先加载那套管理所有程序的底层系统——operating「操作系统的」。operating system 是操作系统全称，operating 是其中的修饰词；离开 system 单独出现时多是『运转的、手术的』。\",\n\"system\":\"画面：空调、传感器和控制器连成一体，室温自动保持恒定——system「系统」。system 是相互配合的部件组成的整体；操作系统是 operating system，生态系统是 ecosystem。\",\n\"mobile\":\"画面：电话从固定在墙上的座机，变成能揣进口袋到处走的设备——mobile「移动的；手机」。mobile 是能移动的；mobile phone 是手机。美式更常说 cell phone。\",\n\"smartphone\":\"画面：一部手机既能打电话，又能上网、拍照、导航——smartphone「智能手机」。smartphone 是带操作系统的多功能手机；smart 在这里是『智能的』，不是『时髦的』。\",\n\"laptop\":\"画面：他把电脑合上夹在腋下，走到咖啡馆打开继续工作——laptop「笔记本电脑」。lap 是大腿，laptop 就是能放在腿上的电脑；台式机是 desktop，正好一对。\",\n\"desktop\":\"画面：一台主机立在桌边，显示器和键盘摆满桌面，搬不动——desktop「台式电脑；桌面」。desktop 是固定在桌上用的电脑；开机后看到的界面也叫桌面 desktop。\",\n\"keyboard\":\"画面：手指在按键上飞舞，字母一个个跳进文档——keyboard「键盘」。key 是键，board 是板；keyboard 是打字的按键板。钢琴的琴键部分也叫 keyboard。\",\n\"mouse\":\"画面：小小的塑料外壳拖着一条线，像只小老鼠在桌上跑——mouse「鼠标」。mouse 因外形和尾巴得名；复数是 mice 和老鼠一样。没有它，光标就动不了。\",\n\"printer\":\"画面：机器嗡嗡作响，一张印满文字的纸缓缓吐出来——printer「打印机」。printer 是把电子文档变成纸的设备；print 是印刷，printer 既可指机器，也可指印刷商。\",\n\"scanner\":\"画面：把照片放进玻璃板，机器用光一行行扫过，图像进了电脑——scanner「扫描仪」。scanner 靠逐行扫描把纸面内容数字化；scan 是『扫描、浏览』，机场安检也用它。\",\n\"drone\":\"画面：四只旋翼嗡嗡转动，小飞行器升上天空航拍整座城市——drone「无人机」。drone 是无人驾驶飞行器；它本义是雄蜂，嗡嗡声就是名字的来历。\",\n\"rocket\":\"画面：点火后，火焰和浓烟喷涌，长长的箭体冲向天空——rocket「火箭」。rocket 靠喷出气体反推升空；价格 rocket 是『飞涨』，同一个冲天画面。\",\n\"spacecraft\":\"画面：舱体穿过大气层，宇航员透过舷窗看见蓝色的地球——spacecraft「航天器」。spacecraft 是进入太空的飞行器总称，单复数同形；卫星、飞船都属 spacecraft。\",\n\"microscope\":\"画面：把洋葱表皮放在载玻片上，调好焦距，细胞一格格清晰起来——microscope「显微镜」。micro- 是『小』，-scope 是『看』；microscope 是看微小世界的仪器，望远镜是 telescope。\",\n\"optic\":\"画面：光线穿过透镜被折射，焦点在屏幕上汇成一点——optic「光学的」。optic 与光和视觉仪器有关；fiber optic 是光纤。optics 是光学这门学科。\",\n\"panel\":\"画面：控制室的墙上，一整排仪表和开关集成在一块板面上——panel「面板；仪表板」。panel 是镶嵌着仪表或开关的平板；太阳能板是 solar panel。它也可指专家小组。\",\n\"wind\":\"画面：风吹过草原，草浪一波波倒向同一个方向——wind「风」。CN 标在科技主题因为风力发电常讲 wind power；wind 本身是最基础的自然词，名词读 /wɪnd/，动词『缠绕』读 /waɪnd/。\",\n\"electric\":\"画面：插头一插，电流顺着电线涌入，灯立刻亮了——electric「电动的；电的」。electric 指由电驱动或与电有关的；electric vehicle 是电动车。情绪『令人兴奋的』是 electric 的比喻义。\",\n\"vehicle\":\"画面：从自行车、汽车到卡车，能载人载货在路上跑的都排成一排——vehicle「车辆」。vehicle 是交通工具的总称，比 car 大得多；motor vehicle 是机动车。\",\n\"hybrid\":\"画面：一辆车起步时用电、高速时用油，两种动力无缝切换——hybrid「混合动力的；混合的」。hybrid 是两种来源的混合体；hybrid car 是混动车，动植物的杂交种也叫 hybrid。\",\n\"engine\":\"画面：引擎盖下，活塞上下运动，燃烧的能量变成车轮的转动——engine「发动机；引擎」。engine 是把燃料能量变成动力的机器；搜索引擎是 search engine，借的也是『动力核心』的画面。\",\n\"brake\":\"画面：前方突然出现行人，司机一脚踩下踏板，车速骤降——brake「刹车」。brake 是让车慢下来或停住的装置，也是踩刹车这个动作；和 break『打破』同音，拼写别混。\",\n\"steering\":\"画面：双手握住方向盘轻轻一转，整辆车跟着改变方向——steering「转向；操舵」。steering 是控制方向的系统和动作；steering wheel 是方向盘，steer 是动词『驾驶、引导』。\",\n\"navigation\":\"画面：屏幕上的箭头随着车移动，提前播报下一个路口——navigation「导航」。navigation 是确定位置并规划路线的技术；navigate 是动词。航海时代靠星星 navigation，如今靠 GPS。\",\n\"gps\":\"画面：头顶的卫星群同时发出信号，手机上的小蓝点精确定位——gps「定位系统」。GPS 是 Global Positioning System 全球定位系统的缩写；说『开 GPS』就是开卫星定位。\",\n\"radar\":\"画面：控制塔屏幕上，电波扫过之处，飞机的光点一个个亮起——radar「雷达」。radar 靠发射无线电波再接收回波定位；它是 radio detection and ranging 的缩写词。\",\n\"sonar\":\"画面：潜艇发出声波，碰到海底礁石后返回，距离被算出来——sonar「声呐」。sonar 用的是声波，radar 用的是电波；蝙蝠和海豚天生自带 sonar 原理。\",\n\"wireless\":\"画面：耳机和手机之间看不见任何线，音乐却照样传过来——wireless「无线的」。wire 是线，-less 是没有；wireless 是不用线连接的技术，Wi-Fi 是其中一种。\",\n\"bluetooth\":\"画面：手机弹窗『是否配对耳机』，点确认，两台设备连上了——bluetooth「蓝牙」。bluetooth 是短距离无线连接标准，名字来自一位北欧国王的绰号；它的标志就是无线配对。\",\n\"wifi\":\"画面：路由器指示灯闪烁，整个房间的设备都连上了网——wifi「无线网络」。Wi-Fi 是基于无线局域网的上网方式；没有 Wi-Fi 时手机用的是 mobile data，别混。\"\n}");
